// --- core/markdown.js ---
// Markdown helpers: fenced code blocks, ATX headings and their GitHub anchors, sections found by a
// token, token matching (KD-6) and task-list checkbox counting with the `[~]` comment rule.
// Ported from the source (legacy rule); setext headings are not supported, as in the source.

/** A task-list box: `[ ]` open, `[x]`/`[X]` done, `[~]` skipped on purpose (needs a comment). */
const CHECKBOX = /^\s*(?:[-*+]|\d+[.)])\s+\[([ xX~])\](?:\s|$)/;
/** Any list item line (it ends the continuation lines of the item above it). */
const LIST_ITEM = /^\s*(?:[-*+]|\d+[.)])(?:\s|$)/;
/** A code fence line: up to 3 spaces of indent, 3+ backticks or tildes, then the info string. */
const FENCE = /^ {0,3}(`{3,}|~{3,})(.*)$/;
/** The required comment of a `[~]` box, found in its continuation lines (joined by spaces). */
const SKIP_COMMENT = /(?:^|\s)\*Skipped on ([^:*]*?):(.*?)\*(?=\s|$)/;
/** An ATX heading line: level marks, the text, optional closing hashes. */
const MD_ATX_HEADING = /^ {0,3}(#{1,6})\s+(.*?)(?:\s+#+)?\s*$/;
/** A character that can be part of a token word (KD-6). */
const MD_WORD_CHAR = /[\p{L}\p{N}_]/u;
/** The first token of a heading, for decision logs. */
const MD_HEADING_TOKEN = /^[A-Za-z0-9._-]+/;

/**
 * Splits a Markdown text into lines and marks each one that is a fence line or inside a fenced
 * code block (CommonMark rules: a closing fence uses the same character, is at least as long as
 * the opener and has no info string). CRLF input is split like LF.
 *
 * @param {string} markdown
 * @returns {{ text: string, fenced: boolean }[]}
 */
function markFences(markdown) {
  let fence = null;
  return markdown.split(/\r?\n/).map((text) => {
    const f = FENCE.exec(text);
    if (f) {
      if (fence === null) fence = f[1];
      else if (f[1][0] === fence[0] && f[1].length >= fence.length && f[2].trim() === '') fence = null;
      return { text, fenced: true };
    }
    return { text, fenced: fence !== null };
  });
}

/**
 * The ATX headings of a Markdown text that are outside fenced code blocks.
 *
 * @param {string} markdown
 * @returns {{ index: number, level: number, text: string }[]} index is the 0-based line
 */
function headings(markdown) {
  const out = [];
  markFences(markdown).forEach(({ text, fenced }, index) => {
    if (fenced) return;
    const h = MD_ATX_HEADING.exec(text);
    if (h) out.push({ index, level: h[1].length, text: h[2] });
  });
  return out;
}

/**
 * The anchors GitHub generates for the headings of a Markdown document (outside fenced code):
 * lowercase, punctuation dropped, spaces turned into hyphens, `-1`, `-2` ... for repeats.
 *
 * @param {string} markdown
 * @returns {Set<string>}
 */
function headingAnchors(markdown) {
  const anchors = new Set();
  const seen = new Map();
  for (const h of headings(markdown)) {
    const slug = h.text
      .replace(/<[^>]+>/g, '')
      .replace(/!?\[([^\]]*)\]\([^)]*\)/g, '$1')
      .replace(/`([^`]*)`/g, '$1')
      .replace(/(\*\*|__|\*|_)(?=\S)([^*_]*?\S)\1/g, '$2')
      .toLowerCase()
      .trim()
      .replace(/[^\p{L}\p{M}\p{N}\p{Pc}\- ]/gu, '')
      .replace(/ /g, '-');
    const n = seen.get(slug) ?? 0;
    seen.set(slug, n + 1);
    anchors.add(n === 0 ? slug : `${slug}-${n}`);
  }
  return anchors;
}

/**
 * The first token of a heading line (`## RD-2: Convert` → `RD-2`), after the level marks, `**`,
 * `__`, backticks and link markup are stripped; trailing `.` and `-` are trimmed.
 *
 * @param {string} headingLine
 * @returns {string | null} null when the heading does not start with a token
 */
function headingId(headingLine) {
  const text = headingLine
    .replace(/^ {0,3}#{1,6}(?=\s|$)/, '')
    .replace(/!?\[([^\]]*)\]\([^)]*\)/g, '$1')
    .replace(/\*\*|__|`/g, '')
    .trim();
  const m = MD_HEADING_TOKEN.exec(text);
  if (!m) return null;
  const token = m[0].replace(/[.-]+$/, '');
  return token === '' ? null : token;
}

/**
 * `true` when `needle` occurs in `haystack` as a token (KD-6): when the needle starts with a word
 * character (letter, digit, `_`), the character before the occurrence is not one; when it ends
 * with a word character, the occurrence is not followed by one, nor by `-` or `.` plus a letter or
 * digit. Any occurrence that satisfies this counts.
 *
 * @param {string} haystack
 * @param {string} needle
 * @returns {boolean}
 */
function tokenMatch(haystack, needle) {
  if (typeof haystack !== 'string' || typeof needle !== 'string' || needle === '') return false;
  const checkBefore = MD_WORD_CHAR.test(needle[0]);
  const checkAfter = MD_WORD_CHAR.test(needle[needle.length - 1]);
  for (let at = haystack.indexOf(needle); at !== -1; at = haystack.indexOf(needle, at + 1)) {
    if (checkBefore && at > 0 && MD_WORD_CHAR.test(haystack[at - 1])) continue;
    const next = at + needle.length;
    if (checkAfter && next < haystack.length) {
      const c = haystack[next];
      if (MD_WORD_CHAR.test(c)) continue;
      if ((c === '-' || c === '.') && next + 1 < haystack.length && /[\p{L}\p{N}]/u.test(haystack[next + 1])) continue;
    }
    return true;
  }
  return false;
}

/**
 * Finds the one heading (outside fences) whose text contains `section` as a token. The section
 * runs from that heading to the next heading of the same or a higher level (a deeper heading does
 * not end it), or to the end of the file.
 *
 * @param {string} markdown
 * @param {string} section
 * @returns {{ ok: true, heading: { index: number, level: number, text: string }, start: number, end: number }
 *   | { ok: false, reason: 'none' | 'many', matches: { index: number, level: number, text: string }[] }}
 *   start is the heading's 0-based line, end is exclusive
 */
function findSection(markdown, section) {
  const all = headings(markdown);
  const matches = all.filter((h) => tokenMatch(h.text, section));
  if (matches.length === 0) return { ok: false, reason: 'none', matches };
  if (matches.length > 1) return { ok: false, reason: 'many', matches };
  const heading = matches[0];
  const after = all.find((h) => h.index > heading.index && h.level <= heading.level);
  const end = after ? after.index : markdown.split(/\r?\n/).length;
  return { ok: true, heading, start: heading.index, end };
}

/**
 * The text of the section `section` (heading line included, LF line endings), or null when no
 * heading or more than one heading matches.
 *
 * @param {string} markdown
 * @param {string} section
 * @returns {string | null}
 */
function sectionText(markdown, section) {
  const r = findSection(markdown, section);
  if (!r.ok) return null;
  return markdown.split(/\r?\n/).slice(r.start, r.end).join('\n');
}

/** The indentation width of a line, tabs expanded to the next multiple of 4 (CommonMark). */
function mdIndentWidth(line) {
  let width = 0;
  for (const ch of line) {
    if (ch === ' ') width += 1;
    else if (ch === '\t') width += 4 - (width % 4);
    else break;
  }
  return width;
}

/** `true` when `iso` is `YYYY-MM-DD` and names a real calendar date. */
function mdIsCalendarDate(iso) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso);
  if (!m) return false;
  const d = new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])));
  return d.toISOString().slice(0, 10) === iso;
}

/** A skip reason as plain text: links reduced to their text, code and emphasis marks dropped. */
function mdPlainReason(reason) {
  return reason
    .replace(/!?\[([^\]]*)\]\([^)]*\)/g, '$1')
    .replace(/[`*_]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Checks the comment of a `[~]` box that starts at `lines[index]`. The comment lives on the
 * item's continuation lines: the non-blank, unfenced lines right after the box line that are
 * indented deeper than the list marker, up to the next list item.
 *
 * @param {{ text: string, fenced: boolean }[]} lines
 * @param {number} index
 * @param {number} min the minimum reason length
 * @returns {string | null} the problem, or null when the comment is valid
 */
function mdSkippedBoxProblem(lines, index, min) {
  const marker = mdIndentWidth(lines[index].text);
  const continuation = [];
  let j = index + 1;
  for (; j < lines.length; j += 1) {
    const { text, fenced } = lines[j];
    if (fenced || text.trim() === '' || LIST_ITEM.test(text) || mdIndentWidth(text) <= marker) break;
    continuation.push(text.trim());
  }
  const format = `*Skipped on YYYY-MM-DD: <reason of at least ${min} characters>*`;
  const m = SKIP_COMMENT.exec(continuation.join(' '));
  if (!m) {
    if (/Skipped on/.test(lines[index].text)) {
      return `the skip comment is on the box line; move it to an indented continuation line ${format}`;
    }
    let k = j;
    while (k < lines.length && !lines[k].fenced && lines[k].text.trim() === '') k += 1;
    if (k > j && k < lines.length && !lines[k].fenced && /Skipped on/.test(lines[k].text)) {
      return `the skip comment is separated from the box by a blank line; put it on the line right after the box`;
    }
    return `"[~]" needs a comment on an indented continuation line: ${format}`;
  }
  if (!mdIsCalendarDate(m[1])) return `skip date ${JSON.stringify(m[1])} is not a valid YYYY-MM-DD calendar date`;
  const reason = mdPlainReason(m[2]);
  if (reason.length < min) {
    return `skip reason ${JSON.stringify(reason)} has ${reason.length} characters; at least ${min} are required`;
  }
  return null;
}

/**
 * Counts Markdown task-list checkboxes on the lines `[start, end)` (0-based), ignoring any inside
 * fenced code blocks (fences are computed on the whole file). `done` counts `[x]`, `[X]` and `[~]`
 * (a skipped box is closed); `skipped` counts `[~]` alone. Every `[~]` without a valid
 * `*Skipped on YYYY-MM-DD: <reason>*` comment (a reason of at least `skipReasonMin` characters) is
 * reported in `problems` with its 1-based line number in the file.
 *
 * @param {string} markdown
 * @param {{ skipReasonMin?: number, start?: number, end?: number }} [options]
 * @returns {{ done: number, total: number, skipped: number, problems: { line: number, message: string }[] }}
 */
function countCheckboxes(markdown, { skipReasonMin = DEFAULTS.skipReasonMin, start = 0, end = Infinity } = {}) {
  let done = 0;
  let total = 0;
  let skipped = 0;
  const problems = [];
  const lines = markFences(markdown);
  const stop = Math.min(end, lines.length);
  for (let i = Math.max(0, start); i < stop; i += 1) {
    const { text, fenced } = lines[i];
    const m = fenced ? null : CHECKBOX.exec(text);
    if (!m) continue;
    total += 1;
    if (m[1] !== ' ') done += 1;
    if (m[1] === '~') {
      skipped += 1;
      const message = mdSkippedBoxProblem(lines, i, skipReasonMin);
      if (message) problems.push({ line: i + 1, message });
    }
  }
  return { done, total, skipped, problems };
}

// --- core/canonical-json.js ---
// Canonical JSON writer for the register: deterministic key order (FIELD_ORDER), 2-space indent,
// LF line endings and one trailing newline. Which objects are printed as blocks and which on one
// line is decided by their path in the document, so a change to one unit stays inside its lines.
//
// Unknown keys throw `Error('canonical-json: unknown field "<path>"')`. The path is written as
// in JavaScript: object keys joined with `.`, array elements as `[i]` (zero-based), e.g. `extra`,
// `config.todos.y`, `units[2].stauts`, `units[0].plans[1].scope2`. The keys of
// `config.todos.unhomed` are free (TODO paths) and are sorted, never reported as unknown.
// Keys whose value is `undefined` are omitted (and never reported). Values whose type does not
// match the expected shape are printed compactly with JSON.stringify; type checks belong to the
// schema rules, not to the writer.

const CANON_INDENT = '  ';

// Shape specs. `block`: multi-line object with known fields; `map`: multi-line object with free,
// sorted keys; `line`: one-line object with known fields; `blocks`/`lines`: arrays of those.
// Any field without a child spec is a scalar or an inline array of scalars.
const CANON_LINE_ARRAY = (fields) => Object.freeze({ shape: 'lines', item: Object.freeze({ shape: 'line', fields }) });

const CANON_SPEC = Object.freeze({
  shape: 'block',
  fields: FIELD_ORDER.root,
  children: Object.freeze({
    config: Object.freeze({
      shape: 'block',
      fields: FIELD_ORDER.config,
      children: Object.freeze({
        keyPatterns: Object.freeze({ shape: 'block', fields: FIELD_ORDER.keyPatterns, children: {} }),
        planDirs: CANON_LINE_ARRAY(FIELD_ORDER.planDir),
        regions: CANON_LINE_ARRAY(FIELD_ORDER.region),
        todos: Object.freeze({
          shape: 'block',
          fields: FIELD_ORDER.todos,
          children: Object.freeze({ unhomed: Object.freeze({ shape: 'map' }) }),
        }),
        decisionLogs: CANON_LINE_ARRAY(FIELD_ORDER.decisionLog),
        archive: Object.freeze({ shape: 'block', fields: FIELD_ORDER.archive, children: {} }),
      }),
    }),
    phases: Object.freeze({
      shape: 'blocks',
      item: Object.freeze({ shape: 'block', fields: FIELD_ORDER.phase, children: {} }),
    }),
    units: Object.freeze({
      shape: 'blocks',
      item: Object.freeze({
        shape: 'block',
        fields: FIELD_ORDER.unit,
        children: Object.freeze({
          plans: CANON_LINE_ARRAY(FIELD_ORDER.plan),
          waitsOn: CANON_LINE_ARRAY(FIELD_ORDER.waitsOn),
        }),
      }),
    }),
  }),
});

function formatRegister(data) {
  if (!canonIsPlainObject(data)) throw new Error('canonical-json: register must be an object');
  return `${canonValue(data, CANON_SPEC, '', '')}\n`;
}

function canonIsPlainObject(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

// One scalar (or anything unexpected) in compact JSON; `undefined` inside arrays becomes `null`, as in JSON.
function canonScalar(v) {
  const s = JSON.stringify(v);
  return s === undefined ? 'null' : s;
}

function canonInline(v) {
  if (Array.isArray(v)) return `[${v.map(canonScalar).join(', ')}]`;
  return canonScalar(v);
}

function canonJoinPath(path, key) {
  return path === '' ? key : `${path}.${key}`;
}

// Known fields of `obj` in spec order, with `undefined` values dropped; throws on unknown keys.
function canonEntries(obj, fields, path) {
  for (const key of Object.keys(obj)) {
    if (obj[key] !== undefined && !fields.includes(key)) {
      throw new Error(`canonical-json: unknown field "${canonJoinPath(path, key)}"`);
    }
  }
  return fields.filter((key) => Object.hasOwn(obj, key) && obj[key] !== undefined).map((key) => [key, obj[key]]);
}

function canonValue(value, spec, indent, path) {
  if (!spec) return canonInline(value);
  if (spec.shape === 'block' || spec.shape === 'map') {
    if (!canonIsPlainObject(value)) return canonScalar(value);
    const entries = spec.shape === 'map'
      ? Object.keys(value).filter((k) => value[k] !== undefined).sort().map((k) => [k, value[k]])
      : canonEntries(value, spec.fields, path);
    if (entries.length === 0) return '{}';
    const inner = indent + CANON_INDENT;
    const lines = entries.map(([key, v]) => {
      const child = spec.shape === 'map' ? undefined : spec.children?.[key];
      return `${inner}${JSON.stringify(key)}: ${canonValue(v, child, inner, canonJoinPath(path, key))}`;
    });
    return `{\n${lines.join(',\n')}\n${indent}}`;
  }
  if (spec.shape === 'line') {
    if (!canonIsPlainObject(value)) return canonScalar(value);
    const entries = canonEntries(value, spec.fields, path);
    if (entries.length === 0) return '{}';
    return `{ ${entries.map(([key, v]) => `${JSON.stringify(key)}: ${canonInline(v)}`).join(', ')} }`;
  }
  // `blocks` / `lines`: one element per line (or per block).
  if (!Array.isArray(value)) return canonScalar(value);
  if (value.length === 0) return '[]';
  const inner = indent + CANON_INDENT;
  const items = value.map((item, i) => `${inner}${canonValue(item, spec.item, inner, `${path}[${i}]`)}`);
  return `[\n${items.join(',\n')}\n${indent}]`;
}

// --- core/graph.js ---
// Pure graph helpers over units `{ key, status, dependsOn, after, waitsOn }`.
// An edge `u -> d` means "u comes after d" (d is listed in u.dependsOn or u.after).
// Self-edges are ignored here (V5 reports them); edges to unknown keys are ignored.

function graphList(value) {
  return Array.isArray(value) ? value : [];
}

// Index of the first unit with each key, in array order.
function graphIndexByKey(units) {
  const index = new Map();
  graphList(units).forEach((u, i) => {
    if (u && typeof u.key === 'string' && !index.has(u.key)) index.set(u.key, i);
  });
  return index;
}

// Predecessor keys of a unit: the given fields, known keys only, no self-edges, de-duplicated.
function graphPredecessors(u, fields, index) {
  const out = [];
  for (const field of fields) {
    for (const d of graphList(u[field])) {
      if (d !== u.key && index.has(d) && !out.includes(d)) out.push(d);
    }
  }
  return out;
}

/**
 * Finds cycles by depth-first search in `keys` order. Returns one path per cycle found, closed by
 * repeating its first key (e.g. `[['A', 'B', 'A']]`). Self-loops and edges to unknown keys are ignored.
 *
 * @param {string[]} keys
 * @param {(key: string) => string[]} edgesOf
 * @returns {string[][]}
 */
function findCycles(keys, edgesOf) {
  const known = new Set(keys);
  const state = new Map(); // key -> 1 (on the current path) or 2 (done)
  const path = [];
  const cycles = [];
  const visit = (key) => {
    state.set(key, 1);
    path.push(key);
    const seen = new Set();
    for (const next of graphList(edgesOf(key))) {
      if (next === key || !known.has(next) || seen.has(next)) continue;
      seen.add(next);
      if (state.get(next) === 1) {
        cycles.push([...path.slice(path.indexOf(next)), next]);
      } else if (!state.has(next)) {
        visit(next);
      }
    }
    path.pop();
    state.set(key, 2);
  };
  for (const key of keys) if (!state.has(key)) visit(key);
  return cycles;
}

/**
 * Topological order (Kahn) over `dependsOn` ∪ `after` edges between known keys; among the units whose
 * predecessors are all placed, the one with the smallest array index goes first.
 *
 * @param {object[]} units
 * @returns {string[]}
 * @throws {Error} `Error('cycle')` when the edges contain a cycle.
 */
function topoOrder(units) {
  const list = graphList(units);
  const index = graphIndexByKey(list);
  const pending = new Map(); // key -> number of unplaced predecessors
  const successors = new Map(); // key -> keys that come after it
  for (const [key, i] of index) {
    const preds = graphPredecessors(list[i], ['dependsOn', 'after'], index);
    pending.set(key, preds.length);
    for (const p of preds) {
      if (!successors.has(p)) successors.set(p, []);
      successors.get(p).push(key);
    }
  }
  const order = [];
  const ready = [...pending.keys()].filter((k) => pending.get(k) === 0);
  while (ready.length > 0) {
    let best = 0;
    for (let j = 1; j < ready.length; j++) if (index.get(ready[j]) < index.get(ready[best])) best = j;
    const key = ready.splice(best, 1)[0];
    order.push(key);
    for (const s of successors.get(key) ?? []) {
      pending.set(s, pending.get(s) - 1);
      if (pending.get(s) === 0) ready.push(s);
    }
  }
  if (order.length !== index.size) throw new Error('cycle');
  return order;
}

// Units in topo order (first occurrence of each key).
function graphUnitsInOrder(units) {
  const list = graphList(units);
  const index = graphIndexByKey(list);
  return topoOrder(list).map((key) => list[index.get(key)]);
}

/**
 * Keys of the units that can start now, in topo order: status `Not started`, every `dependsOn` key
 * names a unit with a closed status, and `waitsOn` is empty. An open `after` does not block.
 *
 * @param {object[]} units
 * @returns {string[]}
 */
function readyUnits(units) {
  const list = graphList(units);
  const index = graphIndexByKey(list);
  const isClosed = (key) => index.has(key) && CLOSED_STATUSES.includes(list[index.get(key)].status);
  return graphUnitsInOrder(list)
    .filter((u) => u.status === 'Not started'
      && graphList(u.dependsOn).every(isClosed)
      && graphList(u.waitsOn).length === 0)
    .map((u) => u.key);
}

/**
 * Keys of the units with status `In progress`, in topo order.
 *
 * @param {object[]} units
 * @returns {string[]}
 */
function activeUnits(units) {
  return graphUnitsInOrder(units).filter((u) => u.status === 'In progress').map((u) => u.key);
}

// Compares two chains given as topo-index sequences: longer first, then lexicographically smaller.
function graphChainBetter(a, b) {
  if (a.length !== b.length) return a.length > b.length;
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return a[i] < b[i];
  return false;
}

/**
 * The longest dependency chain over `dependsOn` edges between open (not closed) units, earliest unit
 * first. Ties: the lexicographically smaller sequence of topo indices (from `topoOrder` of all units).
 * `after` is ordering only and does not form chains. Returns `[]` when no unit is open.
 *
 * @param {object[]} units
 * @returns {string[]}
 */
function longestChain(units) {
  const list = graphList(units);
  const order = topoOrder(list);
  const index = graphIndexByKey(list);
  const topoIndex = new Map(order.map((key, i) => [key, i]));
  const open = new Map();
  for (const key of order) {
    const u = list[index.get(key)];
    if (!CLOSED_STATUSES.includes(u.status)) open.set(key, u);
  }
  const bestEnding = new Map(); // key -> best chain (topo indices) ending at that key
  let best = [];
  for (const [key, u] of open) {
    let chain = [];
    for (const d of graphPredecessors(u, ['dependsOn'], open)) {
      const candidate = bestEnding.get(d);
      if (graphChainBetter(candidate, chain)) chain = candidate;
    }
    chain = [...chain, topoIndex.get(key)];
    bestEnding.set(key, chain);
    if (graphChainBetter(chain, best)) best = chain;
  }
  return best.map((i) => order[i]);
}

// --- core/links.js ---
// Repository paths, links from a region file, Markdown table cells and the `**Source:**` line of
// an executable plan (KD-6, KD-11). `cell` and the link rule are ported from the source (legacy rule).

/** The `**Source:**` line of a plan: optional indent, the label, the value. */
const LINK_SOURCE_RE = /^\s*\*\*Source:\*\*\s*(.*)$/;
/** The `**Goal:**` line of a plan. */
const LINK_GOAL_RE = /^\s*\*\*Goal:\*\*/;
/** Any bold header field such as `**Architecture:**`; it ends the Goal paragraph. */
const LINK_FIELD_RE = /^\s*\*\*[^*\n]+:\*\*/;

/**
 * A POSIX path relative to the repository root, normalized (`./`, `//`, `a/../` removed, no
 * trailing slash). Returns null for anything that is not such a path: a non-string or empty
 * value, the root itself, an absolute path (`/x`, `C:/x`), a path that leaves the repository
 * (`../x`), and any path with a backslash (rejected, not converted: data paths are POSIX).
 *
 * @param {unknown} p
 * @returns {string | null}
 */
function normalizePath(p) {
  if (typeof p !== 'string' || p === '' || p.includes('\\')) return null;
  if (p.startsWith('/') || /^[A-Za-z]:/.test(p)) return null;
  const n = posix.normalize(p).replace(/\/+$/, '');
  if (n === '' || n === '.' || n === '..' || n.startsWith('../')) return null;
  return n;
}

/**
 * `true` when `path` is inside `dir`: directly in it (`recursive` false) or at any depth (true).
 * Both are normalized first; a path that does not normalize, or the directory itself, is not inside.
 *
 * @param {string} path
 * @param {string} dir
 * @param {boolean} recursive
 * @returns {boolean}
 */
function inDir(path, dir, recursive) {
  const p = normalizePath(path);
  const d = normalizePath(dir);
  if (p === null || d === null) return false;
  if (recursive) return p.startsWith(`${d}/`);
  return posix.dirname(p) === d;
}

/**
 * The relative Markdown link from the file `fromFile` to the repository path `repoPathWithAnchor`
 * (both repository-relative). Everything after the first `#` is kept as the anchor. A link that
 * does not go up starts with `./`.
 *
 * @param {string} fromFile
 * @param {string} repoPathWithAnchor
 * @returns {string}
 */
function relLink(fromFile, repoPathWithAnchor) {
  const hash = repoPathWithAnchor.indexOf('#');
  const path = hash === -1 ? repoPathWithAnchor : repoPathWithAnchor.slice(0, hash);
  const anchor = hash === -1 ? '' : repoPathWithAnchor.slice(hash);
  const rel = posix.relative(posix.dirname(posix.normalize(fromFile)), posix.normalize(path));
  return `${rel === '..' || rel.startsWith('../') ? rel : `./${rel}`}${anchor}`;
}

/**
 * Escapes a value for a Markdown table cell: pipes are escaped, line breaks become spaces and
 * HTML comment delimiters are turned into entities, so a cell cannot end a region. null and
 * undefined give an empty cell.
 *
 * @param {unknown} text
 * @returns {string}
 */
function cell(text) {
  return String(text ?? '')
    .replace(/\|/g, '\\|')
    .replace(/\r?\n/g, ' ')
    .replace(/<!--/g, '&lt;!--')
    .replace(/-->/g, '--&gt;');
}

/**
 * The first `**Source:**` line outside fenced code: its 0-based line and its value (trailing
 * whitespace dropped). CRLF input is read as LF.
 *
 * @param {string} markdown
 * @returns {{ index: number, text: string } | null}
 */
function extractSource(markdown) {
  const lines = markFences(markdown);
  for (let index = 0; index < lines.length; index++) {
    if (lines[index].fenced) continue;
    const m = LINK_SOURCE_RE.exec(lines[index].text);
    if (m) return { index, text: m[1].trimEnd() };
  }
  return null;
}

/**
 * `true` when a `**Source:**` value names `key` as a token (KD-6), in either form
 * `<doc>#<key>` or a bare key.
 *
 * @param {string} sourceText
 * @param {string} key
 * @returns {boolean}
 */
function sourceNamesKey(sourceText, key) {
  return tokenMatch(sourceText, key);
}

/**
 * The line index after which a missing `**Source:**` line goes (KD-11), and whether it needs blank
 * lines around it: after the `**Goal:**` paragraph (the Goal line and its continuation lines up to
 * a blank line, another bold field, a heading or a fence), else after the first heading (with
 * blank lines), else at the top (-1, with a blank line after it).
 *
 * @param {string} lf
 * @returns {{ after: number, padded: boolean }}
 */
function linkSourceInsertPoint(lf) {
  const lines = markFences(lf);
  const goal = lines.findIndex((l) => !l.fenced && LINK_GOAL_RE.test(l.text));
  if (goal !== -1) {
    const headingLines = new Set(headings(lf).map((h) => h.index));
    let end = goal;
    for (let i = goal + 1; i < lines.length; i++) {
      const l = lines[i];
      if (l.fenced || l.text.trim() === '' || LINK_FIELD_RE.test(l.text) || headingLines.has(i)) break;
      end = i;
    }
    return { after: end, padded: false };
  }
  const first = headings(lf)[0];
  return first ? { after: first.index, padded: true } : { after: -1, padded: true };
}

/**
 * Makes the `**Source:**` line of a plan name `key` (KD-11). A line that already names the key as
 * a token is left alone; another line is replaced by `**Source:** <doc>#<key>` (its indent kept);
 * a missing line is inserted (see the insert point above). CRLF input is read as LF and the text
 * comes back with LF; `changed` tells whether the Source line was rewritten or added.
 *
 * @param {string} markdown
 * @param {{ key: string, doc: string }} target
 * @returns {{ text: string, changed: boolean, before: string | null, after: string }}
 */
function rewriteSource(markdown, { key, doc } = {}) {
  if (typeof key !== 'string' || key === '') throw new TypeError('rewriteSource: key must be a non-empty string');
  if (typeof doc !== 'string' || doc === '') throw new TypeError('rewriteSource: doc must be a non-empty string');
  const lf = markdown.replace(/\r\n/g, '\n');
  const value = `${doc}#${key}`;
  const found = extractSource(lf);
  if (found && sourceNamesKey(found.text, key)) {
    return { text: lf, changed: false, before: found.text, after: found.text };
  }
  const lines = lf.split('\n');
  if (found) {
    const indent = /^\s*/.exec(lines[found.index])[0];
    lines[found.index] = `${indent}**Source:** ${value}`;
    return { text: lines.join('\n'), changed: true, before: found.text, after: value };
  }
  const { after, padded } = linkSourceInsertPoint(lf);
  const add = [`**Source:** ${value}`];
  if (padded) {
    if (after !== -1) add.unshift('');
    const next = lines[after + 1];
    if (next !== undefined && next.trim() !== '') add.push('');
  }
  lines.splice(after + 1, 0, ...add);
  return { text: lines.join('\n'), changed: true, before: null, after: value };
}

// --- core/schema.js ---
// Structure-only checks of a parsed register (no file system): rules V1, V2, V4, V5, V6 and the
// structural part of V3, V7, V9, V10, plus the `config` checks. Every problem is collected in one
// pass and nothing throws, whatever the input. Mirrors the source's `validateWaves` (legacy rule):
// collect all problems, report unknown fields with the allowed list.
//
// Problem = { rule: 'V1'..'V12', where: string, message: string, fix?: string[] }
// `where` labels: `register`, `config`, `config.<path>` (e.g. `config.regions[0]`), `phase "core"`,
// `unit "ST-3"`, `unit "ST-3" plan docs/plans/x.md`, `unit "ST-3" waitsOn[0]`; an element without a
// usable key is labelled by its index (`units[2]`, `phases[0]`).

/** Messages for each value type checked by `svType`. */
const SV_TYPE_MESSAGES = Object.freeze({
  string: 'must be a non-empty string',
  text: 'must be a string',
  strings: 'must be an array of strings',
  names: 'must be an array of non-empty strings',
  array: 'must be an array',
  object: 'must be an object',
  boolean: 'must be true or false',
  posInt: 'must be a positive integer',
  nonNegInt: 'must be a non-negative integer',
});

/** A `{name}` placeholder in an archive template. */
const SV_PLACEHOLDER_RE = /\{([^{}]*)\}/g;

function svIsObj(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

function svIsStr(v) {
  return typeof v === 'string' && v !== '';
}

function svIsType(v, type) {
  switch (type) {
    case 'string': return svIsStr(v);
    case 'text': return typeof v === 'string';
    case 'strings': return Array.isArray(v) && v.every((x) => typeof x === 'string');
    case 'names': return Array.isArray(v) && v.every(svIsStr);
    case 'array': return Array.isArray(v);
    case 'object': return svIsObj(v);
    case 'boolean': return typeof v === 'boolean';
    case 'posInt': return Number.isInteger(v) && v > 0;
    case 'nonNegInt': return Number.isInteger(v) && v >= 0;
    default: return false;
  }
}

function svPush(out, rule, where, message) {
  out.push({ rule, where, message });
}

/** Strings of an array (other items skipped); [] for a non-array. */
function svStrings(v) {
  return Array.isArray(v) ? v.filter((x) => typeof x === 'string') : [];
}

/** `unknown field` problems (V1) for `obj` against FIELD_ORDER[section]. */
function svUnknown(out, where, obj, section) {
  const allowed = FIELD_ORDER[section];
  for (const k of Object.keys(obj)) {
    if (!allowed.includes(k)) svPush(out, 'V1', where, `unknown field ${JSON.stringify(k)} (allowed: ${allowed.join(', ')})`);
  }
}

/**
 * Checks `obj[field]` against a type. A missing field is a problem only when REQUIRED[section]
 * lists it. Returns true when the field is present and valid.
 */
function svType(out, rule, where, obj, field, section, type) {
  const v = obj[field];
  if (v === undefined && !REQUIRED[section].includes(field)) return false;
  if (svIsType(v, type)) return true;
  svPush(out, rule, where, `${JSON.stringify(field)} ${SV_TYPE_MESSAGES[type]}`);
  return false;
}

/** Compiles a pattern: `{ re, full }` (full = whole-string match) or `{ error }`. */
function svCompile(source) {
  try {
    const re = new RegExp(source);
    return { re, full: new RegExp(`^(?:${source})$`) };
  } catch (e) {
    const text = String(e && e.message !== undefined ? e.message : e);
    return { error: text.replace(/^Invalid regular expression: /, '') };
  }
}

/** Label of an array element: `${name}` when it has a usable key, else `${arrayName}[i]`. */
function svLabel(kind, arrayName, item, i) {
  return svIsObj(item) && svIsStr(item.key) ? `${kind} ${JSON.stringify(item.key)}` : `${arrayName}[${i}]`;
}

function svSamePath(a, b) {
  const na = normalizePath(a);
  return na !== null && na === normalizePath(b);
}

function svPlaceholders(out, where, template, allowed) {
  const seen = new Set();
  for (const m of template.matchAll(SV_PLACEHOLDER_RE)) {
    const name = m[1];
    if (allowed.includes(name) || seen.has(name)) continue;
    seen.add(name);
    svPush(out, 'V1', where, `unknown placeholder {${name}} (allowed: ${allowed.join(', ')})`);
  }
}

/** Config checks. Returns what unit checks need: compiled key patterns and whether a gate pattern is missing. */
function svConfig(out, data) {
  const ctx = { patterns: {}, gateMissing: false };
  if (!svType(out, 'V1', 'register', data, 'config', 'root', 'object')) return ctx;
  const c = data.config;
  svUnknown(out, 'config', c, 'config');
  svType(out, 'V1', 'config', c, 'unitName', 'config', 'string');
  svType(out, 'V1', 'config', c, 'unitNamePlural', 'config', 'string');

  if (svType(out, 'V1', 'config', c, 'keyPatterns', 'config', 'object')) {
    const kp = c.keyPatterns;
    svUnknown(out, 'config.keyPatterns', kp, 'keyPatterns');
    for (const kind of KINDS) {
      if (!svType(out, 'V1', 'config.keyPatterns', kp, kind, 'keyPatterns', 'string')) continue;
      const compiled = svCompile(kp[kind]);
      if (compiled.error !== undefined) {
        svPush(out, 'V2', `config.keyPatterns.${kind}`, `invalid regular expression: ${compiled.error}`);
      } else {
        ctx.patterns[kind] = { source: kp[kind], full: compiled.full };
      }
    }
    ctx.gateMissing = kp.gate === undefined;
  }

  const planDirsOk = svType(out, 'V1', 'config', c, 'planDirs', 'config', 'array');
  if (planDirsOk) {
    c.planDirs.forEach((d, i) => {
      if (!svIsObj(d)) return svPush(out, 'V1', 'config', `planDirs[${i}] must be an object`);
      const where = `config.planDirs[${i}]`;
      svUnknown(out, where, d, 'planDir');
      svType(out, 'V1', where, d, 'path', 'planDir', 'string');
      svType(out, 'V1', where, d, 'recursive', 'planDir', 'boolean');
      return undefined;
    });
  }

  if (svType(out, 'V1', 'config', c, 'regions', 'config', 'array')) {
    const pairs = new Set();
    c.regions.forEach((r, i) => {
      if (!svIsObj(r)) return svPush(out, 'V1', 'config', `regions[${i}] must be an object`);
      const where = `config.regions[${i}]`;
      svUnknown(out, where, r, 'region');
      svType(out, 'V1', where, r, 'file', 'region', 'string');
      if (typeof r.marker !== 'string' || !MARKER_RE.test(r.marker)) {
        svPush(out, 'V1', 'config', `${where}.marker must match ${MARKER_RE.source}`);
      }
      if (svType(out, 'V1', where, r, 'views', 'region', 'strings')) {
        for (const v of r.views) {
          if (!VIEWS.includes(v)) svPush(out, 'V1', where, `view ${JSON.stringify(v)} is not one of ${VIEWS.join(', ')}`);
        }
      }
      if (svIsStr(r.file) && typeof r.marker === 'string') {
        const pair = JSON.stringify([normalizePath(r.file) ?? r.file, r.marker]);
        if (pairs.has(pair)) {
          svPush(out, 'V1', where, `file and marker ${JSON.stringify(r.file)}/${JSON.stringify(r.marker)} are used twice`);
        }
        pairs.add(pair);
      }
      return undefined;
    });
  }

  if (svType(out, 'V1', 'config', c, 'todos', 'config', 'object')) {
    const t = c.todos;
    svUnknown(out, 'config.todos', t, 'todos');
    svType(out, 'V1', 'config.todos', t, 'dir', 'todos', 'string');
    svType(out, 'V1', 'config.todos', t, 'archiveDir', 'todos', 'string');
    svType(out, 'V1', 'config.todos', t, 'exclude', 'todos', 'strings');
    if (svType(out, 'V1', 'config.todos', t, 'unhomed', 'todos', 'object')) {
      for (const [path, reason] of Object.entries(t.unhomed)) {
        if (!svIsStr(reason)) svPush(out, 'V9', 'config.todos.unhomed', `reason for ${path} must be a non-empty string`);
      }
    }
  }

  if (svType(out, 'V1', 'config', c, 'decisionLogs', 'config', 'array')) {
    c.decisionLogs.forEach((log, i) => {
      if (!svIsObj(log)) return svPush(out, 'V1', 'config', `decisionLogs[${i}] must be an object`);
      const where = `config.decisionLogs[${i}]`;
      svUnknown(out, where, log, 'decisionLog');
      svType(out, 'V1', where, log, 'path', 'decisionLog', 'string');
      if (svType(out, 'V1', where, log, 'idPattern', 'decisionLog', 'string')) {
        const compiled = svCompile(log.idPattern);
        if (compiled.error !== undefined) svPush(out, 'V10', `${where}.idPattern`, `invalid regular expression: ${compiled.error}`);
      }
      return undefined;
    });
  }

  svType(out, 'V1', 'config', c, 'skipReasonMin', 'config', 'nonNegInt');

  if (svType(out, 'V1', 'config', c, 'archive', 'config', 'object')) {
    const a = c.archive;
    svUnknown(out, 'config.archive', a, 'archive');
    if (svType(out, 'V1', 'config.archive', a, 'dir', 'archive', 'string') && planDirsOk) {
      const covered = c.planDirs.some((d) => svIsObj(d) && svIsStr(d.path)
        && (svSamePath(a.dir, d.path) || (d.recursive === true && inDir(a.dir, d.path, true))));
      if (!covered) {
        svPush(out, 'V1', 'config', `config.archive.dir ${a.dir} must also be covered by config.planDirs so archived plans stay registered`);
      }
    }
    if (svType(out, 'V1', 'config.archive', a, 'banner', 'archive', 'text')) {
      svPlaceholders(out, 'config.archive.banner', a.banner, BANNER_PLACEHOLDERS);
    }
    if (svType(out, 'V1', 'config.archive', a, 'closedBy', 'archive', 'text')) {
      svPlaceholders(out, 'config.archive.closedBy', a.closedBy, CLOSED_BY_PLACEHOLDERS);
    }
  }

  svType(out, 'V1', 'config', c, 'guidelinesFile', 'config', 'string');
  return ctx;
}

/**
 * Phase checks. Returns `{ ok, keys: Set<key>, names: Map<key | alias, key> }`; `ok` is false when
 * `phases` is present but not an array (unit phases are then not checked).
 */
function svPhases(out, data) {
  const keys = new Set();
  const names = new Map(); // key or alias -> { index, key, label }
  if (!svType(out, 'V1', 'register', data, 'phases', 'root', 'array')) {
    return { ok: data.phases === undefined, keys, names: new Map() };
  }
  data.phases.forEach((p, i) => {
    if (!svIsObj(p)) return svPush(out, 'V1', 'register', `phases[${i}] must be an object`);
    const where = svLabel('phase', 'phases', p, i);
    svUnknown(out, where, p, 'phase');
    if (!svIsStr(p.key) || !PHASE_KEY_RE.test(p.key)) {
      svPush(out, 'V2', where, '"key" must be a lowercase name such as "core"');
    } else {
      keys.add(p.key);
    }
    svType(out, 'V1', where, p, 'title', 'phase', 'string');
    svType(out, 'V1', where, p, 'aliases', 'phase', 'names');
    svType(out, 'V1', where, p, 'roadmap', 'phase', 'string');
    const own = new Set([p.key, ...svStrings(p.aliases)].filter(svIsStr));
    for (const name of own) {
      const owner = names.get(name);
      if (owner !== undefined && owner.index !== i && name === p.key && owner.key === p.key) {
        svPush(out, 'V2', where, `key ${JSON.stringify(name)} is used by more than one phase (phases[${owner.index}], phases[${i}])`);
      } else if (owner !== undefined && owner.index !== i) {
        svPush(out, 'V2', where, `key or alias ${JSON.stringify(name)} is already used by ${owner.label}`);
      } else if (owner === undefined) {
        names.set(name, { index: i, key: p.key, label: where });
      }
    }
    return undefined;
  });
  const byName = new Map();
  for (const [name, owner] of names) if (svIsStr(owner.key)) byName.set(name, owner.key);
  return { ok: true, keys, names: byName };
}

/** Plan entries of one unit (V7 structure, V1 unknown fields) and duplicate registrations. */
function svPlans(out, u, where, registry) {
  if (!svType(out, 'V1', where, u, 'plans', 'unit', 'array')) return;
  u.plans.forEach((p, j) => {
    if (!svIsObj(p)) return svPush(out, 'V7', where, `plans[${j}] must be an object`);
    const planWhere = svIsStr(p.path) ? `${where} plan ${p.path}` : where;
    svUnknown(out, planWhere, p, 'plan');
    if (!svIsStr(p.path)) return svPush(out, 'V7', where, 'plan entry needs a non-empty "path"');
    if (!p.path.endsWith('.md')) svPush(out, 'V7', where, `plan ${p.path} must be a .md file`);
    if (p.role === undefined) {
      svPush(out, 'V7', planWhere, `"role" must be one of ${ROLES.join(', ')}`);
    } else if (!ROLES.includes(p.role)) {
      svPush(out, 'V7', planWhere, `role ${JSON.stringify(p.role)} is not one of ${ROLES.join(', ')}`);
    }
    const sectionOk = p.section === undefined || svIsStr(p.section);
    if (!sectionOk) svPush(out, 'V7', planWhere, '"section" must be a non-empty string when present');
    svType(out, 'V1', planWhere, p, 'scope', 'plan', 'text');
    if (!sectionOk) return undefined;
    const path = normalizePath(p.path) ?? p.path;
    if (!registry.has(path)) registry.set(path, { whole: null, sections: new Map() });
    const entry = registry.get(path);
    if (entry.whole !== null) {
      svPush(out, 'V7', where, `plan ${path} is registered for ${entry.whole} as a whole file and cannot be registered again`);
    } else if (p.section === undefined) {
      if (entry.sections.size > 0) {
        const first = entry.sections.values().next().value;
        svPush(out, 'V7', where, `plan ${path} is already registered by section for ${first} and cannot be registered as a whole file`);
      } else {
        entry.whole = where;
      }
    } else if (entry.sections.has(p.section)) {
      svPush(out, 'V7', where, `plan ${path} (section ${JSON.stringify(p.section)}) is already registered for ${entry.sections.get(p.section)}`);
    } else {
      entry.sections.set(p.section, where);
    }
    return undefined;
  });
}

/** `waitsOn` entries of one unit. */
function svWaitsOn(out, u, where) {
  if (!svType(out, 'V1', where, u, 'waitsOn', 'unit', 'array')) return;
  u.waitsOn.forEach((w, j) => {
    if (!svIsObj(w)) return svPush(out, 'V1', where, `waitsOn[${j}] must be an object`);
    const ww = `${where} waitsOn[${j}]`;
    svUnknown(out, ww, w, 'waitsOn');
    if (w.kind === undefined) {
      svPush(out, 'V1', ww, `"kind" must be one of ${WAITS_KINDS.join(', ')}`);
    } else if (!WAITS_KINDS.includes(w.kind)) {
      svPush(out, 'V1', ww, `kind ${JSON.stringify(w.kind)} is not one of ${WAITS_KINDS.join(', ')}`);
    }
    svType(out, 'V1', ww, w, 'ref', 'waitsOn', 'string');
    svType(out, 'V1', ww, w, 'note', 'waitsOn', 'text');
    return undefined;
  });
}

/** Per-unit structure (pass 1). */
function svUnit(out, u, i, ctx) {
  const where = svLabel('unit', 'units', u, i);
  svUnknown(out, where, u, 'unit');

  const kindOk = u.kind === undefined || KINDS.includes(u.kind);
  const kind = u.kind === undefined ? KINDS[0] : u.kind;
  if (!svIsStr(u.key)) {
    svPush(out, 'V1', where, '"key" must be a non-empty string');
  } else if (kindOk) {
    const pattern = ctx.patterns[kind];
    if (kind === 'gate' && ctx.gateMissing) {
      svPush(out, 'V2', where, 'kind "gate" needs config.keyPatterns.gate');
    } else if (pattern && !pattern.full.test(u.key)) {
      svPush(out, 'V2', where, `key ${JSON.stringify(u.key)} does not match config.keyPatterns.${kind} ${pattern.source}`);
    }
  }
  if (!kindOk) svPush(out, 'V1', where, `kind ${JSON.stringify(u.kind)} is not one of ${KINDS.join(', ')}`);
  svType(out, 'V1', where, u, 'aliases', 'unit', 'names');

  // V2: unit keys and aliases share one namespace.
  for (const name of new Set([u.key, ...svStrings(u.aliases)].filter(svIsStr))) {
    const owner = ctx.unitNames.get(name);
    if (owner === undefined) ctx.unitNames.set(name, { index: i, key: u.key, label: where });
    else if (owner.index !== i && name === u.key && owner.key === u.key) {
      svPush(out, 'V2', where, `key ${JSON.stringify(name)} is used by more than one unit (units[${owner.index}], units[${i}])`);
    } else if (owner.index !== i) svPush(out, 'V2', where, `key or alias ${JSON.stringify(name)} is already used by ${owner.label}`);
  }

  if (u.phase !== undefined) {
    if (!svIsStr(u.phase)) {
      svPush(out, 'V1', where, '"phase" must be a non-empty string');
    } else if (ctx.phases.ok && !ctx.phases.keys.has(u.phase)) {
      const owner = ctx.phases.names.get(u.phase);
      const known = ctx.phases.keys.size > 0 ? [...ctx.phases.keys].join(', ') : 'none';
      svPush(out, 'V3', where, `unknown phase ${JSON.stringify(u.phase)}${owner !== undefined
        ? ` (that is an alias; use the key ${JSON.stringify(owner)})`
        : ` (known: ${known})`}`);
    }
  }

  svType(out, 'V1', where, u, 'title', 'unit', 'string');

  const statusOk = STATUSES.includes(u.status);
  if (u.status === undefined) {
    svPush(out, 'V1', where, `"status" must be one of ${STATUSES.join(', ')}`);
  } else if (!statusOk) {
    svPush(out, 'V4', where, `status ${JSON.stringify(u.status)} is not one of ${STATUSES.join(', ')}`);
  }

  if (u.pr !== undefined) {
    if (!svIsType(u.pr, 'posInt')) svPush(out, 'V1', where, '"pr" must be a positive integer');
    else if (kind === 'gate') svPush(out, 'V4', where, 'a gate has no PR; remove "pr"');
    else if (statusOk && u.status !== 'In progress') svPush(out, 'V4', where, '"pr" is only allowed while "In progress"');
  }
  if (u.owner !== undefined && !svIsStr(u.owner)) svPush(out, 'V4', where, '"owner" must be a non-empty string');

  svType(out, 'V1', where, u, 'dependsOn', 'unit', 'strings');
  svType(out, 'V1', where, u, 'after', 'unit', 'strings');
  svWaitsOn(out, u, where);
  svPlans(out, u, where, ctx.plans);

  if (u.todos !== undefined) {
    if (!svIsType(u.todos, 'names')) svPush(out, 'V9', where, '"todos" must be an array of non-empty strings');
    for (const t of svStrings(u.todos).filter(svIsStr)) {
      const path = normalizePath(t) ?? t;
      const home = ctx.todos.get(path);
      if (home === undefined) ctx.todos.set(path, where);
      else svPush(out, 'V9', where, `TODO ${path} is already homed in ${home}`);
    }
  }
  if (u.decisions !== undefined && !svIsType(u.decisions, 'strings')) {
    svPush(out, 'V10', where, '"decisions" must be an array of strings');
  }

  if (statusOk) {
    if (CLOSED_STATUSES.includes(u.status)) {
      if (!svIsStr(u.closedBy)) svPush(out, 'V4', where, `status ${JSON.stringify(u.status)} needs a non-empty "closedBy"`);
    } else if (u.closedBy !== undefined) {
      svPush(out, 'V4', where, `"closedBy" is only allowed for ${CLOSED_STATUSES.join(' or ')}`);
    }
  }
}

/** References between units (pass 2): V5 unknown / alias / self, V6 closed depends on open. */
function svReferences(out, units, index) {
  units.forEach((u, i) => {
    if (!svIsObj(u)) return;
    const where = svLabel('unit', 'units', u, i);
    const seen = new Set();
    const push = (rule, message) => {
      if (seen.has(message)) return;
      seen.add(message);
      svPush(out, rule, where, message);
    };
    for (const field of ['dependsOn', 'after']) {
      for (const dep of svStrings(u[field])) {
        if (svIsStr(u.key) && dep === u.key) {
          push('V5', 'depends on itself');
        } else if (!index.byKey.has(dep)) {
          const key = index.byName.get(dep);
          if (key !== undefined) push('V5', `depends on ${JSON.stringify(dep)}, which is an alias; use the key ${JSON.stringify(key)}`);
          else push('V5', `depends on unknown unit ${JSON.stringify(dep)}`);
        } else if (field === 'dependsOn' && CLOSED_STATUSES.includes(u.status)) {
          const status = index.byKey.get(dep).status;
          if (STATUSES.includes(status) && !CLOSED_STATUSES.includes(status)) {
            push('V6', `is ${u.status} but depends on ${JSON.stringify(dep)}, which is ${status}`);
          }
        }
      }
    }
  });
}

function svValidate(out, data) {
  if (!svIsObj(data)) return svPush(out, 'V1', 'register', 'the register must be a JSON object');
  if (data.schema === undefined) {
    return svPush(out, 'V1', 'register', `"schema" is missing; plan-register ${VERSION} supports ${SUPPORTED_SCHEMAS.join(', ')}`);
  }
  if (!SUPPORTED_SCHEMAS.includes(data.schema)) {
    return svPush(out, 'V1', 'register', `schema ${JSON.stringify(data.schema)} is not supported by plan-register ${VERSION} `
      + `(supports ${SUPPORTED_SCHEMAS.join(', ')}); update the vendored copy with "plan-register vendor"`);
  }
  svUnknown(out, 'register', data, 'root');
  svType(out, 'V1', 'register', data, '$schema', 'root', 'text');
  svType(out, 'V1', 'register', data, '$comment', 'root', 'text');
  const ctx = svConfig(out, data);
  ctx.phases = svPhases(out, data);
  ctx.unitNames = new Map();
  ctx.plans = new Map();
  ctx.todos = new Map();
  if (!svType(out, 'V1', 'register', data, 'units', 'root', 'array')) return undefined;
  data.units.forEach((u, i) => {
    if (!svIsObj(u)) svPush(out, 'V1', 'register', `units[${i}] must be an object`);
    else svUnit(out, u, i, ctx);
  });
  const index = unitIndex(data);
  svReferences(out, data.units, index);
  const edgesOf = (key) => {
    const u = index.byKey.get(key);
    return [...svStrings(u.dependsOn), ...svStrings(u.after)];
  };
  for (const cycle of findCycles([...index.byKey.keys()], edgesOf)) {
    svPush(out, 'V5', 'register', `dependency cycle: ${cycle.join(' -> ')}`);
  }
  return undefined;
}

/**
 * Structure-only problems of a parsed register, all at once; never throws. An unsupported or
 * missing `schema` gives exactly one V1 problem and nothing else is checked.
 *
 * @param {unknown} data
 * @returns {{ rule: string, where: string, message: string, fix?: string[] }[]}
 */
function validateStructure(data) {
  const out = [];
  try {
    svValidate(out, data);
  } catch (e) {
    svPush(out, 'V1', 'register', `internal error while checking the register: ${e && e.message !== undefined ? e.message : e}`);
  }
  return out;
}

/**
 * Index of units: `byKey` maps each key (first occurrence) to its unit; `byName` maps each key and
 * each alias of such a unit to the key (a key wins over an alias; the first alias wins). Tolerant
 * of any input.
 *
 * @param {unknown} data
 * @returns {{ byKey: Map<string, object>, byName: Map<string, string> }}
 */
function unitIndex(data) {
  const byKey = new Map();
  const byName = new Map();
  const units = svIsObj(data) && Array.isArray(data.units) ? data.units : [];
  for (const u of units) {
    if (svIsObj(u) && svIsStr(u.key) && !byKey.has(u.key)) {
      byKey.set(u.key, u);
      byName.set(u.key, u.key);
    }
  }
  for (const [key, u] of byKey) {
    for (const alias of svStrings(u.aliases)) {
      if (alias !== '' && !byName.has(alias)) byName.set(alias, key);
    }
  }
  return { byKey, byName };
}

/**
 * Resolves a unit key or alias to its key.
 *
 * @param {unknown} data
 * @param {unknown} name
 * @returns {{ key: string, viaAlias: boolean } | null}
 */
function resolveKey(data, name) {
  if (typeof name !== 'string') return null;
  const { byKey, byName } = unitIndex(data);
  if (byKey.has(name)) return { key: name, viaAlias: false };
  const key = byName.get(name);
  return key === undefined ? null : { key, viaAlias: true };
}

/**
 * One line for a problem: `[V5] unit "ST-3": depends on itself`.
 *
 * @param {{ rule: string, where: string, message: string }} p
 * @returns {string}
 */
function problemText(p) {
  return `[${p.rule}] ${p.where}: ${p.message}`;
}

// --- core/conflicts.js ---
// Rule V13: unresolved git conflict markers. One detector for every file the register reads (the
// register itself, plans and briefs, TODO notes, decision logs, roadmaps, region files) and, in
// `tickets check`, for the tickets config and every `ticket.md`.
//
// The exact rule: lines are split on LF (CRLF read as LF) and matched at column 0, fenced code
// included (a conflict inside a code snippet of a plan is still a conflict).
// - `<<<<<<<`, `|||||||` or `>>>>>>>` (exactly seven characters) alone on the line or followed by a
//   space is a marker line; one such line is enough for the file to have conflict markers;
// - `=======` as the whole line is a separator; it is reported only in a file that has one of the
//   other three, so a setext heading underline alone is never a conflict.
// Indented lines, longer runs (`<<<<<<<<`) and `=======` with any other text are not markers; an
// example of a conflict in a document is therefore written indented by at least one space. Conflicts
// written with a non-default `conflict-marker-size` gitattribute are not detected (deliberately).

/** The marker kinds that make a file conflicted on their own (alone or followed by a space). */
const CONFLICT_OPENERS = Object.freeze(['<<<<<<<', '|||||||', '>>>>>>>']);
const CONFLICT_SEPARATOR = '=======';
/** At most this many lines are listed in a message; the rest are counted. */
const CONFLICT_LIST_MAX = 10;

/**
 * The conflict-marker lines of a text, or [] when it has none (see the rule above).
 *
 * @param {string} text
 * @returns {{ line: number, marker: string }[]} line is 1-based; marker is the seven characters
 */
function conflictMarkers(text) {
  if (typeof text !== 'string') return [];
  const found = [];
  let conflicted = false;
  text.split('\n').forEach((raw, i) => {
    const line = raw.endsWith('\r') ? raw.slice(0, -1) : raw;
    if (line === CONFLICT_SEPARATOR) {
      found.push({ line: i + 1, marker: CONFLICT_SEPARATOR });
      return;
    }
    const head = line.slice(0, 7);
    if (CONFLICT_OPENERS.includes(head) && (line.length === 7 || line[7] === ' ')) {
      found.push({ line: i + 1, marker: head });
      conflicted = true;
    }
  });
  return conflicted ? found : [];
}

/**
 * The V13 message for the marker lines of one file: up to ten lines with their marker, then a count.
 *
 * @param {{ line: number, marker: string }[]} markers non-empty
 * @param {string} [note] appended after the fix hint (`; <note>`)
 * @returns {string}
 */
function conflictMessage(markers, note) {
  const listed = markers.slice(0, CONFLICT_LIST_MAX).map((m) => `line ${m.line} (${m.marker})`).join(', ');
  const more = markers.length > CONFLICT_LIST_MAX ? ` and ${markers.length - CONFLICT_LIST_MAX} more` : '';
  const tail = typeof note === 'string' && note !== '' ? `; ${note}` : '';
  return `unresolved git conflict markers at ${listed}${more}; resolve the conflict and remove the marker lines${tail}`;
}

/**
 * The V13 problem of one file, or null when its text has no conflict markers.
 *
 * @param {string} where the repository path of the file
 * @param {string | null} text
 * @param {string} [note]
 * @returns {{ rule: 'V13', where: string, message: string } | null}
 */
function conflictProblem(where, text, note) {
  const markers = conflictMarkers(text);
  return markers.length === 0 ? null : { rule: 'V13', where, message: conflictMessage(markers, note) };
}

// --- core/repo-checks.js ---
// Checks that need the files of the repository: V3 (roadmap file and anchor), V7 (plan file,
// directory, section), V9 (TODO files, open TODOs without a home, stale `unhomed` entries), V10
// (decision logs and decision ids), V11 (the `**Source:**` line of plans) and V13 (git conflict
// markers in every file these checks, the progress count, the scope brief and the regions read).
//
// All file access goes through a view of the repository (`createFsView`): repository-relative POSIX
// paths, sorted listings, CRLF read as LF, and paths that leave the root are treated as missing.
// The checks assume `validateStructure` ran, but they skip any malformed entry and never throw.
// Plan directories and path normalization port legacy tests 19 and 20, with `recursive` honoured.

function rcIsObj(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

function rcIsStr(v) {
  return typeof v === 'string' && v !== '';
}

function rcArr(v) {
  return Array.isArray(v) ? v : [];
}

/** A path for messages and comparisons: normalized when possible, else as given. */
function rcPath(p) {
  return normalizePath(p) ?? p;
}

function rcPush(out, rule, where, message, fix) {
  const p = { rule, where, message };
  if (fix !== undefined) p.fix = fix;
  out.push(p);
}

/** Whole-string matcher of a pattern source, or null when it does not compile. */
function rcFull(source) {
  if (typeof source !== 'string') return null;
  try {
    return new RegExp(`^(?:${source})$`);
  } catch {
    return null;
  }
}

/**
 * A read-only view of the repository at `root`. Every path is repository-relative POSIX and is
 * normalized first; a path that does not normalize (absolute, leaving the root, with a backslash)
 * does not exist, reads as null and lists as [].
 *
 * @param {string} root
 * @returns {{ exists(p: string): boolean, isFile(p: string): boolean, readText(p: string): string | null,
 *   listMd(dir: string, recursive?: boolean): string[] }}
 */
function createFsView(root) {
  const base = resolve(root);
  const abs = (p) => {
    const n = normalizePath(p);
    return n === null ? null : join(base, ...n.split('/'));
  };
  const statOf = (p) => {
    const a = abs(p);
    if (a === null) return null;
    try {
      return statSync(a);
    } catch {
      return null;
    }
  };
  const walk = (dir, recursive, out) => {
    let entries;
    try {
      entries = readdirSync(join(base, ...dir.split('/')), { withFileTypes: true });
    } catch {
      return;
    }
    for (const e of entries) {
      const rel = `${dir}/${e.name}`;
      if (e.isDirectory()) {
        if (recursive) walk(rel, recursive, out);
      } else if (e.name.endsWith('.md') && (e.isFile() || (e.isSymbolicLink() && statOf(rel)?.isFile()))) {
        out.push(rel);
      }
    }
  };
  return {
    exists(p) {
      const a = abs(p);
      return a !== null && existsSync(a);
    },
    isFile(p) {
      const s = statOf(p);
      return s !== null && s.isFile();
    },
    readText(p) {
      const a = abs(p);
      if (a === null) return null;
      try {
        return readFileSync(a, 'utf8').replace(/\r\n/g, '\n');
      } catch {
        return null;
      }
    },
    listMd(dir, recursive = false) {
      const d = normalizePath(dir);
      if (d === null) return [];
      const out = [];
      walk(d, recursive === true, out);
      return out.sort();
    },
  };
}

/** `config.todos` fields that are usable: `{ dir, archiveDir, exclude, unhomed }` (missing ones null). */
function rcTodosConfig(data) {
  const t = rcIsObj(data) && rcIsObj(data.config) && rcIsObj(data.config.todos) ? data.config.todos : null;
  if (t === null) return null;
  const dir = rcIsStr(t.dir) ? normalizePath(t.dir) : null;
  const archiveDir = rcIsStr(t.archiveDir) ? normalizePath(t.archiveDir) : null;
  const exclude = Array.isArray(t.exclude) ? t.exclude.filter((x) => typeof x === 'string') : [...DEFAULTS.todosExclude];
  const unhomed = rcIsObj(t.unhomed) ? t.unhomed : {};
  return { dir, archiveDir, exclude, unhomed };
}

/**
 * Whether `path` (a repository path) names a file that `config.todos.exclude` (default
 * `DEFAULTS.todosExclude`) keeps out of the open TODOs: a name in the list, directly in `todos.dir`
 * (the same match as openTodos). False when `config.todos` or its `dir` is not configured.
 *
 * @param {unknown} data
 * @param {string} path
 * @returns {boolean}
 */
function todoExcluded(data, path) {
  const t = rcTodosConfig(data);
  const p = typeof path === 'string' ? normalizePath(path) : null;
  if (t === null || t.dir === null || p === null || !p.startsWith(`${t.dir}/`)) return false;
  const name = p.slice(t.dir.length + 1);
  return !name.includes('/') && t.exclude.includes(name);
}

/**
 * The open TODOs (KD-4): `*.md` files directly in `config.todos.dir`, except the names in
 * `config.todos.exclude` (default `DEFAULTS.todosExclude`). Sorted repository paths; [] when the
 * directory is not configured or does not exist.
 *
 * @param {unknown} data
 * @param {ReturnType<typeof createFsView>} fsv
 * @returns {string[]}
 */
function openTodos(data, fsv) {
  const t = rcTodosConfig(data);
  if (t === null || t.dir === null) return [];
  return fsv.listMd(t.dir, false).filter((p) => !t.exclude.includes(p.slice(t.dir.length + 1)));
}

/** Usable decision logs: `{ index, path, full }` (path normalized, full = whole-match regex). */
function rcDecisionLogs(data) {
  const logs = rcIsObj(data) && rcIsObj(data.config) ? rcArr(data.config.decisionLogs) : [];
  const out = [];
  logs.forEach((log, index) => {
    if (!rcIsObj(log) || !rcIsStr(log.path)) return;
    const full = rcFull(log.idPattern);
    if (full === null) return;
    out.push({ index, path: rcPath(log.path), full });
  });
  return out;
}

/**
 * The decisions of the configured logs: a heading whose first token (`headingId`) fully matches the
 * log's `idPattern` defines that id. The first definition wins (logs in config order, headings in
 * file order). `heading` is the heading text without the level marks, `line` is 1-based.
 *
 * @param {unknown} data
 * @param {ReturnType<typeof createFsView>} fsv
 * @returns {Map<string, { log: string, heading: string, line: number }>}
 */
function decisionIndex(data, fsv) {
  const index = new Map();
  for (const log of rcDecisionLogs(data)) {
    const text = fsv.readText(log.path);
    if (text === null) continue;
    for (const h of headings(text)) {
      const id = headingId(h.text);
      if (id === null || !log.full.test(id) || index.has(id)) continue;
      index.set(id, { log: log.path, heading: h.text, line: h.index + 1 });
    }
  }
  return index;
}

/** Usable plan directories: `{ path, recursive }` with the path normalized. */
function rcPlanDirs(data) {
  const dirs = rcIsObj(data) && rcIsObj(data.config) ? rcArr(data.config.planDirs) : [];
  return dirs
    .filter((d) => rcIsObj(d) && rcIsStr(d.path) && normalizePath(d.path) !== null)
    .map((d) => ({ path: normalizePath(d.path), recursive: d.recursive === true }));
}

function rcUnits(data) {
  return rcIsObj(data) ? rcArr(data.units).filter((u) => rcIsObj(u) && rcIsStr(u.key)) : [];
}

/** V3: each phase roadmap file exists and its anchor (when present) matches a heading. */
function rcRoadmaps(out, data, fsv) {
  const phases = rcIsObj(data) ? rcArr(data.phases) : [];
  for (const p of phases) {
    if (!rcIsObj(p) || !rcIsStr(p.key) || !rcIsStr(p.roadmap)) continue;
    const where = `phase ${JSON.stringify(p.key)}`;
    const hash = p.roadmap.indexOf('#');
    const file = rcPath(hash === -1 ? p.roadmap : p.roadmap.slice(0, hash));
    const anchor = hash === -1 ? '' : p.roadmap.slice(hash + 1);
    const text = fsv.isFile(file) ? fsv.readText(file) : null;
    if (text === null) {
      rcPush(out, 'V3', where, `roadmap file ${file} does not exist`);
    } else if (anchor !== '' && !headingAnchors(text).has(anchor)) {
      rcPush(out, 'V3', where, `roadmap anchor #${anchor} matches no heading in ${file}`);
    }
  }
}

/** V10: each configured decision log exists. */
function rcLogFiles(out, data, fsv) {
  const logs = rcIsObj(data) && rcIsObj(data.config) ? rcArr(data.config.decisionLogs) : [];
  logs.forEach((log, i) => {
    if (!rcIsObj(log) || !rcIsStr(log.path)) return;
    const path = rcPath(log.path);
    if (!fsv.isFile(path)) rcPush(out, 'V10', `config.decisionLogs[${i}]`, `${path} does not exist`);
  });
}

/** `docs/plans/ (top level) or docs/archived/plans/ (any depth)` */
function rcDirsText(dirs) {
  return dirs.map((d) => `${d.path}/ (${d.recursive ? 'any depth' : 'top level'})`).join(' or ');
}

/** V7 for one plan entry of a unit: file, directory (except `scope`), section. */
function rcPlan(out, where, plan, dirs, fsv) {
  const path = rcPath(plan.path);
  if (plan.role !== 'scope' && !dirs.some((d) => inDir(path, d.path, d.recursive))) {
    const allowed = dirs.length > 0 ? rcDirsText(dirs) : 'one of config.planDirs (none configured)';
    rcPush(out, 'V7', where, `plan ${path} must be in ${allowed}`);
  }
  const text = fsv.isFile(path) ? fsv.readText(path) : null;
  if (text === null) {
    rcPush(out, 'V7', where, `plan ${path} does not exist`);
    return null;
  }
  if (rcIsStr(plan.section)) {
    const r = findSection(text, plan.section);
    const section = JSON.stringify(plan.section);
    if (!r.ok && r.reason === 'none') {
      rcPush(out, 'V7', where, `section ${section} matches no heading in ${path}`);
    } else if (!r.ok) {
      const lines = r.matches.map((h) => h.index + 1).join(', ');
      rcPush(out, 'V7', where, `section ${section} matches ${r.matches.length} headings in ${path}: lines ${lines}; make it unique`);
    }
  }
  return text;
}

/** V11(a): an executable plan names the unit key in its `**Source:**` line. */
function rcExecutableSource(out, where, key, path, text) {
  const src = extractSource(text);
  if (src === null) {
    rcPush(out, 'V11', where, `executable plan ${path} has no **Source:** line; run add-plan again or add "**Source:** <doc>#${key}"`);
  } else if (!sourceNamesKey(src.text, key)) {
    rcPush(out, 'V11', where, `executable plan ${path}: **Source:** does not name ${JSON.stringify(key)} as a separate token`);
  }
}

/** V9 for the TODOs of one unit: file exists and lies directly in `dir` or anywhere in `archiveDir`. */
function rcUnitTodos(out, where, unit, todos, fsv) {
  for (const t of rcArr(unit.todos)) {
    if (!rcIsStr(t)) continue;
    const path = rcPath(t);
    if (!fsv.isFile(path)) rcPush(out, 'V9', where, `TODO ${path} does not exist`);
    if (todos === null || todos.dir === null || todos.archiveDir === null) continue;
    if (!inDir(path, todos.dir, false) && !inDir(path, todos.archiveDir, true)) {
      rcPush(out, 'V9', where, `TODO ${path} must be directly in ${todos.dir}/ or anywhere in ${todos.archiveDir}/`);
    }
  }
}

/** V10 for one unit: `decisions` ids and `waitsOn` decisions whose ref matches some idPattern. */
function rcUnitDecisions(out, where, unit, logs, index) {
  const known = (id) => logs.some((l) => l.full.test(id));
  for (const id of rcArr(unit.decisions)) {
    if (typeof id !== 'string') continue;
    if (!known(id)) rcPush(out, 'V10', where, `decision ${JSON.stringify(id)} matches no configured idPattern`);
    else if (!index.has(id)) rcPush(out, 'V10', where, `decision ${JSON.stringify(id)} is not a heading in any configured decision log`);
  }
  rcArr(unit.waitsOn).forEach((w, j) => {
    if (!rcIsObj(w) || w.kind !== 'decision' || !rcIsStr(w.ref) || !known(w.ref) || index.has(w.ref)) return;
    rcPush(out, 'V10', `${where} waitsOn[${j}]`, `decision ${JSON.stringify(w.ref)} is not a heading in any configured decision log`);
  });
}

/** V9: open TODOs without a home, and `unhomed` entries that are missing, archived or homed. */
function rcTodoHomes(out, data, fsv, todos, homes) {
  if (todos === null) return;
  const unhomed = Object.keys(todos.unhomed).map(rcPath);
  for (const path of openTodos(data, fsv)) {
    if (homes.has(path) || unhomed.includes(path)) continue;
    rcPush(out, 'V9', path, `open TODO has no home; run home-todo ${path} <key>, or list it in config.todos.unhomed with a reason`);
  }
  for (const path of unhomed) {
    const where = 'config.todos.unhomed';
    if (!fsv.isFile(path)) rcPush(out, 'V9', where, `${path} does not exist`);
    else if (todos.archiveDir !== null && inDir(path, todos.archiveDir, true)) rcPush(out, 'V9', where, `${path} is archived; remove it from unhomed`);
    else if (homes.has(path)) rcPush(out, 'V9', where, `${path} is homed in unit ${JSON.stringify(homes.get(path))}; remove it from unhomed`);
  }
}

/**
 * V11(b): an active plan (a `.md` in `planDirs`, not in `archive.dir`) whose `**Source:**` names
 * unit keys (as tokens) must be registered for at least one of them. The `fix` is given only when
 * exactly one key is named and the plan is not registered for any other unit.
 */
function rcUnregisteredPlans(out, data, fsv, dirs, units) {
  const archive = rcIsObj(data.config) && rcIsObj(data.config.archive) && rcIsStr(data.config.archive.dir)
    ? normalizePath(data.config.archive.dir) : null;
  const registered = new Map(); // path -> Set<key>
  for (const u of units) {
    for (const p of rcArr(u.plans)) {
      if (!rcIsObj(p) || !rcIsStr(p.path)) continue;
      const path = rcPath(p.path);
      if (!registered.has(path)) registered.set(path, new Set());
      registered.get(path).add(u.key);
    }
  }
  const keys = [...new Set(units.map((u) => u.key))];
  const active = new Set();
  for (const d of dirs) {
    for (const path of fsv.listMd(d.path, d.recursive)) {
      if (archive === null || !inDir(path, archive, true)) active.add(path);
    }
  }
  for (const path of [...active].sort()) {
    const text = fsv.readText(path);
    const src = text === null ? null : extractSource(text);
    if (src === null) continue;
    const named = keys.filter((k) => sourceNamesKey(src.text, k));
    if (named.length === 0) continue;
    const own = registered.get(path) ?? new Set();
    if (named.some((k) => own.has(k))) continue;
    const list = named.map((k) => JSON.stringify(k));
    if (named.length === 1) {
      const fix = own.size === 0 ? ['add-plan', named[0], path, '--role', 'executable', '--write'] : undefined;
      rcPush(out, 'V11', path, `**Source:** names ${list[0]} but the plan is not registered for it`, fix);
    } else {
      rcPush(out, 'V11', path, `**Source:** names ${list.join(', ')} but the plan is not registered for any of them`);
    }
  }
}

function rcCheck(out, data, fsv) {
  if (!rcIsObj(data)) return;
  const dirs = rcPlanDirs(data);
  const todos = rcTodosConfig(data);
  const logs = rcDecisionLogs(data);
  const index = decisionIndex(data, fsv);
  const units = rcUnits(data);
  rcRoadmaps(out, data, fsv);
  rcLogFiles(out, data, fsv);
  const homes = new Map(); // TODO path -> first unit key
  for (const u of units) {
    const where = `unit ${JSON.stringify(u.key)}`;
    for (const plan of rcArr(u.plans)) {
      if (!rcIsObj(plan) || !rcIsStr(plan.path)) continue;
      const text = rcPlan(out, where, plan, dirs, fsv);
      if (text !== null && plan.role === 'executable') rcExecutableSource(out, where, u.key, rcPath(plan.path), text);
    }
    rcUnitTodos(out, where, u, todos, fsv);
    for (const t of rcArr(u.todos)) if (rcIsStr(t) && !homes.has(rcPath(t))) homes.set(rcPath(t), u.key);
    rcUnitDecisions(out, where, u, logs, index);
  }
  rcTodoHomes(out, data, fsv, todos, homes);
  rcUnregisteredPlans(out, data, fsv, dirs, units);
  rcConflicts(out, data, fsv, dirs, todos, units);
}

/**
 * V13: the files the register reads, each once, in path order: the region files, the decision logs,
 * the phase roadmaps, every registered plan (any role, archived ones included), every TODO a unit
 * homes, the open TODOs, the `unhomed` notes and the active `.md` files of `planDirs`. A missing
 * file is skipped (other rules report it). The register itself is checked when it is loaded.
 */
function rcConflicts(out, data, fsv, dirs, todos, units) {
  const files = new Set();
  const add = (p) => { if (rcIsStr(p)) files.add(rcPath(p)); };
  const c = rcIsObj(data.config) ? data.config : {};
  for (const r of rcArr(c.regions)) if (rcIsObj(r)) add(r.file);
  for (const log of rcArr(c.decisionLogs)) if (rcIsObj(log)) add(log.path);
  for (const ph of rcArr(data.phases)) {
    if (rcIsObj(ph) && rcIsStr(ph.roadmap)) add(ph.roadmap.split('#')[0]);
  }
  for (const u of units) {
    for (const plan of rcArr(u.plans)) if (rcIsObj(plan)) add(plan.path);
    for (const t of rcArr(u.todos)) add(t);
  }
  for (const p of openTodos(data, fsv)) add(p);
  if (todos !== null) for (const p of Object.keys(todos.unhomed)) add(p);
  const archive = rcIsObj(c.archive) && rcIsStr(c.archive.dir) ? normalizePath(c.archive.dir) : null;
  for (const d of dirs) {
    for (const p of fsv.listMd(d.path, d.recursive)) if (archive === null || !inDir(p, archive, true)) add(p);
  }
  for (const path of [...files].sort()) {
    if (!fsv.isFile(path)) continue;
    const problem = conflictProblem(path, fsv.readText(path));
    if (problem !== null) out.push(problem);
  }
}

/**
 * The file-system problems of a register (V3, V7, V9, V10, V11, V13), all at once; never throws.
 * Problems: V3 roadmaps, V10 log files, then per unit V7 / V11(a) / V9 / V10, then V9 open TODOs
 * and `unhomed`, then V11(b) unregistered active plans, then V13 conflict markers by path.
 *
 * @param {unknown} data
 * @param {ReturnType<typeof createFsView>} fsv
 * @returns {{ rule: string, where: string, message: string, fix?: string[] }[]}
 */
function checkRepoFiles(data, fsv) {
  const out = [];
  try {
    rcCheck(out, data, fsv);
  } catch (e) {
    rcPush(out, 'V7', 'register', `internal error while checking files: ${e && e.message !== undefined ? e.message : e}`);
  }
  return out;
}

// --- core/progress.js ---
// Checkbox progress of each unit and rule V8: a `[~]` box needs a valid comment, and a unit that
// is "Not started" must not have a closed box in its plans. Mirrors the legacy rule.
//
// A unit's progress is the sum over its plans except `role: scope`. A plan with `section` counts
// only that section (when exactly one heading matches), otherwise the whole file. Missing files
// and sections that do not match exactly once are skipped here; V7 reports them.

/** `config.skipReasonMin` when it is a non-negative integer, else the default. */
function progressReasonMin(config) {
  const n = config && typeof config === 'object' ? config.skipReasonMin : undefined;
  return Number.isInteger(n) && n >= 0 ? n : DEFAULTS.skipReasonMin;
}

/**
 * Counts the boxes of one plan entry, or returns null when the entry is not counted (scope role,
 * bad entry, missing file, section not found exactly once).
 */
function progressCountPlan(plan, readText, skipReasonMin) {
  if (!plan || typeof plan !== 'object' || plan.role === 'scope') return null;
  if (typeof plan.path !== 'string' || plan.path === '') return null;
  const path = posix.normalize(plan.path);
  const text = readText(path);
  if (typeof text !== 'string') return null;
  let start = 0;
  let end = Infinity;
  if (plan.section !== undefined) {
    if (typeof plan.section !== 'string' || plan.section === '') return null;
    const s = findSection(text, plan.section);
    if (!s.ok) return null;
    start = s.start;
    end = s.end;
  }
  return { path, start, end, counts: countCheckboxes(text, { skipReasonMin, start, end }) };
}

/**
 * Computes the progress of every unit and the V8 problems: every `[~]` box without a valid comment
 * in a counted range (once per file line), then every "Not started" unit with a closed box
 * (`[x]` or `[~]`). A unit without counted plans has progress null and is exempt from the status rule.
 *
 * @param {object} data the parsed register
 * @param {(repoPath: string) => string | null} readText
 * @returns {{ byKey: Map<string, { done: number, total: number, skipped: number } | null>,
 *   problems: { rule: string, where: string, message: string, fix?: string[] }[] }}
 */
function computeProgress(data, readText) {
  const byKey = new Map();
  const skipProblems = [];
  const statusProblems = [];
  const seen = new Set();
  const units = data && typeof data === 'object' && Array.isArray(data.units) ? data.units : [];
  const skipReasonMin = progressReasonMin(data && data.config);
  for (const u of units) {
    if (!u || typeof u !== 'object' || typeof u.key !== 'string') continue;
    const plans = Array.isArray(u.plans) ? u.plans : [];
    let counted = 0;
    let done = 0;
    let total = 0;
    let skipped = 0;
    for (const plan of plans) {
      const c = progressCountPlan(plan, readText, skipReasonMin);
      if (c === null) continue;
      counted += 1;
      done += c.counts.done;
      total += c.counts.total;
      skipped += c.counts.skipped;
      for (const p of c.counts.problems) {
        const where = `${c.path}:${p.line}`;
        const id = `${where}\n${p.message}`;
        if (seen.has(id)) continue;
        seen.add(id);
        skipProblems.push({ rule: 'V8', where, message: p.message });
      }
    }
    if (counted === 0) {
      byKey.set(u.key, null);
      continue;
    }
    byKey.set(u.key, { done, total, skipped });
    if (u.status === 'Not started' && done > 0) {
      statusProblems.push({
        rule: 'V8',
        where: `unit ${JSON.stringify(u.key)}`,
        message: `status is "Not started" but ${done} box(es) are closed in its plans; set "In progress"`,
        fix: ['set', u.key, '--status', 'in-progress', '--write'],
      });
    }
  }
  return { byKey, problems: [...skipProblems, ...statusProblems] };
}

/**
 * The progress cell of a unit: `-` without counted plans, `done/total`, plus ` (n skipped)` when
 * some boxes are skipped.
 *
 * @param {{ done: number, total: number, skipped: number } | null} p
 * @returns {string}
 */
function progressCell(p) {
  if (!p) return '-';
  return `${p.done}/${p.total}${p.skipped > 0 ? ` (${p.skipped} skipped)` : ''}`;
}

// --- core/regions.js ---
// Named generated regions in Markdown files, LF reading and a short line diff.
// A region is the text between `<!-- <marker>:start -->` and `<!-- <marker>:end -->`; one file may hold
// several regions with different markers. Marker errors are returned as values (`{ ok: false, message }`)
// rather than thrown, so `check` can report them as V12 problems.

/**
 * The start and end comments of a region.
 *
 * @param {string} marker
 * @returns {{ start: string, end: string }}
 */
function regionMarkers(marker) {
  return { start: `<!-- ${marker}:start -->`, end: `<!-- ${marker}:end -->` };
}

/**
 * Finds the markers of one region. Missing, duplicated and out-of-order markers are errors (legacy rule).
 *
 * @param {string} text
 * @param {string} marker
 * @param {string} label file label used in messages (POSIX repo-relative path)
 * @returns {{ ok: true, startAt: number, endAt: number, startLen: number } | { ok: false, message: string }}
 */
function regionLocateMarkers(text, marker, label) {
  const m = regionMarkers(marker);
  const startAt = text.indexOf(m.start);
  const endAt = text.indexOf(m.end);
  if (startAt === -1 || endAt === -1) {
    return { ok: false, message: `${label}: missing ${m.start} or ${m.end}` };
  }
  if (text.indexOf(m.start, startAt + 1) !== -1 || text.indexOf(m.end, endAt + 1) !== -1) {
    return { ok: false, message: `${label}: ${marker} markers must appear exactly once` };
  }
  if (endAt < startAt) {
    return { ok: false, message: `${label}: ${m.end} comes before ${m.start}` };
  }
  return { ok: true, startAt, endAt, startLen: m.start.length };
}

/**
 * The content of a region: the text between the markers without the one line break that follows the start
 * marker and the one that precedes the end marker (the layout `replaceRegion` writes), so
 * `extractRegion(replaceRegion(t, m, c).text, m).content === c`.
 *
 * @param {string} text
 * @param {string} marker
 * @param {string} label
 * @returns {{ ok: true, content: string } | { ok: false, message: string }}
 */
function extractRegion(text, marker, label) {
  const loc = regionLocateMarkers(text, marker, label);
  if (!loc.ok) return loc;
  let content = text.slice(loc.startAt + loc.startLen, loc.endAt);
  if (content.startsWith('\n')) content = content.slice(1);
  if (content.endsWith('\n')) content = content.slice(0, -1);
  return { ok: true, content };
}

/**
 * Replaces the text between the markers with `content`, as in the source: the result is
 * `<before>start\n<content>\nend<after>`. Text outside the markers is kept byte for byte.
 *
 * @param {string} text
 * @param {string} marker
 * @param {string} content
 * @param {string} label
 * @returns {{ ok: true, text: string } | { ok: false, message: string }}
 */
function replaceRegion(text, marker, content, label) {
  const loc = regionLocateMarkers(text, marker, label);
  if (!loc.ok) return loc;
  return { ok: true, text: `${text.slice(0, loc.startAt + loc.startLen)}\n${content}\n${text.slice(loc.endAt)}` };
}

/**
 * Reads a UTF-8 text file with CRLF line endings normalised to LF (a Windows checkout may have them).
 *
 * @param {string} absPath
 * @returns {string}
 */
function readLf(absPath) {
  return readFileSync(absPath, 'utf8').replace(/\r\n/g, '\n');
}

/**
 * A short line diff hint: the lines that differ at the same index, prefixed with `- ` (current) and
 * `+ ` (expected). Equal texts give ''.
 *
 * @param {string} current
 * @param {string} expected
 * @returns {string}
 */
function diffHint(current, expected) {
  const a = current.split('\n');
  const b = expected.split('\n');
  const out = [];
  for (let i = 0; i < Math.max(a.length, b.length); i += 1) {
    if (a[i] === b[i]) continue;
    if (a[i] !== undefined) out.push(`- ${a[i]}`);
    if (b[i] !== undefined) out.push(`+ ${b[i]}`);
  }
  return out.join('\n');
}

// --- core/render/units.js ---
// The `units` view: one row per unit with its plans, status, progress and dependencies. The
// shared cell helpers (unit names, Key, Status, Depends on) live here and are used by the other
// views. Ported from the source `renderRegister` (legacy rule) with the v5 blocker rendering.

/** A list field of a unit, or [] when it is missing or not an array. */
function runList(value) {
  return Array.isArray(value) ? value : [];
}

/** First letter upper case. */
function runCapitalize(text) {
  return text === '' ? text : text[0].toUpperCase() + text.slice(1);
}

/**
 * The unit name of a register (`config.unitName`, default `unit`) and its plural
 * (`config.unitNamePlural`, default `<unitName>s`) as written in the config, and both capitalized.
 *
 * @param {object} config
 * @returns {{ singular: string, plural: string, Singular: string, Plural: string }}
 */
function unitNames(config) {
  const c = config && typeof config === 'object' ? config : {};
  const singular = typeof c.unitName === 'string' && c.unitName !== '' ? c.unitName : 'unit';
  const plural = typeof c.unitNamePlural === 'string' && c.unitNamePlural !== '' ? c.unitNamePlural : `${singular}s`;
  return { singular, plural, Singular: runCapitalize(singular), Plural: runCapitalize(plural) };
}

/**
 * The Status cell text (v5 rule 7): the status, `(PR #<n>)` when the unit has a PR, then one
 * `; Blocked (…)` per `waitsOn` entry: `decision: <ref>`, `credential` (the ref is not shown),
 * `external: <ref>`.
 *
 * @param {object} unit
 * @returns {string}
 */
function statusCell(unit) {
  let text = String(unit.status ?? '');
  if (Number.isInteger(unit.pr)) text += ` (PR #${unit.pr})`;
  for (const w of runList(unit.waitsOn)) {
    if (!w || typeof w !== 'object') continue;
    if (w.kind === 'credential') text += '; Blocked (credential)';
    else text += `; Blocked (${w.kind}: ${w.ref})`;
  }
  return text;
}

/**
 * The Key cell text: `` `<key>` ``, then in parentheses the aliases and, for a gate,
 * `gate, owner: <owner>` (or `gate` without an owner), joined by `; `.
 *
 * @param {object} unit
 * @returns {string}
 */
function keyCell(unit) {
  const notes = runList(unit.aliases).map(String);
  if (unit.kind === 'gate') notes.push(typeof unit.owner === 'string' ? `gate, owner: ${unit.owner}` : 'gate');
  return `\`${unit.key}\`${notes.length > 0 ? ` (${notes.join('; ')})` : ''}`;
}

/**
 * The Depends on cell text: `dependsOn` joined by `, `, then `after <key>` for each `after`
 * entry; `none` when both are empty.
 *
 * @param {object} unit
 * @returns {string}
 */
function dependsCell(unit) {
  const deps = [...runList(unit.dependsOn), ...runList(unit.after).map((k) => `after ${k}`)];
  return deps.length > 0 ? deps.join(', ') : 'none';
}

/** The Plans cell: `[basename](link) (role[; scope][; §section])` per entry, joined by `<br>`. */
function runPlansCell(unit, linkFrom) {
  const plans = runList(unit.plans).filter((p) => p && typeof p === 'object' && typeof p.path === 'string');
  if (plans.length === 0) return 'none';
  return plans
    .map((p) => {
      const notes = [p.role, p.scope, p.section !== undefined ? `§${p.section}` : undefined]
        .filter((n) => typeof n === 'string' && n !== '' && n !== '§');
      const path = posix.normalize(p.path);
      return `[${posix.basename(path, '.md')}](${relLink(linkFrom, path)})${notes.length > 0 ? ` (${notes.join('; ')})` : ''}`;
    })
    .join('<br>');
}

/**
 * Renders the `units` view: a heading and one table row per unit, in register order.
 *
 * @param {object} data the parsed register
 * @param {{ linkFrom: string, progress?: Map<string, object | null> }} ctx
 * @returns {string}
 */
function renderUnits(data, ctx) {
  const names = unitNames(data.config);
  const progress = ctx.progress instanceof Map ? ctx.progress : new Map();
  const lines = [
    `**${names.Plural}** (the authority for status, plans and progress):`,
    '',
    '| Key | Phase | Title | Plans | Status | Progress | Depends on | Closed by |',
    '| --- | --- | --- | --- | --- | --- | --- | --- |',
  ];
  for (const u of runList(data.units)) {
    if (!u || typeof u !== 'object') continue;
    const row = [
      keyCell(u),
      typeof u.phase === 'string' ? `\`${u.phase}\`` : '-',
      u.title,
      runPlansCell(u, ctx.linkFrom),
      statusCell(u),
      progressCell(progress.get(u.key) ?? null),
      dependsCell(u),
      typeof u.closedBy === 'string' && u.closedBy !== '' ? u.closedBy : '-',
    ];
    lines.push(`| ${row.map(cell).join(' | ')} |`);
  }
  return lines.join('\n');
}

// --- core/render/phases.js ---
// The `phases` view: one row per phase with its status derived from its units. Ported from the
// source `renderRegister` and `phaseStatus` (legacy rule).

/**
 * A phase's status from the statuses of its units (Superseded units are ignored): `No units yet`
 * without units, `Superseded` when all are superseded, `Done` when all others are done,
 * `Not started` when none of the others has started, `In progress` otherwise.
 *
 * @param {string[]} statuses
 * @returns {string}
 */
function phaseStatus(statuses) {
  if (statuses.length === 0) return 'No units yet';
  const live = statuses.filter((s) => s !== 'Superseded');
  if (live.length === 0) return 'Superseded';
  if (live.every((s) => s === 'Done')) return 'Done';
  if (live.every((s) => s === 'Not started')) return 'Not started';
  return 'In progress';
}

/** A list, or [] when the value is not an array. */
function rphList(value) {
  return Array.isArray(value) ? value : [];
}

/**
 * Renders the `phases` view. Columns: the phase key, its title (linked to `roadmap` when set),
 * its aliases (`-` when none), the number of its units (as in the source) and its status.
 *
 * @param {object} data the parsed register
 * @param {{ linkFrom: string }} ctx
 * @returns {string}
 */
function renderPhases(data, ctx) {
  const names = unitNames(data.config);
  const units = rphList(data.units).filter((u) => u && typeof u === 'object');
  const lines = [
    `**Phases** (status derived from the ${names.plural} below):`,
    '',
    `| Phase | Title | Aliases | ${names.Plural} | Status |`,
    '| --- | --- | --- | --- | --- |',
  ];
  for (const p of rphList(data.phases)) {
    if (!p || typeof p !== 'object') continue;
    const own = units.filter((u) => u.phase === p.key);
    const aliases = rphList(p.aliases);
    const title = typeof p.roadmap === 'string' && p.roadmap !== ''
      ? `[${p.title}](${relLink(ctx.linkFrom, p.roadmap)})`
      : String(p.title ?? '');
    const row = [
      `\`${p.key}\``,
      title,
      aliases.length > 0 ? aliases.join(', ') : '-',
      own.length,
      phaseStatus(own.map((u) => u.status)),
    ];
    lines.push(`| ${row.map(cell).join(' | ')} |`);
  }
  return lines.join('\n');
}

// --- core/render/order.js ---
// The `order` view: the units in topological order with their readiness, then the longest
// dependency chain among the open units. Readiness follows `readyUnits` (Task 4): `after` is
// ordering only and does not block.

/** A list, or [] when the value is not an array. */
function rordList(value) {
  return Array.isArray(value) ? value : [];
}

/**
 * The Ready cell text of a unit: `done` (closed), `in progress`, `ready`, or `waiting: ` with
 * every open `dependsOn` unit as `<key> (<status>)` followed by every `waitsOn` entry (its ref;
 * `credential` for a credential, whose ref is not shown, as in the Status cell).
 */
function rordReadyCell(unit, byKey, ready) {
  if (CLOSED_STATUSES.includes(unit.status)) return 'done';
  if (unit.status === 'In progress') return 'in progress';
  if (ready.has(unit.key)) return 'ready';
  const reasons = [];
  for (const d of rordList(unit.dependsOn)) {
    const dep = byKey.get(d);
    if (!dep) reasons.push(`${d} (unknown)`);
    else if (!CLOSED_STATUSES.includes(dep.status)) reasons.push(`${d} (${dep.status})`);
  }
  for (const w of rordList(unit.waitsOn)) {
    if (!w || typeof w !== 'object') continue;
    reasons.push(w.kind === 'credential' ? 'credential' : String(w.ref));
  }
  return reasons.length > 0 ? `waiting: ${reasons.join(', ')}` : 'waiting';
}

/**
 * Renders the `order` view. On a dependency cycle (which `check` reports before any render) the
 * rows keep register order and the chain line says the order was not computed.
 *
 * @param {object} data the parsed register
 * @returns {string}
 */
function renderOrder(data) {
  const names = unitNames(data.config);
  const units = rordList(data.units).filter((u) => u && typeof u === 'object' && typeof u.key === 'string');
  const byKey = new Map();
  for (const u of units) if (!byKey.has(u.key)) byKey.set(u.key, u);
  let keys;
  let ready;
  let chain;
  try {
    keys = topoOrder(units);
    ready = new Set(readyUnits(units));
    chain = longestChain(units);
  } catch {
    keys = [...byKey.keys()];
    ready = new Set();
    chain = null;
  }
  const lines = [
    '**Order** (topological; ready = not started, hard dependencies closed, nothing waited on):',
    '',
    '| # | Key | Status | Depends on | Ready |',
    '| --- | --- | --- | --- | --- |',
  ];
  keys.forEach((key, i) => {
    const u = byKey.get(key);
    const row = [i + 1, `\`${key}\``, statusCell(u), dependsCell(u), rordReadyCell(u, byKey, ready)];
    lines.push(`| ${row.map(cell).join(' | ')} |`);
  });
  const lead = `Longest dependency chain among open ${names.plural} (dependsOn only; no effort estimates):`;
  let tail;
  if (chain === null) tail = 'not computed (the dependencies contain a cycle).';
  else if (chain.length === 0) tail = 'none.';
  else tail = `${chain.join(' → ')} (${chain.length} ${chain.length === 1 ? names.singular : names.plural}).`;
  lines.push('', cell(`${lead} ${tail}`));
  return lines.join('\n');
}

// --- core/render/todos.js ---
// The `todos` view: every open TODO note (KD-4; the list comes from the caller) with its home
// unit, or the reason from `todos.unhomed`. Archived notes and excluded files are not in the list.

/** A list, or [] when the value is not an array. */
function rtodoList(value) {
  return Array.isArray(value) ? value : [];
}

/**
 * Renders the `todos` view: one row per open TODO, sorted by path. A homed note shows its home
 * units and their Status cells (joined by `, ` when a note has several homes); a note listed in
 * `todos.unhomed` shows `unhomed` and the reason; a note with neither (V9 reports it) shows
 * `none` and `-`. Without open notes the table is replaced by `none`.
 *
 * @param {object} data the parsed register
 * @param {{ linkFrom: string, openTodos?: string[] }} ctx
 * @returns {string}
 */
function renderTodos(data, ctx) {
  const names = unitNames(data.config);
  const units = rtodoList(data.units).filter((u) => u && typeof u === 'object');
  const todosCfg = data.config && typeof data.config.todos === 'object' && data.config.todos !== null
    ? data.config.todos : {};
  const unhomed = todosCfg.unhomed && typeof todosCfg.unhomed === 'object' ? todosCfg.unhomed : {};
  const open = [...new Set(rtodoList(ctx.openTodos).map((p) => posix.normalize(p)))].sort();
  const lines = ['**Open TODO notes** (home of each note):', ''];
  if (open.length === 0) {
    lines.push('none');
    return lines.join('\n');
  }
  lines.push(`| TODO | ${names.Singular} | ${names.Singular} status |`, '| --- | --- | --- |');
  for (const path of open) {
    const link = `[${posix.basename(path, '.md')}](${relLink(ctx.linkFrom, path)})`;
    const homes = units.filter((u) => rtodoList(u.todos).some((t) => typeof t === 'string' && posix.normalize(t) === path));
    let row;
    if (homes.length > 0) {
      row = [link, homes.map((u) => `\`${u.key}\``).join(', '), homes.map(statusCell).join(', ')];
    } else if (Object.prototype.hasOwnProperty.call(unhomed, path)) {
      row = [link, 'unhomed', unhomed[path]];
    } else {
      row = [link, 'none', '-'];
    }
    lines.push(`| ${row.map(cell).join(' | ')} |`);
  }
  return lines.join('\n');
}

// --- core/render/index.js ---
// Region rendering: one view by name, or the whole content of a region (the generated-by comment
// and its views). Not the bundle entry point (that is core/index.js).

/**
 * Renders one view (`phases`, `units`, `order`, `todos`) of the register.
 *
 * @param {string} view
 * @param {object} data the parsed register (without problems)
 * @param {{ linkFrom: string, progress?: Map<string, object | null>, openTodos?: string[], registerPath?: string }} ctx
 *   `linkFrom` is the region file; links are relative to it
 * @returns {string}
 * @throws {Error} on an unknown view
 */
function renderView(view, data, ctx) {
  if (view === 'phases') return renderPhases(data, ctx);
  if (view === 'units') return renderUnits(data, ctx);
  if (view === 'order') return renderOrder(data, ctx);
  if (view === 'todos') return renderTodos(data, ctx);
  throw new Error(`unknown view ${JSON.stringify(view)}`);
}

/**
 * The content of a region (without its markers): the generated-by comment naming the register,
 * then each view of the region, separated by a blank line.
 *
 * @param {{ views: string[] }} region
 * @param {object} data
 * @param {{ linkFrom: string, progress?: Map<string, object | null>, openTodos?: string[], registerPath?: string }} ctx
 * @returns {string}
 */
function renderRegionContent(region, data, ctx) {
  const registerPath = String(typeof ctx.registerPath === 'string' && ctx.registerPath !== ''
    ? ctx.registerPath : DEFAULTS.registerPath).replace(/-->/g, '--&gt;').replace(/\r?\n/g, ' ');
  const header = [
    `<!-- Generated by plan-register from ${registerPath} and the plan checkboxes.`,
    '     Do not edit by hand: change the register with the CLI, then run "write". -->',
  ].join('\n');
  const views = (Array.isArray(region.views) ? region.views : []).map((v) => renderView(v, data, ctx));
  return [header, ...views].join('\n\n');
}

// --- core/load.js ---
// One entry point for the CLI and for programmatic use: finding the repository root, loading the
// register, checking it (V1–V13) and writing the generated regions.
//
// `checkRepo` runs the structure checks (schema.js), the file checks (repo-checks.js) and the V8
// checkbox rule (progress.js). Only when none of them reports a problem are the regions rendered and
// compared with the files (V12); otherwise one V12 line says that the regions were not checked.
// Region files are read with CRLF as LF; every write is LF and happens only when the content changes.

/**
 * The V12 line added when other problems keep the regions from being checked. It is informational
 * (`info: true`): no problem count includes it (check header, `check --json` `problems`/`ok`, `status`,
 * `doctor`); `check` prints it as a note after the list.
 */
const LOAD_NOT_CHECKED = Object.freeze({
  rule: 'V12',
  where: 'register',
  message: 'regions not checked: fix the problems above first',
  info: true,
});

/**
 * The repository root (KD-2): `root` (resolved against `cwd`) when given, else the first directory
 * from `cwd` upwards that contains `registerPath`.
 *
 * @param {{ cwd: string, root?: string, registerPath?: string }} opts
 * @returns {string} absolute root
 * @throws {Error} when no directory upwards contains the register
 */
function resolveRoot({ cwd, root, registerPath = DEFAULTS.registerPath }) {
  if (typeof root === 'string' && root !== '') return resolve(cwd, root);
  let dir = resolve(cwd);
  for (;;) {
    if (existsSync(resolve(dir, registerPath))) return dir;
    const up = dirname(dir);
    if (up === dir) break;
    dir = up;
  }
  throw new Error(`register not found: looked for ${registerPath} from ${cwd} upwards; pass --root or --register`);
}

/** The register path for messages and the generated-by comment: repository-relative POSIX when inside the root. */
function loadRegisterLabel(root, registerPath) {
  if (!isAbsolute(registerPath)) return normalizePath(registerPath) ?? registerPath;
  const rel = relative(resolve(root), registerPath);
  if (rel === '' || rel.startsWith('..') || isAbsolute(rel)) return registerPath;
  return rel.split(sep).join('/');
}

/** `line L, column C` (1-based) of a character offset in `text`. */
function loadPosition(text, offset) {
  const before = text.slice(0, Math.max(0, Math.min(offset, text.length)));
  const line = before.split('\n').length;
  const column = before.length - before.lastIndexOf('\n');
  return `line ${line}, column ${column}`;
}

/**
 * The offset of the first JSON syntax error in `text` (a small strict scanner, so the position does
 * not depend on the engine's message format), or -1 when the scanner finds none.
 */
function loadJsonErrorOffset(text) {
  let i = 0;
  const ws = () => { while (i < text.length && ' \t\n\r'.includes(text[i])) i += 1; };
  const fail = () => { throw i; };
  const str = () => {
    i += 1;
    while (i < text.length && text[i] !== '"') {
      const c = text.charCodeAt(i);
      if (c < 0x20) fail();
      if (text[i] === '\\') {
        i += 1;
        if (text[i] === 'u') {
          if (!/^[0-9a-fA-F]{4}$/.test(text.slice(i + 1, i + 5))) fail();
          i += 4;
        } else if (!'"\\/bfnrt'.includes(text[i] ?? '')) fail();
      }
      i += 1;
    }
    if (i >= text.length) fail();
    i += 1;
  };
  const value = () => {
    ws();
    const c = text[i];
    if (c === '{' || c === '[') {
      const close = c === '{' ? '}' : ']';
      i += 1;
      ws();
      if (text[i] === close) { i += 1; return; }
      for (;;) {
        if (c === '{') {
          ws();
          if (text[i] !== '"') fail();
          str();
          ws();
          if (text[i] !== ':') fail();
          i += 1;
        }
        value();
        ws();
        if (text[i] === ',') { i += 1; continue; }
        if (text[i] === close) { i += 1; return; }
        fail();
      }
    }
    if (c === '"') return str();
    const m = /^(?:true|false|null|-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?)/.exec(text.slice(i, i + 400));
    if (!m) fail();
    i += m[0].length;
    return undefined;
  };
  try {
    value();
    ws();
    return i < text.length ? i : -1;
  } catch (at) {
    if (typeof at === 'number') return at;
    throw at;
  }
}

/** The V1 message of a JSON syntax error, with its line and column. */
function loadJsonMessage(text, error) {
  const at = loadJsonErrorOffset(text);
  if (at === -1) {
    const raw = String(error && error.message !== undefined ? error.message : error);
    return `not valid JSON: ${raw.split('\n')[0]}`;
  }
  const what = at >= text.length ? 'unexpected end of input' : `unexpected ${JSON.stringify(text[at])}`;
  return `not valid JSON at ${loadPosition(text, at)}: ${what}`;
}

/**
 * Reads and parses the register. A missing file or a JSON syntax error is one V1 problem (where = the
 * register path) and `data` is null; a file with git conflict markers is one V13 problem instead of
 * the JSON error. CRLF is read as LF and a leading BOM is ignored.
 *
 * @param {string} root
 * @param {{ registerPath?: string }} [opts]
 * @returns {{ data: object | null, problems: { rule: string, where: string, message: string }[], registerPath: string }}
 */
function loadRegister(root, { registerPath = DEFAULTS.registerPath } = {}) {
  const label = loadRegisterLabel(root, registerPath);
  const file = isAbsolute(registerPath) ? registerPath : resolve(root, registerPath);
  let text;
  try {
    text = readFileSync(file, 'utf8').replace(/\r\n/g, '\n').replace(/^﻿/, '');
  } catch {
    return { data: null, problems: [{ rule: 'V1', where: label, message: 'register file does not exist' }], registerPath: label };
  }
  const conflict = conflictProblem(label, text, 'the register is not valid JSON until then');
  if (conflict !== null) return { data: null, problems: [conflict], registerPath: label };
  try {
    return { data: JSON.parse(text), problems: [], registerPath: label };
  } catch (e) {
    return { data: null, problems: [{ rule: 'V1', where: label, message: loadJsonMessage(text, e) }], registerPath: label };
  }
}

/** True when the parsed register can be checked at all (an object with a supported schema). */
function loadCheckable(data) {
  return data !== null && typeof data === 'object' && !Array.isArray(data) && SUPPORTED_SCHEMAS.includes(data.schema);
}

/**
 * The V1–V11 and V13 problems of parsed register data against a repository view (structure, files, V8),
 * plus the progress of each unit. Shared with the mutation transaction, which passes a view with
 * pending file edits overlaid.
 *
 * @param {object} data
 * @param {ReturnType<typeof createFsView>} fsv
 * @returns {{ problems: object[], progress: Map<string, object | null> }}
 */
function loadDataProblems(data, fsv) {
  const structure = validateStructure(data);
  if (!loadCheckable(data)) return { problems: structure, progress: null };
  const files = checkRepoFiles(data, fsv);
  const prog = computeProgress(data, (p) => fsv.readText(p));
  return { problems: [...structure, ...files, ...prog.problems], progress: prog.byKey };
}

/** The usable regions of the config, with the file normalized. */
function loadRegions(data) {
  const list = data && data.config && Array.isArray(data.config.regions) ? data.config.regions : [];
  return list.map((r) => ({ file: normalizePath(r.file) ?? r.file, marker: r.marker, views: r.views }));
}

/**
 * The expected and current content of each region. A region whose file is missing or whose markers
 * are broken gets `error` (the problem message) instead of `current`.
 */
function loadRegionStates(root, data, progress, registerPath) {
  const fsv = createFsView(root);
  const todos = openTodos(data, fsv);
  return loadRegions(data).map((r) => {
    const label = `${r.file} (${r.marker})`;
    const base = { file: r.file, marker: r.marker, label };
    const text = fsv.isFile(r.file) ? fsv.readText(r.file) : null;
    if (text === null) return { ...base, error: 'region file does not exist' };
    let expected;
    try {
      expected = renderRegionContent(r, data, { linkFrom: r.file, progress, openTodos: todos, registerPath });
    } catch (e) {
      return { ...base, error: `cannot render the region: ${e && e.message !== undefined ? e.message : e}` };
    }
    const got = extractRegion(text, r.marker, label);
    if (!got.ok) return { ...base, error: got.message.startsWith(`${label}: `) ? got.message.slice(label.length + 2) : got.message };
    return { ...base, expected, content: got.content };
  });
}

/**
 * Checks the repository: V1–V11 and V13 first; V12 (regions current) only when there is no other
 * problem. An unreadable register or an unsupported schema gives that single V1 problem.
 *
 * @param {string} root
 * @param {{ registerPath?: string }} [opts]
 * @returns {{ data: object | null, problems: object[],
 *   regions: { file: string, marker: string, current: boolean, diff: string | null }[],
 *   progress: Map<string, object | null> | null }}
 */
function checkRepo(root, opts = {}) {
  const loaded = loadRegister(root, opts);
  if (loaded.data === null) return { data: null, problems: loaded.problems, regions: [], progress: null };
  const data = loaded.data;
  const { problems, progress } = loadDataProblems(data, createFsView(root));
  if (progress === null) return { data, problems, regions: [], progress: null };
  if (problems.length > 0) return { data, problems: [...problems, { ...LOAD_NOT_CHECKED }], regions: [], progress };
  const regions = [];
  const v12 = [];
  for (const s of loadRegionStates(root, data, progress, loaded.registerPath)) {
    if (s.error !== undefined) {
      regions.push({ file: s.file, marker: s.marker, current: false, diff: null });
      v12.push({ rule: 'V12', where: s.label, message: s.error });
    } else if (s.content === s.expected) {
      regions.push({ file: s.file, marker: s.marker, current: true, diff: '' });
    } else {
      const diff = diffHint(s.content, s.expected);
      regions.push({ file: s.file, marker: s.marker, current: false, diff });
      v12.push({ rule: 'V12', where: s.label, message: 'region is stale', fix: ['write'], diff });
    }
  }
  return { data, problems: v12, regions, progress };
}

/**
 * Regenerates every configured region. Several regions of one file are applied in sequence; a file
 * is written (LF) only when one of its regions changes, so a current file keeps its bytes and mtime.
 *
 * @param {string} root
 * @param {{ registerPath?: string }} [opts]
 * @returns {{ file: string, marker: string, changed: boolean }[]}
 * @throws {Error} when the register has V1–V11 or V13 problems, a region file is missing or its markers are broken
 */
function writeRegions(root, opts = {}) {
  const loaded = loadRegister(root, opts);
  const checked = loaded.data === null ? null : loadDataProblems(loaded.data, createFsView(root));
  const problems = checked === null ? loaded.problems : checked.problems;
  if (problems.length > 0) {
    throw new Error(`regions not written: the register has problems:\n${problems.map(problemText).join('\n')}`);
  }
  const states = loadRegionStates(root, loaded.data, checked.progress, loaded.registerPath);
  const broken = states.filter((s) => s.error !== undefined);
  if (broken.length > 0) {
    throw new Error(`regions not written:\n${broken.map((s) => problemText({ rule: 'V12', where: s.label, message: s.error })).join('\n')}`);
  }
  const fsv = createFsView(root);
  const files = new Map(); // file -> { text, changed }
  const out = [];
  for (const s of states) {
    if (!files.has(s.file)) files.set(s.file, { text: fsv.readText(s.file), changed: false });
    const f = files.get(s.file);
    const changed = s.content !== s.expected;
    if (changed) {
      const r = replaceRegion(f.text, s.marker, s.expected, s.label);
      if (!r.ok) throw new Error(`regions not written:\n${r.message}`);
      f.text = r.text;
      f.changed = true;
    }
    out.push({ file: s.file, marker: s.marker, changed });
  }
  for (const [file, f] of files) {
    if (f.changed) writeFileSync(join(resolve(root), ...file.split('/')), f.text);
  }
  return out;
}

// --- core/tickets/config.js ---
// The tickets configuration `docs/tickets/config.json` (schema `tickets/1`): reading, validation (the
// config part of rule TV1) and the defaults of every optional field. The register the config names is
// loaded too: a register that cannot be read is one more TV1 problem, but the config is still returned
// (the rules that need the register are then skipped by the caller).
//
// Problem = { rule: 'TV1', where: <config path>, message: string, fix?: string[] }. Every path in the
// config is a repository-relative POSIX path. Nothing here throws, whatever the file holds.

/** The ticket types of `tickets/1`, in type order (fixed; prefixes and parents are configurable). */
const TICKET_TYPES = Object.freeze(['epic', 'story', 'task', 'defect', 'idea']);

/** The default config path, repository-relative. */
const TICKETS_CONFIG_PATH = 'docs/tickets/config.json';

const TKC_KEYS = Object.freeze(['schema', 'register', 'root', 'archiveDir', 'scheduleSection', 'knownFacts', 'digits',
  'types', 'implementable', 'homeRequired', 'limits', 'regions', 'frozen']);
const TKC_TYPE_KEYS = Object.freeze(['prefix', 'parents', 'topLevel', 'enabled']);
const TKC_DEFAULT_TYPES = Object.freeze({
  epic: Object.freeze({ prefix: 'EP', parents: Object.freeze([]), topLevel: true, enabled: true }),
  story: Object.freeze({ prefix: 'ST', parents: Object.freeze(['epic']), topLevel: true, enabled: true }),
  task: Object.freeze({ prefix: 'TK', parents: Object.freeze(['story', 'epic']), topLevel: true, enabled: true }),
  defect: Object.freeze({ prefix: 'BG', parents: Object.freeze(['epic', 'story', 'task']), topLevel: true, enabled: true }),
  idea: Object.freeze({ prefix: 'ID', parents: Object.freeze(['epic']), topLevel: true, enabled: false }),
});
const TKC_DEFAULT_LIMITS = Object.freeze({
  depth: 3, ticketLines: 120, ticketsPerMilestone: 8, attachmentBytes: 1048576, pathLength: 180, slugLength: 24,
});
const TKC_DEFAULTS = Object.freeze({
  register: 'docs/plans/register.json',
  scheduleSection: 'Milestones',
  digits: 3,
  implementable: Object.freeze(['task', 'defect', 'story']),
  homeRequired: Object.freeze([]),
  marker: 'tickets-index',
});
const TKC_PREFIX_RE = /^[A-Z]{2,6}$/;

function tkcIsObj(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

function tkcIsStr(v) {
  return typeof v === 'string' && v !== '';
}

/**
 * `true` when `iso` is `YYYY-MM-DD` and names a real calendar date.
 *
 * @param {unknown} iso
 * @returns {boolean}
 */
function isCalendarDate(iso) {
  if (typeof iso !== 'string') return false;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso);
  if (!m) return false;
  const d = new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])));
  return d.toISOString().slice(0, 10) === iso;
}

/** `unknown key` messages of `obj` against `allowed`; `prefix` is the dotted path of `obj`. */
function tkcUnknown(out, obj, allowed, prefix) {
  for (const k of Object.keys(obj)) {
    if (!allowed.includes(k)) out.push(`unknown key ${JSON.stringify(`${prefix}${k}`)} (allowed: ${allowed.join(', ')})`);
  }
}

/** A repository path field: the normalized path, or null with a message. */
function tkcPath(out, name, v) {
  if (!tkcIsStr(v)) {
    out.push(`${name} must be a non-empty string`);
    return null;
  }
  const n = normalizePath(v);
  if (n === null) out.push(`${name} must be a repository-relative path (found ${JSON.stringify(v)})`);
  return n;
}

/** A list of type names (`implementable`, `homeRequired`). */
function tkcTypeList(out, name, v, fallback) {
  if (v === undefined) return [...fallback];
  if (!Array.isArray(v) || !v.every((x) => typeof x === 'string')) {
    out.push(`${name} must be an array of type names`);
    return [...fallback];
  }
  for (const t of v) {
    if (!TICKET_TYPES.includes(t)) out.push(`${name}: ${JSON.stringify(t)} is not a type (types: ${TICKET_TYPES.join(', ')})`);
  }
  return [...v];
}

function tkcTypes(out, v) {
  const types = {};
  for (const t of TICKET_TYPES) types[t] = { ...TKC_DEFAULT_TYPES[t], parents: [...TKC_DEFAULT_TYPES[t].parents] };
  if (v === undefined) return types;
  if (!tkcIsObj(v)) {
    out.push('types must be an object');
    return types;
  }
  const missing = TICKET_TYPES.filter((t) => !Object.hasOwn(v, t));
  const unknown = Object.keys(v).filter((t) => !TICKET_TYPES.includes(t));
  if (missing.length > 0 || unknown.length > 0) {
    const parts = [];
    if (missing.length > 0) parts.push(`missing: ${missing.join(', ')}`);
    if (unknown.length > 0) parts.push(`unknown: ${unknown.join(', ')}`);
    out.push(`types must have exactly the keys ${TICKET_TYPES.join(', ')} (${parts.join('; ')})`);
  }
  for (const t of TICKET_TYPES) {
    if (!Object.hasOwn(v, t)) continue;
    const e = v[t];
    const name = `types.${t}`;
    if (!tkcIsObj(e)) {
      out.push(`${name} must be an object`);
      continue;
    }
    tkcUnknown(out, e, TKC_TYPE_KEYS, `${name}.`);
    if (e.prefix !== undefined) {
      if (typeof e.prefix === 'string' && TKC_PREFIX_RE.test(e.prefix)) types[t].prefix = e.prefix;
      else out.push(`${name}.prefix must match ${TKC_PREFIX_RE.source}`);
    }
    if (e.parents !== undefined) {
      if (!Array.isArray(e.parents) || !e.parents.every((x) => typeof x === 'string')) {
        out.push(`${name}.parents must be an array of type names`);
      } else {
        for (const p of e.parents) {
          if (!TICKET_TYPES.includes(p)) out.push(`${name}.parents: ${JSON.stringify(p)} is not a type (types: ${TICKET_TYPES.join(', ')})`);
        }
        types[t].parents = [...e.parents];
      }
    }
    for (const flag of ['topLevel', 'enabled']) {
      if (e[flag] === undefined) continue;
      if (typeof e[flag] === 'boolean') types[t][flag] = e[flag];
      else out.push(`${name}.${flag} must be true or false`);
    }
  }
  const seen = new Map();
  for (const t of TICKET_TYPES) {
    const p = types[t].prefix;
    if (seen.has(p)) out.push(`types.${t}.prefix ${JSON.stringify(p)} is also the prefix of ${seen.get(p)}; prefixes are unique`);
    else seen.set(p, t);
  }
  return types;
}

function tkcLimits(out, v) {
  const limits = { ...TKC_DEFAULT_LIMITS };
  if (v === undefined) return limits;
  if (!tkcIsObj(v)) {
    out.push('limits must be an object');
    return limits;
  }
  tkcUnknown(out, v, Object.keys(TKC_DEFAULT_LIMITS), 'limits.');
  for (const k of Object.keys(TKC_DEFAULT_LIMITS)) {
    if (v[k] === undefined) continue;
    if (Number.isInteger(v[k]) && v[k] > 0) limits[k] = v[k];
    else out.push(`limits.${k} must be a positive integer`);
  }
  return limits;
}

function tkcRegions(out, v, root) {
  if (v === undefined) return [{ file: `${root}/README.md`, marker: TKC_DEFAULTS.marker }];
  if (!Array.isArray(v)) {
    out.push('regions must be an array');
    return [];
  }
  const regions = [];
  const pairs = new Set();
  v.forEach((r, i) => {
    const name = `regions[${i}]`;
    if (!tkcIsObj(r)) {
      out.push(`${name} must be an object`);
      return;
    }
    tkcUnknown(out, r, ['file', 'marker'], `${name}.`);
    const file = tkcPath(out, `${name}.file`, r.file);
    const markerOk = typeof r.marker === 'string' && MARKER_RE.test(r.marker);
    if (!markerOk) out.push(`${name}.marker must match ${MARKER_RE.source}`);
    if (file === null || !markerOk) return;
    const pair = `${file}\0${r.marker}`;
    if (pairs.has(pair)) {
      out.push(`${name}: file and marker ${file} (${r.marker}) are used twice`);
      return;
    }
    pairs.add(pair);
    regions.push({ file, marker: r.marker });
  });
  return regions;
}

function tkcKnownFacts(out, root, v) {
  if (v === undefined) return null;
  if (!tkcIsObj(v)) {
    out.push('knownFacts must be an object');
    return null;
  }
  tkcUnknown(out, v, ['path', 'idPattern'], 'knownFacts.');
  const path = tkcPath(out, 'knownFacts.path', v.path);
  if (path !== null && !existsSync(join(root, ...path.split('/')))) out.push(`knownFacts.path ${path} does not exist`);
  if (!tkcIsStr(v.idPattern)) {
    out.push('knownFacts.idPattern must be a non-empty string');
  } else {
    try {
      new RegExp(v.idPattern);
    } catch (e) {
      out.push(`knownFacts.idPattern is not a valid regular expression: ${String(e.message).replace(/^Invalid regular expression: /, '')}`);
    }
  }
  return path === null ? null : { path, idPattern: v.idPattern };
}

/** The canonical ID form of a type and number: `TK-007` with 3 digits. */
function tkcFormatId(prefix, n, digits) {
  return `${prefix}-${String(n).padStart(digits, '0')}`;
}

function tkcFrozen(out, v, types, digits) {
  if (v === undefined) return null;
  if (!tkcIsObj(v)) {
    out.push('frozen must be an object');
    return null;
  }
  tkcUnknown(out, v, ['date', 'ids'], 'frozen.');
  if (!isCalendarDate(v.date)) out.push('frozen.date must be a calendar date YYYY-MM-DD');
  if (!Array.isArray(v.ids) || !v.ids.every((x) => typeof x === 'string')) {
    out.push('frozen.ids must be an array of ticket IDs');
    return null;
  }
  const re = ticketIdPattern({ types });
  const keys = [];
  for (const id of v.ids) {
    const m = re.exec(id);
    const n = m ? Number(m[2]) : 0;
    if (!m || n < 1 || tkcFormatId(m[1], n, digits) !== id) {
      out.push(`frozen.ids: ${JSON.stringify(id)} is not a canonical ticket ID`);
      continue;
    }
    keys.push([TICKET_TYPES.findIndex((t) => types[t].prefix === m[1]), n]);
  }
  for (let i = 1; i < keys.length; i += 1) {
    const [ta, na] = keys[i - 1];
    const [tb, nb] = keys[i];
    if (ta > tb || (ta === tb && na >= nb)) {
      out.push(`frozen.ids must be sorted by type order (${TICKET_TYPES.join(', ')}), then number, without repeats`);
      break;
    }
  }
  return { date: v.date, ids: [...v.ids] };
}

/**
 * The whole-string pattern of a ticket ID with any configured prefix: group 1 the prefix, group 2 the
 * number as written.
 *
 * @param {{ types: Record<string, { prefix: string }> }} config
 * @returns {RegExp}
 */
function ticketIdPattern(config) {
  const prefixes = TICKET_TYPES.map((t) => config.types[t].prefix);
  return new RegExp(`^(${prefixes.join('|')})-(\\d+)$`);
}

/** The config fields after the schema check; `out` collects the messages. */
function tkcValidate(out, root, configPath, raw) {
  tkcUnknown(out, raw, TKC_KEYS, '');
  const register = raw.register === undefined ? TKC_DEFAULTS.register : tkcPath(out, 'register', raw.register);
  const configDir = posix.dirname(configPath);
  const tRoot = configDir;
  if (raw.root !== undefined) {
    const r = tkcPath(out, 'root', raw.root);
    if (r !== null && r !== configDir) out.push(`root ${r} must be the directory of the config file (${configDir})`);
  }
  let archiveDir = `${tRoot}/archive`;
  if (raw.archiveDir !== undefined) {
    const a = tkcPath(out, 'archiveDir', raw.archiveDir);
    if (a !== null) {
      if (inDir(a, tRoot, true)) archiveDir = a;
      else out.push(`archiveDir ${a} must lie inside root ${tRoot}`);
    }
  }
  let scheduleSection = TKC_DEFAULTS.scheduleSection;
  if (raw.scheduleSection !== undefined) {
    const s = raw.scheduleSection;
    if (tkcIsStr(s) && s.trim() === s && !/[\r\n]/.test(s)) scheduleSection = s;
    else out.push('scheduleSection must be a non-empty token');
  }
  const knownFacts = tkcKnownFacts(out, root, raw.knownFacts);
  let digits = TKC_DEFAULTS.digits;
  if (raw.digits !== undefined) {
    if (Number.isInteger(raw.digits) && raw.digits >= 3 && raw.digits <= 9) digits = raw.digits;
    else out.push('digits must be an integer from 3 to 9');
  }
  const types = tkcTypes(out, raw.types);
  const ticketDir = new RegExp(`^(${TICKET_TYPES.map((t) => types[t].prefix).join('|')})-\\d+(?:-|$)`, 'i');
  const between = archiveDir.slice(tRoot.length + 1).split('/').slice(0, -1);
  const inTicket = between.find((seg) => ticketDir.test(seg));
  if (inTicket !== undefined) out.push(`archiveDir ${archiveDir} must not lie inside a ticket directory (${inTicket})`);
  const implementable = tkcTypeList(out, 'implementable', raw.implementable, TKC_DEFAULTS.implementable);
  const homeRequired = tkcTypeList(out, 'homeRequired', raw.homeRequired, TKC_DEFAULTS.homeRequired);
  const limits = tkcLimits(out, raw.limits);
  const regions = tkcRegions(out, raw.regions, tRoot);
  const frozen = tkcFrozen(out, raw.frozen, types, digits);
  return {
    schema: TICKETS_SCHEMA, register, root: tRoot, archiveDir, scheduleSection, knownFacts, digits, types, implementable,
    homeRequired, limits, regions, frozen,
  };
}

/**
 * Reads and validates the tickets config, then loads the register it names (or `registerPath` when
 * given, as `--register` does). `config` is null when the config has a problem; `register` is null
 * when the config could not be read far enough to name a register.
 *
 * @param {string} root the repository root
 * @param {{ configPath?: string, registerPath?: string }} [opts]
 * @returns {{ configPath: string, config: object | null,
 *   problems: { rule: 'TV1', where: string, message: string, fix?: string[] }[],
 *   register: { data: object | null, registerPath: string } | null }}
 */
function loadTicketsConfig(root, { configPath = TICKETS_CONFIG_PATH, registerPath } = {}) {
  const label = normalizePath(configPath) ?? String(configPath);
  const problems = [];
  const fail = (message) => {
    problems.push({ rule: 'TV1', where: label, message });
    return { configPath: label, config: null, problems, register: null };
  };
  if (normalizePath(configPath) === null) return fail('the config path must be repository-relative');
  if (!label.includes('/')) return fail('the config file must lie in a directory below the repository root');
  let text;
  try {
    text = readFileSync(join(root, ...label.split('/')), 'utf8').replace(/^\uFEFF/, '');
  } catch (e) {
    const code = e && typeof e.code === 'string' ? e.code : 'unknown error';
    if (code === 'ENOENT') return fail('config file does not exist');
    if (code === 'EISDIR') return fail('the config path is a directory');
    return fail(`config file cannot be read (${code})`);
  }
  const conflict = conflictProblem(label, text, 'the config is not valid JSON until then');
  if (conflict !== null) {
    problems.push(conflict);
    return { configPath: label, config: null, problems, register: null };
  }
  let raw;
  try {
    raw = JSON.parse(text);
  } catch (e) {
    return fail(`not valid JSON: ${String(e && e.message !== undefined ? e.message : e)}`);
  }
  if (!tkcIsObj(raw)) return fail('the config must be a JSON object');
  if (raw.schema !== TICKETS_SCHEMA) {
    return fail(`schema must be ${JSON.stringify(TICKETS_SCHEMA)} (found ${raw.schema === undefined ? 'none' : JSON.stringify(raw.schema)})`);
  }
  const messages = [];
  const config = tkcValidate(messages, root, label, raw);
  for (const message of messages) problems.push({ rule: 'TV1', where: label, message });

  const regPath = tkcIsStr(registerPath) ? registerPath : config.register;
  let register = null;
  if (regPath !== null) {
    const loaded = loadRegister(root, { registerPath: regPath });
    let reason = loaded.data === null ? loaded.problems.map((p) => p.message).join('; ') : null;
    if (reason === null && !(tkcIsObj(loaded.data) && SUPPORTED_SCHEMAS.includes(loaded.data.schema))) {
      reason = tkcIsObj(loaded.data) ? `schema ${JSON.stringify(loaded.data.schema ?? null)} is not supported` : 'not a JSON object';
    }
    register = { data: reason === null ? loaded.data : null, registerPath: loaded.registerPath };
    if (reason !== null) {
      const hint = loaded.data === null && reason === 'register file does not exist' ? `; create it or correct "register" in ${label}` : '';
      const fix = loaded.registerPath === DEFAULTS.registerPath ? ['check'] : ['check', '--register', loaded.registerPath];
      problems.push({ rule: 'TV1', where: label, message: `register ${loaded.registerPath} cannot be read: ${reason}${hint}`, fix });
    }
  }
  return { configPath: label, config: messages.length === 0 ? config : null, problems, register };
}

// --- core/tickets/frontmatter.js ---
// The front matter of a `ticket.md` (tickets/1 §2.2): a strict subset of YAML that this module parses and
// writes without a library.
//
//   file    := "---\n" fmline+ "---\n" body
//   fmline  := key ":" ( " " value )? "\n"     no blank lines, no comments, no duplicate keys
//   value   := list | quoted | plain
//   list    := "[" "]" | "[" item ( "," " "* item )* "]"
//   item    := quoted | bare                    bare = [^\s,\[\]"][^,\[\]"]* (trimmed, non-empty)
//   quoted  := a JSON string literal
//   plain   := the rest of the line, trimmed, non-empty, not starting with '[' or '"'
//
// Every problem found here belongs to rule TV1 (format); the caller adds the rule and the file.

/** The keys of the front matter, in canonical (write) order. */
const FRONT_MATTER_KEYS = Object.freeze(['id', 'type', 'title', 'created', 'links', 'supersedes', 'resolution', 'closed', 'by']);

const TKFM_REQUIRED = Object.freeze(['id', 'type', 'title', 'created']);
/** The form each key takes: `plain`, `text` (plain or quoted), `list`, `any` (list, plain or quoted). */
const TKFM_FORMS = Object.freeze({
  id: 'plain', type: 'plain', title: 'text', created: 'plain', links: 'list', supersedes: 'plain', resolution: 'plain',
  closed: 'plain', by: 'any',
});
/** Why the keys a ticket deliberately lacks are not there (the message names where the fact lives). */
const TKFM_ABSENT = Object.freeze({
  status: 'tickets hold no status (computed by tickets status)',
  progress: 'tickets hold no progress (computed by tickets status)',
  parent: 'the directory is the parent',
  unit: 'the brief and the plan own the links to units, milestones and plans',
  milestone: 'the brief and the plan own the links to units, milestones and plans',
  plan: 'the brief and the plan own the links to units, milestones and plans',
  pr: 'tickets record no pull requests',
  estimate: "estimates live in the brief's milestone row",
  priority: 'order is written only where work is scheduled',
  assignee: 'tickets name no assignees or owners',
  owner: 'tickets name no assignees or owners',
});
const TKFM_TRAILING = 'trailing spaces after "---"';
const TKFM_LINE_RE = /^([A-Za-z_][A-Za-z0-9_-]*):(?: (.*))?$/;
const TKFM_BARE_RE = /^[^\s,[\]"][^,[\]"]*$/;

/**
 * Reads a JSON string literal starting at `s[i]` (a `"`). Returns the value and the index after the
 * closing quote, or null when the literal is broken.
 */
function tkfmQuoted(s, i) {
  let k = i + 1;
  while (k < s.length && s[k] !== '"') k += s[k] === '\\' ? 2 : 1;
  if (k >= s.length) return null;
  try {
    return { value: JSON.parse(s.slice(i, k + 1)), next: k + 1 };
  } catch {
    return null;
  }
}

/** Parses a list value `[…]`: `{ items }` or `{ error }`. */
function tkfmList(s) {
  const items = [];
  let i = 1;
  const skip = () => {
    while (i < s.length && (s[i] === ' ' || s[i] === '\t')) i += 1;
  };
  skip();
  if (s[i] === ']') return i + 1 === s.length ? { items } : { error: 'text after "]"' };
  for (;;) {
    skip();
    if (i >= s.length) return { error: 'no closing "]"' };
    if (s[i] === '"') {
      const q = tkfmQuoted(s, i);
      if (q === null) return { error: 'a quoted item is broken' };
      items.push(q.value);
      i = q.next;
    } else {
      let k = i;
      while (k < s.length && !',[]"'.includes(s[k])) k += 1;
      const bare = s.slice(i, k).trim();
      if (bare === '' || !TKFM_BARE_RE.test(bare)) {
        return { error: k < s.length && s[k] !== ',' && s[k] !== ']' ? `unexpected ${JSON.stringify(s[k])}` : 'an empty item' };
      }
      items.push(bare);
      i = k;
    }
    skip();
    if (i >= s.length) return { error: 'no closing "]"' };
    if (s[i] === ']') return i + 1 === s.length ? { items } : { error: 'text after "]"' };
    if (s[i] !== ',') return { error: `unexpected ${JSON.stringify(s[i])} after an item` };
    i += 1;
  }
}

/** One value: `{ value, form: 'list' | 'quoted' | 'plain' }` or `{ error }`. */
function tkfmValue(key, raw) {
  const v = raw.trim();
  if (v.startsWith('[')) {
    const l = tkfmList(v);
    return l.error !== undefined ? { error: `${JSON.stringify(key)} is not a valid list: ${l.error}` } : { value: l.items, form: 'list' };
  }
  if (v.startsWith('"')) {
    const q = tkfmQuoted(v, 0);
    if (q === null || q.next !== v.length) return { error: `${JSON.stringify(key)} is not a valid quoted string` };
    return { value: q.value, form: 'quoted' };
  }
  return { value: v, form: 'plain' };
}

/** The form problem of a known key, or null. */
function tkfmFormProblem(key, form) {
  const want = TKFM_FORMS[key];
  if (want === 'plain' && form !== 'plain') return `${JSON.stringify(key)} must be a plain value (no quotes, no list)`;
  if (want === 'text' && form === 'list') return `${JSON.stringify(key)} must be text, not a list`;
  if (want === 'list' && form !== 'list') return `${JSON.stringify(key)} must be a list [ … ]`;
  return null;
}

/**
 * Parses the front matter of a ticket. CRLF is read as LF. `lines` maps each key to its 1-based line;
 * `bodyStart` is the 0-based index of the first line after the closing `---` (`end` is that line's
 * 1-based number minus one, i.e. the closing line). Values: lists are string arrays, the rest strings.
 *
 * @param {string} text
 * @returns {{ ok: boolean, fields: Record<string, string | string[]>, lines: Record<string, number>,
 *   problems: { line: number, message: string }[], bodyStart: number, end: number }}
 */
function parseFrontMatter(text) {
  const all = String(text).replace(/^\uFEFF/, '').replace(/\r\n/g, '\n').split('\n');
  const fields = {};
  const lines = {};
  const problems = [];
  const isRule = (s) => s.replace(/[ \t]+$/, '') === '---';
  if (!isRule(all[0])) {
    problems.push({ line: 1, message: 'ticket.md must start with a front-matter line "---"' });
    return { ok: false, fields, lines, problems, bodyStart: 0, end: 0 };
  }
  if (all[0] !== '---') problems.push({ line: 1, message: TKFM_TRAILING });
  const close = all.findIndex((s, i) => i > 0 && isRule(s));
  if (close !== -1 && all[close] !== '---') problems.push({ line: close + 1, message: TKFM_TRAILING });
  if (close === -1) {
    problems.push({ line: 1, message: 'the front matter is not closed by a line "---"' });
    return { ok: false, fields, lines, problems, bodyStart: 0, end: 0 };
  }
  for (let i = 1; i < close; i += 1) {
    const line = i + 1;
    const s = all[i];
    if (s.trim() === '') {
      problems.push({ line, message: 'blank line in the front matter' });
      continue;
    }
    if (s.startsWith('#')) {
      problems.push({ line, message: 'comment in the front matter' });
      continue;
    }
    const m = TKFM_LINE_RE.exec(s);
    if (!m) {
      problems.push({ line, message: 'line is not "key: value"' });
      continue;
    }
    const key = m[1];
    if (!FRONT_MATTER_KEYS.includes(key)) {
      const lower = key.toLowerCase();
      const why = Object.hasOwn(TKFM_ABSENT, lower) ? `; ${TKFM_ABSENT[lower]}` : ` (allowed: ${FRONT_MATTER_KEYS.join(', ')})`;
      problems.push({ line, message: `unknown front-matter key ${JSON.stringify(key)}${why}` });
      continue;
    }
    if (Object.hasOwn(lines, key)) {
      problems.push({ line, message: `duplicate key ${JSON.stringify(key)}` });
      continue;
    }
    lines[key] = line;
    if (m[2] === undefined || m[2].trim() === '') {
      problems.push({ line, message: `${JSON.stringify(key)} has no value` });
      continue;
    }
    const v = tkfmValue(key, m[2]);
    if (v.error !== undefined) {
      problems.push({ line, message: v.error });
      continue;
    }
    const formProblem = tkfmFormProblem(key, v.form);
    if (formProblem !== null) {
      problems.push({ line, message: formProblem });
      continue;
    }
    if (key === 'title' && (v.value.trim() === '' || /[\r\n]/.test(v.value))) {
      problems.push({ line, message: '"title" must be one non-empty line' });
      continue;
    }
    if (key === 'created' && !isCalendarDate(v.value)) {
      problems.push({ line, message: '"created" must be a calendar date YYYY-MM-DD' });
      continue;
    }
    fields[key] = v.value;
  }
  for (const key of TKFM_REQUIRED) {
    if (!Object.hasOwn(lines, key)) problems.push({ line: 1, message: `missing required key ${JSON.stringify(key)}` });
  }
  return { ok: problems.length === 0, fields, lines, problems, bodyStart: close + 1, end: close + 1 };
}

/** A scalar as written: plain when it reads back unchanged, else a JSON string. */
function tkfmScalar(v) {
  const s = String(v);
  const plain = s !== '' && s.trim() === s && !s.startsWith('[') && !s.startsWith('"') && !/[\r\n]/.test(s);
  return plain ? s : JSON.stringify(s);
}

/** A list item as written: bare when it reads back unchanged, else a JSON string. */
function tkfmItem(v) {
  const s = String(v);
  return TKFM_BARE_RE.test(s) && s.trim() === s ? s : JSON.stringify(s);
}

/**
 * Writes a front-matter block (`---` lines included, LF, final newline) with the keys in canonical
 * order; keys whose value is undefined or null are left out, unknown keys are ignored.
 *
 * @param {Record<string, string | string[] | null | undefined>} fields
 * @returns {string}
 */
function formatFrontMatter(fields) {
  const out = ['---'];
  for (const key of FRONT_MATTER_KEYS) {
    const v = fields[key];
    if (v === undefined || v === null) continue;
    out.push(`${key}: ${Array.isArray(v) ? `[${v.map(tkfmItem).join(', ')}]` : tkfmScalar(v)}`);
  }
  out.push('---');
  return `${out.join('\n')}\n`;
}

// --- core/tickets/body.js ---
// The body of a `ticket.md` (tickets/1 §2.2-§2.4): the heading line, `## <title>` sections, the
// acceptance items `- A<n>: <text>` and the acceptance digest that plans pin on their `**Ticket:**` line.
// CRLF is read as LF everywhere; line numbers in results are 1-based, section bounds 0-based.

/** An acceptance item line (column 0). */
const TKB_ITEM_RE = /^- A([1-9]\d*): (\S.*)$/;
/** Any column-0 list item line. */
const TKB_LIST_RE = /^(?:[-*+]|\d+[.)])\s/;
const TKB_UNLABELED = 'acceptance item without a label; write "- A<n>: <text>"';
const TKB_ORDER = 'acceptance items must be numbered A1, A2, … in increasing order';

function tkbLf(text) {
  return String(text).replace(/\r\n/g, '\n');
}

/**
 * The first non-blank line at or after the 0-based line `bodyStart` (the line after the front matter).
 *
 * @param {string} text
 * @param {number} bodyStart
 * @returns {{ line: number, text: string } | null}
 */
function ticketHeading(text, bodyStart) {
  const lines = tkbLf(text).split('\n');
  for (let i = Math.max(0, bodyStart); i < lines.length; i += 1) {
    if (lines[i].trim() !== '') return { line: i + 1, text: lines[i] };
  }
  return null;
}

/**
 * Every level-2 heading (outside fences) whose text is exactly `title`, each with its section: from
 * the heading to the next heading of level 1 or 2 (exclusive), or to the end of the text.
 *
 * @param {string} text
 * @param {string} title
 * @returns {{ start: number, end: number }[]} 0-based line bounds, `start` is the heading line
 */
function bodySection(text, title) {
  const lf = tkbLf(text);
  const all = headings(lf);
  const total = lf.split('\n').length;
  return all
    .filter((h) => h.level === 2 && h.text === title)
    .map((h) => {
      const next = all.find((x) => x.index > h.index && x.level <= 2);
      return { start: h.index, end: next ? next.index : total };
    });
}

/**
 * The acceptance items of a ticket (§2.3): `- A<n>: <text>` lines at column 0 of the first
 * `## Acceptance` section, outside fences; continuation lines indented by two or more spaces join the
 * item's text. Problems: a second section, a column-0 list line without a label, numbers that do not
 * increase (gaps are allowed).
 *
 * @param {string} text
 * @returns {{ section: { start: number, end: number } | null,
 *   items: { n: number, id: string, text: string, line: number }[], problems: { line: number, message: string }[] }}
 */
function acceptanceItems(text) {
  const lf = tkbLf(text);
  const sections = bodySection(lf, 'Acceptance');
  const problems = sections.slice(1).map((s) => ({ line: s.start + 1, message: 'more than one "## Acceptance" section; keep one' }));
  if (sections.length === 0) return { section: null, items: [], problems };
  const section = sections[0];
  const lines = markFences(lf);
  const items = [];
  let last = 0;
  let current = null;
  for (let i = section.start + 1; i < section.end; i += 1) {
    const { text: s, fenced } = lines[i];
    if (fenced) {
      current = null;
      continue;
    }
    const m = TKB_ITEM_RE.exec(s);
    if (m) {
      const n = Number(m[1]);
      current = null;
      if (n <= last) {
        problems.push({ line: i + 1, message: TKB_ORDER });
        continue;
      }
      last = n;
      current = { n, id: `A${n}`, text: m[2].trim(), line: i + 1 };
      items.push(current);
      continue;
    }
    if (TKB_LIST_RE.test(s)) {
      problems.push({ line: i + 1, message: TKB_UNLABELED });
      current = null;
      continue;
    }
    if (current !== null && /^ {2,}\S/.test(s) && !TKB_LIST_RE.test(s.trim())) current.text = `${current.text} ${s.trim()}`;
    else current = null;
  }
  problems.sort((a, b) => a.line - b.line);
  return { section, items, problems };
}

/**
 * The acceptance digest (§2.4): the lines after the first `## Acceptance` heading up to the end of its
 * section, line-end whitespace stripped, leading and trailing blank lines dropped, runs of blank lines
 * collapsed to one, joined by LF; SHA-256 of that text, first 8 hex digits. null without the section.
 *
 * @param {string} text
 * @returns {string | null}
 */
function acceptanceDigest(text) {
  const lf = tkbLf(text);
  const sections = bodySection(lf, 'Acceptance');
  if (sections.length === 0) return null;
  const { start, end } = sections[0];
  const kept = [];
  for (const line of lf.split('\n').slice(start + 1, end).map((l) => l.replace(/[ \t]+$/, ''))) {
    if (line === '' && (kept.length === 0 || kept[kept.length - 1] === '')) continue;
    kept.push(line);
  }
  while (kept.length > 0 && kept[kept.length - 1] === '') kept.pop();
  return createHash('sha256').update(kept.join('\n'), 'utf8').digest('hex').slice(0, 8);
}

// --- core/tickets/tree.js ---
// The walk of the tickets tree (tickets/1 §2.6): the live tree under `root` and the archived subtrees
// under `archiveDir`. Finds the ticket directories, their `ticket.md`, child tickets and attachments
// (with sizes), and reports the problems the walk itself can see: TV1 (symbolic links, a ticket
// directory without `ticket.md`, a directory that is not a ticket directory where only ticket
// directories belong), TV2 (directory name, slug length, canonical number, a misnamed ticket directory:
// `TK-004` without a slug, a prefix in the wrong case, or any directory holding a `ticket.md`), TV3 (a ticket directory
// under an attachment directory, live tree only) and the path rules of TV11 (segments `plans` and
// `archive`/`archived`, path length).
//
// Symbolic links are never followed. Entries are read in code-unit order of their names, so the walk
// and its problems do not depend on the file system.

/**
 * The entries of a directory: `{ name, rel, kind: 'file' | 'dir' | 'link' | 'other', bytes }`, sorted. A
 * missing directory has none; any other read error is a TV1 problem.
 */
function tktEntries(ctx, rel) {
  const base = ctx.base;
  let names;
  try {
    names = readdirSync(join(base, ...rel.split('/')));
  } catch (e) {
    const code = e && typeof e.code === 'string' ? e.code : 'unknown error';
    if (code !== 'ENOENT') tktPush(ctx.out, 'TV1', rel, `directory cannot be read (${code})`);
    return [];
  }
  return names
    .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
    .map((name) => {
      const childRel = `${rel}/${name}`;
      let st = null;
      try {
        st = lstatSync(join(base, ...childRel.split('/')));
      } catch {
        // vanished between readdir and lstat: treated as another kind of entry
      }
      const kind = st === null ? 'other' : st.isSymbolicLink() ? 'link' : st.isDirectory() ? 'dir' : st.isFile() ? 'file' : 'other';
      return { name, rel: childRel, kind, bytes: st !== null && kind === 'file' ? st.size : 0 };
    });
}

function tktPush(out, rule, where, message) {
  out.push({ rule, where, message, fix: null });
}

/**
 * The TV2 message of a directory that looks like a ticket directory but does not match `<PREFIX>-<n>-`:
 * a name like `TK-004` or `tk-4-x` (prefix in any case, no slug), or any directory that holds a
 * `ticket.md`. null for any other directory.
 */
function tktMisnamed(ctx, e) {
  const m = ctx.candidate.exec(e.name);
  if (m) {
    const prefix = [...ctx.typeOf.keys()].find((p) => p.toLowerCase() === m[1].toLowerCase());
    const id = `${prefix}-${String(Number(m[2])).padStart(ctx.config.digits, '0')}`;
    return `directory name must be <ID>-<slug>; rename to ${id}-<slug>`;
  }
  let holds = false;
  try {
    lstatSync(join(ctx.base, ...e.rel.split('/'), 'ticket.md'));
    holds = true;
  } catch {
    // no ticket.md: a plain directory
  }
  return holds ? 'directory name must be <ID>-<slug>; rename it to <ID>-<slug> (it holds a ticket.md)' : null;
}

/** The TV11 path rules of one entry (its own name as the segment; its length when it is a file). */
function tktPathRules(ctx, e) {
  const { config, out } = ctx;
  if (e.name === 'plans') {
    tktPush(out, 'TV11', e.rel, `path segment "plans" under ${config.root}/ would match the plan hooks; rename it`);
  }
  const a = config.archiveDir;
  if (/^archived?$/i.test(e.name) && e.rel !== a && !inDir(e.rel, a, true) && !inDir(a, e.rel, true)) {
    tktPush(out, 'TV11', e.rel, `path segment ${JSON.stringify(e.name)} outside ${a}/; rename it`);
  }
  if (e.kind === 'file' && e.rel.length > config.limits.pathLength) {
    tktPush(out, 'TV11', e.rel, `path has ${e.rel.length} characters; at most ${config.limits.pathLength}`);
  }
}

/** Every file below an attachment directory becomes an attachment of `ticket`. */
function tktAttachments(ctx, rel, ticket) {
  for (const e of tktEntries(ctx, rel)) {
    tktPathRules(ctx, e);
    if (e.kind === 'link') {
      tktPush(ctx.out, 'TV1', e.rel, 'symbolic link; the tickets tree holds no links (not followed)');
    } else if (e.kind === 'dir') {
      const misnamed = ctx.loose.test(e.name) ? null : tktMisnamed(ctx, e);
      if (ctx.loose.test(e.name)) {
        if (!ticket.archived) {
          tktPush(ctx.out, 'TV3', e.rel, `ticket directory under the attachment directory ${rel}; move it up or rename it`);
        }
      } else if (misnamed !== null) {
        tktPush(ctx.out, 'TV2', e.rel, misnamed);
      } else {
        tktAttachments(ctx, e.rel, ticket);
      }
    } else if (e.kind === 'file') {
      ticket.attachments.push({ path: e.rel, bytes: e.bytes });
    }
  }
}

/** A ticket directory and, recursively, its child tickets and attachments. */
function tktTicket(ctx, e, parent, depth, archived) {
  const { config, out } = ctx;
  const m = ctx.loose.exec(e.name);
  const prefix = m[1];
  const number = Number(m[2]);
  const id = `${prefix}-${m[2]}`;
  const strict = ctx.strict.exec(e.name);
  const ticket = {
    id,
    prefix,
    number,
    type: ctx.typeOf.get(prefix),
    dir: e.rel,
    name: e.name,
    slug: strict ? strict[3] : null,
    file: `${e.rel}/ticket.md`,
    text: null,
    parent: parent === null ? null : parent.id,
    depth,
    archived,
    children: [],
    attachments: [],
  };
  ctx.tickets.push(ticket);
  if (!strict) {
    tktPush(out, 'TV2', e.rel, 'directory name must be <ID>-<slug>, the slug lowercase letters and digits joined by "-"');
  } else if (strict[3].length > config.limits.slugLength) {
    tktPush(out, 'TV2', e.rel, `slug has ${strict[3].length} characters; at most ${config.limits.slugLength}`);
  }
  const canonical = `${prefix}-${String(number).padStart(config.digits, '0')}`;
  if (number < 1) tktPush(out, 'TV2', e.rel, `ticket numbers start at 1 (found ${id})`);
  else if (canonical !== id) tktPush(out, 'TV2', e.rel, `${id} is not canonical; write ${canonical}`);

  let hasTicketMd = false;
  const children = [];
  for (const c of tktEntries(ctx, e.rel)) {
    tktPathRules(ctx, c);
    if (c.name === 'ticket.md') hasTicketMd = true;
    if (c.kind === 'link') {
      tktPush(out, 'TV1', c.rel, 'symbolic link; the tickets tree holds no links (not followed)');
    } else if (c.name === 'ticket.md') {
      if (c.kind === 'file') {
        try {
          ticket.text = readFileSync(join(ctx.base, ...c.rel.split('/')), 'utf8').replace(/\r\n/g, '\n');
        } catch {
          tktPush(out, 'TV1', c.rel, 'ticket.md cannot be read');
        }
      } else {
        tktPush(out, 'TV1', c.rel, 'ticket.md is not a regular file');
      }
    } else if (c.kind === 'dir') {
      const misnamed = ctx.loose.test(c.name) ? null : tktMisnamed(ctx, c);
      if (ctx.loose.test(c.name)) children.push(tktTicket(ctx, c, ticket, depth + 1, archived));
      else if (misnamed !== null) tktPush(out, 'TV2', c.rel, misnamed);
      else tktAttachments(ctx, c.rel, ticket);
    } else if (c.kind === 'file') {
      ticket.attachments.push({ path: c.rel, bytes: c.bytes });
    }
  }
  if (!hasTicketMd) tktPush(out, 'TV1', e.rel, 'ticket directory has no ticket.md');
  const order = (t) => TICKET_TYPES.indexOf(t.type);
  children.sort((a, b) => order(a) - order(b) || a.number - b.number || (a.dir < b.dir ? -1 : a.dir > b.dir ? 1 : 0));
  ticket.children = children.map((c) => c.id);
  return ticket;
}

/** The archive: only archived top-level ticket directories. */
function tktArchive(ctx, rel) {
  for (const e of tktEntries(ctx, rel)) {
    tktPathRules(ctx, e);
    if (e.kind === 'link') {
      tktPush(ctx.out, 'TV1', e.rel, 'symbolic link; the tickets tree holds no links (not followed)');
    } else if (e.kind === 'dir' && ctx.loose.test(e.name)) {
      tktTicket(ctx, e, null, 1, true);
    } else if (e.kind === 'dir') {
      const misnamed = tktMisnamed(ctx, e);
      if (misnamed !== null) tktPush(ctx.out, 'TV2', e.rel, misnamed);
      else tktPush(ctx.out, 'TV1', e.rel, 'not a ticket directory');
    } else {
      tktPush(ctx.out, 'TV1', e.rel, `only ticket directories belong in ${ctx.config.archiveDir}/`);
    }
  }
}

/** The root (and the directories on the way to a deeper archive): ticket directories and plain files. */
function tktContainer(ctx, rel) {
  for (const e of tktEntries(ctx, rel)) {
    tktPathRules(ctx, e);
    if (e.kind === 'link') {
      tktPush(ctx.out, 'TV1', e.rel, 'symbolic link; the tickets tree holds no links (not followed)');
    } else if (e.kind === 'dir') {
      if (e.rel === ctx.config.archiveDir) tktArchive(ctx, e.rel);
      else if (ctx.loose.test(e.name)) tktTicket(ctx, e, null, 1, false);
      else if (inDir(ctx.config.archiveDir, e.rel, true)) tktContainer(ctx, e.rel);
      else if (tktMisnamed(ctx, e) !== null) tktPush(ctx.out, 'TV2', e.rel, tktMisnamed(ctx, e));
      else tktPush(ctx.out, 'TV1', e.rel, 'not a ticket directory');
    }
  }
}

/**
 * Walks the tickets tree of a valid config. Tickets come in walk order (pre-order, names sorted);
 * `children` lists child IDs in type order, then number. `text` is the LF text of `ticket.md` (null
 * when it is missing or not a regular file); `type` is the type of the directory's prefix.
 *
 * @param {string} root the repository root
 * @param {object} config a config returned by loadTicketsConfig
 * @returns {{ tickets: object[], problems: { rule: string, where: string, message: string, fix: null }[] }}
 */
function scanTickets(root, config) {
  const prefixes = TICKET_TYPES.map((t) => config.types[t].prefix).join('|');
  const ctx = {
    base: root,
    config,
    out: [],
    tickets: [],
    loose: new RegExp(`^(${prefixes})-(\\d+)-`),
    strict: new RegExp(`^(${prefixes})-(\\d+)-([a-z0-9]+(?:-[a-z0-9]+)*)$`),
    candidate: new RegExp(`^(${prefixes})-(\\d+)(?:-|$)`, 'i'),
    typeOf: new Map(TICKET_TYPES.map((t) => [config.types[t].prefix, t])),
  };
  tktContainer(ctx, config.root);
  return { tickets: ctx.tickets, problems: ctx.out };
}

// --- core/tickets/plans.js ---
// What the tickets rules read from the plans and briefs of the register (tickets/1 §2.3, §2.4, §3):
// the rows of the Milestones table of a brief, the `### Task N:` sections of a plan with their
// `**Ticket:**` lines, acceptance citations `(<ID>/A<n>)` and box counts, and the entries of one
// `**Ticket:**` line. Nothing here knows the tickets tree or the register; the rules join them.
//
// CRLF is read as LF. Line numbers in results are 1-based; section bounds are 0-based (end exclusive).
// Problems are `{ line, message }`; the caller adds the rule and the file.

/** A plan task heading: `### Task 3: <title>` (group 1 the number). */
const TKP_TASK_RE = /^Task ([1-9]\d*):/;
/** The `**Ticket:**` line at column 0 (group 1 the value). */
const TKP_TICKET_RE = /^\*\*Ticket:\*\*[ \t]+(.+?)[ \t]*$/;
/** Any `**Ticket:**` label at column 0, also without a value (a line with no value is a grammar problem). */
const TKP_TICKET_LABEL_RE = /^\*\*Ticket:\*\*/;
/** A `**Ticket:**` label that is indented or in a blockquote (not read as a Ticket line). */
const TKP_TICKET_INDENTED_RE = /^[ \t>]+\*\*Ticket:\*\*/;
/** A GFM table delimiter row: `| --- | :--: |`. */
const TKP_DELIM_RE = /^\s*\|?\s*:?-+:?\s*(?:\|\s*:?-+:?\s*)*\|?\s*$/;
/** Plan(s) cell words that mean "no plan". */
const TKP_NO_PLAN = Object.freeze(['none', '—', '-', '–']);
/** A plan name candidate after cleaning: the basename of a plan file without `.md`. */
const TKP_SLUG_RE = /^[A-Za-z0-9._-]+$/;

function tkpLf(text) {
  return String(text).replace(/\r\n/g, '\n');
}

/** The prefixes of the config, in type order, joined for a regex alternation. */
function tkpPrefixes(config) {
  return TICKET_TYPES.map((t) => config.types[t].prefix).join('|');
}

/**
 * The cells of a GFM table row: the outer pipes dropped, split on unescaped `|` (a `\|` stays in the
 * cell as `|`), each trimmed.
 */
function tkpCells(line) {
  let s = line.trim();
  if (s.startsWith('|')) s = s.slice(1);
  if (s.endsWith('|') && !s.endsWith('\\|')) s = s.slice(0, -1);
  const cells = [];
  let cur = '';
  for (let i = 0; i < s.length; i += 1) {
    if (s[i] === '\\' && s[i + 1] === '|') {
      cur += '|';
      i += 1;
    } else if (s[i] === '|') {
      cells.push(cur.trim());
      cur = '';
    } else {
      cur += s[i];
    }
  }
  cells.push(cur.trim());
  return cells;
}

/** A header cell as a name: `**`, `__` and backticks stripped, trimmed, lower case. */
function tkpHeaderName(text) {
  return text.replace(/\*\*|__|`/g, '').trim().toLowerCase();
}

/**
 * The plan names of a Plan(s) cell (§3): code-span contents, link targets and comma or space separated
 * words; each drops `#…`, takes the basename and strips `.md`. `none` when every candidate means "no plan".
 *
 * @returns {{ none: boolean, names: string[] }}
 */
function tkpPlanNames(text) {
  const raw = [];
  let rest = String(text).replace(/`([^`]*)`/g, (_, code) => {
    raw.push(code.trim());
    return ' ';
  });
  rest = rest.replace(/!?\[([^\]]*)\]\(([^)\s]*)[^)]*\)/g, (_, label, target) => {
    raw.push(target);
    return ` ${label} `;
  });
  raw.push(...rest.split(/[\s,]+/));
  const names = [];
  for (const r of raw) {
    for (const w of r.split(/[\s,]+/)) {
      let c = w.replace(/^[[(*_]+|[\])*_.;:]+$/g, '');
      const hash = c.indexOf('#');
      if (hash !== -1) c = c.slice(0, hash);
      c = c.slice(c.lastIndexOf('/') + 1).replace(/\.md$/, '');
      if (c === '' || TKP_NO_PLAN.includes(c.toLowerCase()) || !TKP_SLUG_RE.test(c) || /^[.-]+$/.test(c)) continue;
      if (!names.includes(c)) names.push(c);
    }
  }
  return { none: names.length === 0, names };
}

/**
 * The rows of the Milestones table of a brief (§3, TV7). The range is the brief's `section` when given
 * (found like V7 does), else the whole file. In it, the one heading that contains `scheduleSection` as a
 * token, then the first GFM table of that heading's section. A table without a `Tickets` column
 * schedules nothing (`tickets: false`). When it has one, a `Milestone` column is required.
 *
 * Each row: `line` (1-based), `milestone` (the cell text, `**`/backticks stripped), `ids` (ticket IDs
 * named in the Tickets cell as tokens, in order, without repeats; free text is ignored),
 * `plans` (plan names of the Plan(s) cell, see tkpPlanNames; [] without that column), `noPlan`.
 *
 * @param {string} text the brief
 * @param {{ scheduleSection: string, types: object }} config
 * @param {{ section?: string }} [opts]
 * @returns {{ found: boolean, tickets: boolean, heading: number | null, rows: object[],
 *   problems: { line: number, message: string }[] }}
 */
function scheduleRows(text, config, { section } = {}) {
  const lf = tkpLf(text);
  const lines = markFences(lf);
  const none = (problems = []) => ({ found: false, tickets: false, heading: null, rows: [], problems });
  let from = 0;
  let to = lines.length;
  if (typeof section === 'string' && section !== '') {
    const r = findSection(lf, section);
    if (!r.ok) return none();
    from = r.start;
    to = r.end;
  }
  const inRange = headings(lf).filter((h) => h.index >= from && h.index < to);
  const word = config.scheduleSection;
  const matches = inRange.filter((h) => tokenMatch(h.text, word));
  if (matches.length === 0) return none();
  if (matches.length > 1) {
    return none([{
      line: matches[1].index + 1,
      message: `${matches.length} headings name "${word}" (lines ${matches.map((h) => h.index + 1).join(', ')}); keep one`,
    }]);
  }
  const h = matches[0];
  const next = inRange.find((x) => x.index > h.index && x.level <= h.level);
  const end = next ? next.index : to;
  let at = -1;
  for (let i = h.index + 1; i + 1 < end; i += 1) {
    if (lines[i].fenced || lines[i + 1].fenced) continue;
    if (lines[i].text.includes('|') && TKP_DELIM_RE.test(lines[i + 1].text) && lines[i + 1].text.includes('-')) {
      at = i;
      break;
    }
  }
  const result = { found: true, tickets: false, heading: h.index + 1, rows: [], problems: [] };
  if (at === -1) return result;
  const header = tkpCells(lines[at].text).map(tkpHeaderName);
  const col = (names) => header.findIndex((c) => names.includes(c));
  const ticketsCol = col(['tickets']);
  if (ticketsCol === -1) return result;
  result.tickets = true;
  const milestoneCol = col(['milestone']);
  const planCol = col(['plan(s)', 'plans', 'plan']);
  if (milestoneCol === -1) {
    result.problems.push({ line: at + 1, message: `the ${word} table has a Tickets column but no Milestone column` });
    return result;
  }
  const idRe = new RegExp(`(?<![\\w-])(?:${tkpPrefixes(config)})-\\d+(?![\\w]|-\\w)`, 'g');
  for (let i = at + 2; i < end; i += 1) {
    const { text: s, fenced } = lines[i];
    if (fenced || !s.includes('|') || s.trim() === '') break;
    const cells = tkpCells(s);
    const ids = [];
    for (const m of (cells[ticketsCol] ?? '').matchAll(idRe)) if (!ids.includes(m[0])) ids.push(m[0]);
    const plan = planCol === -1 ? { none: true, names: [] } : tkpPlanNames(cells[planCol] ?? '');
    result.rows.push({
      line: i + 1,
      milestone: (cells[milestoneCol] ?? '').replace(/\*\*|__|`/g, '').trim(),
      ids,
      plans: plan.names,
      noPlan: plan.none,
    });
  }
  return result;
}

/**
 * The entries of one `**Ticket:**` value (§2.4): split on `,`, each trimmed entry `<ID>` or
 * `<ID> @<8 hex>`. An entry that does not match is a problem; an ID named twice is a problem.
 *
 * @param {string} value the text after the label
 * @param {{ types: object }} config
 * @returns {{ entries: { id: string, digest: string | null }[], problems: string[] }}
 */
function ticketLineEntries(value, config) {
  const re = new RegExp(`^((?:${tkpPrefixes(config)})-\\d+)(?:[ \\t]+@([0-9a-f]{8}))?$`);
  const entries = [];
  const problems = [];
  for (const part of String(value).split(',')) {
    const e = part.trim();
    const m = re.exec(e);
    if (!m) {
      problems.push(`**Ticket:** entry ${JSON.stringify(e)} must be "<ID>" or "<ID> @<8 hex digits>"`);
    } else if (entries.some((x) => x.id === m[1])) {
      problems.push(`**Ticket:** names ${m[1]} twice`);
    } else {
      entries.push({ id: m[1], digest: m[2] ?? null });
    }
  }
  return { entries, problems };
}

/**
 * The `### Task N:` sections of a plan (§3). A section runs from its heading to the next heading of
 * level 3 or higher. Each task: `n`, `line` (1-based heading line), `start`/`end` (0-based), `ticket`
 * (`{ line, entries }` of its `**Ticket:**` line, or null), `citations` (`{ line, id, item }` of every
 * `(<ID>/A<n>)` outside fences), `boxes` (`countCheckboxes` of the section: `done`, `total`,
 * `skipped`). Problems (§3 TV6 (1)-(3)): a `### Task <ID>` heading, a `**Ticket:**` line outside a task
 * or a second one in a task, and the grammar of the entries.
 *
 * @param {string} text the plan
 * @param {{ types: object }} config
 * @returns {{ tasks: object[], problems: { line: number, message: string }[] }}
 */
function planTasks(text, config) {
  const lf = tkpLf(text);
  const lines = markFences(lf);
  const all = headings(lf);
  const prefixes = tkpPrefixes(config);
  const idTask = new RegExp(`^Task ((?:${prefixes})-\\d+)\\b`);
  const cite = new RegExp(`\\(((?:${prefixes})-\\d+)\\/A([1-9]\\d*)\\)`, 'g');
  const problems = [];
  const tasks = [];
  // The end of a task section is the next heading of level 3 or higher: found once, from the back.
  const sectionEnd = new Array(all.length);
  let nextTop = lines.length;
  for (let k = all.length - 1; k >= 0; k -= 1) {
    sectionEnd[k] = nextTop;
    if (all[k].level <= 3) nextTop = all[k].index;
  }
  const taskOf = new Array(lines.length).fill(undefined);
  all.forEach((h, k) => {
    if (h.level !== 3) return;
    const bad = idTask.exec(h.text);
    if (bad) {
      problems.push({
        line: h.index + 1,
        message: `### Task ${bad[1]}: plan task headings are numbered "### Task N:"; name the ticket on a **Ticket:** line`,
      });
      return;
    }
    const m = TKP_TASK_RE.exec(h.text);
    if (!m) return;
    const end = sectionEnd[k];
    const counted = countCheckboxes(lines.slice(h.index, end).map((l) => l.text).join('\n'));
    const task = {
      n: Number(m[1]), line: h.index + 1, start: h.index, end, ticket: null, citations: [],
      boxes: { done: counted.done, total: counted.total, skipped: counted.skipped },
    };
    tasks.push(task);
    for (let i = h.index + 1; i < end; i += 1) taskOf[i] = task;
  });
  for (let i = 0; i < lines.length; i += 1) {
    const { text: s, fenced } = lines[i];
    if (fenced) continue;
    const task = taskOf[i];
    if (TKP_TICKET_LABEL_RE.test(s)) {
      if (task === undefined) {
        problems.push({ line: i + 1, message: '**Ticket:** line outside a "### Task N:" section' });
        continue;
      }
      if (task.ticket !== null) {
        problems.push({ line: i + 1, message: `Task ${task.n} has a second **Ticket:** line (first on line ${task.ticket.line}); name every ticket on one line` });
        continue;
      }
      const v = TKP_TICKET_RE.exec(s);
      const parsed = v ? ticketLineEntries(v[1], config) : { entries: [], problems: ['**Ticket:** line has no entries'] };
      task.ticket = { line: i + 1, entries: parsed.entries };
      for (const message of parsed.problems) problems.push({ line: i + 1, message });
    }
    else if (TKP_TICKET_INDENTED_RE.test(s)) {
      problems.push({ line: i + 1, message: '**Ticket:** must start at column 0 (an indented or quoted line is not read)' });
    }
    if (task === undefined) continue;
    for (const c of s.matchAll(cite)) task.citations.push({ line: i + 1, id: c[1], item: `A${c[2]}` });
  }
  problems.sort((a, b) => a.line - b.line);
  return { tasks, problems };
}

// --- core/tickets/state.js ---
// The join of the tickets tree with the register and its plans (tickets/1 §3, §4.4): which brief rows
// schedule a ticket, which plan tasks implement it, and the computed state of a ticket. Read-only; the
// rules (core/tickets/rules.js) and the read views use it.
//
// Scheduling row = a data row of the Milestones table of a registered brief that names the ID in its
// Tickets column. Implementing task = a `### Task N:` section of a registered executable plan whose
// `**Ticket:**` line names the ID. Closed task = total > 0 && done === total; skip-only = total > 0 &&
// skipped === total; implementation = closed and not skip-only.

/** The computed states of an open ticket, lowest first. */
const TKS_ORDER = Object.freeze(['backlog', 'scheduled', 'planned', 'in progress']);

function tksIsObj(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

function tksArr(v) {
  return Array.isArray(v) ? v : [];
}

/** The name of a plan file: its basename without `.md`. */
function tksPlanName(path) {
  return path.slice(path.lastIndexOf('/') + 1).replace(/\.md$/, '');
}

/** `true` when the ticket carries a resolution (a resolved ticket is closed). */
function tksResolved(t) {
  return t.fields !== undefined && typeof t.fields.resolution === 'string';
}

/**
 * The model of the tickets against the register: the units, every registered executable plan (read once,
 * with its tasks; `missing` when its file is not there; `active` when it lies outside the register's `archive.dir`), every brief entry of a
 * unit with its Milestones rows (`unit`, `path`, and the fields of `scheduleRows`), the set of registered
 * paths, and per ticket ID its scheduling rows and implementing tasks.
 *
 * scheduling: ID -> `{ unit, status, open, brief, line, milestone, plans }[]` (`plans` = the plans the
 * row's Plan(s) cell names that are registered as executable for that unit).
 * implementing: ID -> `{ plan, task, n, line, boxes, closed, skipOnly, implementation, active }[]`.
 *
 * @param {string} root the repository root
 * @param {object} config a tickets config (loadTicketsConfig)
 * @param {object} data the register
 * @param {object[]} tickets the tickets of scanTickets (with `fields` set)
 * @returns {object}
 */
function ticketModel(root, config, data, tickets) {
  const fsv = createFsView(root);
  const cfg = tksIsObj(data.config) ? data.config : {};
  const archive = tksIsObj(cfg.archive) ? normalizePath(cfg.archive.dir) : null;
  const units = tksArr(data.units).filter((u) => tksIsObj(u) && typeof u.key === 'string');
  const plans = new Map();
  const briefs = [];
  const registered = new Set();
  for (const u of units) {
    for (const e of tksArr(u.plans)) {
      const path = tksIsObj(e) ? normalizePath(e.path) : null;
      if (path === null) continue;
      registered.add(path);
      const text = fsv.isFile(path) ? fsv.readText(path) : null;
      if (e.role === 'executable') {
        if (!plans.has(path)) {
          const parsed = text === null ? { tasks: [], problems: [] } : planTasks(text, config);
          plans.set(path, {
            path, name: tksPlanName(path), text, missing: text === null, units: [], tasks: parsed.tasks, problems: parsed.problems,
            active: archive === null || !inDir(path, archive, true),
          });
        }
        if (!plans.get(path).units.includes(u.key)) plans.get(path).units.push(u.key);
      } else if (e.role === 'brief' && text !== null) {
        const section = typeof e.section === 'string' && e.section !== '' ? e.section : undefined;
        briefs.push({ unit: u, path, ...scheduleRows(text, config, { section }) });
      }
    }
  }
  const model = {
    fsv, data, archive, units, plans, briefs, registered,
    byId: new Map(tickets.map((t) => [t.id, t])),
    scheduling: new Map(),
    implementing: new Map(),
  };
  const push = (map, id, v) => {
    if (!map.has(id)) map.set(id, []);
    map.get(id).push(v);
  };
  for (const brief of briefs) {
    const byName = unitPlans(model, brief.unit.key);
    const status = brief.unit.status;
    for (const row of brief.rows) {
      for (const id of row.ids) {
        push(model.scheduling, id, {
          unit: brief.unit.key, status, open: !CLOSED_STATUSES.includes(status), brief: brief.path, line: row.line,
          milestone: row.milestone, plans: row.plans.flatMap((n) => byName.get(n) ?? []),
        });
      }
    }
  }
  for (const plan of plans.values()) {
    for (const task of plan.tasks) {
      if (task.ticket === null) continue;
      const { done, total, skipped } = task.boxes;
      const closed = total > 0 && done === total;
      const skipOnly = total > 0 && skipped === total;
      for (const e of task.ticket.entries) {
        push(model.implementing, e.id, {
          plan, task, n: task.n, line: task.ticket.line, boxes: task.boxes, closed, skipOnly,
          implementation: closed && !skipOnly, active: plan.active,
        });
      }
    }
  }
  return model;
}

/**
 * The executable plans registered for a unit, by plan name.
 *
 * @param {object} model a ticketModel
 * @param {string} key
 * @returns {Map<string, object[]>}
 */
function unitPlans(model, key) {
  const byName = new Map();
  for (const p of model.plans.values()) {
    if (!p.units.includes(key)) continue;
    if (!byName.has(p.name)) byName.set(p.name, []);
    byName.get(p.name).push(p);
  }
  return byName;
}

/** The state of a ticket from its own tasks and rows (children not considered). */
function tksOwnState(model, t) {
  const tasks = model.implementing.get(t.id) ?? [];
  if (tasks.some((k) => k.boxes.done - k.boxes.skipped > 0)) return 'in progress';
  if (tasks.length > 0) return 'planned';
  if ((model.scheduling.get(t.id) ?? []).some((r) => r.open)) return 'scheduled';
  return 'backlog';
}

/**
 * The computed state of a ticket (§4.4): `closed` when resolved; else for a leaf `in progress` when an
 * implementing task has a `[x]` box, `planned` when it has an implementing task, `scheduled` when a row
 * of an open unit schedules it, else `backlog`. A ticket with children takes the highest state of itself
 * and its open descendants. null for an unknown ID.
 *
 * @param {object} model a ticketModel
 * @param {string} id
 * @returns {'closed' | 'in progress' | 'planned' | 'scheduled' | 'backlog' | null}
 */
function ticketState(model, id) {
  const t = model.byId.get(id);
  if (t === undefined) return null;
  if (tksResolved(t)) return 'closed';
  let best = TKS_ORDER.indexOf(tksOwnState(model, t));
  const stack = [...t.children];
  const seen = new Set([t.id]);
  while (stack.length > 0) {
    const c = model.byId.get(stack.pop());
    if (c === undefined || seen.has(c.id)) continue;
    seen.add(c.id);
    if (!tksResolved(c)) best = Math.max(best, TKS_ORDER.indexOf(tksOwnState(model, c)));
    stack.push(...c.children);
  }
  return TKS_ORDER[best];
}

// --- core/tickets/render.js ---
// The tickets index region (`tickets-index`, tickets/1 §4.5): the open tickets that are scheduled or
// planned, the open backlog and the closed live tickets, each a table, and the archived count. The
// region never shows "in progress" or box counts, so ticking a plan box never changes it; it changes when
// a ticket is added, moved, closed, scheduled, or named by a newly registered plan.
//
// Also the slim ticket excerpt of `tickets brief` (§4.6): a ticket map with the `**Ticket:**` line to
// write on a plan task, then each ticket cut to the excerpt sections of its type (headings demoted one
// level); the other sections and the attachments are listed by path only.
//
// Links are relative to the region file (relLink), cells are escaped (cell). Rows are sorted by type
// order, then number. Region files are read and written with LF; a file is written only when one of its
// regions changes.

const TKRD_NONE = '—';
/** The excerpt sections of each type (fixed in tickets/1). */
const TKRD_EXCERPT = Object.freeze({
  task: Object.freeze(['Why', 'What', 'Acceptance']),
  story: Object.freeze(['Outcome', 'Acceptance']),
  defect: Object.freeze(['Observed', 'Expected', 'Acceptance']),
  epic: Object.freeze(['Goal', 'Exit']),
  idea: Object.freeze(['Idea']),
});

function tkrdResolved(t) {
  return typeof t.fields.resolution === 'string';
}

/** One table, or `none` when there are no rows. */
function tkrdTable(title, header, rows) {
  const lines = [`**${title}** (${rows.length}):`, ''];
  if (rows.length === 0) {
    lines.push('none');
  } else {
    lines.push(`| ${header.join(' | ')} |`, `| ${header.map(() => '---').join(' | ')} |`);
    for (const r of rows) lines.push(`| ${r.map(cell).join(' | ')} |`);
  }
  return lines.join('\n');
}

/**
 * The content of the tickets index region (without its markers): a generated-by comment, then the
 * groups "Open, scheduled" (open tickets whose computed state is not backlog), "Open, backlog" and
 * "Closed" (live tickets only), then the number of archived tickets with a link to the archive.
 *
 * @param {object} config a tickets config
 * @param {object[]} tickets the tickets of scanTickets with `fields` set
 * @param {object} tm the ticketModel
 * @param {string} linkFrom the region file (links are relative to it)
 * @param {string} configPath the tickets config path (named in the comment)
 * @returns {string}
 */
function renderTicketsIndex(config, tickets, tm, linkFrom, configPath) {
  const order = (t) => TICKET_TYPES.indexOf(t.type);
  const live = tickets.filter((t) => !t.archived)
    .sort((a, b) => order(a) - order(b) || a.number - b.number || (a.dir < b.dir ? -1 : a.dir > b.dir ? 1 : 0));
  const link = (t) => `[${t.id}](${relLink(linkFrom, t.file)})`;
  const parent = (t) => t.parent ?? TKRD_NONE;
  const scheduled = [];
  const backlog = [];
  const closed = [];
  for (const t of live) {
    if (tkrdResolved(t)) {
      closed.push([link(t), t.type, t.fields.title, parent(t), t.fields.resolution, t.fields.closed ?? '']);
      continue;
    }
    const state = ticketState(tm, t.id);
    if (state === 'backlog') {
      backlog.push([link(t), t.type, t.fields.title, parent(t), t.fields.created ?? '']);
      continue;
    }
    let stateCell = state === 'scheduled' ? 'scheduled' : 'planned';
    if (t.children.length > 0) {
      const done = t.children.filter((id) => {
        const c = tm.byId.get(id);
        return c !== undefined && tkrdResolved(c);
      }).length;
      stateCell = `${done}/${t.children.length} children closed`;
    }
    const rows = [...new Set((tm.scheduling.get(t.id) ?? []).filter((r) => r.open).map((r) => `${r.unit} ${r.milestone}`))];
    const tasks = (tm.implementing.get(t.id) ?? [])
      .map((k) => [k.plan.name, k.n])
      .sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : a[1] - b[1]))
      .map(([name, n]) => `${name}#${n}`);
    scheduled.push([link(t), t.type, t.fields.title, parent(t), stateCell,
      rows.length > 0 ? rows.join(', ') : TKRD_NONE, tasks.length > 0 ? [...new Set(tasks)].join(', ') : TKRD_NONE]);
  }
  const archived = tickets.filter((t) => t.archived).length;
  const archiveName = config.archiveDir.slice(config.archiveDir.lastIndexOf('/') + 1);
  const source = String(configPath).replace(/-->/g, '--&gt;').replace(/\r?\n/g, ' ');
  return [
    [
      `<!-- Generated by plan-register tickets from ${source}, the tickets and the register.`,
      '     Do not edit by hand: change the tickets, then run "tickets write". -->',
    ].join('\n'),
    tkrdTable('Open, scheduled', ['Ticket', 'Type', 'Title', 'Parent', 'State', 'Scheduled in', 'Implemented by'], scheduled),
    tkrdTable('Open, backlog', ['Ticket', 'Type', 'Title', 'Parent', 'Created'], backlog),
    tkrdTable('Closed', ['Ticket', 'Type', 'Title', 'Parent', 'Resolution', 'Closed'], closed),
    `Archived: ${archived} ticket(s) in [${archiveName}/](${relLink(linkFrom, config.archiveDir)}/).`,
  ].join('\n\n');
}

/**
 * The state of every configured region: `{ file, marker, label, error }` when the file is missing or its
 * markers are broken, else `{ file, marker, label, text, content, expected }`.
 *
 * @param {object} config
 * @param {object[]} tickets
 * @param {object} tm the ticketModel (its `fsv` reads the files)
 * @param {string} configPath
 * @returns {object[]}
 */
function ticketsRegionStates(config, tickets, tm, configPath) {
  return config.regions.map((r) => {
    const label = `${r.file} (${r.marker})`;
    const base = { file: r.file, marker: r.marker, label };
    const text = tm.fsv.isFile(r.file) ? tm.fsv.readText(r.file) : null;
    if (text === null) return { ...base, error: 'region file does not exist' };
    const got = extractRegion(text, r.marker, label);
    if (!got.ok) return { ...base, error: got.message.startsWith(`${label}: `) ? got.message.slice(label.length + 2) : got.message };
    const expected = renderTicketsIndex(config, tickets, tm, r.file, configPath);
    return { ...base, text, content: got.content, expected, diff: got.content === expected ? '' : diffHint(got.content, expected) };
  });
}

/**
 * Writes every configured region whose content differs (LF; a file only when one of its regions
 * changes). Nothing is written when any region has a missing file or broken markers.
 *
 * @param {string} root the repository root
 * @param {object[]} states ticketsRegionStates
 * @returns {{ ok: true, written: { file: string, marker: string, changed: boolean }[] }
 *   | { ok: false, errors: { where: string, message: string }[] }}
 */
function writeTicketsRegions(root, states) {
  const broken = states.filter((s) => s.error !== undefined);
  if (broken.length > 0) return { ok: false, errors: broken.map((s) => ({ where: s.label, message: s.error })) };
  const files = new Map();
  const written = [];
  for (const s of states) {
    if (!files.has(s.file)) files.set(s.file, { text: s.text, changed: false });
    const f = files.get(s.file);
    const changed = s.content !== s.expected;
    if (changed) {
      const r = replaceRegion(f.text, s.marker, s.expected, s.label);
      if (!r.ok) return { ok: false, errors: [{ where: s.label, message: r.message }] };
      f.text = r.text;
      f.changed = true;
    }
    written.push({ file: s.file, marker: s.marker, changed });
  }
  for (const [file, f] of files) {
    if (f.changed) writeFileSync(join(resolve(root), ...file.split('/')), f.text);
  }
  return { ok: true, written };
}

/** `EP-001 Launch exit › ST-001 Time to first value`, or `none (top level)`. */
function tkrdChain(tickets, t) {
  const up = tickets.filter((a) => t.dir.startsWith(`${a.dir}/`)).sort((a, b) => a.depth - b.depth);
  return up.length > 0 ? up.map((a) => `${a.id} ${a.fields.title ?? ''}`).join(' › ') : 'none (top level)';
}

/** One excerpt section: its lines with headings (outside fences) demoted one level, trailing blank lines dropped. */
function tkrdSection(lines, section) {
  const out = [];
  for (let i = section.start; i < section.end; i += 1) {
    const { text, fenced } = lines[i];
    out.push(!fenced && /^ {0,3}#{1,5}(?=\s|$)/.test(text) ? text.replace(/#/, '##') : text);
  }
  while (out.length > 0 && out[out.length - 1].trim() === '') out.pop();
  return out;
}

/** The body of one ticket in the excerpt. */
function tkrdTicket(tickets, t) {
  const f = t.fields;
  const lines = markFences(t.text);
  const out = [
    `## ${t.id}: ${f.title ?? ''}`,
    '',
    `- Type: ${t.type} · Path: \`${t.file}\``,
    `- Parent chain: ${tkrdChain(tickets, t)}`,
    `- Links: ${Array.isArray(f.links) && f.links.length > 0 ? f.links.join(', ') : 'none'}`,
  ];
  const excerpt = TKRD_EXCERPT[t.type] ?? [];
  for (const title of excerpt) {
    const found = bodySection(t.text, title);
    if (found.length === 0) continue;
    out.push('', ...tkrdSection(lines, found[0]));
  }
  const rest = headings(t.text)
    .filter((h) => h.level === 2 && h.index >= t.fm.bodyStart && !excerpt.includes(h.text))
    .map((h) => `\`## ${h.text}\` of ticket.md`);
  const byPath = [...rest, ...t.attachments.map((a) => `\`${a.path}\``)];
  if (byPath.length > 0) out.push('', `Read by path: ${byPath.join('; ')}.`);
  return out;
}

/**
 * The text of `tickets brief` (§4.6), without a final line break. `ids` are known ticket IDs (in this
 * order); `name` titles an `--index-only` answer (`# Tickets of <name>`). The `(<n> lines)` of the
 * title is the line count of the whole text, title included. Without `ids`, `none` (a sentence such as
 * `unit Rel-2 schedules no tickets`) is the whole body.
 *
 * @param {object} result a checkTickets result with a model
 * @param {{ ids: string[], name: string, none?: string, indexOnly?: boolean }} opts
 * @returns {string}
 */
function ticketsBriefMarkdown(result, { ids, name, none = '', indexOnly = false }) {
  if (ids.length === 0) {
    const head = indexOnly ? `# Tickets of ${name}` : `# Ticket excerpt: ${name}`;
    return `${head} (3 lines)\n\n${none}`;
  }
  const tickets = result.model.tickets;
  const byId = result.model.state.byId;
  const list = ids.map((id) => byId.get(id));
  const lines = [
    '',
    '',
    ...(indexOnly
      ? [`Source: ${result.configPath} (${TICKETS_SCHEMA}, plan-register ${VERSION}).`]
      : [`Source: ${result.configPath} (${TICKETS_SCHEMA}, plan-register ${VERSION}). Each ticket is cut to its excerpt sections;`,
        'notes and attachments are listed by path only.']),
    '',
  ];
  if (indexOnly) {
    lines.push('| Ticket | Type | Title | Parent chain | Resolution |', '| --- | --- | --- | --- | --- |');
    for (const t of list) {
      lines.push(`| ${[t.id, t.type, t.fields.title ?? '', tkrdChain(tickets, t), t.fields.resolution ?? 'open'].map(cell).join(' | ')} |`);
    }
  } else {
    lines.push('## Ticket map', '', '| Ticket | Title | Write on the plan task | Acceptance items |', '| --- | --- | --- | --- |');
    for (const t of list) {
      const digest = acceptanceDigest(t.text);
      const items = acceptanceItems(t.text).items.map((it) => it.id);
      const ticketLine = `\`**Ticket:** ${t.id}${digest === null ? '' : ` @${digest}`}\``;
      lines.push(`| ${[t.id, cell(t.fields.title ?? ''), ticketLine, items.length > 0 ? items.join(', ') : 'none'].join(' | ')} |`);
    }
    for (const t of list) lines.push('', ...tkrdTicket(tickets, t));
  }
  const title = indexOnly ? `# Tickets of ${name}` : `# Ticket excerpt: ${ids.join(', ')}`;
  lines[0] = `${title} (${lines.length} lines)`;
  return lines.join('\n');
}

// --- core/tickets/rules.js ---
// The tickets check: rules TV1-TV13 of tickets/1 in rule order. This module runs TV1 (config, register,
// tree format, front matter, heading, acceptance grammar), TV2 (identity), TV3 (nesting), TV4 (closure
// format and the plan lookup of `done` entries), TV5 (no second status), TV6 (plan links), TV7 (one
// home), TV8 (closure matches the boxes), TV9 (closed means closed), TV10 (links), TV11 (the index
// regions and the path rules), TV12 (size warnings) and TV13 (Milestones rows against the plans), and
// the register's rule V13 (git conflict markers) on the ticket files: every `ticket.md` (archive
// included), the `knownFacts` file and the region files; the config itself in loadTicketsConfig. The
// tree walk is core/tickets/tree.js, the reading of briefs and plans core/tickets/plans.js, the join with
// the register core/tickets/state.js, the index region core/tickets/render.js.
//
// Problem = { rule: 'TV<k>', where: string, message: string, fix: string[] | null } (a stale region also
// carries `diff`); `where` is a repository path, `<file>:<line>`, `<file> (<marker>)` or the config
// path. Problems and warnings are sorted by rule number, then by `where` (path in code-unit order, then
// line as a number). Rules that cannot run are skipped with one note each (`notes[]`, not counted).

/** The rules this module checks after TV1, in order (each gets a note when the config is unusable). */
const TKR_AFTER_CONFIG = Object.freeze(['TV2', 'TV3', 'TV4', 'TV5', 'TV6', 'TV7', 'TV8', 'TV9', 'TV10', 'TV11', 'TV12', 'TV13']);
/** The rules that need the register (each gets a note when it cannot be read). */
const TKR_NEED_REGISTER = Object.freeze(['TV6', 'TV7', 'TV8', 'TV9', 'TV10', 'TV13']);
/** TV10 body links: an inline link or image `[t](target "title")` (group 1 the target). */
const TKR_INLINE_LINK_RE = /!?\[(?:[^\]\\]|\\.)*\]\(\s*(<[^>]*>|[^\s)]+)(?:\s+(?:"[^"]*"|'[^']*'|\([^)]*\)))?\s*\)/g;
/** TV10 body links: a reference definition `[x]: target` (group 1 the target). */
const TKR_REF_DEF_RE = /^ {0,3}\[[^\]]+\]:\s*(<[^>]*>|\S+)/;
/** A link target with a scheme (`https:`, `mailto:`): not checked. */
const TKR_EXTERNAL_RE = /^[a-z][a-z0-9+.-]*:/;
const TKR_UNKNOWN_LINK = 'unknown link kind; use a ticket ID, a decision ID, a known fact, todo:<name> or a root-absolute path /…';
/** Counts in messages: "two open units". */
const TKR_COUNT_WORDS = Object.freeze(['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine']);
/** A `**Ticket:**` label at column 0 (TV6 (8): unregistered plans that name tickets). */
const TKR_TICKET_LABEL_RE = /^\*\*Ticket:\*\*/;
const TKR_NOT_CHECKED = 'not checked: fix the TV1 problems above first';
/** Regions are compared only on a sound tree (like V12 after V1-V11 and V13): this note says why they were not. */
const TKR_REGIONS_BLOCKED = 'regions not checked: fix the TV1-TV3 problems above first';
/** The same note when only V13 (conflict markers in ticket files) keeps the regions from being compared. */
const TKR_REGIONS_BLOCKED_V13 = 'regions not checked: fix the V13 problems above first';
/** The rules whose problems keep the tickets regions from being compared or written. */
const TKR_BLOCKING = Object.freeze(['TV1', 'TV2', 'TV3', 'V13']);
/** The least length of a dropped reason or a "no plan" reason, whatever the register's skipReasonMin. */
const TKR_REASON_FLOOR = 15;
const TKR_RESOLUTIONS = Object.freeze(['done', 'dropped', 'superseded', 'promoted']);
/** A `by` entry naming a plan task: `<plan slug>#<task number>`. */
const TKR_PLAN_TASK_RE = /^[A-Za-z0-9._-]+#[1-9]\d*$/;
const TKR_COMMIT_RE = /^commit:[0-9a-f]{7,40}$/;
const TKR_NO_PLAN_RE = /^no plan:(.*)$/;
/**
 * TV5: a task-list box, a status line (`__Status__` counts like `**Status**`, so the word may also end at a
 * closing `__`), a heading that states progress or starts with state, progress or status.
 */
const TKR_BOX_RE = /^\s*(?:[-*+]|\d+[.)])\s+\[[ xX~]\]/;
const TKR_STATUS_RE = /^\s*(?:(?:[-*+]|\d+[.)])\s+)?(?:\*\*|__)?(?:state|progress|status)(?:\b|(?=__))/i;
const TKR_STATE_HEADING_RE = /\b(in progress|blocked)\b/i;
const TKR_STATUS_HEADING_RE = /^(state|progress|status)\b/i;

function tkrPush(out, rule, where, message, fix = null) {
  out.push({ rule, where, message, fix });
}

/** `{ path, line }` of a `where` (line 0 when it has none). */
function tkrWhereParts(where) {
  const m = /^(.*):(\d+)$/.exec(where);
  return m ? { path: m[1], line: Number(m[2]) } : { path: where, line: 0 };
}

/** The sort rank of a rule: `TV<k>` is k; V13 (conflict markers, the likely cause of the rest) is 0. */
function tkrRuleRank(rule) {
  return rule.startsWith('TV') ? Number(rule.slice(2)) : 0;
}

/** Rule rank, then path (code-unit order), then line number; stable otherwise. */
function tkrCompare(a, b) {
  const ra = tkrRuleRank(a.rule);
  const rb = tkrRuleRank(b.rule);
  if (ra !== rb) return ra - rb;
  const wa = tkrWhereParts(a.where);
  const wb = tkrWhereParts(b.where);
  if (wa.path !== wb.path) return wa.path < wb.path ? -1 : 1;
  return wa.line - wb.line;
}

/** The front-matter, heading and acceptance rules of one ticket (TV1). */
function tkrFormat(out, t) {
  const fm = t.fm;
  for (const p of fm.problems) tkrPush(out, 'TV1', `${t.file}:${p.line}`, p.message);
  if (fm.bodyStart > 0 && typeof fm.fields.id === 'string' && typeof fm.fields.title === 'string') {
    const expected = `# ${fm.fields.id}: ${fm.fields.title}`;
    const h = ticketHeading(t.text, fm.bodyStart);
    if (h === null || h.text.trimEnd() !== expected) {
      tkrPush(out, 'TV1', `${t.file}:${h === null ? fm.bodyStart + 1 : h.line}`, `heading must be ${JSON.stringify(expected)}`);
    }
  }
  for (const p of acceptanceItems(t.text).problems) tkrPush(out, 'TV1', `${t.file}:${p.line}`, p.message);
}

/** TV2 from the front matter and over all tickets: id, type, enabled types, unique IDs, the freeze. */
function tkrIdentity(out, config, tickets) {
  for (const t of tickets) {
    const f = t.fm === null ? {} : t.fm.fields;
    if (typeof f.id === 'string' && f.id !== t.id) {
      tkrPush(out, 'TV2', `${t.file}:${t.fm.lines.id}`, `id ${f.id} differs from the directory's ID ${t.id}`);
    }
    if (typeof f.type === 'string') {
      if (!TICKET_TYPES.includes(f.type)) {
        tkrPush(out, 'TV2', `${t.file}:${t.fm.lines.type}`, `type ${JSON.stringify(f.type)} is not one of ${TICKET_TYPES.join(', ')}`);
      } else if (f.type !== t.type) {
        tkrPush(out, 'TV2', `${t.file}:${t.fm.lines.type}`, `type ${JSON.stringify(f.type)} does not match the prefix ${t.prefix} (${t.type})`);
      }
    }
    if (!config.types[t.type].enabled) tkrPush(out, 'TV2', t.dir, `type ${JSON.stringify(t.type)} is disabled in config.types`);
  }
  const byKey = new Map();
  for (const t of tickets) {
    const key = `${t.prefix}-${t.number}`;
    if (!byKey.has(key)) byKey.set(key, []);
    byKey.get(key).push(t);
  }
  for (const group of byKey.values()) {
    if (group.length < 2) continue;
    const paths = group.map((t) => t.dir).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
    const times = group.length === 2 ? 'twice' : `${group.length} times`;
    tkrPush(out, 'TV2', paths[0], `${group[0].id} is used ${times}: ${paths.join(', ')}; IDs are never reused`);
  }
  if (config.frozen !== null) {
    const frozen = new Set(config.frozen.ids.map((id) => {
      const m = /^(.*)-(\d+)$/.exec(id);
      return `${m[1]}-${Number(m[2])}`;
    }));
    for (const t of tickets) {
      if (!frozen.has(`${t.prefix}-${t.number}`)) {
        tkrPush(out, 'TV2', t.dir, `${t.id} was created after the freeze of ${config.frozen.date}`);
      }
    }
  }
}

/** TV3 of the live tree: parent types, top level, depth. */
function tkrNesting(out, config, tickets) {
  const byDir = new Map(tickets.map((t) => [t.dir, t]));
  for (const t of tickets) {
    if (t.archived) continue;
    const spec = config.types[t.type];
    const allowed = spec.parents.length > 0 ? spec.parents.join(', ') : 'none';
    if (t.parent !== null) {
      const parent = byDir.get(t.dir.slice(0, t.dir.lastIndexOf('/')));
      if (parent !== undefined && !spec.parents.includes(parent.type)) {
        tkrPush(out, 'TV3', t.dir, `${t.type} ${t.id} cannot be a child of ${parent.type} ${parent.id} (allowed: ${allowed})`);
      }
    } else if (!spec.topLevel) {
      tkrPush(out, 'TV3', t.dir, `${t.type} ${t.id} cannot be at the top level (allowed parents: ${allowed})`);
    }
    if (t.depth > config.limits.depth) tkrPush(out, 'TV3', t.dir, `depth ${t.depth} exceeds limits.depth ${config.limits.depth}`);
  }
}

/** The `by` problems of a ticket resolved `done` (format only: plan tasks are looked up with the plans). */
function tkrDoneBy(t, by, ctx) {
  const form = 'by of a done ticket must be a list: [<plan>#<task>, …], [<child ID>, …] or [commit:<sha>, "no plan: <reason>"]';
  if (!Array.isArray(by)) return [form];
  if (by.length === 0) return ['by of a done ticket needs at least one entry'];
  if (by.some((e) => e.startsWith('commit:'))) {
    const commit = by.find((e) => e.startsWith('commit:'));
    if (!TKR_COMMIT_RE.test(commit)) return [`by entry ${JSON.stringify(commit)} must be commit:<7-40 hex digits>`];
    if (by.length === 1) {
      return [`by ${JSON.stringify(commit)} needs a second entry "no plan: <reason of at least ${ctx.reasonMin} characters>"`];
    }
    if (by.length !== 2 || by[0] !== commit) return ['by with a commit has exactly two entries: [commit:<sha>, "no plan: <reason>"]'];
    const m = TKR_NO_PLAN_RE.exec(by[1]);
    if (!m) return [`by ${JSON.stringify(commit)} needs a second entry "no plan: <reason of at least ${ctx.reasonMin} characters>"`];
    const reason = m[1].trim();
    return reason.length < ctx.reasonMin
      ? [`the "no plan" reason has ${reason.length} characters; at least ${ctx.reasonMin} are required`] : [];
  }
  const out = [];
  for (const e of by) {
    if (TKR_PLAN_TASK_RE.test(e)) {
      if (ctx.findPlan !== undefined) out.push(...tkrPlanEntry(t, e, ctx));
      continue;
    }
    if (ctx.idRe.test(e)) {
      const child = ctx.byKey.get(ctx.key(e));
      if (child === undefined || child.parent !== t.id || child.dir.slice(0, child.dir.lastIndexOf('/')) !== t.dir) {
        out.push(`by entry ${e} is not a child ticket of ${t.id}`);
      } else if (typeof child.fields.resolution !== 'string') {
        out.push(`by entry ${e} is a child ticket that is not resolved`);
      }
      continue;
    }
    out.push(`by entry ${JSON.stringify(e)} is neither <plan>#<task> nor a child ticket ID`);
  }
  return out;
}

/** TV4 of one ticket: the resolution, its date and its `by`, and `supersedes`. */
function tkrResolution(out, t, ctx) {
  const f = t.fields;
  const at = (key) => `${t.file}:${t.fm.lines[key]}`;
  const has = (key) => Object.hasOwn(t.fm.lines, key);
  if (has('supersedes') && typeof f.supersedes === 'string') {
    const x = ctx.idRe.test(f.supersedes) ? ctx.byKey.get(ctx.key(f.supersedes)) : undefined;
    const ok = x !== undefined && x.fields.resolution === 'superseded' && typeof x.fields.by === 'string'
      && ctx.key(x.fields.by) === ctx.key(t.id);
    if (!ok) tkrPush(out, 'TV4', at('supersedes'), `supersedes ${f.supersedes}, but ${f.supersedes} is not resolved superseded by ${t.id}`);
  }
  if (!has('resolution')) {
    if (has('closed')) tkrPush(out, 'TV4', at('closed'), '"closed" without a resolution');
    if (has('by')) tkrPush(out, 'TV4', at('by'), '"by" without a resolution');
    return;
  }
  const r = f.resolution;
  if (typeof r !== 'string') return;
  if (!TKR_RESOLUTIONS.includes(r)) {
    tkrPush(out, 'TV4', at('resolution'), `resolution ${JSON.stringify(r)} is not one of ${TKR_RESOLUTIONS.join(', ')}`);
    return;
  }
  if (!has('closed')) tkrPush(out, 'TV4', at('resolution'), 'resolution needs "closed: YYYY-MM-DD"');
  else if (typeof f.closed === 'string' && !isCalendarDate(f.closed)) tkrPush(out, 'TV4', at('closed'), '"closed" must be a calendar date YYYY-MM-DD');
  else if (typeof f.closed === 'string' && typeof f.created === 'string' && f.closed < f.created) {
    tkrPush(out, 'TV4', at('closed'), `closed ${f.closed} is before created ${f.created}`);
  }
  if (r === 'promoted' && t.type !== 'idea') tkrPush(out, 'TV4', at('resolution'), `only an idea can be promoted (${t.id} is a ${t.type})`);
  if (!has('by')) {
    tkrPush(out, 'TV4', at('resolution'), 'resolution needs "by"');
    return;
  }
  const by = f.by;
  if (by === undefined) return;
  const messages = [];
  if (r === 'done') {
    messages.push(...tkrDoneBy(t, by, ctx));
  } else if (r === 'dropped') {
    if (Array.isArray(by)) messages.push('by of a dropped ticket must be the reason (text, not a list)');
    else if (by.trim().length < ctx.reasonMin) messages.push(`the reason has ${by.trim().length} characters; at least ${ctx.reasonMin} are required`);
  } else if (Array.isArray(by) || !ctx.idRe.test(by)) {
    messages.push(r === 'superseded'
      ? 'by of a superseded ticket must be the ID of the ticket that replaces it'
      : 'by of a promoted idea must be the ID of the story it became');
  } else if (!ctx.byKey.has(ctx.key(by))) {
    messages.push(`by ${by} does not exist`);
  } else if (r === 'superseded' && ctx.key(by) === ctx.key(t.id)) {
    messages.push('a ticket cannot be superseded by itself');
  } else if (r === 'promoted' && ctx.byKey.get(ctx.key(by)).type !== 'story') {
    messages.push(`by ${by} is not a story`);
  }
  for (const m of messages) tkrPush(out, 'TV4', at('by'), m);
}

/** TV5 of one ticket: no boxes, no status lines, no headings that state progress (outside fences; the `# <ID>: <title>` heading is the title, checked by TV1). */
function tkrNoStatus(out, t) {
  const lines = markFences(t.text);
  for (let i = t.fm.bodyStart; i < lines.length; i += 1) {
    const { text, fenced } = lines[i];
    if (fenced) continue;
    if (TKR_BOX_RE.test(text)) tkrPush(out, 'TV5', `${t.file}:${i + 1}`, 'checkbox in a ticket; progress lives on plan boxes');
    else if (TKR_STATUS_RE.test(text)) tkrPush(out, 'TV5', `${t.file}:${i + 1}`, 'status line in a ticket; state is computed by tickets status');
  }
  const title = ticketHeading(t.text, t.fm.bodyStart);
  for (const h of headings(t.text)) {
    if (h.index < t.fm.bodyStart) continue;
    if (h.level === 1 && title !== null && h.index === title.line - 1) continue; // the title is checked by TV1
    const m = TKR_STATE_HEADING_RE.exec(h.text) ?? TKR_STATUS_HEADING_RE.exec(h.text.replace(/^(?:\*\*|__)/, ''));
    if (m) tkrPush(out, 'TV5', `${t.file}:${h.index + 1}`, `heading says ${JSON.stringify(m[1].toLowerCase())}; state is computed`);
  }
}

function tkrIsObj(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

function tkrArr(v) {
  return Array.isArray(v) ? v : [];
}

/** `A1-A3`, `A1, A3, A4-A6`: the item labels with consecutive runs joined. */
function tkrItemRanges(items) {
  const runs = [];
  for (const it of items) {
    const last = runs[runs.length - 1];
    if (last !== undefined && it.n === last[1] + 1) last[1] = it.n;
    else runs.push([it.n, it.n]);
  }
  return runs.map(([a, b]) => (a === b ? `A${a}` : `A${a}-A${b}`)).join(', ');
}

/** TV6 (1)-(7) of one registered plan. */
function tkrPlanLinks(out, warnings, plan, ctx) {
  const at = (line) => `${plan.path}:${line}`;
  for (const p of plan.problems) tkrPush(out, 'TV6', at(p.line), p.message);
  const implementable = ctx.config.implementable;
  for (const task of plan.tasks) {
    const named = task.ticket === null ? [] : task.ticket.entries;
    for (const entry of named) {
      const where = at(task.ticket.line);
      const t = ctx.byId.get(entry.id);
      if (t === undefined) {
        tkrPush(out, 'TV6', where, `**Ticket:** names ${entry.id}, which does not exist`);
        continue;
      }
      if (!implementable.includes(t.type)) {
        tkrPush(out, 'TV6', where, `${t.id} has type ${t.type}; plan tasks implement only ${implementable.join(', ')} tickets`);
      } else if (t.type === 'story' && t.children.length > 0) {
        tkrPush(out, 'TV6', where, `${t.id} is a story with child tickets; name its child tickets on the **Ticket:** line`);
      }
      if (t.text === null) continue;
      const digest = acceptanceDigest(t.text);
      if (entry.digest === null && digest !== null) {
        tkrPush(out, 'TV6', where, `**Ticket:** ${t.id} has no acceptance digest; write "${t.id} @${digest}"`);
      } else if (entry.digest !== null && digest === null) {
        tkrPush(out, 'TV6', where, `**Ticket:** ${t.id} @${entry.digest}, but ${t.id} has no "## Acceptance" section; write "${t.id}" without a digest`);
      } else if (entry.digest !== digest) {
        tkrPush(warnings, 'TV6', where, `acceptance of ${t.id} changed after planning (plan @${entry.digest}, ticket @${digest}); `
          + "review the task's criteria, then update the digest");
      }
    }
    for (const c of task.citations) {
      const where = at(c.line);
      if (!named.some((e) => e.id === c.id)) {
        tkrPush(out, 'TV6', where, `cites ${c.id}/${c.item}, but ${c.id} is not on the task's **Ticket:** line`);
        continue;
      }
      const t = ctx.byId.get(c.id);
      if (t === undefined || t.text === null) continue;
      const items = acceptanceItems(t.text).items;
      if (items.some((it) => it.id === c.item)) continue;
      const has = items.length === 0 ? 'has no acceptance items' : `has ${tkrItemRanges(items)}`;
      tkrPush(out, 'TV6', where, `cites ${c.id}/${c.item}, but ${c.id} ${has}`);
    }
  }
}

/** TV6 (8): an active `.md` in planDirs that no unit registers, with `**Ticket:**` lines. */
function tkrUnregisteredPlans(out, pc) {
  const cfg = tkrIsObj(pc.data.config) ? pc.data.config : {};
  const archive = tkrIsObj(cfg.archive) ? normalizePath(cfg.archive.dir) : null;
  const seen = new Set();
  for (const d of tkrArr(cfg.planDirs)) {
    const dir = tkrIsObj(d) ? normalizePath(d.path) : null;
    if (dir === null) continue;
    for (const path of pc.fsv.listMd(dir, d.recursive === true)) {
      if (seen.has(path) || pc.registered.has(path) || (archive !== null && inDir(path, archive, true))) continue;
      seen.add(path);
      const lines = markFences(pc.fsv.readText(path) ?? '');
      const i = lines.findIndex((l) => !l.fenced && TKR_TICKET_LABEL_RE.test(l.text));
      if (i !== -1) {
        tkrPush(out, 'TV6', `${path}:${i + 1}`,
          'plan is not registered for any unit, but names tickets on **Ticket:** lines; register it (add-plan) or remove the lines');
      }
    }
  }
}

/** `rows M1, M3 of Rel-2 do not` / `row M1 of Rel-2 does not`. */
function tkrRowsText(rows, key) {
  const names = rows.map((r) => r.milestone).join(', ');
  return rows.length === 1 ? `row ${names} of ${key} does not` : `rows ${names} of ${key} do not`;
}

/** TV13 of one brief: the rows that name only registered plans, grouped by shared plans. */
function tkrCoverage(out, pc, brief) {
  if (!brief.tickets) return;
  const key = brief.unit.key;
  const byName = unitPlans(pc, key);
  const rows = brief.rows.filter((r) => !r.noPlan && r.plans.every((n) => byName.has(n)));
  const parent = rows.map((_, i) => i);
  const find = (i) => (parent[i] === i ? i : (parent[i] = find(parent[i])));
  const owner = new Map();
  rows.forEach((r, i) => {
    for (const name of r.plans) {
      if (owner.has(name)) parent[find(i)] = find(owner.get(name));
      else owner.set(name, i);
    }
  });
  const groups = new Map();
  rows.forEach((r, i) => {
    const g = find(i);
    if (!groups.has(g)) groups.set(g, []);
    groups.get(g).push(r);
  });
  for (const group of groups.values()) {
    const names = [...new Set(group.flatMap((r) => r.plans))].sort();
    const plans = names.flatMap((n) => byName.get(n));
    if (plans.some((p) => p.missing)) continue; // V7 owns a registered plan whose file is missing
    const scheduled = new Set(group.flatMap((r) => r.ids));
    const named = new Set();
    for (const plan of plans) {
      for (const task of plan.tasks) {
        if (task.ticket === null) continue;
        for (const e of task.ticket.entries) {
          named.add(e.id);
          if (!scheduled.has(e.id)) {
            tkrPush(out, 'TV13', `${plan.path}:${task.ticket.line}`,
              `${plan.name} names ${e.id} on Task ${task.n}, which ${tkrRowsText(group, key)} schedule`);
          }
        }
      }
    }
    for (const r of group) {
      for (const id of r.ids) {
        if (!named.has(id)) {
          tkrPush(out, 'TV13', `${brief.path}:${r.line}`, `${id} is scheduled in ${key} ${r.milestone} but no task of ${names.join(' or ')} names it`);
        }
      }
    }
  }
}

/** `true` when the ticket's front matter was read (the rules that need its fields can judge it). */
function tkrUsable(t) {
  return t.fm !== null && t.fm.bodyStart > 0;
}

function tkrResolved(t) {
  return typeof t.fields.resolution === 'string';
}

/**
 * The plan files a `done` entry can name: every `.md` in the register's planDirs and anywhere in its
 * archive directory, by name (basename without `.md`), each read once with its tasks.
 */
function tkrPlanFinder(tm, config) {
  const cfg = tkrIsObj(tm.data.config) ? tm.data.config : {};
  const byName = new Map();
  const add = (path) => {
    const name = path.slice(path.lastIndexOf('/') + 1).replace(/\.md$/, '');
    if (!byName.has(name)) byName.set(name, new Set());
    byName.get(name).add(path);
  };
  for (const d of tkrArr(cfg.planDirs)) {
    const dir = tkrIsObj(d) ? normalizePath(d.path) : null;
    if (dir !== null) for (const path of tm.fsv.listMd(dir, d.recursive === true)) add(path);
  }
  if (tm.archive !== null) for (const path of tm.fsv.listMd(tm.archive, true)) add(path);
  const parsed = new Map([...tm.plans.values()].map((p) => [p.path, p.tasks]));
  return (name) => {
    const paths = [...(byName.get(name) ?? [])].sort();
    return paths.map((path) => {
      if (!parsed.has(path)) parsed.set(path, planTasks(tm.fsv.readText(path) ?? '', config).tasks);
      return { path, tasks: parsed.get(path) };
    });
  };
}

/** TV4: a `<plan>#<N>` entry of a done ticket names one plan file whose Task N names the ticket. */
function tkrPlanEntry(t, entry, ctx) {
  const [name, n] = entry.split('#');
  const found = ctx.findPlan(name);
  if (found.length === 0) return [`by entry ${entry}: no plan ${name}.md in the plan directories of the register`];
  if (found.length > 1) return [`by entry ${entry}: ${name}.md is ambiguous: ${found.map((f) => f.path).join(', ')}`];
  const { path, tasks } = found[0];
  const task = tasks.find((k) => k.n === Number(n));
  if (task === undefined) return [`by entry ${entry}: ${path} has no Task ${n}`];
  if (task.ticket === null || !task.ticket.entries.some((e) => e.id === t.id)) {
    return [`by entry ${entry}: Task ${n} of ${path} does not name ${t.id} on its **Ticket:** line`];
  }
  return [];
}

/** TV7: the Milestones sections, IDs that do not exist, and tickets scheduled by two open units. */
function tkrHomes(out, tm) {
  for (const b of tm.briefs) {
    for (const p of b.problems) tkrPush(out, 'TV7', `${b.path}:${p.line}`, p.message);
    for (const r of b.rows) {
      for (const id of r.ids) {
        if (!tm.byId.has(id)) tkrPush(out, 'TV7', `${b.path}:${r.line}`, `Milestones row ${r.milestone} names ${id}, which does not exist`);
      }
    }
  }
  for (const [id, rows] of tm.scheduling) {
    const t = tm.byId.get(id);
    if (t === undefined) continue;
    const units = new Map();
    for (const r of rows) {
      if (!r.open) continue;
      if (!units.has(r.unit)) units.set(r.unit, []);
      if (!units.get(r.unit).includes(r.milestone)) units.get(r.unit).push(r.milestone);
    }
    if (units.size < 2) continue;
    const count = TKR_COUNT_WORDS[units.size] ?? String(units.size);
    const list = [...units].map(([u, ms]) => `${u} (${ms.join(', ')})`).join(', ');
    tkrPush(out, 'TV7', t.file, `${id} is scheduled by ${count} open units: ${list}; one home only`);
  }
}

/** `plan-a#2` */
function tkrTaskRef(k) {
  return `${k.plan.name}#${k.n}`;
}

/**
 * The open tickets TV8 (a) and (a') speak of: every scheduling row has a row plan with an implementing
 * task and all those tasks are closed. `refs` are the implementation tasks (closed and not skip-only) as
 * `<plan>#<n>`, sorted by plan name and number; empty when every task is skipped ([~]) (a').
 */
function tkrClosable(tm, tickets) {
  const out = [];
  for (const t of tickets) {
    if (t.archived || !tkrUsable(t) || tkrResolved(t)) continue;
    const implementing = tm.implementing.get(t.id) ?? [];
    const rows = tm.scheduling.get(t.id) ?? [];
    if (rows.length === 0) continue;
    const tasks = new Map();
    let everyRow = true;
    for (const r of rows) {
      const inRow = implementing.filter((k) => r.plans.includes(k.plan));
      if (inRow.length === 0) everyRow = false;
      for (const k of inRow) tasks.set(`${k.plan.path}#${k.n}`, k);
    }
    const list = [...tasks.values()];
    if (!everyRow || !list.every((k) => k.closed)) continue;
    const done = list.filter((k) => k.implementation)
      .sort((a, b) => (a.plan.name < b.plan.name ? -1 : a.plan.name > b.plan.name ? 1 : a.n - b.n));
    out.push({ ticket: t, refs: done.map(tkrTaskRef) });
  }
  return out;
}

/**
 * The open tickets whose implementing tasks are all closed with at least one implementation task: what
 * TV8 (a) asks to close (`tickets close --auto`). Skip-only tickets (a') are not listed.
 *
 * @param {object} tm a ticketModel
 * @param {object[]} tickets the tickets of scanTickets, with `fm` and `fields` set
 * @returns {{ ticket: object, refs: string[] }[]} `refs` as `plan#n`
 */
function closableTickets(tm, tickets) {
  return tkrClosable(tm, tickets).filter((c) => c.refs.length > 0);
}

/** TV8: an open ticket whose implementing tasks are all closed, a done ticket with open boxes. */
function tkrClosure(out, tm, tickets) {
  for (const t of tickets) {
    if (t.archived || !tkrUsable(t) || !tkrResolved(t) || t.fields.resolution !== 'done') continue;
    for (const k of tm.implementing.get(t.id) ?? []) {
      const open = k.boxes.total - k.boxes.done;
      if (k.active && open > 0) {
        tkrPush(out, 'TV8', `${t.file}:${t.fm.lines.resolution}`, `${t.id} is resolved done but ${tkrTaskRef(k)} has ${open} open box(es)`);
      }
    }
  }
  for (const { ticket: t, refs } of tkrClosable(tm, tickets)) {
    if (refs.length > 0) {
      tkrPush(out, 'TV8', t.file, `all implementing tasks of ${t.id} are closed; close it`,
        ['tickets', 'close', t.id, '--done', '--by', refs.join(','), '--write']);
    } else {
      tkrPush(out, 'TV8', t.file, `every implementing task of ${t.id} is skipped ([~]); drop it or schedule it again`);
    }
  }
}

/** TV9: open tickets under resolved ones, open tickets only Done units schedule, containers to close. */
function tkrClosedMeansClosed(out, warnings, tm, tickets) {
  const live = tickets.filter((t) => !t.archived && tkrUsable(t));
  const order = (t) => TICKET_TYPES.indexOf(t.type);
  for (const t of live) {
    if (!tkrResolved(t)) continue;
    const open = live.filter((d) => d.dir.startsWith(`${t.dir}/`) && !tkrResolved(d))
      .sort((a, b) => order(a) - order(b) || a.number - b.number);
    for (const d of open) tkrPush(out, 'TV9', `${t.file}:${t.fm.lines.resolution}`, `${t.id} is resolved but ${d.id} under it is open`);
  }
  for (const b of tm.briefs) {
    if (b.unit.status !== 'Done') continue;
    for (const r of b.rows) {
      for (const id of r.ids) {
        const t = tm.byId.get(id);
        if (t === undefined || !tkrUsable(t) || tkrResolved(t)) continue;
        if ((tm.scheduling.get(id) ?? []).some((x) => x.open)) continue;
        tkrPush(out, 'TV9', `${b.path}:${r.line}`, `unit ${b.unit.key} is Done but ${id} it scheduled is open; close it or schedule it in an open unit`);
      }
    }
  }
  for (const t of live) {
    if (tkrResolved(t) || t.children.length === 0) continue;
    const children = t.children.map((id) => tm.byId.get(id));
    if (!children.every((c) => c !== undefined && tkrUsable(c) && tkrResolved(c))) continue;
    tkrPush(warnings, 'TV9', t.file, `all children of ${t.id} are resolved`,
      ['tickets', 'close', t.id, '--done', '--by', t.children.join(','), '--write']);
  }
}

/** Whole-string matcher of a pattern source, or null when it does not compile. */
function tkrFull(source) {
  if (typeof source !== 'string') return null;
  try {
    return new RegExp(`^(?:${source})$`);
  } catch {
    return null;
  }
}

/** The IDs a known-facts file defines: heading ids and the first token of the first cell of table rows. */
function tkrFactIds(text) {
  const ids = new Set();
  const lines = markFences(text);
  for (const h of headings(text)) {
    const id = headingId(h.text);
    if (id !== null) ids.add(id);
  }
  for (const { text: s, fenced } of lines) {
    const row = s.trim();
    if (fenced || !row.startsWith('|') || /^\|[\s:|-]*$/.test(row)) continue;
    const first = row.slice(1).split('|')[0].replace(/\*\*|__|`/g, '').trim();
    const m = /^[A-Za-z0-9._-]+/.exec(first);
    if (m && m[0].replace(/[.-]+$/, '') !== '') ids.add(m[0].replace(/[.-]+$/, ''));
  }
  return ids;
}

/** What TV10 needs from the register and the config: decision logs, known facts, TODO directories, homes. */
function tkrLinkContext(tm, config) {
  const cfg = tkrIsObj(tm.data.config) ? tm.data.config : {};
  const todos = tkrIsObj(cfg.todos) ? cfg.todos : null;
  const homes = new Map();
  for (const u of tm.units) {
    for (const p of tkrArr(u.todos)) {
      const n = normalizePath(p);
      if (n !== null && !homes.has(n)) homes.set(n, u.key);
    }
  }
  let facts = null;
  if (config.knownFacts !== null) {
    const re = tkrFull(config.knownFacts.idPattern);
    if (re !== null) facts = { re, path: config.knownFacts.path, ids: tkrFactIds(tm.fsv.readText(config.knownFacts.path) ?? '') };
  }
  return {
    tm,
    idRe: ticketIdPattern(config),
    decisionRes: tkrArr(cfg.decisionLogs).map((l) => (tkrIsObj(l) ? tkrFull(l.idPattern) : null)).filter((r) => r !== null),
    decisions: decisionIndex(tm.data, tm.fsv),
    facts,
    todoDir: todos === null ? null : normalizePath(todos.dir),
    todoArchive: todos === null ? null : normalizePath(todos.archiveDir),
    homes,
  };
}

/** TV10 of one `todo:` link: exactly one note; a defect's note archived; the note's home (warning). */
function tkrTodoLink(out, warnings, t, e, where, lc) {
  const raw = e.slice('todo:'.length);
  if (raw === '' || raw.includes('/')) {
    tkrPush(out, 'TV10', where, `${e} must name a note without a directory`);
    return;
  }
  const name = raw.replace(/\.md$/, '');
  const { fsv } = lc.tm;
  if (lc.todoDir === null) {
    tkrPush(out, 'TV10', where, `${e}: the register has no config.todos.dir`);
    return;
  }
  const direct = `${lc.todoDir}/${name}.md`;
  const found = fsv.isFile(direct) ? [direct] : [];
  if (lc.todoArchive !== null) {
    for (const p of fsv.listMd(lc.todoArchive, true)) if (p.endsWith(`/${name}.md`)) found.push(p);
  }
  found.sort();
  if (found.length === 0) {
    const dirs = lc.todoArchive === null ? `${lc.todoDir}/` : `${lc.todoDir}/ or ${lc.todoArchive}/`;
    tkrPush(out, 'TV10', where, `${e} matches no file in ${dirs}`);
    return;
  }
  if (found.length > 1) {
    tkrPush(out, 'TV10', where, `${e} matches ${found.length} files: ${found.join(', ')}`);
    return;
  }
  const path = found[0];
  if (t.type === 'defect' && path === direct) {
    const target = `${lc.todoArchive ?? `${lc.todoDir}/archive`}/${name}.md`;
    tkrPush(out, 'TV10', where, `promoted note ${path} is still open; archive it: git mv ${path} ${target}, then home-todo ${target} --replace ${path} --write`);
  }
  const home = lc.homes.get(path);
  const units = [...new Set((lc.tm.scheduling.get(t.id) ?? []).map((r) => r.unit))];
  if (home !== undefined && units.length > 0 && !units.includes(home)) {
    tkrPush(warnings, 'TV10', where, `note ${path} is homed in ${home} but ${t.id} is scheduled by ${units.join(', ')}`,
      units.length === 1 ? ['home-todo', path, units[0], '--move', '--write'] : null);
  }
}

/** TV10: a defect ticket is created only by promoting a TODO note, so it links one. */
const TKR_DEFECT_NO_TODO = 'defect ticket without a todo: link; a defect ticket is created only by promoting a TODO note (archive the note, then create the ticket with --link todo:<name>; the ticket-new skill does both with --from-todo)';

/** TV10 of the front-matter links of one ticket, in the order of the kinds (§2.5). */
function tkrFrontLinks(out, warnings, t, lc) {
  if (t.type === 'defect' && !(Array.isArray(t.fields.links) && t.fields.links.some((e) => typeof e === 'string' && e.startsWith('todo:')))) {
    tkrPush(out, 'TV10', `${t.file}:${t.fm.lines.type}`, TKR_DEFECT_NO_TODO);
  }
  if (!Array.isArray(t.fields.links)) return;
  const where = `${t.file}:${t.fm.lines.links}`;
  for (const e of t.fields.links) {
    if (lc.idRe.test(e)) {
      if (!lc.tm.byId.has(e)) tkrPush(out, 'TV10', where, `link ${e}: no ticket ${e} in the tree or the archive`);
    } else if (e.startsWith('todo:')) {
      tkrTodoLink(out, warnings, t, e, where, lc);
    } else if (lc.decisionRes.some((re) => re.test(e))) {
      if (!lc.decisions.has(e)) tkrPush(out, 'TV10', where, `decision ${e} is not a heading in any configured decision log`);
    } else if (lc.facts !== null && lc.facts.re.test(e)) {
      if (!lc.facts.ids.has(e)) tkrPush(out, 'TV10', where, `known fact ${e} is not in ${lc.facts.path}`);
    } else if (e.startsWith('/')) {
      const p = normalizePath(e.slice(1).split('#')[0]);
      if (p === null || !lc.tm.fsv.exists(p)) tkrPush(out, 'TV10', where, `path ${e} does not exist`);
    } else {
      tkrPush(out, 'TV10', where, `link ${JSON.stringify(e)}: ${TKR_UNKNOWN_LINK}`);
    }
  }
}

/** TV10 of one body link target of a ticket. */
function tkrBodyTarget(out, t, raw, where, fsv) {
  const target = raw.startsWith('<') && raw.endsWith('>') ? raw.slice(1, -1) : raw;
  if (target === '' || target.startsWith('#') || TKR_EXTERNAL_RE.test(target)) return;
  const hash = target.indexOf('#');
  let path = hash === -1 ? target : target.slice(0, hash);
  try {
    path = decodeURI(path);
  } catch {
    // kept as written
  }
  if (path.startsWith('/')) {
    const p = normalizePath(path.slice(1));
    if (p === null || !fsv.exists(p)) tkrPush(out, 'TV10', where, `link ${target} does not exist`);
    return;
  }
  const computed = posix.normalize(posix.join(t.dir, path)).replace(/\/+$/, '');
  if (computed !== t.dir && !computed.startsWith(`${t.dir}/`)) {
    tkrPush(out, 'TV10', where, `link ${target} leaves the ticket's directory; write it root-absolute: /${computed}${hash === -1 ? '' : target.slice(hash)}`);
  } else if (!fsv.exists(computed)) {
    tkrPush(out, 'TV10', where, `link ${target} does not exist`);
  }
}

/** TV10 of the body links of one ticket: inline links and reference definitions outside fences and code. */
function tkrBodyLinks(out, t, fsv) {
  const lines = markFences(t.text);
  for (let i = t.fm.bodyStart; i < lines.length; i += 1) {
    if (lines[i].fenced) continue;
    const s = lines[i].text.replace(/`[^`]*`/g, (c) => ' '.repeat(c.length));
    const where = `${t.file}:${i + 1}`;
    for (const m of s.matchAll(TKR_INLINE_LINK_RE)) tkrBodyTarget(out, t, m[1], where, fsv);
    const def = TKR_REF_DEF_RE.exec(s);
    if (def) tkrBodyTarget(out, t, def[1], where, fsv);
  }
}

/** TV12: sizes of live tickets, rows with many tickets, homeRequired types, small tickets (warnings). */
function tkrSize(warnings, config, tm, tickets) {
  const { limits } = config;
  const live = tickets.filter((t) => !t.archived);
  for (const t of live) {
    if (t.text !== null) {
      const n = t.text.endsWith('\n') ? t.text.split('\n').length - 1 : t.text.split('\n').length;
      if (n > limits.ticketLines) tkrPush(warnings, 'TV12', t.file, `ticket.md has ${n} lines; limit ${limits.ticketLines}`);
    }
    for (const a of t.attachments) {
      if (a.bytes > limits.attachmentBytes) tkrPush(warnings, 'TV12', a.path, `attachment has ${a.bytes} bytes; limit ${limits.attachmentBytes}`);
    }
  }
  if (tm === null) return;
  const seen = new Set();
  for (const b of tm.briefs) {
    for (const r of b.rows) {
      const where = `${b.path}:${r.line}`;
      if (seen.has(where) || r.ids.length <= limits.ticketsPerMilestone) continue;
      seen.add(where);
      tkrPush(warnings, 'TV12', where, `row ${r.milestone} names ${r.ids.length} tickets; limit ${limits.ticketsPerMilestone}`);
    }
  }
  for (const t of live) {
    if (!tkrUsable(t) || tkrResolved(t)) continue;
    if (config.homeRequired.includes(t.type) && (tm.scheduling.get(t.id) ?? []).filter((r) => r.open).length === 0) {
      tkrPush(warnings, 'TV12', t.file, `${t.id} has no scheduling row; config.homeRequired lists ${t.type}`);
    }
    if (!config.implementable.includes(t.type) || t.attachments.length > 0 || (tm.implementing.get(t.id) ?? []).length !== 1) continue;
    const items = acceptanceItems(t.text).items.length;
    if (items > 1) continue;
    tkrPush(warnings, 'TV12', t.file, `${t.id} has ${items === 0 ? 'no acceptance items' : 'one acceptance item'}, no attachment and one task; `
      + 'may be below the ticket threshold; unless it is a promoted defect or spans more than one milestone or unit, '
      + 'a free-text line in the Milestones row is enough');
  }
}

/**
 * The problems that keep the tickets regions from being compared or written (`tickets write`, the
 * tickets part of a top-level `write`): TV1-TV3 and V13.
 *
 * @param {{ rule: string }[]} problems
 * @returns {{ rule: string }[]}
 */
function ticketsBlocking(problems) {
  return problems.filter((p) => TKR_BLOCKING.includes(p.rule));
}

/** V13 on the ticket files: each `ticket.md` read by the scan, the `knownFacts` file, the region files. */
function tkrConflicts(out, root, config, tickets) {
  const files = new Map();
  for (const t of tickets) if (t.text !== null) files.set(t.file, t.text);
  const fsv = createFsView(root);
  const extra = [...(config.knownFacts ? [config.knownFacts.path] : []), ...config.regions.map((r) => r.file)];
  for (const path of extra) {
    if (typeof path === 'string' && !files.has(path) && fsv.isFile(path)) files.set(path, fsv.readText(path));
  }
  for (const path of [...files.keys()].sort()) {
    const problem = conflictProblem(path, files.get(path));
    if (problem !== null) out.push({ ...problem, fix: null });
  }
}

/**
 * Checks the tickets of a repository.
 *
 * @param {string} root the repository root
 * @param {{ configPath?: string, registerPath?: string }} [opts] `registerPath` replaces `config.register`
 * @returns {{ configPath: string, config: object | null, register: object | null,
 *   problems: object[], warnings: object[], notes: { rule: string, where: string, message: string }[],
 *   regions: { file: string, marker: string, current: boolean }[], tickets: number, archived: number,
 *   model: { tickets: object[], state: object | null } | null }}
 */
function checkTickets(root, opts = {}) {
  const loaded = loadTicketsConfig(root, opts);
  const problems = [...loaded.problems];
  const warnings = [];
  const notes = [];
  const base = { configPath: loaded.configPath, config: loaded.config, register: loaded.register };
  if (loaded.config === null) {
    const conflicted = problems.some((p) => p.rule === 'V13');
    for (const rule of TKR_AFTER_CONFIG) {
      notes.push({ rule, where: loaded.configPath, message: conflicted ? TKR_NOT_CHECKED.replace('TV1', 'V13') : TKR_NOT_CHECKED });
    }
    return { ...base, problems: problems.sort(tkrCompare), warnings, notes, regions: [], tickets: 0, archived: 0, model: null };
  }
  const config = loaded.config;
  const scan = scanTickets(root, config);
  problems.push(...scan.problems);
  tkrConflicts(problems, root, config, scan.tickets);
  for (const t of scan.tickets) {
    t.fm = t.text === null ? null : parseFrontMatter(t.text);
    t.fields = t.fm === null ? {} : t.fm.fields;
    if (t.fm !== null) tkrFormat(problems, t);
  }
  tkrIdentity(problems, config, scan.tickets);
  tkrNesting(problems, config, scan.tickets);
  const data = loaded.register === null ? null : loaded.register.data;
  const min = data !== null && data.config !== null && typeof data.config === 'object' ? data.config.skipReasonMin : undefined;
  const key = (id) => {
    const m = /^(.*)-(\d+)$/.exec(id);
    return m ? `${m[1]}-${Number(m[2])}` : id;
  };
  const ctx = {
    reasonMin: Math.max(TKR_REASON_FLOOR, Number.isInteger(min) ? min : 0),
    idRe: ticketIdPattern(config),
    key,
    byKey: new Map(scan.tickets.map((t) => [key(t.id), t])),
  };
  const tm = data === null ? null : ticketModel(root, config, data, scan.tickets);
  if (tm !== null) ctx.findPlan = tkrPlanFinder(tm, config);
  for (const t of scan.tickets) {
    if (!tkrUsable(t)) continue;
    tkrResolution(problems, t, ctx);
    tkrNoStatus(problems, t);
  }
  if (tm === null) {
    for (const rule of TKR_NEED_REGISTER) notes.push({ rule, where: loaded.configPath, message: TKR_NOT_CHECKED });
  } else {
    const planCtx = { config, byId: tm.byId };
    for (const plan of tm.plans.values()) tkrPlanLinks(problems, warnings, plan, planCtx);
    tkrUnregisteredPlans(problems, tm);
    tkrHomes(problems, tm);
    tkrClosure(problems, tm, scan.tickets);
    tkrClosedMeansClosed(problems, warnings, tm, scan.tickets);
    const lc = tkrLinkContext(tm, config);
    for (const t of scan.tickets) {
      if (!tkrUsable(t)) continue;
      tkrFrontLinks(problems, warnings, t, lc);
      tkrBodyLinks(problems, t, tm.fsv);
    }
    for (const brief of tm.briefs) tkrCoverage(problems, tm, brief);
  }
  tkrSize(warnings, config, tm, scan.tickets);
  const regions = [];
  if (tm === null) {
    notes.push({ rule: 'TV11', where: loaded.configPath, message: `regions ${TKR_NOT_CHECKED}` });
  } else if (ticketsBlocking(problems).length > 0) {
    const tv = problems.some((p) => p.rule === 'TV1' || p.rule === 'TV2' || p.rule === 'TV3');
    notes.push({ rule: 'TV11', where: loaded.configPath, message: tv ? TKR_REGIONS_BLOCKED : TKR_REGIONS_BLOCKED_V13 });
  } else {
    for (const st of ticketsRegionStates(config, scan.tickets, tm, loaded.configPath)) {
      const current = st.error === undefined && st.content === st.expected;
      regions.push({ file: st.file, marker: st.marker, current });
      if (st.error !== undefined) problems.push({ rule: 'TV11', where: st.label, message: st.error, fix: null });
      else if (!current) problems.push({ rule: 'TV11', where: st.label, message: 'region is stale', fix: ['tickets', 'write'], diff: st.diff });
    }
  }
  const archived = scan.tickets.filter((t) => t.archived).length;
  return {
    ...base,
    problems: problems.sort(tkrCompare),
    warnings: warnings.sort(tkrCompare),
    notes,
    regions,
    tickets: scan.tickets.length - archived,
    archived,
    model: { tickets: scan.tickets, state: tm },
  };
}

// --- core/transaction.js ---
// The change transaction shared by `set`, `add-unit`, `add-plan` and `home-todo` (KD-7).
//
// The register is checked (V1–V11 and V13, without V12) before and after the change; the change is written
// only when it adds no problem (compared by rule + where + message; V8 `[~]` places without the line;
// the statuses, counts and line lists inside V6/V7/V8 messages left out), so a change may fix one problem
// while others remain. The "after" check runs on the new data with the pending file edits overlaid on
// the repository view, so the checks (V11 in particular) see the files as they would be written.
// File edits are applied only after the register write; `write: true` also regenerates the regions.

/**
 * The identity of a problem for the before/after comparison. A V8 `[~]` problem is placed at
 * `<path>:<line>`; its line number is left out, so a file edit that shifts lines (such as a
 * `**Source:**` line inserted above the box) does not make an old problem look new. Identities are
 * compared as a multiset (see `txNewProblems`), so one more bad box in the same file is still new.
 */
function txProblemId(p) {
  const where = p.rule === 'V8' && typeof p.where === 'string' ? p.where.replace(/:\d+$/, '') : p.where;
  return `${p.rule}\n${where}\n${txStableMessage(p)}`;
}

/**
 * A problem message without the data a change may alter while the problem stays the same one: the
 * statuses in a V6 message (the unit and the dependency key stay), the box count of a V8 "box(es) are
 * closed" message, and the heading count and line list of a V7 "matches N headings" message (the
 * section and the file stay), and the line list of a V13 conflict-marker message (the file stays; an
 * edit such as a `**Source:**` line inserted above the markers only shifts them). Every other message
 * is compared as it is.
 */
function txStableMessage(p) {
  const m = typeof p.message === 'string' ? p.message : String(p.message);
  if (p.rule === 'V6') {
    const v6 = /^is .+ but depends on ("(?:[^"\\]|\\.)*"), which is .+$/.exec(m);
    if (v6 !== null) return `depends on ${v6[1]}, which is not closed`;
  }
  if (p.rule === 'V8') return m.replace(/ but \d+ box\(es\) are closed /, ' but <n> box(es) are closed ');
  if (p.rule === 'V13') return 'unresolved git conflict markers';
  if (p.rule === 'V7') return m.replace(/ matches \d+ headings in (.+): lines [\d, ]+; make it unique$/, ' matches <n> headings in $1: lines <lines>; make it unique');
  return m;
}

/** The problems of `after` that are not in `before` (identities counted, not just looked up). */
function txNewProblems(before, after) {
  const counts = new Map();
  for (const p of before) counts.set(txProblemId(p), (counts.get(txProblemId(p)) ?? 0) + 1);
  return after.filter((p) => {
    const id = txProblemId(p);
    const left = counts.get(id) ?? 0;
    if (left === 0) return true;
    counts.set(id, left - 1);
    return false;
  });
}

/**
 * The problems that keep the canonical writer from writing the register as it is (fields it cannot
 * place: V1 "unknown field"), or null when it can write it. A change is not attempted then: the
 * unknown fields must be fixed by hand first.
 */
function txUnwritable(data, problems) {
  try {
    formatRegister(data);
    return null;
  } catch (e) {
    const unknown = problems.filter((p) => p.rule === 'V1' && typeof p.message === 'string' && p.message.startsWith('unknown field '));
    if (unknown.length > 0) return unknown;
    const message = String(e && e.message !== undefined ? e.message : e).replace(/^canonical-json: /, '');
    return [{ rule: 'V1', where: 'register', message: `${message}; the register cannot be rewritten until it is fixed by hand` }];
  }
}

/** A file's text with CRLF read as LF, or null when it cannot be read. */
function txReadLf(abs) {
  try {
    return readFileSync(abs, 'utf8').replace(/\r\n/g, '\n');
  } catch {
    return null;
  }
}

/**
 * The validated file edits: a Map of repository path → LF text (a later edit of the same path wins).
 *
 * @throws {Error} on a malformed edit or a path that is not repository-relative
 */
function txEdits(fileEdits) {
  const edits = new Map();
  if (fileEdits === undefined || fileEdits === null) return edits;
  if (!Array.isArray(fileEdits)) throw new Error('applyMutation: fileEdits must be an array');
  for (const e of fileEdits) {
    const path = e && typeof e === 'object' ? normalizePath(e.path) : null;
    if (path === null) throw new Error(`applyMutation: file edit path ${JSON.stringify(e && e.path)} is not a repository-relative path`);
    if (typeof e.text !== 'string') throw new Error(`applyMutation: file edit ${path} has no text`);
    edits.set(path, e.text.replace(/\r\n/g, '\n'));
  }
  return edits;
}

/**
 * A repository view with pending edits overlaid: edited paths exist as files with the new text and
 * new `.md` files appear in the listings of their directories.
 *
 * @param {ReturnType<typeof createFsView>} base
 * @param {Map<string, string>} edits
 * @returns {ReturnType<typeof createFsView>}
 */
function txOverlay(base, edits) {
  const key = (p) => normalizePath(p);
  return {
    exists(p) {
      return edits.has(key(p)) || base.exists(p);
    },
    isFile(p) {
      return edits.has(key(p)) || base.isFile(p);
    },
    readText(p) {
      const k = key(p);
      return edits.has(k) ? edits.get(k) : base.readText(p);
    },
    listMd(dir, recursive = false) {
      const listed = new Set(base.listMd(dir, recursive));
      for (const path of edits.keys()) {
        if (path.endsWith('.md') && inDir(path, dir, recursive === true)) listed.add(path);
      }
      return [...listed].sort();
    },
  };
}

/**
 * Applies a change to the register as one transaction (KD-7).
 *
 * `fn(data)` gets a deep copy of the register and returns `{ data, changes, fileEdits? }`; errors it
 * throws (usage errors) propagate and nothing is written. The result:
 * - `written`: true when the register or a file edit was written (false when refused or unchanged);
 * - `changes`: the change lines of `fn`;
 * - `newProblems`: problems the change would add (non-empty = refused, nothing written); when the
 *   register cannot be read or has an unsupported schema, that V1 problem (V13 for conflict markers), and when it has fields the
 *   canonical writer cannot place, its V1 "unknown field" problems; `fn` is not called then;
 * - `problems`: every V1–V11 and V13 problem of the result;
 * - `regions` (only with `write: true`): the `writeRegions` result, or null when problems remain
 *   (regions are not regenerated from a register with problems).
 *
 * @param {string} root
 * @param {{ registerPath?: string, write?: boolean }} opts
 * @param {(data: object) => { data: object, changes?: string[], fileEdits?: { path: string, text: string }[] }} fn
 * @returns {{ written: boolean, changes: string[], newProblems: object[], problems: object[],
 *   regions?: { file: string, marker: string, changed: boolean }[] | null }}
 */
/**
 * A wrong command-line usage detected while applying a change (bad flag value, flag not allowed for the
 * unit, missing argument). The CLI prints the message and exits with code 2; the register is not touched.
 */
class UsageError extends Error {
  constructor(message) {
    super(message);
    this.name = 'UsageError';
  }
}

function applyMutation(root, { registerPath = DEFAULTS.registerPath, write = false } = {}, fn) {
  const loaded = loadRegister(root, { registerPath });
  if (loaded.data === null) return { written: false, changes: [], newProblems: loaded.problems, problems: loaded.problems };
  const fsv = createFsView(root);
  const before = loadDataProblems(loaded.data, fsv);
  if (before.progress === null) return { written: false, changes: [], newProblems: before.problems, problems: before.problems };
  const unwritable = txUnwritable(loaded.data, before.problems);
  if (unwritable !== null) return { written: false, changes: [], newProblems: unwritable, problems: before.problems };

  const result = fn(structuredClone(loaded.data));
  if (!result || typeof result !== 'object' || result.data === undefined) {
    throw new Error('applyMutation: the change must return { data, changes }');
  }
  const changes = Array.isArray(result.changes) ? result.changes : [];
  const edits = txEdits(result.fileEdits);
  const after = loadDataProblems(result.data, txOverlay(fsv, edits));
  const newProblems = txNewProblems(before.problems, after.problems);
  if (newProblems.length > 0) return { written: false, changes, newProblems, problems: after.problems };

  const base = resolve(root);
  const registerFile = isAbsolute(registerPath) ? registerPath : resolve(base, registerPath);
  const text = formatRegister(result.data);
  let written = false;
  if (txReadLf(registerFile) !== text) {
    writeFileSync(registerFile, text);
    written = true;
  }
  for (const [path, editText] of edits) {
    const abs = join(base, ...path.split('/'));
    if (txReadLf(abs) === editText) continue;
    mkdirSync(dirname(abs), { recursive: true });
    writeFileSync(abs, editText);
    written = true;
  }
  const out = { written, changes, newProblems: [], problems: after.problems };
  if (write === true) out.regions = after.problems.length === 0 ? writeRegions(root, { registerPath }) : null;
  return out;
}

// --- core/query.js ---
// Read-only answers about the register: `status`, `show`, `next`, `chain`, `check` and `version`,
// as JSON (contract `plan-register-show/1`) and as short text forms for the terminal.
//
// Every JSON answer carries `contract`, `tool` (the plugin version), `schema` (the register schema)
// and `view`. The answers work on a query context (`queryContext`):
//
//   { root, registerPath, data, fsv, progress, problems, regions }
//
//   root          absolute repository root
//   registerPath  the register path as checkRepo labels it (repository-relative when inside root)
//   data          the parsed register (never null in a context)
//   fsv           createFsView(root)
//   progress      Map<key, { done, total, skipped } | null> from computeProgress
//   problems      the problems of checkRepo (V1–V13), counted by `status`
//   regions       the region states of checkRepo
//
// A context may also be built by hand (tests, other callers): only `data` and `fsv` are needed;
// a missing `progress` is computed, missing `problems` count as none.
//
// The graph functions throw on a dependency cycle (which `check` reports as V5). Here a cycle is
// guarded: nothing is ready, `active` falls back to register order and the chain is empty.

function qIsObj(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

function qList(v) {
  return Array.isArray(v) ? v : [];
}

function qStrOrNull(v) {
  return typeof v === 'string' && v !== '' ? v : null;
}

/** The common head of every JSON answer. */
function qHead(view) {
  return { contract: SHOW_CONTRACT, tool: VERSION, schema: SCHEMA, view };
}

/** The usable units of the register (objects with a string key), in register order. */
function qUnits(ctx) {
  return qList(ctx.data && ctx.data.units).filter((u) => qIsObj(u) && typeof u.key === 'string');
}

/** The first unit of each key. */
function qByKey(ctx) {
  const byKey = new Map();
  for (const u of qUnits(ctx)) if (!byKey.has(u.key)) byKey.set(u.key, u);
  return byKey;
}

/** The progress map of the context (computed when the context has none). */
function qProgress(ctx) {
  if (ctx.progress instanceof Map) return ctx.progress;
  return computeProgress(ctx.data, (p) => ctx.fsv.readText(p)).byKey;
}

/** `fn()`, or `fallback` when it throws (the graph functions throw on a cycle). */
function qGuard(fn, fallback) {
  try {
    return fn();
  } catch {
    return fallback;
  }
}

/** Keys of the ready units ([] on a cycle). */
function qReady(ctx) {
  return qGuard(() => readyUnits(qUnits(ctx)), []);
}

/** Keys of the units in progress (register order on a cycle). */
function qActive(ctx) {
  const units = qUnits(ctx);
  return qGuard(() => activeUnits(units), units.filter((u) => u.status === 'In progress').map((u) => u.key));
}

/** The longest open chain, or null on a cycle. */
function qChain(ctx) {
  return qGuard(() => longestChain(qUnits(ctx)), null);
}

/**
 * Builds the query context of a repository: loads and checks the register (checkRepo).
 *
 * @param {string} root
 * @param {{ registerPath?: string }} [opts]
 * @returns {{ root: string, registerPath: string, data: object, fsv: ReturnType<typeof createFsView>,
 *   progress: Map<string, object | null>, problems: object[], regions: object[] }}
 * @throws {Error} when the register cannot be read or its schema is not supported (the V1 problem text)
 */
function queryContext(root, opts = {}) {
  const registerPath = typeof opts.registerPath === 'string' && opts.registerPath !== '' ? opts.registerPath : DEFAULTS.registerPath;
  const checked = checkRepo(root, { registerPath });
  if (checked.data === null || checked.progress === null) {
    throw new Error(checked.problems.map(problemText).join('\n'));
  }
  const label = normalizePath(registerPath) ?? registerPath;
  return {
    root,
    registerPath: label,
    data: checked.data,
    fsv: createFsView(root),
    progress: checked.progress,
    problems: checked.problems,
    regions: checked.regions,
  };
}

/**
 * Resolves a unit key or alias. `note` is the stderr note for an alias (`"Stage 2.2" is an alias of ST-22`).
 *
 * @param {{ data: object }} ctx
 * @param {string} name
 * @returns {{ key: string, viaAlias: boolean, unit: object, note: string | null }}
 * @throws {Error} `unknown unit "X" (known: A, B)` with `code: 'unknown-unit'`
 */
function resolveUnit(ctx, name) {
  const r = resolveKey(ctx.data, name);
  const unit = r === null ? undefined : qByKey(ctx).get(r.key);
  if (r === null || unit === undefined) {
    const known = [...qByKey(ctx).keys()];
    const err = new Error(`unknown unit ${JSON.stringify(String(name))} (known: ${known.length > 0 ? known.join(', ') : 'none'})`);
    err.code = 'unknown-unit';
    throw err;
  }
  return {
    key: r.key,
    viaAlias: r.viaAlias,
    unit,
    note: r.viaAlias ? `${JSON.stringify(String(name))} is an alias of ${r.key}` : null,
  };
}

/** The date for file names: `date` when given (YYYY-MM-DD), else today (UTC). */
function qDate(date) {
  if (date === undefined || date === null) return new Date().toISOString().slice(0, 10);
  if (typeof date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
    throw new UsageError(`--date must be YYYY-MM-DD, got ${JSON.stringify(String(date))}`);
  }
  const parsed = new Date(`${date}T00:00:00Z`);
  if (Number.isNaN(parsed.getTime()) || parsed.toISOString().slice(0, 10) !== date) {
    throw new UsageError(`--date is not a calendar date: ${JSON.stringify(date)}`);
  }
  return date;
}

/** The slug of a title: its first six words in `[a-z0-9]`, joined by `-`, at most 40 characters. */
function qSlug(title) {
  const words = String(title ?? '').toLowerCase().split(/[^a-z0-9]+/).filter((w) => w !== '').slice(0, 6);
  while (words.length > 1 && words.join('-').length > 40) words.pop();
  return words.join('-').slice(0, 40).replace(/-+$/, '');
}

/** The usable plan directories, normalized. */
function qPlanDirs(data) {
  const dirs = qIsObj(data) && qIsObj(data.config) ? qList(data.config.planDirs) : [];
  return dirs
    .filter((d) => qIsObj(d) && typeof d.path === 'string' && normalizePath(d.path) !== null)
    .map((d) => normalizePath(d.path));
}

/**
 * The suggested path of a new plan for a unit:
 * `<first planDir that is not archive.dir or inside it>/<date>-<key lower case>-<slug of the title>.md`.
 * Null when every plan directory is in the archive.
 *
 * @param {object} data
 * @param {object} unit
 * @param {{ date?: string }} [opts]
 * @returns {string | null}
 */
function suggestedPlanPath(data, unit, { date } = {}) {
  const day = qDate(date);
  const archive = qIsObj(data) && qIsObj(data.config) && qIsObj(data.config.archive)
    && typeof data.config.archive.dir === 'string' ? normalizePath(data.config.archive.dir) : null;
  const dir = qPlanDirs(data).find((d) => archive === null || (d !== archive && !inDir(d, archive, true)));
  if (dir === undefined) return null;
  const slug = qSlug(unit.title);
  return `${dir === '.' ? '' : `${dir}/`}${day}-${String(unit.key).toLowerCase()}${slug === '' ? '' : `-${slug}`}.md`;
}

/**
 * The document for the `**Source:**` line of a unit's executable plan (KD-11): the path of its first
 * `brief` plan, else of its first `scope` plan, else the file of the first region; null when none.
 *
 * @param {object} data
 * @param {object} unit
 * @returns {string | null}
 */
function querySourceDoc(data, unit) {
  const plans = qList(unit.plans).filter((p) => qIsObj(p) && typeof p.path === 'string');
  const brief = plans.find((p) => p.role === 'brief');
  const scope = plans.find((p) => p.role === 'scope');
  const pick = brief ?? scope;
  if (pick !== undefined) return normalizePath(pick.path) ?? pick.path;
  const regions = qIsObj(data) && qIsObj(data.config) ? qList(data.config.regions) : [];
  const region = regions.find((r) => qIsObj(r) && typeof r.file === 'string');
  return region === undefined ? null : normalizePath(region.file) ?? region.file;
}

/** The blockers of a unit: open `dependsOn` units, then each `waitsOn` entry. */
function qBlockers(unit, byKey) {
  const out = [];
  for (const d of qList(unit.dependsOn)) {
    const dep = byKey.get(d);
    if (dep === undefined) out.push({ type: 'dependsOn', key: d, status: null });
    else if (!CLOSED_STATUSES.includes(dep.status)) out.push({ type: 'dependsOn', key: d, status: dep.status });
  }
  for (const w of qList(unit.waitsOn)) {
    if (!qIsObj(w)) continue;
    const b = { type: w.kind, ref: w.ref };
    if (w.note !== undefined) b.note = w.note;
    out.push(b);
  }
  return out;
}

/**
 * One blocker as text: `Lot-3 (In progress)`, `Lot-9 (unknown)`, `decision: DX-1`, `credential`
 * (its ref is not shown, as in the Status cell), `external: <ref>`.
 *
 * @param {{ type: string, key?: string, status?: string | null, ref?: string }} b
 * @returns {string}
 */
function queryBlockerText(b) {
  if (b.type === 'dependsOn') return `${b.key} (${b.status ?? 'unknown'})`;
  if (b.type === 'credential') return 'credential';
  return `${b.type}: ${b.ref}`;
}

/** The `unit` object of the show answer. */
function qShowUnit(ctx, unit) {
  const byKey = qByKey(ctx);
  const progress = qProgress(ctx).get(unit.key) ?? null;
  const open = openTodos(ctx.data, ctx.fsv);
  const decisions = decisionIndex(ctx.data, ctx.fsv);
  return {
    key: unit.key,
    kind: typeof unit.kind === 'string' ? unit.kind : KINDS[0],
    aliases: qList(unit.aliases),
    phase: qStrOrNull(unit.phase),
    title: unit.title ?? null,
    status: unit.status ?? null,
    pr: Number.isInteger(unit.pr) ? unit.pr : null,
    owner: qStrOrNull(unit.owner),
    dependsOn: qList(unit.dependsOn),
    after: qList(unit.after),
    waitsOn: qList(unit.waitsOn),
    progress: progress === null ? null : { done: progress.done, total: progress.total, skipped: progress.skipped },
    ready: qReady(ctx).includes(unit.key),
    blockers: qBlockers(unit, byKey),
    dependents: qUnits(ctx).filter((u) => qList(u.dependsOn).includes(unit.key)).map((u) => u.key),
    plans: qList(unit.plans).filter((p) => qIsObj(p) && typeof p.path === 'string').map((p) => {
      const path = normalizePath(p.path) ?? p.path;
      return {
        path,
        section: qStrOrNull(p.section),
        role: p.role ?? null,
        scope: qStrOrNull(p.scope),
        exists: ctx.fsv.isFile(path),
      };
    }),
    todos: qList(unit.todos).filter((t) => typeof t === 'string').map((t) => {
      const path = normalizePath(t) ?? t;
      return { path, open: open.includes(path) };
    }),
    decisions: qList(unit.decisions).filter((id) => typeof id === 'string').map((id) => {
      const d = decisions.get(id);
      return d === undefined
        ? { id, log: null, heading: null, line: null }
        : { id, log: d.log, heading: d.heading, line: d.line };
    }),
    closedBy: qStrOrNull(unit.closedBy),
  };
}

/**
 * The `show` answer of one unit (key or alias).
 *
 * `blockers`: every open `dependsOn` unit as `{ type: 'dependsOn', key, status }` (status null for an
 * unknown key), then every `waitsOn` entry as `{ type: <kind>, ref, note? }`. `dependents`: the units
 * that list this unit in `dependsOn`. `decisions`: log, heading and 1-based line from the decision
 * logs (all null when the id is not found).
 *
 * @param {object} ctx a query context
 * @param {string} name
 * @param {{ date?: string }} [opts] the date of `suggestedPlanPath` (default: today, UTC)
 * @returns {object}
 * @throws {Error} on an unknown unit (see resolveUnit)
 */
function showJson(ctx, name, { date } = {}) {
  const { unit } = resolveUnit(ctx, name);
  const doc = querySourceDoc(ctx.data, unit);
  return {
    ...qHead('show'),
    unit: qShowUnit(ctx, unit),
    suggestedPlanPath: suggestedPlanPath(ctx.data, unit, { date }),
    sourceLine: doc === null ? null : `**Source:** ${doc}#${unit.key}`,
  };
}

/** The readiness line of a shown unit: `ready`, `in progress (PR #7)`, `closed (Done)` or `not ready: …`. */
function qReadyText(u) {
  if (CLOSED_STATUSES.includes(u.status)) return `closed (${u.status})`;
  if (u.status === 'In progress') return `in progress${u.pr !== null ? ` (PR #${u.pr})` : ''}`;
  if (u.ready) return 'ready';
  return `not ready: ${u.blockers.length > 0 ? u.blockers.map(queryBlockerText).join(', ') : 'waiting'}`;
}

/**
 * The text form of `show`: the unit, its readiness, plans, TODOs, decisions and the suggestions.
 *
 * @param {object} ctx
 * @param {string} name
 * @param {{ date?: string }} [opts]
 * @returns {string}
 */
function showText(ctx, name, opts = {}) {
  const s = showJson(ctx, name, opts);
  const u = s.unit;
  const lines = [`${u.key} — ${u.title}`];
  lines.push(`  ${u.kind} · phase ${u.phase ?? '-'} · ${u.status}${u.pr !== null ? ` (PR #${u.pr})` : ''}`
    + `${u.owner !== null ? ` · owner ${u.owner}` : ''} · progress ${progressCell(u.progress)}`);
  if (u.aliases.length > 0) lines.push(`  Aliases: ${u.aliases.join(', ')}`);
  lines.push(`  Ready: ${qReadyText(u)}`);
  lines.push(`  Depends on: ${u.dependsOn.length > 0 ? u.dependsOn.join(', ') : 'none'}`
    + `${u.after.length > 0 ? `; after ${u.after.join(', ')}` : ''}`);
  if (u.dependents.length > 0) lines.push(`  Needed by: ${u.dependents.join(', ')}`);
  lines.push('  Plans:');
  if (u.plans.length === 0) lines.push('    none');
  for (const p of u.plans) {
    const notes = [p.role, p.scope !== null ? `scope: ${p.scope}` : null, p.exists ? null : 'missing'].filter((n) => n !== null);
    lines.push(`    ${p.path}${p.section !== null ? ` § ${p.section}` : ''} (${notes.join('; ')})`);
  }
  if (u.todos.length > 0) {
    lines.push('  TODO notes:');
    for (const t of u.todos) lines.push(`    ${t.path}${t.open ? '' : ' (archived)'}`);
  }
  if (u.decisions.length > 0) {
    lines.push('  Decisions:');
    for (const d of u.decisions) lines.push(d.log === null ? `    ${d.id} (not found)` : `    ${d.heading} (${d.log}:${d.line})`);
  }
  if (u.closedBy !== null) lines.push(`  Closed by: ${u.closedBy}`);
  if (s.suggestedPlanPath !== null) lines.push(`  Suggested plan path: ${s.suggestedPlanPath}`);
  if (s.sourceLine !== null) lines.push(`  Source line: ${s.sourceLine}`);
  return lines.join('\n');
}

/** Open TODOs without a home and not listed in `config.todos.unhomed`. */
function qUnhomedTodos(ctx) {
  const homes = new Set();
  for (const u of qUnits(ctx)) for (const t of qList(u.todos)) if (typeof t === 'string') homes.add(normalizePath(t) ?? t);
  const t = qIsObj(ctx.data.config) && qIsObj(ctx.data.config.todos) ? ctx.data.config.todos : null;
  const unhomed = new Set(t !== null && qIsObj(t.unhomed) ? Object.keys(t.unhomed).map((p) => normalizePath(p) ?? p) : []);
  return openTodos(ctx.data, ctx.fsv).filter((p) => !homes.has(p) && !unhomed.has(p));
}

/**
 * Open TODOs listed in `config.todos.unhomed` with a reason that starts with PENDING_TODO_PREFIX:
 * left unhomed only until they are placed in a unit.
 */
function qPendingTodos(ctx) {
  const t = qIsObj(ctx.data.config) && qIsObj(ctx.data.config.todos) ? ctx.data.config.todos : null;
  if (t === null || !qIsObj(t.unhomed)) return [];
  const pending = new Set();
  for (const [p, reason] of Object.entries(t.unhomed)) {
    if (typeof reason === 'string' && reason.startsWith(PENDING_TODO_PREFIX)) pending.add(normalizePath(p) ?? p);
  }
  return openTodos(ctx.data, ctx.fsv).filter((p) => pending.has(p));
}

/**
 * The `status` answer. `counts` has every status (0 included) in the order of STATUSES; `phases`
 * lists the keys of each phase's units in `units`; `problems` is the number of problems checkRepo
 * found, without informational entries (`info: true`, the V12 "regions not checked" note); 0 for a
 * hand-built context without `problems`.
 *
 * @param {object} ctx
 * @returns {object}
 */
function statusJson(ctx) {
  const units = qUnits(ctx);
  const progress = qProgress(ctx);
  const ready = qReady(ctx);
  const byKey = qByKey(ctx);
  const counts = {};
  for (const s of STATUSES) counts[s] = 0;
  for (const u of units) if (typeof u.status === 'string') counts[u.status] = (counts[u.status] ?? 0) + 1;
  return {
    ...qHead('status'),
    unitName: unitNames(ctx.data.config).singular,
    counts,
    phases: qList(ctx.data.phases).filter((p) => qIsObj(p) && typeof p.key === 'string').map((p) => {
      const own = units.filter((u) => u.phase === p.key);
      return { key: p.key, title: p.title ?? null, status: phaseStatus(own.map((u) => u.status)), units: own.map((u) => u.key) };
    }),
    units: units.map((u) => {
      const p = progress.get(u.key) ?? null;
      return {
        key: u.key,
        kind: typeof u.kind === 'string' ? u.kind : KINDS[0],
        title: u.title ?? null,
        status: u.status ?? null,
        pr: Number.isInteger(u.pr) ? u.pr : null,
        progress: p === null ? null : { done: p.done, total: p.total, skipped: p.skipped },
        ready: ready.includes(u.key),
      };
    }),
    ready,
    active: qActive(ctx).map((key) => ({ key, pr: Number.isInteger(byKey.get(key).pr) ? byKey.get(key).pr : null })),
    unhomedTodos: qUnhomedTodos(ctx),
    pendingTodos: qPendingTodos(ctx),
    pendingTodoPrefix: PENDING_TODO_PREFIX,
    problems: Array.isArray(ctx.problems) ? ctx.problems.filter((p) => !(p && p.info === true)).length : 0,
  };
}

/** `Lot-3 — Split large modules (PR #7)` */
function qUnitLine(u) {
  return `  ${u.key} — ${u.title}${Number.isInteger(u.pr) ? ` (PR #${u.pr})` : ''}`;
}

/**
 * The text form of `status`: a counts line, then `Active:`, `Ready:` and `Blocked:` (one unit per
 * line; a blocked unit is a `Not started` unit that is not ready, with its blockers), then
 * `Unhomed TODO notes:` and `TODO notes awaiting placement:` only when there are some. Empty lists
 * print `none`.
 *
 * @param {object} ctx
 * @returns {string}
 */
function statusText(ctx) {
  const s = statusJson(ctx);
  const names = unitNames(ctx.data.config);
  const byKey = qByKey(ctx);
  const counts = Object.entries(s.counts).filter(([, n]) => n > 0).map(([status, n]) => `${n} ${status}`);
  const total = s.units.length;
  const lines = [`${total} ${total === 1 ? names.singular : names.plural}: ${counts.length > 0 ? counts.join(', ') : 'none'}; ${s.problems} problem(s)`];
  const section = (title, rows) => {
    lines.push(`${title}:`);
    if (rows.length === 0) lines.push('  none');
    else lines.push(...rows);
  };
  section('Active', s.active.map((a) => qUnitLine(byKey.get(a.key))));
  section('Ready', s.ready.map((key) => qUnitLine(byKey.get(key))));
  const blocked = s.units.filter((u) => u.status === 'Not started' && !u.ready).map((u) => {
    const b = qBlockers(byKey.get(u.key), byKey);
    return `${qUnitLine(byKey.get(u.key))}: waiting: ${b.length > 0 ? b.map(queryBlockerText).join(', ') : 'dependency cycle'}`;
  });
  section('Blocked', blocked);
  if (s.unhomedTodos.length > 0) section('Unhomed TODO notes', s.unhomedTodos.map((p) => `  ${p}`));
  if (s.pendingTodos.length > 0) section('TODO notes awaiting placement', s.pendingTodos.map((p) => `  ${p}`));
  return lines.join('\n');
}

/**
 * The `next` answer: the ready units and the units in progress.
 *
 * @param {object} ctx
 * @returns {object}
 */
function nextJson(ctx) {
  const byKey = qByKey(ctx);
  return {
    ...qHead('next'),
    ready: qReady(ctx).map((key) => {
      const u = byKey.get(key);
      return { key, title: u.title ?? null, kind: typeof u.kind === 'string' ? u.kind : KINDS[0], status: u.status };
    }),
    active: qActive(ctx).map((key) => {
      const u = byKey.get(key);
      return { key, title: u.title ?? null, pr: Number.isInteger(u.pr) ? u.pr : null };
    }),
  };
}

/**
 * The text form of `next`: `Ready:` then `Active:`, one unit per line (`none` when empty).
 *
 * @param {object} ctx
 * @returns {string}
 */
function nextText(ctx) {
  const n = nextJson(ctx);
  const lines = ['Ready:'];
  if (n.ready.length === 0) lines.push('  none');
  for (const u of n.ready) lines.push(`  ${u.key} — ${u.title}${u.kind !== KINDS[0] ? ` (${u.kind})` : ''}`);
  lines.push('Active:');
  if (n.active.length === 0) lines.push('  none');
  for (const u of n.active) lines.push(qUnitLine(u));
  return lines.join('\n');
}

/**
 * The `chain` answer: the longest dependency chain among the open units (`[]` when none is open or
 * the dependencies contain a cycle).
 *
 * @param {object} ctx
 * @returns {{ contract: string, tool: string, schema: string, view: 'chain', chain: string[], length: number }}
 */
function chainJson(ctx) {
  const chain = qChain(ctx) ?? [];
  return { ...qHead('chain'), chain, length: chain.length };
}

/**
 * The text form of `chain`: `A → B → C (3 <plural>)` with the register's unit name
 * (`(1 <singular>)` for one unit), `none` without open units, or a note on a cycle.
 *
 * @param {object} ctx
 * @returns {string}
 */
function chainText(ctx) {
  const chain = qChain(ctx);
  if (chain === null) return 'not computed (the dependencies contain a cycle; run check)';
  if (chain.length === 0) return 'none';
  const names = unitNames(ctx.data.config);
  return `${chain.join(' → ')} (${chain.length} ${chain.length === 1 ? names.singular : names.plural})`;
}

/**
 * The `check` answer from a checkRepo result. `fix` is the CLI argument list of an unambiguous fix
 * (KD-8) or null; pass `fixText` to turn it into a command line. Informational entries (`info: true`,
 * the V12 "regions not checked" line) go to `notes` `{rule, where, message}`, not to `problems`, and do
 * not affect `ok`.
 *
 * @param {{ problems: object[], regions: object[] }} result
 * @param {{ fixText?: (args: string[]) => string }} [opts]
 * @returns {object}
 */
function checkJson(result, { fixText } = {}) {
  const all = qList(result && result.problems);
  const notes = all.filter((p) => p && p.info === true).map((p) => ({ rule: p.rule, where: p.where, message: p.message }));
  const problems = all.filter((p) => !(p && p.info === true)).map((p) => {
    const fix = Array.isArray(p.fix) ? p.fix : null;
    return {
      rule: p.rule,
      where: p.where,
      message: p.message,
      fix: fix !== null && typeof fixText === 'function' ? fixText(fix) : fix,
    };
  });
  return {
    ...qHead('check'),
    ok: problems.length === 0,
    problems,
    notes,
    regions: qList(result && result.regions).map((r) => ({ file: r.file, marker: r.marker, current: r.current === true })),
  };
}

/**
 * The `version` answer. `header` is what the caller read from the running file's first line
 * (e.g. the parsed copy header), or null.
 *
 * @param {{ header?: unknown }} [opts]
 * @returns {object}
 */
function versionJson({ header = null } = {}) {
  return { ...qHead('version'), version: VERSION, schemas: [...SUPPORTED_SCHEMAS], header };
}

// --- core/brief.js ---
// The scope brief of a unit (`show <key> --brief`): a Markdown page for whoever writes the unit's
// executable plan. It collects the unit record, the verbatim text of its plan sections, its TODO
// notes and decisions with their headings, the status of its dependencies with a not-ready warning,
// the suggested plan path, the recommended `**Source:**` line and the `add-plan` command that will
// write that line (KD-11).
//
// Plan sections: an entry with `section` inlines the section text (heading included). An entry
// without `section` inlines the whole file for the `brief` and `scope` roles; an `executable` plan
// is already a written plan and is listed without its text. A missing file or a section that does
// not match exactly one heading gets a one-line note instead of text. Empty sections print `none`.

/** A table cell: one line, `|` escaped. */
function brCell(text) {
  return String(text).replace(/\r?\n/g, ' ').replace(/\|/g, '\\|');
}

/** A shell argument: as is when it is plain, else double-quoted. */
function brArg(text) {
  const s = String(text);
  return /^[A-Za-z0-9._/:=@+-]+$/.test(s) ? s : `"${s.replace(/(["\\$`])/g, '\\$1')}"`;
}

/** Text without trailing blank lines. */
function brTrimEnd(text) {
  return text.replace(/\s+$/, '');
}

/** The **Ready:** value of the brief. */
function brReadyLine(u) {
  if (CLOSED_STATUSES.includes(u.status)) return `Closed (${u.status})`;
  if (u.status === 'In progress') return `In progress${u.pr !== null ? ` (PR #${u.pr})` : ''}`;
  if (u.ready) return 'Ready';
  return `Not ready: ${u.blockers.length > 0 ? u.blockers.map(queryBlockerText).join(', ') : 'waiting'}`;
}

/** Dependency rows: each `dependsOn` and `after` key with the status of that unit. */
function brDependencies(ctx, u) {
  const byKey = new Map();
  for (const x of Array.isArray(ctx.data.units) ? ctx.data.units : []) {
    if (x && typeof x === 'object' && typeof x.key === 'string' && !byKey.has(x.key)) byKey.set(x.key, x);
  }
  const rows = [];
  for (const [type, keys] of [['dependsOn', u.dependsOn], ['after', u.after]]) {
    for (const k of keys) {
      const dep = byKey.get(k);
      rows.push(`| \`${brCell(k)}\` | ${type} | ${brCell(dep === undefined ? 'unknown' : dep.status)} |`);
    }
  }
  if (rows.length === 0) return ['none'];
  return ['| Key | Type | Status |', '| --- | --- | --- |', ...rows];
}

/** One line per `waitsOn` entry: `decision: DX-1`, `credential: supplier portal access (K-1)`. */
function brWaitsOn(u) {
  const rows = u.waitsOn
    .filter((w) => w && typeof w === 'object')
    .map((w) => `- ${w.kind}: ${w.ref}${w.note !== undefined ? ` (${w.note})` : ''}`);
  return rows.length > 0 ? rows : ['none'];
}

/** `path § section` or `path`. */
function brPlanName(p) {
  return p.section !== null ? `${p.path} § ${p.section}` : p.path;
}

function brPlans(u) {
  const rows = u.plans.map((p) => {
    const notes = [p.role, p.scope !== null ? `scope: ${p.scope}` : null, p.exists ? null : 'file missing'].filter((n) => n !== null);
    return `- ${brPlanName(p)} (${notes.join('; ')})`;
  });
  return rows.length > 0 ? rows : ['none'];
}

/** `### <plan>` and the verbatim text (or a note) of each plan entry. */
function brPlanSections(ctx, u) {
  const out = [];
  for (const p of u.plans) {
    out.push(`### ${brPlanName(p)}`, '');
    const text = p.exists ? ctx.fsv.readText(p.path) : null;
    if (text === null) {
      out.push(`(file ${p.path} does not exist)`, '');
    } else if (p.section !== null) {
      const s = sectionText(text, p.section);
      out.push(s === null ? `(section "${p.section}" does not match exactly one heading in ${p.path})` : brTrimEnd(s), '');
    } else if (p.role === 'executable') {
      out.push('(executable plan; read the file itself)', '');
    } else {
      out.push(brTrimEnd(text), '');
    }
  }
  if (out.length === 0) return ['none'];
  out.pop();
  return out;
}

/** One line per TODO note: path, its first heading, open or archived. */
function brTodos(ctx, u) {
  const rows = u.todos.map((t) => {
    const text = ctx.fsv.isFile(t.path) ? ctx.fsv.readText(t.path) : null;
    const first = text === null ? undefined : headings(text)[0];
    const title = first === undefined ? '' : ` — ${first.text}`;
    return `- ${t.path}${title} (${text === null ? 'missing' : t.open ? 'open' : 'archived'})`;
  });
  return rows.length > 0 ? rows : ['none'];
}

/** One line per decision: its heading and where it is. */
function brDecisions(u) {
  const rows = u.decisions.map((d) => (d.log === null
    ? `- ${d.id} (not found in the decision logs)`
    : `- ${d.heading} (${d.log}:${d.line})`));
  return rows.length > 0 ? rows : ['none'];
}

/**
 * The scope brief of a unit as Markdown (LF, ends with a newline).
 *
 * @param {object} ctx a query context (see core/query.js)
 * @param {string} name unit key or alias
 * @param {{ date?: string, scriptPath?: string, registerPath?: string }} [opts] `date` for the suggested
 *   plan path (default: today, UTC); `scriptPath` of the CLI in the command lines (default
 *   `scripts/plan-register.mjs`); `registerPath` of the run: a non-default one is appended to the
 *   command lines as `--register <path>`
 * @returns {string}
 * @throws {Error} on an unknown unit
 */
function briefMarkdown(ctx, name, { date, scriptPath = DEFAULTS.scriptPath, registerPath = DEFAULTS.registerPath } = {}) {
  const s = showJson(ctx, name, { date });
  const register = registerPath !== DEFAULTS.registerPath ? ` --register ${brArg(registerPath)}` : '';
  const u = s.unit;
  const lines = [
    `# Scope brief: ${u.key} — ${u.title}`,
    '',
    `**Unit:** \`${u.key}\` · ${u.kind} · phase \`${u.phase ?? '-'}\` · ${u.status}${u.pr !== null ? ` (PR #${u.pr})` : ''}`
      + `${u.owner !== null ? ` · owner ${u.owner}` : ''}`,
    `**Ready:** ${brReadyLine(u)}`,
    `**Suggested plan path:** ${s.suggestedPlanPath ?? 'none (every plan directory is in the archive)'}`,
    `**Source line for the plan:** ${s.sourceLine === null ? 'none' : `${s.sourceLine} (add-plan writes it for you)`}`,
    '',
    '## Dependencies',
    '',
    ...brDependencies(ctx, u),
    '',
    '## Waits on',
    '',
    ...brWaitsOn(u),
    '',
    '## Plans',
    '',
    ...brPlans(u),
    '',
    '## Plan sections',
    '',
    ...brPlanSections(ctx, u),
    '',
    '## TODO notes',
    '',
    ...brTodos(ctx, u),
    '',
    '## Decisions',
    '',
    ...brDecisions(u),
    '',
    '## After the plan is written',
    '',
    `node ${scriptPath} add-plan ${brArg(u.key)} <plan path> --role executable --scope "<part>" --write${register}`,
    '',
  ];
  return lines.join('\n');
}

// --- core/mutate-units.js ---
// Pure changes of units for `set` and `add-unit` (run inside applyMutation, KD-7).
//
// Each function takes a (deep-copied) register and returns `{ data, changes }`; it throws UsageError on
// a wrong usage (unknown unit, bad flag value, flags that cannot go together). Everything else is left
// to the V1–V11 and V13 checks of the transaction: a change that adds a problem (an unknown dependency, a
// closed unit with an open dependency, a duplicate key, a gate without config.keyPatterns.gate) is
// refused there and nothing is written. Phases and `config` are never changed here.
//
// Unit names given as arguments (the key, `dependsOn`, `after`, `insertAfter`) may be aliases: they
// are resolved to keys with resolveKey, and a change line says so (`"Stage 2.2" read as "ST-22"`).
// Names that are neither a key nor an alias are kept as given, so V5 reports them.

// The option names each function accepts (anything else is a programming error of the caller).
const MU_SET_OPTIONS = Object.freeze(['status', 'pr', 'noPr', 'mergeSha', 'closedBy', 'title', 'phase', 'owner',
  'dependsOn', 'after', 'addWaitsOn', 'removeWaitsOn', 'addDecision', 'removeDecision', 'addAlias']);
const MU_ADD_OPTIONS = Object.freeze(['title', 'phase', 'owner', 'kind', 'dependsOn', 'after', 'waitsOn', 'alias',
  'decision', 'insertAfter']);

/**
 * The canonical status for a command-line status: the canonical names and their kebab forms in any
 * case (`Not started`, `not-started`, `IN_PROGRESS`, `done`, `superseded`).
 *
 * @param {unknown} s
 * @returns {'Not started' | 'In progress' | 'Done' | 'Superseded' | null}
 */
function parseStatus(s) {
  if (typeof s !== 'string') return null;
  const norm = s.trim().toLowerCase().replace(/[-_\s]+/g, ' ');
  return STATUSES.find((st) => st.toLowerCase() === norm) ?? null;
}

function muCheckOptions(opts, allowed, fnName) {
  if (opts === undefined || opts === null) return {};
  if (typeof opts !== 'object' || Array.isArray(opts)) throw new TypeError(`${fnName}: opts must be an object`);
  for (const name of Object.keys(opts)) {
    if (!allowed.includes(name)) throw new TypeError(`${fnName}: unknown option "${name}"`);
  }
  return opts;
}

function muList(v, flag) {
  if (v === undefined) return [];
  const list = Array.isArray(v) ? v : [v];
  for (const item of list) {
    if (typeof item !== 'string' || item.trim() === '') throw new UsageError(`${flag} needs a non-empty value`);
  }
  return list.map((item) => item.trim());
}

function muText(v, flag) {
  if (typeof v !== 'string' || v.trim() === '') throw new UsageError(`${flag} needs a non-empty value`);
  return v.trim();
}

function muPr(v) {
  if (typeof v === 'number' && Number.isInteger(v) && v > 0) return v;
  if (typeof v === 'string' && /^[1-9]\d*$/.test(v.trim())) return Number(v.trim());
  throw new UsageError(`--pr must be a positive integer, got ${JSON.stringify(v)}`);
}

function muUnitOf(data, name) {
  const r = resolveKey(data, name);
  if (r === null) throw new UsageError(`unknown unit ${JSON.stringify(name)}`);
  return data.units.find((u) => u && u.key === r.key);
}

function muFmtList(list) {
  return `[${list.join(', ')}]`;
}

/**
 * Resolves the names of a `dependsOn`/`after` list: aliases become keys, empty names are dropped,
 * duplicates are kept once. Unknown names are kept as given (V5 reports them).
 *
 * @returns {{ keys: string[], notes: string[] }}
 */
function muResolveNames(data, names, flag) {
  if (!Array.isArray(names)) throw new UsageError(`${flag} needs a list of unit keys`);
  const keys = [];
  const notes = [];
  for (const raw of names) {
    if (typeof raw !== 'string') throw new UsageError(`${flag} needs a list of unit keys`);
    const name = raw.trim();
    if (name === '') continue;
    const r = resolveKey(data, name);
    const key = r === null ? name : r.key;
    if (r !== null && r.viaAlias) notes.push(`${JSON.stringify(name)} read as ${JSON.stringify(key)}`);
    if (!keys.includes(key)) keys.push(key);
  }
  return { keys, notes };
}

/** Replaces a `dependsOn`/`after` list of a unit; pushes the change line when it differs. */
function muSetNames(data, u, field, names, flag, changes) {
  const { keys, notes } = muResolveNames(data, names, flag);
  const before = Array.isArray(u[field]) ? u[field] : [];
  const same = before.length === keys.length && before.every((k, i) => k === keys[i]);
  if (!same) {
    u[field] = keys;
    const note = notes.length > 0 ? ` (${notes.join(', ')})` : '';
    changes.push(`unit ${JSON.stringify(u.key)}: ${field} ${muFmtList(before)} → ${muFmtList(keys)}${note}`);
  } else if (notes.length > 0) {
    changes.push(`unit ${JSON.stringify(u.key)}: ${field} unchanged (${notes.join(', ')})`);
  }
}

/** Parses `kind:ref[:note]` (the note is everything after the second colon). */
function muParseWaitsOn(spec, flag) {
  if (typeof spec !== 'string') throw new UsageError(`${flag} needs kind:ref[:note]`);
  const first = spec.indexOf(':');
  if (first < 0) throw new UsageError(`${flag} ${JSON.stringify(spec)}: expected kind:ref[:note] with kind one of ${WAITS_KINDS.join(', ')}`);
  const kind = spec.slice(0, first).trim();
  const rest = spec.slice(first + 1);
  const second = rest.indexOf(':');
  const ref = (second < 0 ? rest : rest.slice(0, second)).trim();
  const note = second < 0 ? '' : rest.slice(second + 1).trim();
  if (!WAITS_KINDS.includes(kind)) {
    throw new UsageError(`${flag} ${JSON.stringify(spec)}: kind ${JSON.stringify(kind)} is not one of ${WAITS_KINDS.join(', ')}`);
  }
  if (ref === '') throw new UsageError(`${flag} ${JSON.stringify(spec)}: the ref is empty`);
  const entry = { kind, ref };
  if (note !== '') entry.note = note;
  return entry;
}

function muWaitsText(w) {
  return `${w.kind}:${w.ref}${w.note !== undefined ? `:${w.note}` : ''}`;
}

/** Adds `waitsOn` entries; an entry with the same kind and ref is replaced (its note changes). */
function muAddWaits(u, specs, flag, changes) {
  for (const spec of specs) {
    const entry = muParseWaitsOn(spec, flag);
    const list = Array.isArray(u.waitsOn) ? u.waitsOn : [];
    const i = list.findIndex((w) => w && w.kind === entry.kind && w.ref === entry.ref);
    if (i >= 0) {
      if (list[i].note === entry.note) continue;
      changes.push(`unit ${JSON.stringify(u.key)}: waitsOn ${muWaitsText(list[i])} → ${muWaitsText(entry)}`);
      list[i] = entry;
    } else {
      list.push(entry);
      changes.push(`unit ${JSON.stringify(u.key)}: waitsOn ${muWaitsText(entry)} added`);
    }
    u.waitsOn = list;
  }
}

/** Removes the `waitsOn` entries matching `ref` or `kind:ref`; an empty list is removed. */
function muRemoveWaits(u, refs, changes) {
  for (const ref of refs) {
    const list = Array.isArray(u.waitsOn) ? u.waitsOn : [];
    const match = (w) => w && (w.ref === ref || `${w.kind}:${w.ref}` === ref);
    const removed = list.filter(match);
    if (removed.length === 0) throw new UsageError(`unit ${JSON.stringify(u.key)} does not wait on ${JSON.stringify(ref)}`);
    const kept = list.filter((w) => !match(w));
    if (kept.length > 0) u.waitsOn = kept;
    else delete u.waitsOn;
    for (const w of removed) changes.push(`unit ${JSON.stringify(u.key)}: waitsOn ${muWaitsText(w)} removed`);
  }
}

/** Adds names to a list field (`decisions`, `aliases`); a name already there is skipped. */
function muAddNames(u, field, label, names, changes) {
  for (const name of names) {
    const list = Array.isArray(u[field]) ? u[field] : [];
    if (list.includes(name)) continue;
    list.push(name);
    u[field] = list;
    changes.push(`unit ${JSON.stringify(u.key)}: ${label} ${JSON.stringify(name)} added`);
  }
}

function muRemoveDecisions(u, ids, changes) {
  for (const id of ids) {
    const list = Array.isArray(u.decisions) ? u.decisions : [];
    if (!list.includes(id)) throw new UsageError(`unit ${JSON.stringify(u.key)} has no decision ${JSON.stringify(id)}`);
    const kept = list.filter((d) => d !== id);
    if (kept.length > 0) u.decisions = kept;
    else delete u.decisions;
    changes.push(`unit ${JSON.stringify(u.key)}: decision ${JSON.stringify(id)} removed`);
  }
}

function muSetField(u, field, value, changes) {
  if (u[field] === value) return;
  const before = u[field] === undefined ? 'none' : JSON.stringify(u[field]);
  u[field] = value;
  changes.push(`unit ${JSON.stringify(u.key)}: ${field} ${before} → ${JSON.stringify(value)}`);
}

/** Status, `pr` and `closedBy` of `set` (the flag rules of the Task 17 contract and V4/Q-3). */
function muStatusFields(data, u, opts, changes) {
  const isGate = u.kind === 'gate';
  const name = JSON.stringify(u.key);
  let status = u.status;
  if (opts.status !== undefined) {
    status = parseStatus(opts.status);
    if (status === null) {
      throw new UsageError(`unknown status ${JSON.stringify(opts.status)}; use one of not-started, in-progress, done, superseded`);
    }
  }
  const hasPr = opts.pr !== undefined && opts.pr !== null;
  const pr = hasPr ? muPr(opts.pr) : undefined;
  const hasSha = opts.mergeSha !== undefined && opts.mergeSha !== null;
  const hasClosedBy = opts.closedBy !== undefined && opts.closedBy !== null;
  if (hasPr && opts.noPr === true) throw new UsageError('--pr and --no-pr cannot be used together');
  if (hasSha && hasClosedBy) throw new UsageError('--merge-sha and --closed-by cannot be used together');
  if (isGate && hasPr) throw new UsageError(`unit ${name} is a gate; a gate has no PR (use --closed-by)`);
  if (isGate && hasSha) throw new UsageError(`unit ${name} is a gate; a gate has no PR, so --merge-sha does not apply (use --closed-by)`);

  let closedBy;
  if (hasSha) {
    const sha = muText(opts.mergeSha, '--merge-sha');
    if (opts.status === undefined) status = 'Done';
    if (!CLOSED_STATUSES.includes(status)) {
      throw new UsageError(`--merge-sha closes the unit; it cannot go with status ${JSON.stringify(status)}`);
    }
    const prNum = hasPr ? pr : u.pr;
    if (prNum === undefined) throw new UsageError('no PR known; pass --pr');
    const archive = data.config && typeof data.config === 'object' ? data.config.archive : undefined;
    const template = archive && typeof archive.closedBy === 'string' ? archive.closedBy : DEFAULTS.closedBy;
    closedBy = template.replace(/\{pr\}/g, String(prNum)).replace(/\{sha\}/g, sha);
  } else if (hasClosedBy) {
    closedBy = muText(opts.closedBy, '--closed-by');
    if (!CLOSED_STATUSES.includes(status)) {
      throw new UsageError(`--closed-by is only allowed for ${CLOSED_STATUSES.join(' or ')}; unit ${name} would be ${JSON.stringify(status)}`);
    }
  }
  if (hasPr && !hasSha && status !== 'In progress') {
    throw new UsageError(`--pr needs status "In progress"; unit ${name} would be ${JSON.stringify(status)}`);
  }

  if (status !== u.status) {
    changes.push(`unit ${name}: status ${u.status} → ${status}`);
    u.status = status;
  }
  if (u.pr !== undefined && (status !== 'In progress' || opts.noPr === true)) {
    changes.push(`unit ${name}: pr #${u.pr} cleared`);
    delete u.pr;
  } else if (hasPr && !hasSha && u.pr !== pr) {
    changes.push(u.pr === undefined ? `unit ${name}: pr #${pr} set` : `unit ${name}: pr #${u.pr} → #${pr}`);
    u.pr = pr;
  }
  if (closedBy !== undefined) {
    if (u.closedBy !== closedBy) {
      changes.push(u.closedBy === undefined
        ? `unit ${name}: closedBy ${JSON.stringify(closedBy)} set`
        : `unit ${name}: closedBy ${JSON.stringify(u.closedBy)} → ${JSON.stringify(closedBy)}`);
      u.closedBy = closedBy;
    }
  } else if (u.closedBy !== undefined && !CLOSED_STATUSES.includes(status)) {
    changes.push(`unit ${name}: closedBy ${JSON.stringify(u.closedBy)} cleared`);
    delete u.closedBy;
  }
}

/**
 * `set <key>`: changes one unit. The key may be an alias.
 *
 * Options (the CLI maps its flags to them; `undefined` = flag not given):
 * - `status` (string, canonical or kebab form, see parseStatus): new status. A status other than
 *   "In progress" removes `pr`; a status that is not closed (Done/Superseded) removes `closedBy`.
 * - `pr` (positive integer or digit string): sets `pr`; the resulting status must be "In progress".
 *   With `mergeSha` it only fills `{pr}` and is not stored. Not allowed for a gate.
 * - `noPr` (true): removes `pr`.
 * - `mergeSha` (string): `closedBy` from `config.archive.closedBy` (or DEFAULTS.closedBy) with `{pr}`
 *   (from `pr` or the unit) and `{sha}`; the status defaults to "Done". Not with `closedBy`; not for a gate.
 * - `closedBy` (string): sets `closedBy`; the resulting status must be closed.
 * - `title`, `phase`, `owner` (string): replace the field.
 * - `dependsOn`, `after` (string[]): replace the list; `[]` clears it (the CLI maps `""` to `[]`).
 *   Aliases are resolved to keys.
 * - `addWaitsOn` (string[], each `kind:ref[:note]`), `removeWaitsOn` (string[], each `ref` or `kind:ref`).
 * - `addDecision`, `removeDecision`, `addAlias` (string[]).
 *
 * @param {object} data the register (changed in place and returned)
 * @param {string} key unit key or alias
 * @param {object} opts
 * @returns {{ data: object, changes: string[] }}
 * @throws {UsageError} unknown unit, no option given, bad value, flags that cannot go together
 */
function setUnit(data, key, opts) {
  const o = muCheckOptions(opts, MU_SET_OPTIONS, 'setUnit');
  const given = Object.keys(o).filter((k) => o[k] !== undefined && o[k] !== null && o[k] !== false);
  if (given.length === 0) throw new UsageError('nothing to change; pass at least one flag');
  const u = muUnitOf(data, key);
  const changes = [];

  if (o.status !== undefined || o.pr !== undefined || o.noPr === true || o.mergeSha !== undefined || o.closedBy !== undefined) {
    muStatusFields(data, u, o, changes);
  }
  if (o.title !== undefined) muSetField(u, 'title', muText(o.title, '--title'), changes);
  if (o.phase !== undefined) muSetField(u, 'phase', muText(o.phase, '--phase'), changes);
  if (o.owner !== undefined) muSetField(u, 'owner', muText(o.owner, '--owner'), changes);
  if (o.dependsOn !== undefined) muSetNames(data, u, 'dependsOn', o.dependsOn, '--depends-on', changes);
  if (o.after !== undefined) muSetNames(data, u, 'after', o.after, '--after', changes);
  muAddWaits(u, muList(o.addWaitsOn, '--add-waits-on'), '--add-waits-on', changes);
  muRemoveWaits(u, muList(o.removeWaitsOn, '--remove-waits-on'), changes);
  muAddNames(u, 'decisions', 'decision', muList(o.addDecision, '--add-decision'), changes);
  muRemoveDecisions(u, muList(o.removeDecision, '--remove-decision'), changes);
  muAddNames(u, 'aliases', 'alias', muList(o.addAlias, '--add-alias'), changes);
  return { data, changes };
}

/**
 * `add-unit <key>`: creates a unit with `status: "Not started"`, `dependsOn: []`, `after: []`,
 * `plans: []`. A duplicate key (or a key that is an alias) is not checked here: V2 refuses it.
 *
 * Options:
 * - `title` (string, required);
 * - `phase`, `owner` (string);
 * - `kind` ('delivery' | 'gate'; 'delivery' is not stored; a gate needs config.keyPatterns.gate, V2);
 * - `dependsOn`, `after` (string[]; aliases are resolved to keys);
 * - `waitsOn` (string[], each `kind:ref[:note]`), `alias` (string[]), `decision` (string[]);
 * - `insertAfter` (string, key or alias): the new unit goes right after that unit, otherwise at the end.
 *
 * @param {object} data the register (changed in place and returned)
 * @param {string} key
 * @param {object} opts
 * @returns {{ data: object, changes: string[] }}
 * @throws {UsageError} empty key, missing title, bad value, unknown --insert-after unit
 */
function addUnit(data, key, opts) {
  const o = muCheckOptions(opts, MU_ADD_OPTIONS, 'addUnit');
  if (typeof key !== 'string' || key.trim() === '') throw new UsageError('add-unit needs a unit key');
  const name = key.trim();
  if (o.title === undefined) throw new UsageError('--title is required');
  const changes = [`unit ${JSON.stringify(name)} added`];
  const u = { key: name };
  if (o.kind !== undefined && o.kind !== null) {
    if (!KINDS.includes(o.kind)) throw new UsageError(`--kind must be one of ${KINDS.join(', ')}, got ${JSON.stringify(o.kind)}`);
    if (o.kind !== KINDS[0]) u.kind = o.kind;
  }
  const aliases = muList(o.alias, '--alias');
  if (aliases.length > 0) u.aliases = [...new Set(aliases)];
  if (o.phase !== undefined) u.phase = muText(o.phase, '--phase');
  u.title = muText(o.title, '--title');
  u.status = STATUSES[0];
  if (o.owner !== undefined) u.owner = muText(o.owner, '--owner');
  for (const [field, flag] of [['dependsOn', '--depends-on'], ['after', '--after']]) {
    const { keys, notes } = muResolveNames(data, o[field] === undefined ? [] : o[field], flag);
    u[field] = keys;
    if (notes.length > 0) changes.push(`unit ${JSON.stringify(name)}: ${field} ${notes.join(', ')}`);
  }
  const waits = muList(o.waitsOn, '--waits-on');
  if (waits.length > 0) {
    u.waitsOn = [];
    for (const spec of waits) {
      const entry = muParseWaitsOn(spec, '--waits-on');
      if (!u.waitsOn.some((w) => w.kind === entry.kind && w.ref === entry.ref)) u.waitsOn.push(entry);
    }
  }
  u.plans = [];
  const decisions = muList(o.decision, '--decision');
  if (decisions.length > 0) u.decisions = [...new Set(decisions)];

  if (!Array.isArray(data.units)) throw new UsageError('the register has no "units" array');
  if (o.insertAfter !== undefined && o.insertAfter !== null) {
    const after = muText(o.insertAfter, '--insert-after');
    const r = resolveKey(data, after);
    if (r === null) throw new UsageError(`unknown unit ${JSON.stringify(after)} for --insert-after`);
    const i = data.units.findIndex((x) => x && x.key === r.key);
    data.units.splice(i + 1, 0, u);
    changes[0] = `unit ${JSON.stringify(name)} added after ${JSON.stringify(r.key)}`;
  } else {
    data.units.push(u);
  }
  return { data, changes };
}

// --- core/mutate-links.js ---
// Plan and TODO registration: `add-plan` (with the `**Source:**` rewrite of KD-11) and `home-todo`.
// Both are pure changes for `applyMutation` (KD-7): they take a copy of the register and return
// `{ data, changes, fileEdits? }`; the transaction checks the result and writes it (file edits only
// after the register write, so a refused register leaves the plan file as it is).
//
// Problems the repository checks already report are left to them: a plan file that does not exist
// (V7), a plan registered twice (V7), a TODO file that does not exist or lies outside the TODO
// directories (V9) refuse the change there. Wrong usage (unknown unit, bad path or role, an entry to
// replace that is not registered, a TODO homed elsewhere without `move`) throws `UsageError`.

function mlIsObj(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

function mlIsStr(v) {
  return typeof v === 'string' && v !== '';
}

/** The repository path of an argument, or a UsageError naming the argument. */
function mlPath(value, label) {
  const path = normalizePath(value);
  if (path === null) throw new UsageError(`${label} ${JSON.stringify(value)} is not a repository-relative path`);
  return path;
}

/** The unit for a key or alias, or a UsageError. */
function mlUnit(data, name) {
  const found = resolveKey(data, name);
  if (found === null) throw new UsageError(`unknown unit ${JSON.stringify(name)}`);
  return data.units.find((u) => mlIsObj(u) && u.key === found.key);
}

/** `docs/plans/x.md added (executable; Task 2)`: the entry's path (and section), a verb, its role and scope. */
function mlEntryText(entry, verb) {
  const section = entry.section === undefined ? '' : ` section ${JSON.stringify(entry.section)}`;
  const scope = entry.scope === undefined ? '' : `; ${entry.scope}`;
  return verb === null ? `${entry.path}${section} (${entry.role}${scope})` : `${entry.path}${section} ${verb} (${entry.role}${scope})`;
}

/** A plan entry with the fields in canonical order and absent ones left out. */
function mlEntry(path, section, role, scope) {
  const entry = { path };
  if (section !== undefined) entry.section = section;
  entry.role = role;
  if (scope !== undefined) entry.scope = scope;
  return entry;
}

/**
 * The document of a new `**Source:**` line (KD-11): `sourceDoc`, else the file of the unit's first
 * `brief` plan, else of its first `scope` plan, else the file of the first configured region.
 */
function mlSourceDoc(data, unit, sourceDoc) {
  if (sourceDoc !== undefined) return mlPath(sourceDoc, 'source document');
  const plans = unit.plans.filter((p) => mlIsObj(p) && mlIsStr(p.path));
  for (const role of ['brief', 'scope']) {
    const p = plans.find((q) => q.role === role && normalizePath(q.path) !== null);
    if (p) return normalizePath(p.path);
  }
  const regions = mlIsObj(data.config) && Array.isArray(data.config.regions) ? data.config.regions : [];
  const region = regions.find((r) => mlIsObj(r) && normalizePath(r.file) !== null);
  if (region) return normalizePath(region.file);
  throw new UsageError(`unit ${JSON.stringify(unit.key)} has no brief or scope plan and no region is configured; pass --source-doc`);
}

/**
 * Registers a plan for a unit (`add-plan`).
 *
 * - `key` is a unit key or alias; `path` the plan file (repository-relative).
 * - Without `replace`, a new entry `{ path, section, role, scope }` is added; `role` defaults to
 *   `executable`. When the unit already has an entry for the same path and section, that entry is
 *   kept and only the role and scope passed are updated (a repeated call changes nothing).
 * - `replace` (a path) replaces that entry of the unit by `path` in place, keeping its `section`,
 *   `role` and `scope` unless they are passed. This is why `role` has no default in the signature:
 *   `executable` applies only to new entries.
 * - When the resulting role is `executable` and `keepSource` is not set, the plan's `**Source:**`
 *   line is made to name the key (KD-11, `rewriteSource`): a line that already names it is left
 *   alone, another is replaced by `<doc>#<key>`, a missing one is inserted after `**Goal:**` (or the
 *   first heading). The new text is returned in `fileEdits`. `readText(path)` (repository path →
 *   text or null; the CLI passes `createFsView(root).readText`) reads the plan; when it returns null
 *   the file does not exist, no edit is made and V7 refuses the change.
 *
 * @param {object} data a copy of the register (changed in place and returned)
 * @param {string} key
 * @param {string} path
 * @param {{ section?: string, role?: string, scope?: string, replace?: string, keepSource?: boolean,
 *   sourceDoc?: string, readText?: (path: string) => string | null }} [opts]
 * @returns {{ data: object, changes: string[], fileEdits: { path: string, text: string }[] }}
 * @throws {UsageError}
 */
function addPlan(data, key, path, { section, role, scope, replace, keepSource = false, sourceDoc, readText } = {}) {
  const unit = mlUnit(data, key);
  if (!Array.isArray(unit.plans)) unit.plans = [];
  const planPath = mlPath(path, 'plan path');
  if (role !== undefined && !ROLES.includes(role)) {
    throw new UsageError(`role ${JSON.stringify(role)} is not one of ${ROLES.join(', ')}`);
  }
  if (section !== undefined && !mlIsStr(section)) throw new UsageError('section must be a non-empty string');
  if (scope !== undefined && !mlIsStr(scope)) throw new UsageError('scope must be a non-empty string');
  const where = `unit ${JSON.stringify(unit.key)}`;
  const changes = [];
  let entry;
  if (replace !== undefined) {
    const oldPath = mlPath(replace, 'plan to replace');
    const i = unit.plans.findIndex((p) => mlIsObj(p) && normalizePath(p.path) === oldPath);
    if (i === -1) throw new UsageError(`${where} has no plan ${oldPath} to replace`);
    const old = unit.plans[i];
    entry = mlEntry(planPath, section ?? old.section, role ?? old.role, scope ?? old.scope);
    unit.plans[i] = entry;
    if (oldPath !== planPath || JSON.stringify(old) !== JSON.stringify(entry)) {
      changes.push(`${where}: plan ${oldPath} replaced by ${mlEntryText(entry, null)}`);
    }
  } else {
    const i = unit.plans.findIndex((p) => mlIsObj(p) && normalizePath(p.path) === planPath && p.section === section);
    if (i === -1) {
      entry = mlEntry(planPath, section, role ?? 'executable', scope);
      unit.plans.push(entry);
      changes.push(`${where}: plan ${mlEntryText(entry, 'added')}`);
    } else {
      const old = unit.plans[i];
      entry = mlEntry(planPath, section, role ?? old.role, scope ?? old.scope);
      unit.plans[i] = entry;
      if (JSON.stringify(old) !== JSON.stringify(entry)) changes.push(`${where}: plan ${mlEntryText(entry, 'updated')}`);
    }
  }

  const fileEdits = [];
  if (entry.role === 'executable' && keepSource !== true) {
    if (typeof readText !== 'function') throw new TypeError('addPlan: opts.readText is required to rewrite **Source:**');
    const text = readText(planPath);
    if (typeof text === 'string') {
      const doc = mlSourceDoc(data, unit, sourceDoc);
      const r = rewriteSource(text, { key: unit.key, doc });
      if (r.changed) {
        fileEdits.push({ path: planPath, text: r.text });
        const verb = r.before === null ? 'added as' : 'rewritten to';
        changes.push(`${planPath}: **Source:** ${verb} ${JSON.stringify(r.after)}`);
      }
    }
  }
  return { data, changes, fileEdits };
}

/** The `config.todos` object of the register, or null. */
function mlTodosConfig(data) {
  return mlIsObj(data.config) && mlIsObj(data.config.todos) ? data.config.todos : null;
}

/** The keys of the units whose `todos` list `path`. */
function mlHomes(data, path) {
  return data.units
    .filter((u) => mlIsObj(u) && Array.isArray(u.todos) && u.todos.some((t) => normalizePath(t) === path))
    .map((u) => u.key);
}

/** Removes `path` from the `todos` of the unit `key` (dropping an emptied list). */
function mlRemoveTodo(data, key, path) {
  const u = data.units.find((x) => mlIsObj(x) && x.key === key);
  u.todos = u.todos.filter((t) => normalizePath(t) !== path);
  if (u.todos.length === 0) delete u.todos;
}

/** `true` when `path` lies in `config.todos.archiveDir` (V9 does not allow such a note in `unhomed`). */
function mlInTodoArchive(data, path) {
  const todos = mlTodosConfig(data);
  const dir = todos !== null && mlIsStr(todos.archiveDir) ? normalizePath(todos.archiveDir) : null;
  return dir !== null && inDir(path, dir, true);
}

/** The `unhomed` key of `path` (as written in the register), or null. */
function mlUnhomedKey(data, path) {
  const todos = mlTodosConfig(data);
  if (todos === null || !mlIsObj(todos.unhomed)) return null;
  return Object.keys(todos.unhomed).find((k) => normalizePath(k) === path) ?? null;
}

/**
 * Gives a TODO note a home (`home-todo`).
 *
 * - `key` (unit key or alias): adds the note to the unit's `todos`. A note already homed in another
 *   unit is refused (UsageError naming that unit) unless `move` is set, which removes it there. A
 *   note listed in `config.todos.unhomed` is removed from it (otherwise V9 would refuse the change).
 * - `key` null with `unhomed` (a reason): writes `config.todos.unhomed[todo] = reason`. A note homed
 *   in a unit is refused unless `move` is set, which removes it from the unit.
 * - `replace` (a path): the note `replace` (typically just moved to the archive by `git mv`) is
 *   replaced by `todo` where it is listed: in place in its unit, or under the same reason in
 *   `unhomed`. With a `key` other than the unit that holds it, `move` is needed; with `key` and an
 *   `unhomed` holder, the note is homed in `key`. `key` may be null with `replace`. A note listed only
 *   in `unhomed`, replaced without a `key` by a path in `todos.archiveDir`, is dropped from `unhomed`
 *   (V9 refuses an archived note there).
 * - A `todo` whose name is in `config.todos.exclude` directly in `todos.dir` (default `README.md`) is
 *   not a note: UsageError.
 *
 * @param {object} data a copy of the register (changed in place and returned)
 * @param {string} todoPath
 * @param {string | null} key
 * @param {{ move?: boolean, unhomed?: string, replace?: string }} [opts]
 * @returns {{ data: object, changes: string[] }}
 * @throws {UsageError}
 */
function homeTodo(data, todoPath, key, { move = false, unhomed, replace } = {}) {
  const path = mlPath(todoPath, 'TODO path');
  if (todoExcluded(data, path)) throw new UsageError(`${path} is excluded by config.todos.exclude; it is not a TODO note`);
  const hasKey = key !== null && key !== undefined;
  if (unhomed !== undefined && !mlIsStr(unhomed)) throw new UsageError('the unhomed reason must be a non-empty string');
  if (hasKey && unhomed !== undefined) throw new UsageError('pass either a unit key or --unhomed, not both');
  if (!hasKey && unhomed === undefined && replace === undefined) throw new UsageError('pass a unit key, --unhomed "<reason>" or --replace');
  if (replace !== undefined && unhomed !== undefined) throw new UsageError('--replace cannot be combined with --unhomed');
  const unit = hasKey ? mlUnit(data, key) : null;
  const changes = [];
  const todos = mlTodosConfig(data);

  if (replace !== undefined) {
    const oldPath = mlPath(replace, 'TODO to replace');
    const holders = mlHomes(data, oldPath);
    const unhomedKey = mlUnhomedKey(data, oldPath);
    if (holders.length === 0 && unhomedKey === null) throw new UsageError(`TODO ${oldPath} is not listed in any unit or in config.todos.unhomed`);
    if (holders.length > 0) {
      const holder = holders[0];
      if (unit === null || unit.key === holder) {
        const u = data.units.find((x) => mlIsObj(x) && x.key === holder);
        u.todos = u.todos.map((t) => (normalizePath(t) === oldPath ? path : t));
        changes.push(`TODO ${oldPath} replaced by ${path} in ${JSON.stringify(holder)}`);
      } else {
        if (move !== true) throw new UsageError(`TODO ${oldPath} is homed in ${JSON.stringify(holder)}; pass --move to move it to ${JSON.stringify(unit.key)}`);
        for (const h of holders) mlRemoveTodo(data, h, oldPath);
        unit.todos = [...(unit.todos ?? []), path];
        changes.push(`TODO ${oldPath} replaced by ${path} and moved from ${JSON.stringify(holder)} to ${JSON.stringify(unit.key)}`);
      }
    }
    if (unhomedKey !== null) {
      const reason = todos.unhomed[unhomedKey];
      delete todos.unhomed[unhomedKey];
      if (unit === null || holders.length > 0) {
        if (holders.length === 0 && mlInTodoArchive(data, path)) {
          changes.push(`TODO ${oldPath} removed from config.todos.unhomed (archived as ${path})`);
        } else if (holders.length === 0) {
          todos.unhomed[path] = reason;
          changes.push(`TODO ${oldPath} replaced by ${path} in config.todos.unhomed`);
        } else {
          changes.push(`TODO ${oldPath} removed from config.todos.unhomed`);
        }
      } else {
        unit.todos = [...(unit.todos ?? []), path];
        changes.push(`TODO ${oldPath} removed from config.todos.unhomed; ${path} homed in ${JSON.stringify(unit.key)}`);
      }
    }
    return { data, changes };
  }

  const holders = mlHomes(data, path);
  const others = holders.filter((h) => unit === null || h !== unit.key);
  if (others.length > 0) {
    if (move !== true) throw new UsageError(`TODO ${path} is already homed in ${JSON.stringify(others[0])}; pass --move to move it`);
    for (const h of others) mlRemoveTodo(data, h, path);
  }

  if (unit === null) {
    if (todos === null) throw new UsageError('config.todos is not configured; cannot list an unhomed TODO');
    if (!mlIsObj(todos.unhomed)) todos.unhomed = {};
    const old = mlUnhomedKey(data, path);
    const prevReason = old === null ? undefined : todos.unhomed[old];
    if (old !== null) delete todos.unhomed[old];
    todos.unhomed[path] = unhomed;
    if (others.length > 0) changes.push(`TODO ${path} removed from ${others.map((h) => JSON.stringify(h)).join(', ')}`);
    if (old !== path || prevReason !== unhomed) {
      changes.push(`TODO ${path} listed as unhomed: ${JSON.stringify(unhomed)}`);
    }
    return { data, changes };
  }

  const unhomedKey = mlUnhomedKey(data, path);
  if (unhomedKey !== null) {
    delete todos.unhomed[unhomedKey];
    changes.push(`TODO ${path} removed from config.todos.unhomed`);
  }
  if (!holders.includes(unit.key)) {
    unit.todos = [...(unit.todos ?? []), path];
    const from = others.length > 0 ? ` (moved from ${others.map((h) => JSON.stringify(h)).join(', ')})` : '';
    changes.push(`TODO ${path} homed in ${JSON.stringify(unit.key)}${from}`);
  }
  return { data, changes };
}

// --- core/tickets/query.js ---
// Read views of the tickets: the `tickets-check/1` answer of `tickets check --json` (also the `tickets`
// field of a top-level `check --json`), and the `status` and `show` views of `tickets-show/1` with their
// text forms. Within `/1` fields may be added; removing or renaming one needs `/2`.

function tkqList(v) {
  return Array.isArray(v) ? v : [];
}

/**
 * The `tickets-check/1` answer of a `checkTickets` result. `fixText` turns a fix argument list into the
 * printed command line (KD-8); without it the list is kept.
 *
 * @param {object} result a checkTickets result
 * @param {{ fixText?: (args: string[]) => string }} [opts]
 * @returns {object}
 */
function ticketsCheckJson(result, { fixText } = {}) {
  const entry = (p) => {
    const fix = Array.isArray(p.fix) ? p.fix : null;
    return { rule: p.rule, where: p.where, message: p.message, fix: fix !== null && typeof fixText === 'function' ? fixText(fix) : fix };
  };
  const problems = tkqList(result.problems).map(entry);
  return {
    contract: TICKETS_CHECK_CONTRACT,
    tool: VERSION,
    schema: TICKETS_SCHEMA,
    config: result.configPath,
    ok: problems.length === 0,
    problems,
    warnings: tkqList(result.warnings).map(entry),
    notes: tkqList(result.notes).map((n) => ({ rule: n.rule, where: n.where, message: n.message })),
    regions: tkqList(result.regions).map((r) => ({ file: r.file, marker: r.marker, current: r.current === true })),
    tickets: result.tickets,
    archived: result.archived,
  };
}

/** The head of every `tickets-show/1` answer. */
function tkqHead(view) {
  return { contract: TICKETS_SHOW_CONTRACT, tool: VERSION, schema: TICKETS_SCHEMA, view };
}

function tkqResolved(t) {
  return typeof t.fields.resolution === 'string';
}

function tkqStr(v) {
  return typeof v === 'string' ? v : null;
}

/** Whole days from `from` to `to` (calendar dates), or null when either is not a date. */
function tkqDays(from, to) {
  if (!isCalendarDate(from) || !isCalendarDate(to)) return null;
  return Math.round((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / 86400000);
}

/** Type order, then number. */
function tkqOrder(a, b) {
  return TICKET_TYPES.indexOf(a.type) - TICKET_TYPES.indexOf(b.type) || a.number - b.number || (a.dir < b.dir ? -1 : a.dir > b.dir ? 1 : 0);
}

function tkqScheduledIn(tm, id) {
  return (tm.scheduling.get(id) ?? []).map((r) => ({ unit: r.unit, milestone: r.milestone, brief: r.brief }));
}

function tkqImplementedBy(tm, id) {
  return (tm.implementing.get(id) ?? [])
    .map((k) => ({ plan: k.plan.path, task: k.n, done: k.boxes.done, total: k.boxes.total, skipped: k.boxes.skipped }))
    .sort((a, b) => (a.plan < b.plan ? -1 : a.plan > b.plan ? 1 : a.task - b.task));
}

/** The live tickets (not archived) in type order, then number. */
function tkqLive(result) {
  return result.model.tickets.filter((t) => !t.archived).sort(tkqOrder);
}

/**
 * The `status` view of `tickets-show/1`. `today` is a calendar date (the CLI passes `--today` or today
 * UTC); `staleDays` (or null) lists the open backlog tickets older than that many days in `stale`.
 * `archivable` names the live top-level tickets whose whole subtree is resolved, with the units (in
 * register order) whose rows schedule any ticket of the subtree.
 *
 * @param {object} result a checkTickets result with a model and a register
 * @param {{ today: string, staleDays?: number | null }} opts
 * @returns {object}
 */
function ticketsStatusJson(result, { today, staleDays = null }) {
  const tm = result.model.state;
  const live = tkqLive(result);
  const counts = { backlog: 0, scheduled: 0, planned: 0, inProgress: 0, closed: 0, archived: result.archived };
  const tickets = live.map((t) => {
    const state = ticketState(tm, t.id);
    counts[state === 'in progress' ? 'inProgress' : state] += 1;
    return {
      id: t.id, type: t.type, title: tkqStr(t.fields.title), path: t.file, parent: t.parent, state,
      resolution: tkqStr(t.fields.resolution), created: tkqStr(t.fields.created), closed: tkqStr(t.fields.closed),
      ageDays: tkqDays(t.fields.created, today), scheduledIn: tkqScheduledIn(tm, t.id), implementedBy: tkqImplementedBy(tm, t.id),
    };
  });
  const stale = staleDays === null ? [] : tickets.filter((t) => t.state === 'backlog' && t.ageDays !== null && t.ageDays > staleDays).map((t) => t.id);
  const unitOrder = tm.units.map((u) => u.key);
  const archivable = [];
  for (const t of live) {
    if (t.parent !== null) continue;
    const subtree = live.filter((d) => d === t || d.dir.startsWith(`${t.dir}/`));
    if (!subtree.every(tkqResolved)) continue;
    const units = new Set(subtree.flatMap((d) => (tm.scheduling.get(d.id) ?? []).map((r) => r.unit)));
    archivable.push({ id: t.id, units: unitOrder.filter((k) => units.has(k)) });
  }
  return {
    ...tkqHead('status'),
    today,
    staleDays,
    counts,
    problems: result.problems.length,
    warnings: result.warnings.length,
    tickets,
    stale,
    archivable,
  };
}

/** `plan-a#2` of an implementedBy entry. */
function tkqTaskRef(k) {
  return `${k.plan.slice(k.plan.lastIndexOf('/') + 1).replace(/\.md$/, '')}#${k.task}`;
}

/** `TK-001 (task) Regression budget: Rel-2 M1; plan-a#1 1/2` */
function tkqLine(t) {
  const rows = t.scheduledIn.map((r) => `${r.unit} ${r.milestone}`);
  const tasks = t.implementedBy.map((k) => `${tkqTaskRef(k)} ${k.done}/${k.total}${k.skipped > 0 ? ` (${k.skipped} skipped)` : ''}`);
  const detail = [rows.join(', '), tasks.join(', ')].filter((x) => x !== '').join('; ');
  return `  ${t.id} (${t.type}) ${t.title ?? ''}${detail === '' ? '' : `: ${detail}`}`;
}

/**
 * The text form of `status`: a totals line, the counts by state, the tickets in progress, planned and
 * scheduled (with their rows and tasks), the backlog count, the stale tickets (with --stale) and the
 * archivable top-level tickets. Empty lists print `none`.
 *
 * @param {object} result
 * @param {{ today: string, staleDays?: number | null }} opts
 * @returns {string}
 */
function ticketsStatusText(result, opts) {
  const s = ticketsStatusJson(result, opts);
  const c = s.counts;
  const lines = [
    `plan-register tickets: ${s.tickets.length} ticket(s), ${c.archived} archived; ${s.problems} problem(s), ${s.warnings} warning(s)`,
    `Counts: ${c.backlog} backlog, ${c.scheduled} scheduled, ${c.planned} planned, ${c.inProgress} in progress, ${c.closed} closed`,
  ];
  const section = (title, rows) => {
    lines.push(`${title}:`);
    lines.push(...(rows.length === 0 ? ['  none'] : rows));
  };
  for (const [title, state] of [['In progress', 'in progress'], ['Planned', 'planned'], ['Scheduled', 'scheduled']]) {
    section(title, s.tickets.filter((t) => t.state === state).map(tkqLine));
  }
  lines.push(`Backlog: ${c.backlog} ticket(s)`);
  if (s.staleDays !== null) {
    const byId = new Map(s.tickets.map((t) => [t.id, t]));
    section(`Stale (backlog, older than ${s.staleDays} day(s) on ${s.today})`,
      s.stale.map((id) => `  ${id} (${byId.get(id).type}) ${byId.get(id).title ?? ''}: ${byId.get(id).ageDays} day(s)`));
  }
  section('Archivable', s.archivable.map((a) => `  ${a.id}${a.units.length > 0 ? `: scheduled by ${a.units.join(', ')}` : ''}`));
  return lines.join('\n');
}

/**
 * The `show` view of one ticket (live or archived), or null for an unknown ID. `references` are the
 * lines of registered briefs and plans that name the ID as a token, and the `links` lines of other
 * tickets that list it, sorted by file, then line.
 *
 * @param {object} result
 * @param {string} id
 * @returns {object | null}
 */
function ticketShowJson(result, id) {
  const tm = result.model.state;
  const t = tm.byId.get(id);
  if (t === undefined) return null;
  const f = t.fields;
  const ancestors = result.model.tickets
    .filter((a) => t.dir.startsWith(`${a.dir}/`))
    .sort((a, b) => a.depth - b.depth)
    .map((a) => ({ id: a.id, title: tkqStr(a.fields.title) }));
  const children = t.children.map((c) => {
    const ct = tm.byId.get(c);
    return { id: c, title: ct === undefined ? null : tkqStr(ct.fields.title), resolution: ct === undefined ? null : tkqStr(ct.fields.resolution) };
  });
  const references = [];
  for (const path of [...tm.registered].sort()) {
    const text = tm.fsv.readText(path);
    if (text === null) continue;
    text.split('\n').forEach((line, i) => {
      if (tokenMatch(line, id)) references.push({ file: path, line: i + 1 });
    });
  }
  for (const o of result.model.tickets) {
    if (o === t || o.fm === null || !Array.isArray(o.fields.links) || !o.fields.links.includes(id)) continue;
    references.push({ file: o.file, line: o.fm.lines.links });
  }
  references.sort((a, b) => (a.file < b.file ? -1 : a.file > b.file ? 1 : a.line - b.line));
  const by = Array.isArray(f.by) ? [...f.by] : typeof f.by === 'string' ? [f.by] : [];
  return {
    ...tkqHead('show'),
    ticket: {
      id: t.id, type: t.type, title: tkqStr(f.title), path: t.file, parent: t.parent, ancestors, children,
      state: ticketState(tm, t.id), resolution: tkqStr(f.resolution), closed: tkqStr(f.closed), by,
      links: Array.isArray(f.links) ? [...f.links] : [],
      acceptance: t.text === null ? [] : acceptanceItems(t.text).items.map((it) => ({ id: it.id, text: it.text })),
      digest: t.text === null ? null : acceptanceDigest(t.text),
      scheduledIn: tkqScheduledIn(tm, t.id), implementedBy: tkqImplementedBy(tm, t.id), references,
    },
  };
}

/**
 * The text form of `show`, or null for an unknown ID.
 *
 * @param {object} result
 * @param {string} id
 * @returns {string | null}
 */
function ticketShowText(result, id) {
  const s = ticketShowJson(result, id);
  if (s === null) return null;
  const t = s.ticket;
  const list = (items) => (items.length > 0 ? items.join(', ') : 'none');
  const lines = [`${t.id}: ${t.title ?? ''}`, `  ${t.type} · ${t.state} · ${t.path}`];
  lines.push(`  Parent chain: ${t.ancestors.length > 0 ? t.ancestors.map((a) => `${a.id} ${a.title ?? ''}`).join(' › ') : 'none (top level)'}`);
  lines.push(`  Children: ${list(t.children.map((c) => `${c.id}${c.resolution === null ? '' : ` (${c.resolution})`}`))}`);
  lines.push(`  Resolution: ${t.resolution === null ? 'none' : `${t.resolution} on ${t.closed ?? '?'} by ${t.by.join(', ')}`}`);
  lines.push(`  Links: ${list(t.links)}`);
  if (t.digest === null) {
    lines.push('  Acceptance: none');
  } else {
    lines.push(`  Acceptance (@${t.digest}):`);
    lines.push(...(t.acceptance.length > 0 ? t.acceptance.map((a) => `    ${a.id}: ${a.text}`) : ['    no items']));
  }
  lines.push(`  Scheduled in: ${list(t.scheduledIn.map((r) => `${r.unit} ${r.milestone} (${r.brief})`))}`);
  lines.push(`  Implemented by: ${list(t.implementedBy.map((k) => `${tkqTaskRef(k)} ${k.done}/${k.total}${k.skipped > 0 ? ` (${k.skipped} skipped)` : ''} (${k.plan})`))}`);
  lines.push(`  References: ${list(t.references.map((r) => `${r.file}:${r.line}`))}`);
  return lines.join('\n');
}

/** The highest number of `prefix` among ticket directory names in `paths` (any segment), or 0. */
function tkqHighest(paths, prefix) {
  const re = new RegExp(`^${prefix}-(\\d+)-`);
  let max = 0;
  for (const p of paths) {
    for (const seg of p.split('/')) {
      const m = re.exec(seg);
      if (m) max = Math.max(max, Number(m[1]));
    }
  }
  return max;
}

/**
 * The `next-id` view of `tickets-show/1`: the next free ID of `type`, one above the highest number of its
 * prefix over the live tree, the archive and the freeze list (`highest.workingTree`) and the names under
 * the tickets root at `ref` (`highest.ref`). `refNames` are the paths `git ls-tree -r --name-only <ref>`
 * printed, relative to the repository root; null when the ref was not read (`--no-ref`, no git, no
 * repository, unknown ref). The number is padded to `digits` and grows past it (`TK-1000`).
 *
 * @param {object} result a checkTickets result with a valid config
 * @param {{ type: string, ref?: string | null, refNames?: string[] | null }} opts
 * @returns {object}
 */
function nextTicketId(result, { type, ref = null, refNames = null }) {
  const config = result.config;
  const prefix = config.types[type].prefix;
  const tickets = result.model === null ? [] : result.model.tickets;
  const own = tickets.filter((t) => t.prefix === prefix).map((t) => t.number);
  const frozen = config.frozen === null ? [] : config.frozen.ids
    .map((id) => /^(.*)-(\d+)$/.exec(id))
    .filter((m) => m !== null && m[1] === prefix)
    .map((m) => Number(m[2]));
  const workingTree = Math.max(0, ...own, ...frozen);
  const fromRef = refNames === null ? null : tkqHighest(refNames.filter((p) => inDir(p, config.root, true)), prefix);
  const n = Math.max(workingTree, fromRef ?? 0) + 1;
  return {
    ...tkqHead('next-id'),
    type,
    prefix,
    next: `${prefix}-${String(n).padStart(config.digits, '0')}`,
    highest: { workingTree, ref: fromRef },
    ref: refNames === null ? null : ref,
    refRead: refNames !== null,
    frozen: config.frozen !== null,
  };
}

// --- core/tickets/bodies.js ---
// The body templates of a new ticket per type (tickets/1 §5.3): the text after the `# <ID>: <title>`
// heading, written by `tickets new`. Placeholders are in angle brackets; acceptance criteria are labelled
// items `- A<n>: …` (§2.3). Attachment folders named here are only `evidence/`, `spike/` and `notes/`.
// A body holds no status, no checkbox and no heading that says "in progress" or "blocked" (TV5).

const TKB_ACCEPTANCE = ['## Acceptance', '', '- A1: <observable outcome>', ''];
const TKB_NOTES = ['## Notes', '', '<context and decisions; longer material goes to notes/>', ''];

/** The body of a new ticket by type (LF, ends with a newline). */
const TICKET_BODIES = Object.freeze({
  epic: [
    '## Goal', '', '<the outcome the epic delivers>', '',
    '## Exit', '', '<when the epic is done: the observable end state>', '',
    '## Out of scope', '', '<what this epic does not cover>', '',
  ].join('\n'),
  story: [
    '## Outcome', '', '<what a user can do or see when the story is done>', '',
    ...TKB_ACCEPTANCE,
    ...TKB_NOTES,
  ].join('\n'),
  task: [
    '## Why', '', '<the problem or need this work answers>', '',
    '## What', '', '<the change, in a few sentences>', '',
    ...TKB_ACCEPTANCE,
    ...TKB_NOTES,
    '## Files in this ticket', '', '<one line per attachment; attachment folders: evidence/, spike/, notes/>', '',
  ].join('\n'),
  defect: [
    '## Observed', '', '<what happens, with the steps to reproduce>', '',
    '## Expected', '', '<what should happen instead>', '',
    ...TKB_ACCEPTANCE,
    '## Evidence', '', '<logs, screenshots and runs; files go to evidence/>', '',
    '## Fix direction', '', '<the suspected cause and the intended fix>', '',
  ].join('\n'),
  idea: [
    '## Idea', '', '<the idea in a few sentences>', '',
    '## Trigger', '', '<the observation or event that would make it worth doing>', '',
  ].join('\n'),
});

// --- core/tickets/mutate.js ---
// The change commands of the tickets (tickets/1 §4.1): `tickets new`, `tickets freeze`, `tickets close`, `tickets archive` and `tickets move`. Each change is
// applied, then checked: the TV errors after the change are compared with those before (a multiset of
// rule + where + message; TV11 "region is stale" is left out, as V12 is for the register); an error the
// change added restores the previous state (created directories removed, rewritten files restored) and
// the change is refused with the new problems. Regions are not written here (the CLI's --write does
// that); the register is never written.
//
// A refusal that needs no check (frozen tickets, a disabled type, a parent the type does not allow, depth,
// path length) throws an Error before anything is changed; a bad value throws UsageError.

const TKM_SLUG_RE = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

function tkmAbs(root, rel) {
  return join(root, ...rel.split('/'));
}

/** The error keys of a check (TV11 "region is stale" left out) with their counts. */
function tkmErrorKeys(result) {
  const keys = new Map();
  for (const p of result.problems) {
    if (p.rule === 'TV11' && p.message === 'region is stale') continue;
    const k = `${p.rule}\0${p.where}\0${p.message}`;
    keys.set(k, (keys.get(k) ?? 0) + 1);
  }
  return keys;
}

/** The problems of `after` that `before` did not have (as a multiset). */
function tkmAddedProblems(before, after) {
  const left = tkmErrorKeys(before);
  const added = [];
  for (const p of after.problems) {
    if (p.rule === 'TV11' && p.message === 'region is stale') continue;
    const k = `${p.rule}\0${p.where}\0${p.message}`;
    const n = left.get(k) ?? 0;
    if (n > 0) left.set(k, n - 1);
    else added.push(p);
  }
  return added;
}

/**
 * The slug of a title: NFKD, ASCII only, lowercase, every run of other characters one "-", cut to `max`
 * characters at the last "-" (or hard when there is none).
 */
function tkmSlug(title, max) {
  let s = title.normalize('NFKD').replace(/[^\x20-\x7e]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  if (s.length > max) {
    const cut = s.slice(0, max + 1).lastIndexOf('-');
    s = (cut > 0 ? s.slice(0, cut) : s.slice(0, max)).replace(/-+$/, '');
  }
  return s;
}

/** The check before a change: the result, or the TV1 problems that stop it (config or register unreadable). */
function tkmBefore(root, opts) {
  const before = checkTickets(root, { configPath: opts.configPath, registerPath: opts.registerPath });
  if (before.config === null) return { before, invalid: before.problems.filter((p) => p.rule === 'TV1') };
  return { before, invalid: null };
}

/** The parent of a new ticket: a live, open ticket whose type the new type allows. */
function tkmParent(config, tickets, type, parentId) {
  const spec = config.types[type];
  if (parentId === null) {
    if (!spec.topLevel) throw new Error(`${type} cannot be at the top level (allowed parents: ${spec.parents.join(', ') || 'none'})`);
    return null;
  }
  const found = tickets.filter((t) => t.id === parentId);
  if (found.length === 0) throw new Error(`unknown ticket ${parentId}`);
  const parent = found.find((t) => !t.archived);
  if (parent === undefined) throw new Error(`parent ${parentId} is archived`);
  const resolution = parent.fields.resolution;
  if (typeof resolution === 'string') {
    throw new Error(`parent ${parentId} is resolved (${resolution}); a new ticket under it would be open under a closed ticket`);
  }
  if (!spec.parents.includes(parent.type)) {
    throw new Error(`${type} cannot be a child of ${parent.type} ${parent.id} (allowed: ${spec.parents.join(', ') || 'none'})`);
  }
  return parent;
}

/**
 * `tickets new`: creates `<parent dir or root>/<ID>-<slug>/ticket.md` with the front matter, the heading
 * and the type's body, then checks; an added TV error removes the directory again.
 *
 * `listRef(ticketsRoot)` reads the names on the ref (`{ names }`) or says why it could not (`{ error }`);
 * without it the ref is not read.
 *
 * @param {string} root the repository root
 * @param {{ configPath?: string, registerPath?: string, type: string, title: string, parent?: string | null,
 *   slug?: string | null, links?: string[], date: string, ref?: string | null,
 *   listRef?: ((ticketsRoot: string) => { names: string[] } | { error: string }) | null }} opts
 * @returns {{ status: 'invalid' | 'refused', problems: object[], configPath: string, refError: string | null }
 *   | { status: 'created', id: string, dir: string, file: string, configPath: string, refError: string | null }}
 * @throws {Error} a refusal before any change; {UsageError} a bad value
 */
function newTicket(root, opts) {
  const { type, title, date } = opts;
  if (!TICKET_TYPES.includes(type)) throw new UsageError(`--type must be one of ${TICKET_TYPES.join(', ')}`);
  const { before, invalid } = tkmBefore(root, opts);
  if (invalid !== null) return { status: 'invalid', problems: invalid, configPath: before.configPath, refError: null };
  const config = before.config;
  if (config.frozen !== null) throw new Error(`tickets are frozen since ${config.frozen.date} (config.frozen); new tickets are refused`);
  if (!config.types[type].enabled) throw new Error(`type ${JSON.stringify(type)} is disabled in config.types`);
  const parent = tkmParent(config, before.model.tickets, type, opts.parent ?? null);
  if (type === 'defect' && !(Array.isArray(opts.links) && opts.links.some((l) => l.startsWith('todo:')))) {
    throw new Error('a defect ticket is created only by promoting a TODO note: archive the note, then run tickets new --type defect --link todo:<name> (the ticket-new skill does both with --from-todo)');
  }

  let slug = opts.slug ?? null;
  if (slug === null) {
    slug = tkmSlug(title, config.limits.slugLength);
    if (slug === '') throw new UsageError('the title gives no slug; pass --slug <slug>');
  } else if (!TKM_SLUG_RE.test(slug)) {
    throw new UsageError('--slug must be lowercase letters and digits joined by "-"');
  }
  if (slug.length > config.limits.slugLength) throw new Error(`slug has ${slug.length} characters; at most ${config.limits.slugLength}`);
  const depth = parent === null ? 1 : parent.depth + 1;
  if (depth > config.limits.depth) throw new Error(`depth ${depth} exceeds limits.depth ${config.limits.depth}`);

  const ref = opts.ref ?? null;
  const listed = ref !== null && typeof opts.listRef === 'function' ? opts.listRef(config.root) : null;
  const refNames = listed !== null && Array.isArray(listed.names) ? listed.names : null;
  const refError = listed !== null && refNames === null ? String(listed.error) : null;
  const id = nextTicketId(before, { type, ref, refNames }).next;
  const dir = `${parent === null ? config.root : parent.dir}/${id}-${slug}`;
  const file = `${dir}/ticket.md`;
  if (file.length > config.limits.pathLength) throw new Error(`path ${file} has ${file.length} characters; at most ${config.limits.pathLength}`);
  if (existsSync(tkmAbs(root, dir))) throw new Error(`${dir} already exists`);

  const links = Array.isArray(opts.links) && opts.links.length > 0 ? opts.links : undefined;
  const text = `${formatFrontMatter({ id, type, title, created: date, links })}\n# ${id}: ${title}\n\n${TICKET_BODIES[type]}`;
  mkdirSync(tkmAbs(root, dir));
  try {
    writeFileSync(tkmAbs(root, file), text);
    const added = tkmAddedProblems(before, checkTickets(root, { configPath: opts.configPath, registerPath: opts.registerPath }));
    if (added.length > 0) {
      rmSync(tkmAbs(root, dir), { recursive: true, force: true });
      return { status: 'refused', problems: added, configPath: before.configPath, refError };
    }
  } catch (e) {
    rmSync(tkmAbs(root, dir), { recursive: true, force: true });
    throw e;
  }
  return { status: 'created', id, dir, file, configPath: before.configPath, refError };
}

/**
 * `tickets freeze`: writes `config.frozen = { date, ids }` with every ID of the tree and the archive
 * (canonical, type order, then number) into the tickets config (JSON, 2 spaces, LF; the other keys keep
 * their order), then checks; an added TV error restores the config's bytes.
 *
 * @param {string} root the repository root
 * @param {{ configPath?: string, registerPath?: string, date: string }} opts
 * @returns {{ status: 'invalid' | 'refused', problems: object[], configPath: string }
 *   | { status: 'frozen', date: string, ids: string[], configPath: string }}
 * @throws {Error} when the tickets are frozen already
 */
function freezeTickets(root, opts) {
  const { before, invalid } = tkmBefore(root, opts);
  if (invalid !== null) return { status: 'invalid', problems: invalid, configPath: before.configPath };
  const config = before.config;
  if (config.frozen !== null) {
    throw new Error(`tickets are already frozen since ${config.frozen.date}; lifting a freeze is a hand edit of config.frozen`);
  }
  const seen = new Map();
  for (const t of before.model.tickets) {
    const id = `${t.prefix}-${String(t.number).padStart(config.digits, '0')}`;
    if (!seen.has(id)) seen.set(id, [TICKET_TYPES.indexOf(t.type), t.number]);
  }
  const ids = [...seen.keys()].sort((a, b) => seen.get(a)[0] - seen.get(b)[0] || seen.get(a)[1] - seen.get(b)[1]);
  const path = tkmAbs(root, before.configPath);
  const old = readFileSync(path);
  const raw = JSON.parse(old.toString('utf8').replace(/^﻿/, ''));
  writeFileSync(path, `${JSON.stringify({ ...raw, frozen: { date: opts.date, ids } }, null, 2)}\n`);
  try {
    const added = tkmAddedProblems(before, checkTickets(root, { configPath: opts.configPath, registerPath: opts.registerPath }));
    if (added.length > 0) {
      writeFileSync(path, old);
      return { status: 'refused', problems: added, configPath: before.configPath };
    }
  } catch (e) {
    writeFileSync(path, old);
    throw e;
  }
  return { status: 'frozen', date: opts.date, ids, configPath: before.configPath };
}

/** A closure value as written: a list in `[ … ]` (bare items, a "no plan:" item quoted) or a plain/quoted scalar. */
function tkmClosureValue(by) {
  const plain = (v) => v !== '' && v.trim() === v && !v.startsWith('[') && !v.startsWith('"') && !/[\r\n]/.test(v);
  if (Array.isArray(by)) {
    const bare = (v) => /^[^\s,[\]"][^,[\]"]*$/.test(v) && v.trim() === v && !v.startsWith('no plan:');
    return `[${by.map((v) => (bare(v) ? v : JSON.stringify(v))).join(', ')}]`;
  }
  return plain(by) ? by : JSON.stringify(by);
}

/**
 * The text of a `ticket.md` with the closure lines (`resolution`, `closed`, `by`) inserted before the line
 * that closes the front matter; every other byte stays, the new lines take the file's line end.
 */
function tkmInsertClosure(raw, ticket, c) {
  const lines = raw.split('\n');
  const cr = lines[0].endsWith('\r') ? '\r' : '';
  const at = ticket.fm.bodyStart - 1;
  const add = [`resolution: ${c.resolution}`, `closed: ${c.date}`, `by: ${tkmClosureValue(c.by)}`].map((l) => `${l}${cr}`);
  lines.splice(at, 0, ...add);
  return lines.join('\n');
}

/** The ticket a close is asked for: live, readable and open (an Error says why not). */
function tkmClosable(tickets, id) {
  const found = tickets.filter((t) => t.id === id);
  if (found.length === 0) throw new Error(`unknown ticket ${id}`);
  const t = found.find((x) => !x.archived);
  if (t === undefined) throw new Error(`${id} is archived; archived tickets are not changed`);
  if (t.fm === null || t.fm.bodyStart === 0) throw new Error(`${id} has no readable front matter; fix the TV1 problems first`);
  if (typeof t.fields.resolution === 'string') {
    throw new Error(`${id} is already resolved (${t.fields.resolution}${typeof t.fields.closed === 'string' ? ` on ${t.fields.closed}` : ''})`);
  }
  return t;
}

/**
 * Writes the closure of `picks` (`{ ticket, resolution, by }`) with `date`, then checks; an added TV error
 * restores every file.
 */
function tkmClose(root, before, opts, picks) {
  const olds = new Map();
  const closed = [];
  const restore = () => {
    for (const [path, old] of olds) {
      try { writeFileSync(path, old); } catch { /* best effort: restore the others */ }
    }
  };
  try {
    for (const p of picks) {
      const path = tkmAbs(root, p.ticket.file);
      const old = readFileSync(path);
      olds.set(path, old);
      writeFileSync(path, tkmInsertClosure(old.toString('utf8'), p.ticket, { resolution: p.resolution, date: opts.date, by: p.by }));
      closed.push({ id: p.ticket.id, file: p.ticket.file, resolution: p.resolution, by: p.by });
    }
    const added = tkmAddedProblems(before, checkTickets(root, { configPath: opts.configPath, registerPath: opts.registerPath }));
    if (added.length > 0) {
      restore();
      return { status: 'refused', problems: added, configPath: before.configPath };
    }
  } catch (e) {
    restore();
    throw e;
  }
  return { status: 'closed', closed, configPath: before.configPath };
}

/**
 * `tickets close <id>`: writes `resolution`, `closed` and `by` into the ticket's front matter (the rest of the
 * file keeps its bytes), then checks; an added TV error restores the file. `by` is a list for `done`, the
 * reason for `dropped` and a ticket ID for `superseded` and `promoted`; what TV4 rejects is refused by the check.
 *
 * @param {string} root the repository root
 * @param {{ configPath?: string, registerPath?: string, id: string, resolution: 'done' | 'dropped' | 'superseded' | 'promoted',
 *   by: string | string[], date: string }} opts
 * @returns {{ status: 'invalid' | 'refused', problems: object[], configPath: string }
 *   | { status: 'closed', closed: { id: string, file: string, resolution: string, by: string | string[] }[], configPath: string }}
 * @throws {Error} an unknown, archived or already resolved ticket
 */
function closeTicket(root, opts) {
  const { before, invalid } = tkmBefore(root, opts);
  if (invalid !== null) return { status: 'invalid', problems: invalid, configPath: before.configPath };
  const ticket = tkmClosable(before.model.tickets, opts.id);
  return tkmClose(root, before, opts, [{ ticket, resolution: opts.resolution, by: opts.by }]);
}

/**
 * `tickets close --auto` closes `done` every open ticket whose implementing tasks are all closed
 * (TV8 (a)), `by` = its implementation tasks; tickets whose tasks are only skipped are left. All or nothing.
 *
 * @param {string} root the repository root
 * @param {{ configPath?: string, registerPath?: string, date: string }} opts
 * @returns {{ status: 'invalid' | 'refused', problems: object[], configPath: string }
 *   | { status: 'nothing', configPath: string }
 *   | { status: 'closed', closed: { id: string, file: string, resolution: string, by: string[] }[], configPath: string }}
 */
function closeAuto(root, opts) {
  const { before, invalid } = tkmBefore(root, opts);
  if (invalid !== null) return { status: 'invalid', problems: invalid, configPath: before.configPath };
  if (before.model.state === null) return { status: 'nothing', configPath: before.configPath };
  const order = (t) => TICKET_TYPES.indexOf(t.type);
  const picks = closableTickets(before.model.state, before.model.tickets)
    .sort((a, b) => order(a.ticket) - order(b.ticket) || a.ticket.number - b.ticket.number)
    .map((c) => ({ ticket: c.ticket, resolution: 'done', by: c.refs }));
  if (picks.length === 0) return { status: 'nothing', configPath: before.configPath };
  return tkmClose(root, before, opts, picks);
}

/** The ticket of an ID in the live tree; an Error when it is unknown or only archived. */
function tkmLive(tickets, id, archivedMessage) {
  const found = tickets.filter((t) => t.id === id);
  if (found.length === 0) throw new Error(`unknown ticket ${id}`);
  const t = found.find((x) => !x.archived);
  if (t === undefined) throw new Error(archivedMessage);
  return t;
}

/** The tickets below `t` in the live tree (children first, in the order of `children`). */
function tkmDescendants(byId, t) {
  const out = [];
  const stack = [...t.children].reverse();
  while (stack.length > 0) {
    const d = byId.get(stack.pop());
    if (d === undefined) continue;
    out.push(d);
    stack.push(...[...d.children].reverse());
  }
  return out;
}

/**
 * Creates the directory `rel` (and its parents); returns the first path it created, or null when it was there.
 * When a creation fails, the directories this call made are removed again.
 */
function tkmMakeDirs(root, rel) {
  const parts = rel.split('/');
  let first = null;
  try {
    for (let i = 1; i <= parts.length; i += 1) {
      const sub = parts.slice(0, i).join('/');
      if (existsSync(tkmAbs(root, sub))) continue;
      mkdirSync(tkmAbs(root, sub));
      if (first === null) first = sub;
    }
  } catch (e) {
    if (first !== null) rmSync(tkmAbs(root, first), { recursive: true, force: true });
    throw new Error(`cannot create ${rel}: ${e && e.code ? `${e.code} ` : ''}${e && e.message ? e.message : e}`);
  }
  return first;
}

/**
 * Renames `from` to `to` (both repository paths), then checks; an added TV error reverses the rename and
 * removes the directories this run created (`created`). A rename that fails (for example EXDEV: the two paths
 * lie on different file systems) removes them too and throws a readable Error.
 */
function tkmRename(root, before, opts, from, to, created) {
  const dropCreated = () => {
    if (created !== null) rmSync(tkmAbs(root, created), { recursive: true, force: true });
  };
  try {
    renameSync(tkmAbs(root, from), tkmAbs(root, to));
  } catch (e) {
    dropCreated();
    const code = e && e.code ? e.code : 'error';
    const why = code === 'EXDEV' ? 'EXDEV: the two paths are on different file systems, and a rename cannot cross them' : `${code}: ${e && e.message ? e.message : e}`;
    throw new Error(`cannot move ${from} to ${to} (${why}); nothing was changed`);
  }
  const undo = () => {
    renameSync(tkmAbs(root, to), tkmAbs(root, from));
    dropCreated();
  };
  try {
    const added = tkmAddedProblems(before, checkTickets(root, { configPath: opts.configPath, registerPath: opts.registerPath }));
    if (added.length > 0) {
      undo();
      return { status: 'refused', problems: added, configPath: before.configPath };
    }
  } catch (e) {
    undo();
    throw e;
  }
  return { status: 'moved', from, to, configPath: before.configPath };
}

/**
 * `tickets archive <id>`: a resolved top-level ticket whose whole subtree is resolved moves (renameSync) to
 * `<archiveDir>/<its directory name>`; the archive directory is created when it is missing. Then checks; an
 * added TV error reverses the rename.
 *
 * @param {string} root the repository root
 * @param {{ configPath?: string, registerPath?: string, id: string }} opts
 * @returns {{ status: 'invalid' | 'refused', problems: object[], configPath: string }
 *   | { status: 'moved', from: string, to: string, configPath: string }}
 * @throws {Error} an unknown or archived ticket, one that is not top-level, not resolved or has an open descendant, or a target that exists
 */
function archiveTicket(root, opts) {
  const { before, invalid } = tkmBefore(root, opts);
  if (invalid !== null) return { status: 'invalid', problems: invalid, configPath: before.configPath };
  const config = before.config;
  const tickets = before.model.tickets;
  const t = tkmLive(tickets, opts.id, `${opts.id} is already archived`);
  const byId = new Map(tickets.filter((x) => !x.archived).map((x) => [x.id, x]));
  if (t.parent !== null) {
    let top = t;
    while (top.parent !== null && byId.has(top.parent)) top = byId.get(top.parent);
    throw new Error(`${t.id} is not a top-level ticket (it is under ${t.parent}); archive its top-level ticket ${top.id}`);
  }
  if (typeof t.fields.resolution !== 'string') throw new Error(`${t.id} cannot be archived: it is not resolved`);
  const open = tkmDescendants(byId, t).find((d) => typeof d.fields.resolution !== 'string');
  if (open !== undefined) throw new Error(`${t.id} cannot be archived: ${open.id} under it is open`);
  const to = `${config.archiveDir}/${t.name}`;
  if (existsSync(tkmAbs(root, to))) throw new Error(`${to} already exists`);
  const created = tkmMakeDirs(root, config.archiveDir);
  return tkmRename(root, before, opts, t.dir, to, created);
}

/**
 * `tickets move <id> (<parent> | top)`: re-parents a live subtree by renaming its directory (no content
 * edit). The target is checked first as TV3 would (parent type or top level, depth with the height of the
 * subtree), plus TV9 (an open ticket under a resolved ticket); then the rename is checked like any change.
 *
 * @param {string} root the repository root
 * @param {{ configPath?: string, registerPath?: string, id: string, parent: string | null }} opts `parent` null = the top level
 * @returns {{ status: 'invalid' | 'refused', problems: object[], configPath: string }
 *   | { status: 'moved', from: string, to: string, configPath: string }}
 * @throws {Error} a refusal before any change
 */
function moveTicket(root, opts) {
  const { before, invalid } = tkmBefore(root, opts);
  if (invalid !== null) return { status: 'invalid', problems: invalid, configPath: before.configPath };
  const config = before.config;
  const tickets = before.model.tickets;
  const t = tkmLive(tickets, opts.id, `${opts.id} is archived; archived tickets are not moved`);
  const parent = opts.parent === null ? null : tkmLive(tickets, opts.parent, `parent ${opts.parent} is archived`);
  if (parent !== null && parent.id === t.id) throw new Error(`cannot move ${t.id} under itself`);
  if (parent !== null && parent.dir.startsWith(`${t.dir}/`)) throw new Error(`cannot move ${t.id} under ${parent.id}, which lies inside it`);
  if (t.parent === (parent === null ? null : parent.id)) {
    throw new Error(parent === null ? `${t.id} is already at the top level` : `${t.id} is already under ${parent.id}`);
  }
  const spec = config.types[t.type];
  if (parent === null) {
    if (!spec.topLevel) throw new Error(`${t.type} cannot be at the top level (allowed parents: ${spec.parents.join(', ') || 'none'})`);
  } else if (!spec.parents.includes(parent.type)) {
    throw new Error(`${t.type} cannot be a child of ${parent.type} ${parent.id} (allowed: ${spec.parents.join(', ') || 'none'})`);
  }
  const byId = new Map(tickets.filter((x) => !x.archived).map((x) => [x.id, x]));
  const subtree = [t, ...tkmDescendants(byId, t)];
  const depth = (parent === null ? 1 : parent.depth + 1) + Math.max(...subtree.map((x) => x.depth)) - t.depth;
  if (depth > config.limits.depth) throw new Error(`depth ${depth} exceeds limits.depth ${config.limits.depth}`);
  if (subtree.some((x) => typeof x.fields.resolution !== 'string')) {
    for (let a = parent; a !== null; a = a.parent === null ? null : byId.get(a.parent) ?? null) {
      if (typeof a.fields.resolution === 'string') {
        throw new Error(`${a.id} is resolved (${a.fields.resolution}); an open ticket under it would be open under a closed ticket`);
      }
    }
  }
  const to = `${parent === null ? config.root : parent.dir}/${t.name}`;
  if (existsSync(tkmAbs(root, to))) throw new Error(`${to} already exists`);
  return tkmRename(root, before, opts, t.dir, to, null);
}

// --- core/tickets/cli.js ---
// `plan-register tickets <subcommand> …`: the subcommand table, its parser and the handlers. core/cli.js
// hands over the tokens after `tickets` together with the common flags given before it and a few
// functions of its own (no import of core/cli.js from here, so there is no cycle).
//
// Every subcommand takes the common flags `--root <dir>`, `--register <path>` and the tickets common flag
// `--tickets-config <path>`. The root: `--root`, else the first directory from the working directory
// upwards that contains the tickets config path (default docs/tickets/config.json). The register:
// `--register`, else the `register` of the tickets config.
//
// Usage errors are UsageError with `usageLine` set; core/cli.js prints them and exits 2.

/** Flags every tickets subcommand accepts besides the common flags of the CLI. */
const TICKETS_COMMON_FLAGS = Object.freeze(['--tickets-config']);

/** The tickets subcommands: positional arguments, own flags, required flags and a one-line summary. */
const TICKETS_COMMANDS = Object.freeze({
  check: Object.freeze({
    args: Object.freeze([]),
    flags: Object.freeze(['--json']),
    required: Object.freeze([]),
    summary: 'Check the tickets: config, tree, files, plan links, homes, closure, links, regions (TV1-TV13); --json prints tickets-check/1.',
  }),
  write: Object.freeze({
    args: Object.freeze([]),
    flags: Object.freeze([]),
    required: Object.freeze([]),
    summary: 'Regenerate the tickets index regions; refuses while TV1-TV3 or V13 problems exist or the register cannot be read.',
  }),
  status: Object.freeze({
    args: Object.freeze([]),
    flags: Object.freeze(['--stale', '--today', '--json']),
    required: Object.freeze([]),
    summary: 'Counts by state, the tickets in progress, planned and scheduled, the backlog, stale and archivable tickets; --json prints tickets-show/1.',
  }),
  show: Object.freeze({
    args: Object.freeze(['<id>']),
    flags: Object.freeze(['--json']),
    required: Object.freeze([]),
    summary: 'One ticket: path, parent chain, children, state, closure, links, acceptance, rows, tasks, references.',
  }),
  brief: Object.freeze({
    args: Object.freeze([]),
    flags: Object.freeze(['--ids', '--unit', '--milestone', '--index-only', '--out']),
    required: Object.freeze([]),
    summary: 'A slim ticket excerpt for a plan writer: by --ids, --unit or --milestone <key> <milestone>; --index-only for one table.',
  }),
  new: Object.freeze({
    args: Object.freeze([]),
    flags: Object.freeze(['--type', '--title', '--parent', '--slug', '--link', '--date', '--ref', '--no-ref', '--write']),
    required: Object.freeze(['--type', '--title']),
    summary: 'Create a ticket with the next ID and the body of its type; refused when frozen, for a disabled type or a parent it cannot have; --write also regenerates the regions.',
  }),
  'next-id': Object.freeze({
    args: Object.freeze([]),
    flags: Object.freeze(['--type', '--ref', '--no-ref', '--json']),
    required: Object.freeze(['--type']),
    summary: 'The next free ID of a type over the tree, the archive, the freeze list and the names on origin/main (or --ref); --json prints tickets-show/1.',
  }),
  freeze: Object.freeze({
    args: Object.freeze([]),
    flags: Object.freeze(['--date']),
    required: Object.freeze([]),
    summary: 'Write config.frozen: the date and every ticket ID; tickets new is refused afterwards and TV2 flags any later ID.',
  }),
  close: Object.freeze({
    args: Object.freeze(['[<id>]']),
    flags: Object.freeze(['--done', '--by', '--reason', '--dropped', '--superseded', '--promoted', '--auto', '--date', '--write']),
    required: Object.freeze([]),
    summary: 'Close a ticket: --done --by <plan#N,…|ID,…>, --done --by commit:<sha> --reason <text>, --dropped <reason>, --superseded <id> or --promoted <id>; --auto closes every ticket whose implementing tasks are all closed.',
  }),
  archive: Object.freeze({
    args: Object.freeze(['<id>']),
    flags: Object.freeze(['--write']),
    required: Object.freeze([]),
    summary: 'Move a resolved top-level ticket with its whole (resolved) subtree into the archive directory; a plain rename.',
  }),
  move: Object.freeze({
    args: Object.freeze(['<id>', '[<parent>]']),
    flags: Object.freeze(['--top', '--write']),
    required: Object.freeze([]),
    summary: 'Re-parent a live ticket subtree under <parent> or at the top level (--top); the target is checked first; a plain rename.',
  }),
  help: Object.freeze({
    args: Object.freeze(['[<subcommand>]']),
    flags: Object.freeze([]),
    required: Object.freeze([]),
    summary: 'Show the tickets subcommands, or the usage of one subcommand.',
  }),
});

const TKCLI_FLAG_SPECS = Object.freeze({
  '--root': { kind: 'value', meta: '<dir>' },
  '--register': { kind: 'value', meta: '<path>' },
  '--tickets-config': { kind: 'value', meta: '<path>' },
  '--json': { kind: 'bool' },
  '--stale': { kind: 'value', meta: '<days>' },
  '--today': { kind: 'value', meta: 'YYYY-MM-DD' },
  '--ids': { kind: 'value', meta: '<id,…>' },
  '--unit': { kind: 'value', meta: '<key>' },
  '--milestone': { kind: 'pair', meta: '<key> <milestone>' },
  '--index-only': { kind: 'bool' },
  '--out': { kind: 'value', meta: '<file|->' },
  '--type': { kind: 'value', meta: '<type>' },
  '--title': { kind: 'value', meta: '<text>' },
  '--parent': { kind: 'value', meta: '<id>' },
  '--slug': { kind: 'value', meta: '<slug>' },
  '--link': { kind: 'repeat', meta: '<entry>' },
  '--date': { kind: 'value', meta: 'YYYY-MM-DD' },
  '--ref': { kind: 'value', meta: '<ref>' },
  '--no-ref': { kind: 'bool' },
  '--write': { kind: 'bool' },
  '--done': { kind: 'bool' },
  '--by': { kind: 'value', meta: '<entries>' },
  '--reason': { kind: 'value', meta: '<text>' },
  '--dropped': { kind: 'value', meta: '<reason>' },
  '--superseded': { kind: 'value', meta: '<id>' },
  '--promoted': { kind: 'value', meta: '<id>' },
  '--auto': { kind: 'bool' },
  '--top': { kind: 'bool' },
});

/** The synopsis of a subcommand, common flags included: `check [--json] [--root <dir>] …`. */
function tkcliSynopsis(name, common) {
  const c = TICKETS_COMMANDS[name];
  const flag = (f) => {
    const spec = TKCLI_FLAG_SPECS[f];
    const shown = spec.kind === 'bool' ? f : `${f} ${spec.meta}`;
    return `${c.required.includes(f) ? shown : `[${shown}]`}${spec.kind === 'repeat' ? '…' : ''}`;
  };
  return [name, ...c.args, ...c.flags.map(flag), ...common.map(flag), ...TICKETS_COMMON_FLAGS.map(flag)].join(' ');
}

/** `usage: …` of a subcommand, or of `tickets` as a whole. */
function tkcliUsageLine(ctx, sub) {
  if (sub !== null && Object.hasOwn(TICKETS_COMMANDS, sub)) {
    return `usage: node ${ctx.rt.script} tickets ${tkcliSynopsis(sub, ctx.commonFlags)}`;
  }
  return `usage: node ${ctx.rt.script} tickets <subcommand> [<args>] [<flags>] (run "node ${ctx.rt.script} tickets help")`;
}

function tkcliError(ctx, message, sub) {
  const e = new UsageError(message);
  e.usageLine = tkcliUsageLine(ctx, sub);
  return e;
}

function tkcliIsFlag(token) {
  return typeof token === 'string' && token.length > 1 && token.startsWith('-');
}

/** Parses the tokens after `tickets` into `{ sub, positionals, flags }`; `flags` starts from the common flags given before. */
function tkcliParse(rest, ctx) {
  const flags = new Map(ctx.flags);
  const positionals = [];
  let sub = null;
  let i = 0;
  while (i < rest.length) {
    const token = rest[i];
    if (!tkcliIsFlag(token)) {
      if (sub === null) {
        if (!Object.hasOwn(TICKETS_COMMANDS, token)) throw tkcliError(ctx, `unknown tickets subcommand ${JSON.stringify(token)}`, null);
        sub = token;
      } else {
        positionals.push(token);
      }
      i += 1;
      continue;
    }
    const eq = token.indexOf('=');
    const name = eq === -1 ? token : token.slice(0, eq);
    const inline = eq === -1 ? undefined : token.slice(eq + 1);
    const allowed = [...(sub === null ? [] : TICKETS_COMMANDS[sub].flags), ...ctx.commonFlags, ...TICKETS_COMMON_FLAGS];
    if (!allowed.includes(name) || !Object.hasOwn(TKCLI_FLAG_SPECS, name)) {
      throw tkcliError(ctx, `unknown flag ${name} for tickets${sub === null ? '' : ` ${sub}`}`, sub);
    }
    const spec = TKCLI_FLAG_SPECS[name];
    if (spec.kind === 'bool') {
      if (inline !== undefined) throw tkcliError(ctx, `${name} takes no value`, sub);
      flags.set(name, true);
      i += 1;
      continue;
    }
    if (spec.kind === 'pair') {
      const values = inline === undefined ? rest.slice(i + 1, i + 3) : [inline, rest[i + 1]];
      if (values.length < 2 || values.some((v) => v === undefined || tkcliIsFlag(v))) throw tkcliError(ctx, `${name} needs two values ${spec.meta}`, sub);
      if (flags.has(name)) throw tkcliError(ctx, `${name} is given more than once`, sub);
      flags.set(name, values);
      i += inline === undefined ? 3 : 2;
      continue;
    }
    let value = inline;
    let next = i + 1;
    if (value === undefined) {
      if (i + 1 >= rest.length || tkcliIsFlag(rest[i + 1])) throw tkcliError(ctx, `${name} needs a value ${spec.meta}`, sub);
      value = rest[i + 1];
      next = i + 2;
    }
    if (spec.kind === 'repeat') {
      flags.set(name, [...(flags.get(name) ?? []), value]);
      i = next;
      continue;
    }
    if (flags.has(name)) throw tkcliError(ctx, `${name} is given more than once`, sub);
    if (name === '--tickets-config' && normalizePath(value) === null) {
      throw tkcliError(ctx, '--tickets-config must be a repository-relative POSIX path', sub);
    }
    flags.set(name, value);
    i = next;
  }
  if (sub !== null) {
    const args = TICKETS_COMMANDS[sub].args;
    const required = args.filter((a) => !a.startsWith('['));
    if (positionals.length < required.length) throw tkcliError(ctx, `missing argument ${required[positionals.length]}`, sub);
    if (positionals.length > args.length) throw tkcliError(ctx, `unexpected argument ${JSON.stringify(positionals[args.length])}`, sub);
    for (const f of TICKETS_COMMANDS[sub].required) if (!flags.has(f)) throw tkcliError(ctx, `missing flag ${f}`, sub);
  }
  return { sub, positionals, flags };
}

/** The tickets help text. */
function tkcliHelpText(ctx) {
  const script = ctx.rt.script;
  const width = Math.max(...Object.keys(TICKETS_COMMANDS).map((n) => n.length));
  return [
    `plan-register tickets (schema ${TICKETS_SCHEMA}): work-item tickets`,
    '',
    `usage: node ${script} tickets <subcommand> [<args>] [<flags>]`,
    '',
    'Subcommands:',
    ...Object.entries(TICKETS_COMMANDS).map(([name, c]) => `  ${name.padEnd(width)}  ${c.summary}`),
    '',
    'Flags of every subcommand:',
    '  --root <dir>              repository root (default: the first directory upwards that contains the tickets config)',
    '  --register <path>         register path relative to the root (default: the register the tickets config names)',
    `  --tickets-config <path>   tickets config relative to the root (default ${TICKETS_CONFIG_PATH})`,
    '',
    'Exit codes: 0 ok · 1 problems · 2 usage error.',
    `Run "node ${script} tickets help <subcommand>" for the flags of one subcommand.`,
  ].join('\n');
}

/** The help of one subcommand. */
function tkcliCommandHelp(ctx, name) {
  const c = TICKETS_COMMANDS[name];
  const lines = [`usage: node ${ctx.rt.script} tickets ${tkcliSynopsis(name, ctx.commonFlags)}`, '', c.summary, '', 'Flags:'];
  for (const f of [...c.flags, ...ctx.commonFlags, ...TICKETS_COMMON_FLAGS]) {
    const spec = TKCLI_FLAG_SPECS[f];
    const notes = `${c.required.includes(f) ? ' (required)' : ''}${spec.kind === 'repeat' ? ' (repeatable)' : ''}`;
    lines.push(`  ${spec.kind === 'bool' ? f : `${f} ${spec.meta}`}${notes}`);
  }
  return lines.join('\n');
}

/** The tickets config path of the run (`--tickets-config` or the default). */
function tkcliConfigPath(p) {
  const v = p.flags.get('--tickets-config');
  return typeof v === 'string' && v !== '' ? v : TICKETS_CONFIG_PATH;
}

/** The repository root: `--root`, else the first directory upwards that contains the tickets config. */
function tkcliRoot(p, ctx) {
  const root = p.flags.get('--root');
  if (typeof root === 'string' && root !== '') return resolve(ctx.rt.cwd, root);
  const configPath = tkcliConfigPath(p);
  let dir = resolve(ctx.rt.cwd);
  for (;;) {
    if (existsSync(resolve(dir, configPath))) return dir;
    const up = dirname(dir);
    if (up === dir) break;
    dir = up;
  }
  throw new Error(`tickets config not found: looked for ${configPath} from ${ctx.rt.cwd} upwards; pass --root or --tickets-config`);
}

/** A fix printed as a command line: a tickets fix gains `--tickets-config` when it is not the default. */
function tkcliFixText(p, ctx, args) {
  const extra = args[0] === 'tickets' && tkcliConfigPath(p) !== TICKETS_CONFIG_PATH ? ['--tickets-config', tkcliConfigPath(p)] : [];
  // A fix that names its register already does not get the run's --register a second time.
  const flags = args.includes('--register') ? new Map([...p.flags].filter(([k]) => k !== '--register')) : p.flags;
  return ctx.commandLine([...args, ...extra], flags);
}

/** At most this many lines of a region diff are printed (as for V12). */
const TKCLI_DIFF_LINES = 20;

/** Prints one block of problems or warnings in the check format (with the diff hint of a stale region). */
function tkcliPrintBlock(ctx, p, header, list) {
  ctx.rt.err(header);
  for (const pr of list) {
    ctx.rt.err(`  - [${pr.rule}] ${pr.where}: ${pr.message}`);
    if (Array.isArray(pr.fix)) ctx.rt.err(`      fix: ${tkcliFixText(p, ctx, pr.fix)}`);
    if (typeof pr.diff === 'string' && pr.diff !== '') {
      const lines = pr.diff.split('\n');
      for (const l of lines.slice(0, TKCLI_DIFF_LINES)) ctx.rt.err(`      ${l}`);
      if (lines.length > TKCLI_DIFF_LINES) ctx.rt.err(`      … ${lines.length - TKCLI_DIFF_LINES} more line(s)`);
    }
  }
}

/** The tickets check of the run (root, config and register from the flags). */
function tkcliRun(p, ctx) {
  const root = tkcliRoot(p, ctx);
  const register = p.flags.get('--register');
  const result = checkTickets(root, {
    configPath: tkcliConfigPath(p),
    registerPath: typeof register === 'string' && register !== '' ? register : undefined,
  });
  return { root, result };
}

function tkcliCheck(p, ctx) {
  const { result } = tkcliRun(p, ctx);
  if (p.flags.has('--json')) {
    const answer = ticketsCheckJson(result, { fixText: (args) => tkcliFixText(p, ctx, args) });
    ctx.rt.out(JSON.stringify(answer, null, 2));
    return answer.ok ? 0 : 1;
  }
  const label = result.configPath;
  if (result.problems.length === 0) {
    const warned = result.warnings.length > 0 ? `; ${result.warnings.length} warning(s)` : '';
    ctx.rt.out(`plan-register tickets: ${result.tickets} ticket(s), ${result.archived} archived valid; `
      + `${result.regions.length} region(s) current${warned}`);
  } else {
    tkcliPrintBlock(ctx, p, `${label}: ${result.problems.length} problem(s)`, result.problems);
  }
  if (result.warnings.length > 0) tkcliPrintBlock(ctx, p, `${label}: ${result.warnings.length} warning(s)`, result.warnings);
  for (const n of result.notes) ctx.rt.err(`note: [${n.rule}] ${n.where}: ${n.message}`);
  return result.problems.length === 0 ? 0 : 1;
}

/** `tickets write`: regenerates the regions unless TV1-TV3 or V13 problems or an unreadable register stop it. */
function tkcliWrite(p, ctx) {
  return tkcliWriteRegions(p, ctx, tkcliRun(p, ctx));
}

/** Writes the regions of a check result (`tickets write`, and `--write` of a change command). */
function tkcliWriteRegions(p, ctx, { root, result }) {
  const label = result.configPath;
  const blocking = ticketsBlocking(result.problems);
  const tm = result.model === null ? null : result.model.state;
  if (blocking.length > 0 || tm === null) {
    if (blocking.length > 0) tkcliPrintBlock(ctx, p, `${label}: ${blocking.length} problem(s)`, blocking);
    ctx.rt.err('regions not written');
    return 1;
  }
  const r = writeTicketsRegions(root, ticketsRegionStates(result.config, result.model.tickets, tm, label));
  if (!r.ok) {
    tkcliPrintBlock(ctx, p, `${label}: ${r.errors.length} problem(s)`, r.errors.map((e) => ({ rule: 'TV11', ...e, fix: null })));
    ctx.rt.err('regions not written');
    return 1;
  }
  for (const w of r.written) ctx.rt.out(`${w.file} (${w.marker}): ${w.changed ? 'updated' : 'already current'}`);
  return 0;
}

/** The tickets check of a read view; prints the problems and returns null when the model is not available. */
function tkcliModel(p, ctx) {
  const { result } = tkcliRun(p, ctx);
  if (result.model !== null && result.model.state !== null) return result;
  const blocking = result.problems.filter((pr) => pr.rule === 'TV1');
  tkcliPrintBlock(ctx, p, `${result.configPath}: ${blocking.length} problem(s)`, blocking);
  return null;
}

/** `tickets status`: never refuses on problems (it counts them); exit 1 only without a usable config and register. */
function tkcliStatus(p, ctx) {
  const staleRaw = p.flags.get('--stale');
  const todayRaw = p.flags.get('--today');
  if (staleRaw !== undefined && !/^\d+$/.test(staleRaw)) throw tkcliError(ctx, '--stale must be a whole number of days', 'status');
  if (todayRaw !== undefined && !isCalendarDate(todayRaw)) throw tkcliError(ctx, '--today must be a calendar date YYYY-MM-DD', 'status');
  const result = tkcliModel(p, ctx);
  if (result === null) return 1;
  const opts = {
    today: todayRaw ?? new Date().toISOString().slice(0, 10),
    staleDays: staleRaw === undefined ? null : Number(staleRaw),
  };
  if (p.flags.has('--json')) ctx.rt.out(JSON.stringify(ticketsStatusJson(result, opts), null, 2));
  else ctx.rt.out(ticketsStatusText(result, opts));
  return 0;
}

/** `tickets show <id>`: exit 1 for an unknown ID. */
function tkcliShow(p, ctx) {
  const result = tkcliModel(p, ctx);
  if (result === null) return 1;
  const id = p.positionals[0];
  const json = p.flags.has('--json') ? ticketShowJson(result, id) : null;
  const text = json === null ? ticketShowText(result, id) : null;
  if (json === null && text === null) throw new Error(`unknown ticket ${id}`);
  ctx.rt.out(json !== null ? JSON.stringify(json, null, 2) : text);
  return 0;
}

/**
 * The ticket IDs a brief selector names (unknown IDs, units and rows are errors: exit 1). A known unit or
 * row that schedules no tickets is normal (free-text rows): no IDs and `none`, the sentence for the answer.
 */
function tkcliBriefIds(p, ctx, tm) {
  if (p.flags.has('--ids')) {
    const ids = [...new Set(String(p.flags.get('--ids')).split(',').map((x) => x.trim()).filter((x) => x !== ''))];
    if (ids.length === 0) throw tkcliError(ctx, '--ids needs at least one ticket ID', 'brief');
    for (const id of ids) if (!tm.byId.has(id)) throw new Error(`unknown ticket ${id}`);
    return { ids, name: ids.join(', ') };
  }
  const [name, milestone] = p.flags.has('--unit') ? [p.flags.get('--unit'), null] : p.flags.get('--milestone');
  const r = resolveKey(tm.data, name);
  if (r === null) throw new Error(`unknown unit ${name}`);
  let rows = tm.briefs.filter((b) => b.unit.key === r.key).flatMap((b) => b.rows);
  if (milestone !== null) {
    rows = rows.filter((row) => row.milestone === milestone);
    if (rows.length === 0) throw new Error(`unit ${r.key} has no Milestones row ${milestone}`);
  }
  const ids = [...new Set(rows.flatMap((row) => row.ids))];
  const label = milestone === null ? r.key : `${r.key} ${milestone}`;
  if (ids.length === 0) return { ids, name: label, none: `${milestone === null ? `unit ${r.key}` : `row ${milestone} of ${r.key}`} schedules no tickets` };
  for (const id of ids) if (!tm.byId.has(id)) throw new Error(`${label} schedules ${id}, which does not exist`);
  return { ids, name: label };
}

/** `tickets brief`: the excerpt on stdout or into `--out <file>` (relative to the working directory). */
function tkcliBrief(p, ctx) {
  const selectors = ['--ids', '--unit', '--milestone'].filter((f) => p.flags.has(f));
  if (selectors.length !== 1) throw tkcliError(ctx, 'give exactly one of --ids, --unit, --milestone', 'brief');
  const result = tkcliModel(p, ctx);
  if (result === null) return 1;
  const { ids, name, none } = tkcliBriefIds(p, ctx, result.model.state);
  const text = ticketsBriefMarkdown(result, { ids, name, none, indexOnly: p.flags.has('--index-only') });
  const out = p.flags.has('--out') ? String(p.flags.get('--out')) : '-';
  if (out === '-') {
    ctx.rt.out(text);
  } else {
    writeFileSync(resolve(ctx.rt.cwd, out), `${text}\n`);
    ctx.rt.out(`wrote ${out} (${text.split('\n').length} lines)`);
  }
  return 0;
}

/** The value of `--date`, else today (UTC); a bad value is a usage error. */
function tkcliDate(p, ctx, sub) {
  const raw = p.flags.get('--date');
  if (raw === undefined) return new Date().toISOString().slice(0, 10);
  if (!isCalendarDate(raw)) throw tkcliError(ctx, '--date must be a calendar date YYYY-MM-DD', sub);
  return raw;
}

/** `--type`: one of the ticket types. */
function tkcliType(p, ctx, sub) {
  const type = p.flags.get('--type');
  if (!TICKET_TYPES.includes(type)) throw tkcliError(ctx, `--type must be one of ${TICKET_TYPES.join(', ')}`, sub);
  return type;
}

/** The ref to read: `--ref`, `origin/main` by default, null with `--no-ref`. */
function tkcliRef(p, ctx, sub) {
  const ref = p.flags.get('--ref');
  if (ref !== undefined && p.flags.has('--no-ref')) throw tkcliError(ctx, '--ref and --no-ref cannot go together', sub);
  if (p.flags.has('--no-ref')) return null;
  if (ref === undefined) return 'origin/main';
  if (!/^[^\s-][^\s]*$/.test(ref)) throw tkcliError(ctx, '--ref must name a git ref', sub);
  return ref;
}

/**
 * The file names under `ticketsRoot` at `ref`: `git -C <root> ls-tree -r -z --name-only <ref> -- <ticketsRoot>`.
 * `{ names }`, or `{ error }` when git is missing, the root is not in a repository or the ref is unknown.
 */
function tkcliListRef(root, ref, ticketsRoot) {
  try {
    const out = execFileSync('git', ['-C', root, 'ls-tree', '-r', '-z', '--name-only', ref, '--', ticketsRoot], {
      encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], maxBuffer: 64 * 1024 * 1024,
    });
    return { names: out.split('\0').filter((l) => l !== '') };
  } catch (e) {
    if (e && e.code === 'ENOENT') return { error: 'git not found' };
    const stderr = e && e.stderr !== undefined ? String(e.stderr) : '';
    if (/not a git repository/i.test(stderr)) return { error: 'not a git repository' };
    if (/not a valid object name|not a tree object|unknown revision|bad revision|ambiguous argument/i.test(stderr)) return { error: 'unknown ref' };
    const first = stderr.split('\n').map((l) => l.trim()).find((l) => l !== '');
    return { error: first === undefined ? 'git ls-tree failed' : first };
  }
}

function tkcliRefNote(ctx, ref, refError) {
  if (refError !== null) ctx.rt.err(`note: ${ref} not read (${refError}); using the working tree only`);
}

/** The run's `--tickets-config` and `--register` as options of a change. */
function tkcliChangeOpts(p) {
  const register = p.flags.get('--register');
  return { configPath: tkcliConfigPath(p), registerPath: typeof register === 'string' && register !== '' ? register : undefined };
}

/** Prints the TV1 problems that stop a change, or the problems it added and the refusal line. */
function tkcliRefused(p, ctx, res) {
  tkcliPrintBlock(ctx, p, `${res.configPath}: ${res.problems.length} problem(s)`, res.problems);
  if (res.status === 'refused') ctx.rt.err('refused: nothing was changed');
  return 1;
}

/** A UsageError thrown by a change gets the usage line of its subcommand. */
function tkcliUsage(ctx, sub, fn) {
  try {
    return fn();
  } catch (e) {
    if (e instanceof UsageError && typeof e.usageLine !== 'string') e.usageLine = tkcliUsageLine(ctx, sub);
    throw e;
  }
}

/** `tickets new`: the ticket with the next ID; `--write` also regenerates the regions. */
function tkcliNew(p, ctx) {
  const type = tkcliType(p, ctx, 'new');
  const title = String(p.flags.get('--title')).trim();
  if (title === '' || /[\r\n]/.test(title)) throw tkcliError(ctx, '--title must be one non-empty line', 'new');
  const slug = p.flags.has('--slug') ? String(p.flags.get('--slug')) : null;
  if (slug !== null && !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug)) throw tkcliError(ctx, '--slug must be lowercase letters and digits joined by "-"', 'new');
  const date = tkcliDate(p, ctx, 'new');
  const ref = tkcliRef(p, ctx, 'new');
  const root = tkcliRoot(p, ctx);
  const res = tkcliUsage(ctx, 'new', () => newTicket(root, {
    ...tkcliChangeOpts(p),
    type,
    title,
    parent: p.flags.has('--parent') ? String(p.flags.get('--parent')) : null,
    slug,
    links: p.flags.get('--link') ?? [],
    date,
    ref,
    listRef: (ticketsRoot) => tkcliListRef(root, ref, ticketsRoot),
  }));
  tkcliRefNote(ctx, ref, res.refError);
  if (res.status !== 'created') return tkcliRefused(p, ctx, res);
  ctx.rt.out(`created ${res.file} (${res.id})`);
  if (!p.flags.has('--write')) {
    ctx.rt.out(`regions not updated; run: ${tkcliFixText(p, ctx, ['tickets', 'write'])}`);
    return 0;
  }
  return tkcliWriteRegions(p, ctx, tkcliRun(p, ctx));
}

/** `tickets next-id`: the next free ID of a type (the ref adds the names on origin/main). */
function tkcliNextId(p, ctx) {
  const type = tkcliType(p, ctx, 'next-id');
  const ref = tkcliRef(p, ctx, 'next-id');
  const { root, result } = tkcliRun(p, ctx);
  if (result.config === null) {
    const blocking = result.problems.filter((pr) => pr.rule === 'TV1');
    tkcliPrintBlock(ctx, p, `${result.configPath}: ${blocking.length} problem(s)`, blocking);
    return 1;
  }
  const listed = ref === null ? null : tkcliListRef(root, ref, result.config.root);
  const refNames = listed !== null && Array.isArray(listed.names) ? listed.names : null;
  tkcliRefNote(ctx, ref, listed !== null && refNames === null ? listed.error : null);
  const view = nextTicketId(result, { type, ref, refNames });
  ctx.rt.out(p.flags.has('--json') ? JSON.stringify(view, null, 2) : view.next);
  return 0;
}

/** `tickets freeze`: writes config.frozen. */
function tkcliFreeze(p, ctx) {
  const date = tkcliDate(p, ctx, 'freeze');
  const root = tkcliRoot(p, ctx);
  const res = freezeTickets(root, { ...tkcliChangeOpts(p), date });
  if (res.status !== 'frozen') return tkcliRefused(p, ctx, res);
  ctx.rt.out(`froze ${res.ids.length} ticket ID(s) on ${res.date} in ${res.configPath}`);
  return 0;
}

/** One line per closed ticket: `closed TK-001 done by plan-a#1`. */
function tkcliClosedLine(c) {
  if (c.resolution === 'done') return `closed ${c.id} done by ${c.by.join(', ')}`;
  if (c.resolution === 'dropped') return `closed ${c.id} dropped: ${c.by}`;
  return `closed ${c.id} ${c.resolution === 'promoted' ? 'promoted to' : 'superseded by'} ${c.by}`;
}

/** The resolution of `tickets close <id>` from its flags (usage errors for flags that do not fit). */
function tkcliResolution(p, ctx) {
  const modes = ['--done', '--dropped', '--superseded', '--promoted'].filter((f) => p.flags.has(f));
  if (modes.length === 0) throw tkcliError(ctx, 'give one of --done, --dropped, --superseded, --promoted', 'close');
  if (modes.length > 1) throw tkcliError(ctx, 'give only one of --done, --dropped, --superseded, --promoted', 'close');
  const mode = modes[0];
  if (p.flags.has('--by') && mode !== '--done') throw tkcliError(ctx, '--by goes with --done', 'close');
  if (mode !== '--done') {
    if (p.flags.has('--reason')) throw tkcliError(ctx, '--reason goes with --done --by commit:<sha>', 'close');
    const value = String(p.flags.get(mode));
    if (mode === '--dropped') {
      const reason = value.trim();
      if (reason === '' || /[\r\n]/.test(reason)) throw tkcliError(ctx, '--dropped must be one non-empty line', 'close');
      return { resolution: 'dropped', by: reason };
    }
    return { resolution: mode === '--promoted' ? 'promoted' : 'superseded', by: value.trim() };
  }
  if (!p.flags.has('--by')) throw tkcliError(ctx, '--done needs --by', 'close');
  const entries = String(p.flags.get('--by')).split(',').map((x) => x.trim()).filter((x) => x !== '');
  if (entries.length === 0) throw tkcliError(ctx, '--by needs at least one entry', 'close');
  if (!entries.some((e) => e.startsWith('commit:'))) {
    if (p.flags.has('--reason')) throw tkcliError(ctx, '--reason goes with --done --by commit:<sha>', 'close');
    return { resolution: 'done', by: entries };
  }
  if (entries.length > 1) throw tkcliError(ctx, '--by commit:<sha> cannot be combined with other entries', 'close');
  if (!p.flags.has('--reason')) throw tkcliError(ctx, '--by commit:<sha> needs --reason <text>', 'close');
  const reason = String(p.flags.get('--reason')).trim();
  if (reason === '' || /[\r\n]/.test(reason)) throw tkcliError(ctx, '--reason must be one non-empty line', 'close');
  return { resolution: 'done', by: [entries[0], `no plan: ${reason}`] };
}

/** `tickets close <id> …` and `tickets close --auto`; `--write` also regenerates the regions. */
function tkcliClose(p, ctx) {
  const auto = p.flags.has('--auto');
  const id = p.positionals[0];
  let what = null;
  if (auto) {
    if (id !== undefined) throw tkcliError(ctx, '--auto takes no ticket ID', 'close');
    if (['--done', '--by', '--reason', '--dropped', '--superseded', '--promoted'].some((f) => p.flags.has(f))) {
      throw tkcliError(ctx, '--auto cannot go with a resolution flag', 'close');
    }
  } else {
    if (id === undefined) throw tkcliError(ctx, 'give a ticket ID or --auto', 'close');
    what = tkcliResolution(p, ctx);
  }
  const date = tkcliDate(p, ctx, 'close');
  const root = tkcliRoot(p, ctx);
  const opts = { ...tkcliChangeOpts(p), date };
  const res = auto ? closeAuto(root, opts) : closeTicket(root, { ...opts, id, ...what });
  if (res.status === 'nothing') {
    ctx.rt.out('nothing to close');
    return 0;
  }
  if (res.status !== 'closed') return tkcliRefused(p, ctx, res);
  for (const c of res.closed) ctx.rt.out(tkcliClosedLine(c));
  if (!p.flags.has('--write')) {
    ctx.rt.out(`regions not updated; run: ${tkcliFixText(p, ctx, ['tickets', 'write'])}`);
    return 0;
  }
  return tkcliWriteRegions(p, ctx, tkcliRun(p, ctx));
}

/** Shell word: bare when it has only safe characters, else single-quoted. */
function tkcliShellWord(w) {
  return /^[A-Za-z0-9_@%+=:,./-]+$/.test(w) ? w : `'${w.replace(/'/g, `'\\''`)}'`;
}

/**
 * The git line that records a rename from any working directory: `git -C <root> add -A -- <parent of from> <to>`.
 * The parent directory (not `from`, which a never-committed ticket has no pathspec match for) lets git see the removal.
 */
function tkcliGitAdd(root, from, to) {
  const parent = dirname(from);
  return ['git', '-C', tkcliShellWord(root), 'add', '-A', '--', tkcliShellWord(parent), tkcliShellWord(to)].join(' ');
}

/** Prints what a rename did and the git follow-up, then the regions as every change does. */
function tkcliMoved(p, ctx, verb, id, res) {
  ctx.rt.out(`${verb} ${id} -> ${res.to}`);
  ctx.rt.out(`next: ${tkcliGitAdd(tkcliRoot(p, ctx), res.from, res.to)}`);
  if (!p.flags.has('--write')) {
    ctx.rt.out(`regions not updated; run: ${tkcliFixText(p, ctx, ['tickets', 'write'])}`);
    return 0;
  }
  return tkcliWriteRegions(p, ctx, tkcliRun(p, ctx));
}

/** `tickets archive <id>`: a resolved top-level subtree into the archive directory. */
function tkcliArchive(p, ctx) {
  const id = p.positionals[0];
  const res = archiveTicket(tkcliRoot(p, ctx), { ...tkcliChangeOpts(p), id });
  if (res.status !== 'moved') return tkcliRefused(p, ctx, res);
  return tkcliMoved(p, ctx, 'archived', id, res);
}

/** `tickets move <id> (<parent> | --top)`: a live subtree to another parent or the top level. */
function tkcliMove(p, ctx) {
  const id = p.positionals[0];
  const parent = p.positionals[1];
  if (parent === undefined && !p.flags.has('--top')) throw tkcliError(ctx, 'give a new parent or --top', 'move');
  if (parent !== undefined && p.flags.has('--top')) throw tkcliError(ctx, 'give a new parent or --top, not both', 'move');
  const res = moveTicket(tkcliRoot(p, ctx), { ...tkcliChangeOpts(p), id, parent: parent === undefined ? null : parent });
  if (res.status !== 'moved') return tkcliRefused(p, ctx, res);
  return tkcliMoved(p, ctx, 'moved', id, res);
}

function tkcliHelp(p, ctx) {
  const name = p.positionals[0];
  if (name === undefined) {
    ctx.rt.out(tkcliHelpText(ctx));
    return 0;
  }
  if (!Object.hasOwn(TICKETS_COMMANDS, name)) throw tkcliError(ctx, `unknown tickets subcommand ${JSON.stringify(name)}`, 'help');
  ctx.rt.out(tkcliCommandHelp(ctx, name));
  return 0;
}

const TKCLI_HANDLERS = Object.freeze({
  check: tkcliCheck,
  write: tkcliWrite,
  status: tkcliStatus,
  show: tkcliShow,
  brief: tkcliBrief,
  new: tkcliNew,
  'next-id': tkcliNextId,
  freeze: tkcliFreeze,
  close: tkcliClose,
  archive: tkcliArchive,
  move: tkcliMove,
  help: tkcliHelp,
});

/**
 * Runs `tickets <subcommand> …`.
 *
 * @param {string[]} rest the tokens after `tickets`
 * @param {{ rt: { cwd: string, script: string, out(line: string): unknown, err(line: string): unknown },
 *   flags: Map<string, unknown>, commonFlags: readonly string[],
 *   commandLine: (args: string[], flags: Map<string, unknown>) => string }} ctx
 *   `flags` are the common flags given before `tickets`; `commandLine` prints a fix (KD-8)
 * @returns {Promise<0 | 1 | 2>}
 * @throws {UsageError} with `usageLine`, for every usage error
 */
async function ticketsMain(rest, ctx) {
  const p = tkcliParse(rest, ctx);
  if (p.sub === null) {
    ctx.rt.err(tkcliHelpText(ctx));
    return 2;
  }
  return TKCLI_HANDLERS[p.sub](p, ctx);
}

// --- core/locate.js ---
// Delivery logic: the first-line header of dist/ and of the vendored copy, semver comparison,
// locating the installed plugin (KD-3), the vendor target and content, and the doctor report.

// dist line 1: // plan-register <version> · schema <schema> · built from lift-planning core/ — do not edit
// copy line 1: // plan-register <version> · schema <schema> · vendored from lift-planning@<sha|v<version>> · do not edit; run "plan-register vendor"
const HEADER_RE = /^\/\/ plan-register (\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?) · schema (plan-register\/\d+) · (.*)$/;

const LOCATE_DIST_TAIL = 'built from lift-planning core/ — do not edit';
const LOCATE_COPY_TAIL_RE = /^vendored from lift-planning@(\S+) · do not edit; run "plan-register vendor"$/;
const LOCATE_SEMVER_RE = /^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?$/;
const LOCATE_PLUGIN_NAME = 'lift-planning';
const LOCATE_DIST_REL = ['dist', 'plan-register.mjs'];
// The plugin's JSON Schema; `vendor` copies it to DEFAULTS.schemaCopyPath of the project.
const LOCATE_SCHEMA_REL = ['schema', 'plan-register-1.schema.json'];
const LOCATE_LEVEL_RANK = Object.freeze({ note: 0, warn: 1, error: 2 });

// Parses the first line of a dist file or a vendored copy (CRLF tolerated).
// → { version, schema, vendoredFrom: string | null } | null (any other text).
function parseHeader(text) {
  if (typeof text !== 'string') return null;
  const nl = text.indexOf('\n');
  const line = (nl === -1 ? text : text.slice(0, nl)).replace(/\r$/, '');
  const m = HEADER_RE.exec(line);
  if (!m) return null;
  if (m[3] === LOCATE_DIST_TAIL) return { version: m[1], schema: m[2], vendoredFrom: null };
  const c = LOCATE_COPY_TAIL_RE.exec(m[3]);
  if (c) return { version: m[1], schema: m[2], vendoredFrom: c[1] };
  return null;
}

function distHeader({ version, schema }) {
  return `// plan-register ${version} · schema ${schema} · ${LOCATE_DIST_TAIL}`;
}

// from = short git sha of the plugin, or `v${version}` when the sha is unknown.
function copyHeader({ version, schema, from }) {
  return `// plan-register ${version} · schema ${schema} · vendored from lift-planning@${from} · do not edit; run "plan-register vendor"`;
}

function locateSemverParts(v) {
  const m = typeof v === 'string' ? LOCATE_SEMVER_RE.exec(v) : null;
  if (!m) throw new Error(`not a semver version: ${JSON.stringify(v)}`);
  return { core: [Number(m[1]), Number(m[2]), Number(m[3])], pre: m[4] === undefined ? [] : m[4].split('.') };
}

function locateCompareIdent(a, b) {
  const an = /^\d+$/.test(a);
  const bn = /^\d+$/.test(b);
  if (an && bn) return Math.sign(Number(a) - Number(b));
  if (an) return -1;
  if (bn) return 1;
  return a < b ? -1 : a > b ? 1 : 0;
}

// Semver 2.0.0 precedence (build metadata is not accepted). → -1 | 0 | 1; throws on a non-semver string.
function compareSemver(a, b) {
  const pa = locateSemverParts(a);
  const pb = locateSemverParts(b);
  for (let i = 0; i < 3; i++) {
    if (pa.core[i] !== pb.core[i]) return pa.core[i] < pb.core[i] ? -1 : 1;
  }
  if (pa.pre.length === 0 || pb.pre.length === 0) {
    if (pa.pre.length === pb.pre.length) return 0;
    return pa.pre.length === 0 ? 1 : -1;
  }
  const n = Math.min(pa.pre.length, pb.pre.length);
  for (let i = 0; i < n; i++) {
    const c = locateCompareIdent(pa.pre[i], pb.pre[i]);
    if (c !== 0) return c;
  }
  return Math.sign(pa.pre.length - pb.pre.length);
}

function locateIsSemver(v) {
  return typeof v === 'string' && LOCATE_SEMVER_RE.test(v);
}

function locateReaddir(dir) {
  try {
    return readdirSync(dir, { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name).sort();
  } catch {
    return [];
  }
}

// <home>/.claude/plugins/cache/<marketplace>/lift-planning/<version>, highest version first.
// Directory names that are not semver versions come last, in name order.
function locateClaudeCacheEntries(home) {
  const cache = join(home, '.claude', 'plugins', 'cache');
  const entries = [];
  for (const marketplace of locateReaddir(cache)) {
    const base = join(cache, marketplace, LOCATE_PLUGIN_NAME);
    for (const version of locateReaddir(base)) entries.push({ version, dir: join(base, version) });
  }
  entries.sort((x, y) => {
    const xs = locateIsSemver(x.version);
    const ys = locateIsSemver(y.version);
    if (xs && ys) return compareSemver(y.version, x.version) || (x.dir < y.dir ? -1 : 1);
    if (xs !== ys) return xs ? -1 : 1;
    return x.dir < y.dir ? -1 : 1;
  });
  return entries.map((e) => e.dir);
}

// Candidate plugin directories in KD-3 order:
// explicit (--plugin-root) → env (LIFT_PLANNING_ROOT) → <home>/.gemini/config/plugins/lift-planning
// → <home>/.gemini/antigravity-cli/plugins/lift-planning → <home>/.claude/plugins/cache/*/lift-planning/*
// (expanded by readdir, highest version first). Empty or missing inputs are skipped.
function pluginCandidates({ explicit, env, home } = {}) {
  const list = [];
  if (explicit) list.push(resolve(explicit));
  if (env) list.push(resolve(env));
  if (home) {
    list.push(join(home, '.gemini', 'config', 'plugins', LOCATE_PLUGIN_NAME));
    list.push(join(home, '.gemini', 'antigravity-cli', 'plugins', LOCATE_PLUGIN_NAME));
    list.push(...locateClaudeCacheEntries(home));
  }
  return list;
}

function locateReadManifest(dir) {
  // The Antigravity manifest sits at the root; a Claude Code install also carries .claude-plugin/plugin.json.
  for (const rel of [['plugin.json'], ['.claude-plugin', 'plugin.json']]) {
    let parsed;
    try {
      parsed = JSON.parse(readFileSync(join(dir, ...rel), 'utf8'));
    } catch {
      continue;
    }
    if (parsed && typeof parsed === 'object' && parsed.name === LOCATE_PLUGIN_NAME) return parsed;
  }
  return null;
}

// A plugin root has plugin.json (or .claude-plugin/plugin.json) with name "lift-planning" and dist/plan-register.mjs.
function isPluginRoot(dir) {
  if (typeof dir !== 'string' || dir === '') return false;
  return locateReadManifest(dir) !== null && existsSync(join(dir, ...LOCATE_DIST_REL));
}

// The first candidate (pluginCandidates order) that is a plugin root; an invalid candidate is skipped.
// version = plugin.json `version`; when it is absent or not semver, the version in the dist header; else null.
// → { root, version } | null
function findPluginRoot({ explicit, env, home } = {}) {
  for (const dir of pluginCandidates({ explicit, env, home })) {
    if (!isPluginRoot(dir)) continue;
    const manifest = locateReadManifest(dir);
    let version = locateIsSemver(manifest.version) ? manifest.version : null;
    if (version === null) {
      let header = null;
      try {
        header = parseHeader(readFileSync(join(dir, ...LOCATE_DIST_REL), 'utf8'));
      } catch {
        header = null;
      }
      version = header ? header.version : null;
    }
    return { root: dir, version };
  }
  return null;
}

// Absolute path of the plugin's JSON Schema file.
function pluginSchemaPath(pluginRoot) {
  return join(resolve(pluginRoot), ...LOCATE_SCHEMA_REL);
}

// Whether `dir` or a directory above it holds `.git` (a directory, or a file in a worktree or submodule).
// Only the file system is looked at; no git binary is needed.
function insideGitRepository(dir) {
  let d = resolve(dir);
  for (;;) {
    if (existsSync(join(d, '.git'))) return true;
    const up = dirname(d);
    if (up === d) return false;
    d = up;
  }
}

// Absolute path of the vendored copy: <repoRoot>/<to>/plan-register.mjs. `to` may be relative to repoRoot or absolute,
// but must resolve inside repoRoot.
function vendorTarget({ repoRoot, to = 'scripts' }) {
  const root = resolve(repoRoot);
  const dir = resolve(root, to);
  const rel = relative(root, dir);
  if (rel === '..' || rel.startsWith('..' + '/') || rel.startsWith('..' + '\\') || isAbsolute(rel)) {
    throw new Error(`vendor writes only inside the current repository: ${to}`);
  }
  return join(dir, 'plan-register.mjs');
}

// The copy content: dist text with line 1 replaced by copyHeader (version and schema taken from the dist header).
// CRLF is written as LF.
function vendoredContent(distText, from) {
  const header = parseHeader(distText);
  if (!header) throw new Error('dist file has no plan-register header on line 1');
  const text = distText.replace(/\r\n/g, '\n');
  const nl = text.indexOf('\n');
  const rest = nl === -1 ? '' : text.slice(nl);
  return copyHeader({ version: header.version, schema: header.schema, from }) + rest;
}

/**
 * Builds the doctor report. Input (every part may be null/undefined to skip its checks):
 *   copy:     { path: string, text: string | null }   path as printed (repo-relative); text = file content,
 *                                                       null when the file does not exist (→ copy-missing).
 *                                                       Only the plugin's doctor can see a missing copy.
 *   plugin:   { root: string, version: string | null } | null   result of findPluginRoot (null → plugin-not-found).
 *   register: { path: string, exists: boolean, schema: string | null, problemCount: number | null }
 *             schema = the register's `schema` field (null when unreadable); problemCount = number of check
 *             problems (null when check was not run).
 *   schemaCopy: { path: string, text: string | null, expected: string | null } | null
 *             the project copy of the JSON Schema (path as printed; text null when missing) and the plugin's
 *             schema text (expected; null when unreadable). Compared only when the plugin is known and
 *             expected is a string: missing → schema-copy-missing, other bytes → schema-copy-differs (warn).
 *   tickets:  { path: string, invalid: string | null, problemCount: number | null, command: string } | null
 *             only when the tickets config exists: `invalid` = the first TV1 message when the config or its
 *             register cannot be used (→ tickets-config-invalid), else `problemCount` = the number of
 *             ticket problems (→ tickets-problems when > 0); `command` = the line that runs the check.
 *             Both are warnings, never errors.
 *   supportedSchemas: schemas the running code reads (default SUPPORTED_SCHEMAS).
 * Output: { level: 'ok'|'warn'|'error', items: { level: 'note'|'warn'|'error', code, message }[] }
 * level = the worst item level, where a note counts as ok.
 */
function doctorReport({ copy, plugin, register, schemaCopy, tickets, supportedSchemas = SUPPORTED_SCHEMAS } = {}) {
  const items = [];
  const add = (level, code, message) => items.push({ level, code, message });
  let copyVersion = null;
  if (copy) {
    if (copy.text === null || copy.text === undefined) {
      add('error', 'copy-missing', `${copy.path} not found; run: node ${plugin && plugin.root ? plugin.root : '<plugin>'}/dist/plan-register.mjs vendor`);
    } else {
      const header = parseHeader(copy.text);
      if (!header) add('error', 'copy-header-unreadable', `${copy.path}: line 1 is not a plan-register header; run "plan-register vendor"`);
      else copyVersion = header.version;
    }
  }
  if (!plugin) {
    add('note', 'plugin-not-found', 'lift-planning plugin not found (use --plugin-root or LIFT_PLANNING_ROOT); copy version not compared');
  } else if (copy && copyVersion !== null && locateIsSemver(plugin.version)) {
    const c = compareSemver(copyVersion, plugin.version);
    if (c < 0) add('warn', 'copy-older', `${copy.path} is ${copyVersion}, the plugin at ${plugin.root} is ${plugin.version}; run: node ${plugin.root}/dist/plan-register.mjs vendor`);
    if (c > 0) add('note', 'copy-newer', `${copy.path} is ${copyVersion}, newer than the plugin at ${plugin.root} (${plugin.version})`);
  }
  if (plugin && schemaCopy && typeof schemaCopy.expected === 'string') {
    const vendor = `run: node ${plugin.root}/dist/plan-register.mjs vendor`;
    if (schemaCopy.text === null || schemaCopy.text === undefined) {
      add('warn', 'schema-copy-missing', `${schemaCopy.path} not found; ${vendor}`);
    } else if (schemaCopy.text !== schemaCopy.expected) {
      add('warn', 'schema-copy-differs', `${schemaCopy.path} differs from the plugin's ${LOCATE_SCHEMA_REL.join('/')}; ${vendor}`);
    }
  }
  if (register) {
    if (!register.exists) {
      add('error', 'register-missing', `${register.path} not found`);
    } else if (typeof register.schema !== 'string' || !supportedSchemas.includes(register.schema)) {
      const shown = typeof register.schema === 'string' ? JSON.stringify(register.schema) : 'missing or unreadable';
      add('error', 'schema-unsupported', `${register.path}: schema ${shown} is not supported (supported: ${supportedSchemas.join(', ')})`);
    } else if (typeof register.problemCount === 'number' && register.problemCount > 0) {
      add('warn', 'check-problems', `${register.path}: ${register.problemCount} problem(s); run check`);
    }
  }
  if (tickets) {
    if (typeof tickets.invalid === 'string') {
      add('warn', 'tickets-config-invalid', `${tickets.path}: ${tickets.invalid}; run: ${tickets.command}`);
    } else if (typeof tickets.problemCount === 'number' && tickets.problemCount > 0) {
      add('warn', 'tickets-problems', `${tickets.problemCount} ticket problem(s); run: ${tickets.command}`);
    }
  }
  let rank = 0;
  for (const item of items) rank = Math.max(rank, LOCATE_LEVEL_RANK[item.level]);
  return { level: rank === 2 ? 'error' : rank === 1 ? 'warn' : 'ok', items };
}

// Text lines for a doctor report: `<level> <code>: <message>` per item, then `plan-register doctor: <level>`.
// quiet → only warn and error items, no summary line (empty when nothing needs attention).
function doctorLines(report, { quiet = false } = {}) {
  const shown = quiet ? report.items.filter((i) => i.level !== 'note') : report.items;
  const lines = shown.map((i) => `${i.level} ${i.code}: ${i.message}`);
  if (!quiet) lines.push(`plan-register doctor: ${report.level}`);
  return lines;
}

// --- core/cli.js ---
// The `plan-register` command line: argument parsing (no libraries), output and exit codes.
//
// Exit codes: 0 success · 1 problems, refused change, unknown unit, environment error · 2 usage error
// (unknown command or flag, missing or extra argument, bad flag value; also every UsageError thrown by
// the core). Usage errors print `plan-register: <message>` and `usage: …` on stderr.
//
// `COMMANDS` is the single table of commands, their arguments and their own flags; the skill linter and
// the docs test read it. The flags every command accepts (`--root <dir>`, `--register <path>`) are
// listed once, in `COMMON_FLAGS`, and are not repeated in `COMMANDS`. Common flags may come before the
// command (`plan-register --root <dir> check`) or after it. A flag value is given as `--flag value` or
// `--flag=value`.
//
// The repository root (KD-2): `--root`, else the first directory from the working directory upwards
// that contains the register path (`--register`, default docs/plans/register.json). Paths given as
// arguments (plans, TODO notes, `--copy`, `--to`) are repository-relative; only `show --brief <file>`
// is relative to the working directory.
//
// A ready-made fix (KD-8) is printed as `node <script> <args…>`, where <script> is the file that is
// actually running: relative to the working directory when it lies inside it, else absolute.

/** Flags accepted by every command (listed once; not repeated in COMMANDS). */
const COMMON_FLAGS = Object.freeze(['--root', '--register']);

/**
 * The commands: positional arguments (`[<x>]` = optional), the command's own flags (without
 * COMMON_FLAGS), the flags among them that must be given (`required`, shown without brackets) and a
 * one-line summary.
 */
const COMMANDS = Object.freeze({
  check: Object.freeze({
    args: Object.freeze([]),
    flags: Object.freeze(['--json']),
    required: Object.freeze([]),
    summary: 'Check the register (V1–V11, V13) and that every generated region is current (V12).',
  }),
  write: Object.freeze({
    args: Object.freeze([]),
    flags: Object.freeze([]),
    required: Object.freeze([]),
    summary: 'Regenerate every region; writes nothing while the register has problems.',
  }),
  render: Object.freeze({
    args: Object.freeze(['[<view>]']),
    flags: Object.freeze([]),
    required: Object.freeze([]),
    summary: 'Print every region, or one view (phases, units, order, todos), without writing.',
  }),
  status: Object.freeze({
    args: Object.freeze([]),
    flags: Object.freeze(['--json']),
    required: Object.freeze([]),
    summary: 'Counts by status, then the active, ready and blocked units.',
  }),
  show: Object.freeze({
    args: Object.freeze(['<key>']),
    flags: Object.freeze(['--json', '--brief', '--date']),
    required: Object.freeze([]),
    summary: 'One unit (key or alias): plans, TODO notes, decisions, readiness; --brief writes a scope brief.',
  }),
  next: Object.freeze({
    args: Object.freeze([]),
    flags: Object.freeze(['--json']),
    required: Object.freeze([]),
    summary: 'The units that are ready to start and the units in progress.',
  }),
  chain: Object.freeze({
    args: Object.freeze([]),
    flags: Object.freeze(['--json']),
    required: Object.freeze([]),
    summary: 'The longest dependency chain among the open units.',
  }),
  set: Object.freeze({
    args: Object.freeze(['<key>']),
    flags: Object.freeze(['--status', '--pr', '--no-pr', '--merge-sha', '--closed-by', '--title', '--phase', '--owner',
      '--depends-on', '--after', '--add-waits-on', '--remove-waits-on', '--add-decision', '--remove-decision',
      '--add-alias', '--write']),
    required: Object.freeze([]),
    summary: 'Change a unit (status, PR, closedBy, fields, dependencies); refused when it adds a problem.',
  }),
  'add-unit': Object.freeze({
    args: Object.freeze(['<key>']),
    flags: Object.freeze(['--title', '--phase', '--owner', '--kind', '--depends-on', '--after', '--waits-on', '--alias',
      '--decision', '--insert-after', '--write']),
    required: Object.freeze(['--title']),
    summary: 'Add a unit (status Not started); refused when it adds a problem.',
  }),
  'add-plan': Object.freeze({
    args: Object.freeze(['<key>', '<path>']),
    flags: Object.freeze(['--section', '--role', '--scope', '--replace', '--keep-source', '--source-doc', '--write']),
    required: Object.freeze([]),
    summary: 'Register a plan for a unit; an executable plan gets its **Source:** line naming the key.',
  }),
  'home-todo': Object.freeze({
    args: Object.freeze(['<todo>', '[<key>]']),
    flags: Object.freeze(['--move', '--replace', '--unhomed', '--write']),
    required: Object.freeze([]),
    summary: 'Give a TODO note a home in a unit, or list it as unhomed with a reason.',
  }),
  vendor: Object.freeze({
    args: Object.freeze([]),
    flags: Object.freeze(['--to']),
    required: Object.freeze([]),
    summary: 'Copy the plugin CLI into the repository (default scripts/plan-register.mjs); run from the plugin.',
  }),
  version: Object.freeze({
    args: Object.freeze([]),
    flags: Object.freeze(['--json']),
    required: Object.freeze([]),
    summary: 'Print the tool version and the register schema it reads.',
  }),
  doctor: Object.freeze({
    args: Object.freeze([]),
    flags: Object.freeze(['--quiet', '--json', '--plugin-root', '--copy']),
    required: Object.freeze([]),
    summary: 'Check the vendored copy, the installed plugin and the register; --quiet prints only warnings and errors.',
  }),
  help: Object.freeze({
    args: Object.freeze(['[<command>]']),
    flags: Object.freeze([]),
    required: Object.freeze([]),
    summary: 'Show the commands, or the usage of one command.',
  }),
  tickets: Object.freeze({
    args: Object.freeze(['<subcommand>', '[<args>…]']),
    flags: Object.freeze([]),
    required: Object.freeze([]),
    summary: 'Work-item tickets (schema tickets/1): check, write, status, show, brief, new, next-id, freeze, close, archive, move, help; run "tickets help".',
  }),
});

// How each flag is read: `bool` (no value), `value` (once), `repeat` (may be given several times),
// `csv` (comma-separated keys, may be repeated; "" gives an empty list). `meta` is the value name in usage.
const CLI_FLAG_SPECS = Object.freeze({
  '--root': { kind: 'value', meta: '<dir>' },
  '--register': { kind: 'value', meta: '<path>' },
  '--json': { kind: 'bool' },
  '--brief': { kind: 'value', meta: '<file|->' },
  '--date': { kind: 'value', meta: 'YYYY-MM-DD' },
  '--status': { kind: 'value', meta: '<status>' },
  '--pr': { kind: 'value', meta: '<n>' },
  '--no-pr': { kind: 'bool' },
  '--merge-sha': { kind: 'value', meta: '<sha>' },
  '--closed-by': { kind: 'value', meta: '<text>' },
  '--title': { kind: 'value', meta: '<text>' },
  '--phase': { kind: 'value', meta: '<phase>' },
  '--owner': { kind: 'value', meta: '<owner>' },
  '--kind': { kind: 'value', meta: '<delivery|gate>' },
  '--depends-on': { kind: 'csv', meta: '<key[,key…]>' },
  '--after': { kind: 'csv', meta: '<key[,key…]>' },
  '--add-waits-on': { kind: 'repeat', meta: '<kind:ref[:note]>' },
  '--remove-waits-on': { kind: 'repeat', meta: '<ref>' },
  '--add-decision': { kind: 'repeat', meta: '<id>' },
  '--remove-decision': { kind: 'repeat', meta: '<id>' },
  '--add-alias': { kind: 'repeat', meta: '<alias>' },
  '--waits-on': { kind: 'repeat', meta: '<kind:ref[:note]>' },
  '--alias': { kind: 'repeat', meta: '<alias>' },
  '--decision': { kind: 'repeat', meta: '<id>' },
  '--insert-after': { kind: 'value', meta: '<key>' },
  '--section': { kind: 'value', meta: '<section>' },
  '--role': { kind: 'value', meta: '<brief|executable|scope>' },
  '--scope': { kind: 'value', meta: '<text>' },
  '--replace': { kind: 'value', meta: '<old path>' },
  '--keep-source': { kind: 'bool' },
  '--source-doc': { kind: 'value', meta: '<doc>' },
  '--move': { kind: 'bool' },
  '--unhomed': { kind: 'value', meta: '<reason>' },
  '--to': { kind: 'value', meta: '<dir>' },
  '--quiet': { kind: 'bool' },
  '--plugin-root': { kind: 'value', meta: '<dir>' },
  '--copy': { kind: 'value', meta: '<path>' },
  '--write': { kind: 'bool' },
});

const CLI_VENDOR_REFUSAL = 'vendor must be run from the lift-planning plugin: node <plugin>/dist/plan-register.mjs vendor';
const CLI_DIFF_LINES = 20;

/** A UsageError that remembers the command for the usage line. */
function cliUsageError(message, command) {
  const e = new UsageError(message);
  e.command = command;
  return e;
}

function cliIsFlag(token) {
  return typeof token === 'string' && token.length > 1 && token.startsWith('-');
}

/** One shell-safe argument: bare when it has only safe characters, else in double quotes. */
function cliArg(text) {
  const s = String(text);
  if (/^[A-Za-z0-9._/:=@+,-]+$/.test(s)) return s;
  // (No template literal here: the bundler's scanner does not read a backtick inside a regex in ${…}.)
  const escaped = s.replace(/(["\\$\x60])/g, '\\$1');
  return '"' + escaped + '"';
}

/** The synopsis of a command: `show <key> [--json] [--brief <file|->] …` (common flags included). */
function cliSynopsis(name) {
  const c = COMMANDS[name];
  const flag = (f) => {
    const spec = CLI_FLAG_SPECS[f];
    const shown = spec.kind === 'bool' ? f : `${f} ${spec.meta}`;
    const body = c.required.includes(f) ? shown : `[${shown}]`;
    return `${body}${spec.kind === 'repeat' ? '…' : ''}`;
  };
  const flags = [...c.required, ...c.flags.filter((f) => !c.required.includes(f))];
  return [name, ...c.args, ...flags.map(flag), ...COMMON_FLAGS.map(flag)].join(' ');
}

/** `usage: …` for a command, or the general usage line. */
function cliUsageLine(rt, command) {
  if (command !== undefined && command !== null && Object.hasOwn(COMMANDS, command)) {
    return `usage: node ${rt.script} ${cliSynopsis(command)}`;
  }
  return `usage: node ${rt.script} <command> [<args>] [--root <dir>] [--register <path>] (run "node ${rt.script} help")`;
}

/** The full help text. */
function cliHelpText(rt) {
  const lines = [
    `plan-register ${VERSION} (schema ${SCHEMA}): the delivery-unit register CLI`,
    '',
    `usage: node ${rt.script} <command> [<args>] [<flags>]`,
    '',
    'Commands:',
  ];
  const width = Math.max(...Object.keys(COMMANDS).map((n) => n.length));
  for (const [name, c] of Object.entries(COMMANDS)) lines.push(`  ${name.padEnd(width)}  ${c.summary}`);
  lines.push(
    '',
    'Flags of every command:',
    '  --root <dir>        repository root (default: the first directory upwards that contains the register)',
    `  --register <path>   register path relative to the root (default ${DEFAULTS.registerPath})`,
    '',
    'Exit codes: 0 ok · 1 problems or refused · 2 usage error.',
    `Run "node ${rt.script} help <command>" for the flags of one command.`,
  );
  return lines.join('\n');
}

/** The help of one command. */
function cliCommandHelp(rt, name) {
  const c = COMMANDS[name];
  const lines = [`usage: node ${rt.script} ${cliSynopsis(name)}`, '', c.summary];
  const flags = [...c.flags, ...COMMON_FLAGS];
  if (flags.length > 0) {
    lines.push('', 'Flags:');
    for (const f of flags) {
      const spec = CLI_FLAG_SPECS[f];
      const repeat = spec.kind === 'repeat' ? ' (repeatable)' : spec.kind === 'csv' ? ' (comma-separated; "" clears)' : '';
      const required = c.required.includes(f) ? ' (required)' : '';
      lines.push(`  ${spec.kind === 'bool' ? f : `${f} ${spec.meta}`}${required}${repeat}`);
    }
  }
  return lines.join('\n');
}

/** Reads one flag at argv[i] into `flags`; returns the index of the next token. */
function cliTakeFlag(argv, i, allowed, flags, command) {
  const token = argv[i];
  const eq = token.indexOf('=');
  const name = eq === -1 ? token : token.slice(0, eq);
  const inline = eq === -1 ? undefined : token.slice(eq + 1);
  if (!allowed.includes(name) || !Object.hasOwn(CLI_FLAG_SPECS, name)) {
    throw cliUsageError(`unknown flag ${name}${command === null ? '' : ` for ${command}`}`, command);
  }
  const spec = CLI_FLAG_SPECS[name];
  if (spec.kind === 'bool') {
    if (inline !== undefined) throw cliUsageError(`${name} takes no value`, command);
    flags.set(name, true);
    return i + 1;
  }
  let value = inline;
  let next = i + 1;
  if (value === undefined) {
    if (i + 1 >= argv.length || cliIsFlag(argv[i + 1])) throw cliUsageError(`${name} needs a value ${spec.meta}`, command);
    value = argv[i + 1];
    next = i + 2;
  }
  if (spec.kind === 'value') {
    if (flags.has(name)) throw cliUsageError(`${name} is given more than once`, command);
    flags.set(name, value);
  } else if (spec.kind === 'repeat') {
    flags.set(name, [...(flags.get(name) ?? []), value]);
  } else {
    const keys = value.split(',').map((k) => k.trim()).filter((k) => k !== '');
    flags.set(name, [...(flags.get(name) ?? []), ...keys]);
  }
  return next;
}

/**
 * Parses argv into `{ command, positionals, flags }`. Common flags may precede the command.
 *
 * @throws {UsageError}
 */
function cliParse(argv) {
  const flags = new Map();
  const positionals = [];
  let command = null;
  let i = 0;
  while (i < argv.length) {
    const token = argv[i];
    if (cliIsFlag(token)) {
      const allowed = command === null ? COMMON_FLAGS : [...COMMANDS[command].flags, ...COMMON_FLAGS];
      i = cliTakeFlag(argv, i, allowed, flags, command);
    } else if (command === null) {
      if (!Object.hasOwn(COMMANDS, token)) throw cliUsageError(`unknown command ${JSON.stringify(token)}`, null);
      command = token;
      i += 1;
      // `tickets` parses its own subcommands and flags (core/tickets/cli.js): keep the rest as it is.
      if (command === 'tickets') return { command, positionals, flags, rest: argv.slice(i) };
    } else {
      positionals.push(token);
      i += 1;
    }
  }
  if (command !== null) {
    const args = COMMANDS[command].args;
    const required = args.filter((a) => !a.startsWith('['));
    if (positionals.length < required.length) {
      throw cliUsageError(`missing argument ${required[positionals.length]}`, command);
    }
    if (positionals.length > args.length) {
      throw cliUsageError(`unexpected argument ${JSON.stringify(positionals[args.length])}`, command);
    }
  }
  return { command, positionals, flags };
}

/** How a path is shown: relative to `cwd` (POSIX) when inside it, else absolute. */
function cliDisplayPath(abs, cwd) {
  const rel = relative(resolve(cwd), abs);
  if (rel === '' || rel === '..' || rel.startsWith(`..${sep}`) || isAbsolute(rel)) return abs;
  return rel.split(sep).join('/');
}

/** The register path of the run (`--register` or the default). */
function cliRegisterPath(p) {
  const v = p.flags.get('--register');
  return typeof v === 'string' && v !== '' ? v : DEFAULTS.registerPath;
}

/** The register path as messages show it. */
function cliRegisterLabel(root, registerPath) {
  if (!isAbsolute(registerPath)) return normalizePath(registerPath) ?? registerPath;
  return cliDisplayPath(registerPath, root);
}

/** The repository root (KD-2); throws an Error when no register is found upwards. */
function cliRoot(p, rt) {
  return resolveRoot({ cwd: rt.cwd, root: p.flags.get('--root'), registerPath: cliRegisterPath(p) });
}

/** A command line of this script: `node <script> <args…>` (plus `--register` when it is not the default). */
function cliCommandLine(rt, p, args) {
  const extra = p.flags.has('--register') && cliRegisterPath(p) !== DEFAULTS.registerPath
    ? ['--register', cliRegisterPath(p)] : [];
  return ['node', rt.script, ...[...args, ...extra].map(cliArg)].join(' ');
}

/**
 * Prints problems in the check format: header, one line per problem, its fix and diff hint. An
 * informational entry (`info: true`, the V12 "regions not checked" line) is not counted in the header
 * and is printed after the list as `note: [V12] <where>: <message>`.
 */
function cliPrintProblems(rt, p, label, problems) {
  const counted = problems.filter((pr) => pr.info !== true);
  rt.err(`${label}: ${counted.length} problem(s)`);
  for (const pr of counted) {
    rt.err(`  - [${pr.rule}] ${pr.where}: ${pr.message}`);
    if (Array.isArray(pr.fix)) rt.err(`      fix: ${cliCommandLine(rt, p, pr.fix)}`);
    if (typeof pr.diff === 'string' && pr.diff !== '') {
      const lines = pr.diff.split('\n');
      for (const l of lines.slice(0, CLI_DIFF_LINES)) rt.err(`      ${l}`);
      if (lines.length > CLI_DIFF_LINES) rt.err(`      … ${lines.length - CLI_DIFF_LINES} more line(s)`);
    }
  }
  for (const pr of problems) {
    if (pr.info === true) rt.err(`note: [${pr.rule}] ${pr.where}: ${pr.message}`);
  }
}

function cliJson(rt, value) {
  rt.out(JSON.stringify(value, null, 2));
}

/** The query context of the run (throws an Error when the register cannot be read). */
function cliContext(p, rt) {
  const root = cliRoot(p, rt);
  return queryContext(root, { registerPath: cliRegisterPath(p) });
}

/** Problems other than V12 (the ones that keep regions from being rendered or written). */
function cliBlockingProblems(problems) {
  return problems.filter((pr) => pr.rule !== 'V12' || pr.info === true);
}

/**
 * The tickets part of top-level `check` and `write` (only with the default tickets config, so a
 * repository without it gets the 0.1.1 output byte for byte): null without the config; `{ note }`
 * when the config names another register than the one the run reads; else `{ result }` (checkTickets).
 */
function cliTicketsPart(rt, root, registerPath) {
  if (!existsSync(resolve(root, ...TICKETS_CONFIG_PATH.split('/')))) return null;
  const result = checkTickets(root);
  const own = cliRegisterLabel(root, registerPath);
  if (result.register !== null && result.register.registerPath !== own) {
    return { note: `note: [TV1] ${TICKETS_CONFIG_PATH}: names register ${result.register.registerPath}; run: node ${rt.script} tickets check` };
  }
  return { result };
}

/** A tickets fix as a command line; a fix that names its register does not get `--register` twice. */
function cliTicketsFix(rt, p, args) {
  const flags = args.includes('--register') ? new Map([...p.flags].filter(([k]) => k !== '--register')) : p.flags;
  return cliCommandLine(rt, { flags }, args);
}

/** One block of tickets problems or warnings on stderr, in the check format (with region diff hints). */
function cliTicketsPrint(rt, p, header, list) {
  rt.err(header);
  for (const pr of list) {
    rt.err(`  - [${pr.rule}] ${pr.where}: ${pr.message}`);
    if (Array.isArray(pr.fix)) rt.err(`      fix: ${cliTicketsFix(rt, p, pr.fix)}`);
    if (typeof pr.diff === 'string' && pr.diff !== '') {
      const lines = pr.diff.split('\n');
      for (const l of lines.slice(0, CLI_DIFF_LINES)) rt.err(`      ${l}`);
      if (lines.length > CLI_DIFF_LINES) rt.err(`      … ${lines.length - CLI_DIFF_LINES} more line(s)`);
    }
  }
}

/** The tickets block of a text `check`: success line or problems, warnings, notes. Returns the exit code of the part. */
function cliTicketsBlock(rt, p, r) {
  const label = r.configPath;
  if (r.problems.length === 0) {
    const warned = r.warnings.length > 0 ? `; ${r.warnings.length} warning(s)` : '';
    rt.out(`plan-register: tickets valid; ${r.tickets} ticket(s), ${r.archived} archived; ${r.regions.length} region(s) current${warned}`);
  } else {
    cliTicketsPrint(rt, p, `${label}: ${r.problems.length} problem(s)`, r.problems);
  }
  if (r.warnings.length > 0) cliTicketsPrint(rt, p, `${label}: ${r.warnings.length} warning(s)`, r.warnings);
  for (const n of r.notes) rt.err(`note: [${n.rule}] ${n.where}: ${n.message}`);
  return r.problems.length === 0 ? 0 : 1;
}

async function cliCheck(p, rt) {
  const root = cliRoot(p, rt);
  const registerPath = cliRegisterPath(p);
  const result = checkRepo(root, { registerPath });
  const tickets = cliTicketsPart(rt, root, registerPath);
  if (p.flags.has('--json')) {
    const answer = checkJson(result, { fixText: (args) => cliCommandLine(rt, p, args) });
    if (tickets !== null && tickets.result !== undefined) {
      answer.tickets = ticketsCheckJson(tickets.result, { fixText: (args) => cliTicketsFix(rt, p, args) });
    } else if (tickets !== null) {
      // the config names another register: no tickets block, and the note that text mode prints on stderr
      answer.tickets = null;
      answer.ticketsNotes = [tickets.note];
    }
    cliJson(rt, answer);
    return answer.ok && (answer.tickets === undefined || answer.tickets === null || answer.tickets.ok) ? 0 : 1;
  }
  let code = 0;
  if (result.problems.every((pr) => pr.info === true)) {
    rt.out(`plan-register: register valid; ${result.regions.length} region(s) current`);
  } else {
    cliPrintProblems(rt, p, cliRegisterLabel(root, registerPath), result.problems);
    code = 1;
  }
  if (tickets === null) return code;
  if (tickets.note !== undefined) {
    rt.err(tickets.note);
    return code;
  }
  return Math.max(code, cliTicketsBlock(rt, p, tickets.result));
}

/**
 * Whether the tickets part of a top-level `write` refuses (§1.4): a TV1-TV3 or V13 problem or an
 * unreadable register. Prints the problems and the refusal; asked before any region is written.
 */
function cliTicketsRefuses(rt, p, r) {
  const blocking = ticketsBlocking(r.problems);
  if (blocking.length === 0 && r.model !== null && r.model.state !== null) return false;
  if (blocking.length > 0) cliTicketsPrint(rt, p, `${r.configPath}: ${blocking.length} problem(s)`, blocking);
  rt.err('tickets regions not written');
  return true;
}

/** The tickets regions of a top-level `write`, after cliTicketsRefuses said no. */
function cliTicketsWrite(rt, p, root, r) {
  const w = writeTicketsRegions(root, ticketsRegionStates(r.config, r.model.tickets, r.model.state, r.configPath));
  if (!w.ok) {
    cliTicketsPrint(rt, p, `${r.configPath}: ${w.errors.length} problem(s)`, w.errors.map((e) => ({ rule: 'TV11', ...e })));
    rt.err('tickets regions not written');
    return 1;
  }
  for (const x of w.written) rt.out(`${x.file} (${x.marker}): ${x.changed ? 'updated' : 'already current'}`);
  return 0;
}

async function cliWrite(p, rt) {
  const root = cliRoot(p, rt);
  const registerPath = cliRegisterPath(p);
  const result = checkRepo(root, { registerPath });
  const blocking = result.problems.filter((pr) => !(pr.rule === 'V12' && pr.message === 'region is stale'));
  if (blocking.length > 0) {
    cliPrintProblems(rt, p, cliRegisterLabel(root, registerPath), blocking);
    rt.err('regions not written');
    return 1;
  }
  // a tickets refusal is known before any region is written: nothing is written then
  const tickets = cliTicketsPart(rt, root, registerPath);
  if (tickets !== null && tickets.result !== undefined && cliTicketsRefuses(rt, p, tickets.result)) return 1;
  for (const r of writeRegions(root, { registerPath })) {
    rt.out(`${r.file} (${r.marker}): ${r.changed ? 'updated' : 'already current'}`);
  }
  if (tickets === null) return 0;
  if (tickets.note !== undefined) {
    rt.err(tickets.note);
    return 0;
  }
  return cliTicketsWrite(rt, p, root, tickets.result);
}

async function cliRender(p, rt) {
  const ctx = cliContext(p, rt);
  const view = p.positionals[0];
  if (view !== undefined && !VIEWS.includes(view)) {
    throw cliUsageError(`unknown view ${JSON.stringify(view)} (views: ${VIEWS.join(', ')})`, 'render');
  }
  const blocking = cliBlockingProblems(ctx.problems);
  if (blocking.length > 0) {
    cliPrintProblems(rt, p, ctx.registerPath, blocking);
    rt.err('nothing rendered: fix the problems first');
    return 1;
  }
  const regions = (Array.isArray(ctx.data.config.regions) ? ctx.data.config.regions : [])
    .map((r) => ({ ...r, file: normalizePath(r.file) ?? r.file }));
  const todos = openTodos(ctx.data, ctx.fsv);
  const rctx = (linkFrom) => ({ linkFrom, progress: ctx.progress, openTodos: todos, registerPath: ctx.registerPath });
  if (view === undefined) {
    const blocks = regions.map((r) => `== ${r.file} (${r.marker}) ==\n${renderRegionContent(r, ctx.data, rctx(r.file))}`);
    rt.out(blocks.join('\n\n'));
    return 0;
  }
  const region = regions.find((r) => Array.isArray(r.views) && r.views.includes(view));
  rt.out(renderView(view, ctx.data, rctx(region === undefined ? ctx.registerPath : region.file)));
  return 0;
}

async function cliStatus(p, rt) {
  const ctx = cliContext(p, rt);
  if (p.flags.has('--json')) cliJson(rt, statusJson(ctx));
  else rt.out(statusText(ctx));
  return 0;
}

async function cliNext(p, rt) {
  const ctx = cliContext(p, rt);
  if (p.flags.has('--json')) cliJson(rt, nextJson(ctx));
  else rt.out(nextText(ctx));
  return 0;
}

async function cliChain(p, rt) {
  const ctx = cliContext(p, rt);
  if (p.flags.has('--json')) cliJson(rt, chainJson(ctx));
  else rt.out(chainText(ctx));
  return 0;
}

/** Resolves a key argument (alias note on stderr); an unknown unit throws the `unknown-unit` Error. */
function cliResolveKey(rt, data, name) {
  const r = resolveUnit({ data }, name);
  if (r.note !== null) rt.err(r.note);
  return r.key;
}

async function cliShow(p, rt) {
  if (p.flags.has('--json') && p.flags.has('--brief')) throw cliUsageError('--json and --brief cannot be used together', 'show');
  const ctx = cliContext(p, rt);
  const name = p.positionals[0];
  cliResolveKey(rt, ctx.data, name);
  const date = p.flags.get('--date');
  if (p.flags.has('--json')) {
    cliJson(rt, showJson(ctx, name, { date }));
    return 0;
  }
  if (p.flags.has('--brief')) {
    const target = p.flags.get('--brief');
    const md = briefMarkdown(ctx, name, { date, scriptPath: rt.script, registerPath: cliRegisterPath(p) });
    if (target === '-') {
      rt.write(md);
      return 0;
    }
    const abs = resolve(rt.cwd, target);
    mkdirSync(dirname(abs), { recursive: true });
    writeFileSync(abs, md);
    rt.out(`brief written to ${cliDisplayPath(abs, rt.cwd)}`);
    return 0;
  }
  rt.out(showText(ctx, name, { date }));
  return 0;
}

/**
 * Runs a change through the transaction (KD-7) and prints the result. `keyNames` (unit arguments to
 * resolve first, for the alias note and the unknown-unit message, exit 1) may be empty.
 */
function cliMutate(p, rt, keyNames, fn) {
  const root = cliRoot(p, rt);
  const registerPath = cliRegisterPath(p);
  const write = p.flags.has('--write');
  if (keyNames.length > 0) {
    const loaded = loadRegister(root, { registerPath });
    if (loaded.data !== null) for (const name of keyNames) cliResolveKey(rt, loaded.data, name);
  }
  const res = applyMutation(root, { registerPath, write }, fn);
  if (res.newProblems.length > 0) {
    cliPrintProblems(rt, p, cliRegisterLabel(root, registerPath), res.newProblems);
    rt.err('refused: the register was not changed');
    return 1;
  }
  for (const c of res.changes) rt.out(c);
  if (res.changes.length === 0 && !res.written) rt.out('nothing changed');
  if (write) {
    if (res.regions === null || res.regions === undefined) {
      rt.err(`regions not updated: ${res.problems.length} problem(s) remain; run: ${cliCommandLine(rt, p, ['check'])}`);
    } else {
      for (const r of res.regions) rt.out(`${r.file} (${r.marker}): ${r.changed ? 'updated' : 'already current'}`);
    }
  } else if (res.written) {
    rt.out(`regions not updated; run: ${cliCommandLine(rt, p, ['write'])}`);
  }
  return 0;
}

/** The options object of the given flags: `{ optName: flagValue }` for each flag that was passed. */
function cliOptions(p, map) {
  const o = {};
  for (const [flag, opt] of Object.entries(map)) {
    if (p.flags.has(flag)) o[opt] = p.flags.get(flag);
  }
  return o;
}

async function cliSet(p, rt) {
  const key = p.positionals[0];
  const opts = cliOptions(p, {
    '--status': 'status', '--pr': 'pr', '--no-pr': 'noPr', '--merge-sha': 'mergeSha', '--closed-by': 'closedBy',
    '--title': 'title', '--phase': 'phase', '--owner': 'owner', '--depends-on': 'dependsOn', '--after': 'after',
    '--add-waits-on': 'addWaitsOn', '--remove-waits-on': 'removeWaitsOn', '--add-decision': 'addDecision',
    '--remove-decision': 'removeDecision', '--add-alias': 'addAlias',
  });
  return cliMutate(p, rt, [key], (data) => setUnit(data, key, opts));
}

async function cliAddUnit(p, rt) {
  const key = p.positionals[0];
  const opts = cliOptions(p, {
    '--title': 'title', '--phase': 'phase', '--owner': 'owner', '--kind': 'kind', '--depends-on': 'dependsOn',
    '--after': 'after', '--waits-on': 'waitsOn', '--alias': 'alias', '--decision': 'decision', '--insert-after': 'insertAfter',
  });
  // The new key is not resolved (it must not exist yet; V2 refuses a duplicate); --insert-after is.
  const names = typeof opts.insertAfter === 'string' && opts.insertAfter.trim() !== '' ? [opts.insertAfter.trim()] : [];
  return cliMutate(p, rt, names, (data) => addUnit(data, key, opts));
}

async function cliAddPlan(p, rt) {
  const key = p.positionals[0];
  const path = p.positionals[1];
  const opts = cliOptions(p, {
    '--section': 'section', '--role': 'role', '--scope': 'scope', '--replace': 'replace',
    '--keep-source': 'keepSource', '--source-doc': 'sourceDoc',
  });
  const fsv = createFsView(cliRoot(p, rt));
  return cliMutate(p, rt, [key], (data) => addPlan(data, key, path, { ...opts, readText: (x) => fsv.readText(x) }));
}

async function cliHomeTodo(p, rt) {
  const todo = p.positionals[0];
  const key = p.positionals.length > 1 ? p.positionals[1] : null;
  const opts = cliOptions(p, { '--move': 'move', '--unhomed': 'unhomed', '--replace': 'replace' });
  return cliMutate(p, rt, key === null ? [] : [key], (data) => homeTodo(data, todo, key, opts));
}

/** The real path of a file, or its resolved path when it cannot be resolved. */
function cliRealPath(path) {
  try {
    return realpathSync(path);
  } catch {
    return resolve(path);
  }
}

/** The plugin root when the running script is `<root>/dist/plan-register.mjs` of a plugin, else null. */
function cliRunningPluginRoot(rt) {
  if (rt.scriptAbs === null) return null;
  const file = cliRealPath(rt.scriptAbs);
  if (basename(file) !== 'plan-register.mjs' || basename(dirname(file)) !== 'dist') return null;
  const root = dirname(dirname(file));
  return isPluginRoot(root) ? root : null;
}

/** A file's text, or null when it cannot be read. */
function cliReadText(abs) {
  try {
    return readFileSync(abs, 'utf8');
  } catch {
    return null;
  }
}

async function cliVersion(p, rt) {
  const text = rt.scriptAbs === null ? null : cliReadText(rt.scriptAbs);
  if (p.flags.has('--json')) {
    cliJson(rt, versionJson({ header: text === null ? null : parseHeader(text) }));
    return 0;
  }
  rt.out(`plan-register ${VERSION} (schema ${SCHEMA})`);
  return 0;
}

/** The repository root for doctor and vendor: KD-2, falling back to --root or the working directory. */
function cliRootOrFallback(p, rt) {
  try {
    return { root: cliRoot(p, rt), found: true };
  } catch {
    const r = p.flags.get('--root');
    return { root: resolve(rt.cwd, typeof r === 'string' && r !== '' ? r : '.'), found: false };
  }
}

/**
 * The tickets input of `doctor`: null unless the default tickets config exists (a repository without it gets
 * the 0.1.1 report). The config or the register it names cannot be used → the first TV1 message; else the
 * number of ticket problems.
 */
function cliDoctorTickets(p, rt, root) {
  if (!existsSync(resolve(root, ...TICKETS_CONFIG_PATH.split('/')))) return null;
  const result = checkTickets(root);
  const unusable = result.config === null || result.model === null || result.model.state === null;
  const first = result.problems.find((pr) => pr.rule === 'TV1');
  return {
    path: TICKETS_CONFIG_PATH,
    invalid: unusable ? (first === undefined ? 'the tickets config cannot be used' : first.message) : null,
    problemCount: unusable ? null : result.problems.length,
    command: cliCommandLine(rt, p, ['tickets', 'check']),
  };
}

async function cliDoctor(p, rt) {
  const located = cliRootOrFallback(p, rt);
  const root = located.root;
  const registerPath = cliRegisterPath(p);
  const runningPlugin = cliRunningPluginRoot(rt);

  let copy = null;
  if (p.flags.has('--copy')) {
    const rel = p.flags.get('--copy');
    copy = { path: normalizePath(rel) ?? rel, text: cliReadText(resolve(root, rel)) };
  } else if (runningPlugin !== null) {
    copy = { path: DEFAULTS.scriptPath, text: cliReadText(resolve(root, DEFAULTS.scriptPath)) };
  } else if (rt.scriptAbs !== null) {
    const shown = cliDisplayPath(cliRealPath(rt.scriptAbs), cliRealPath(root));
    if (!isAbsolute(shown)) copy = { path: shown, text: cliReadText(rt.scriptAbs) };
  }

  const explicit = p.flags.get('--plugin-root') ?? runningPlugin ?? undefined;
  const plugin = findPluginRoot({
    explicit: typeof explicit === 'string' ? resolve(rt.cwd, explicit) : undefined,
    env: rt.env.LIFT_PLANNING_ROOT || undefined,
    home: rt.env.HOME || undefined,
  });

  const label = cliRegisterLabel(root, registerPath);
  const registerFile = isAbsolute(registerPath) ? registerPath : resolve(root, registerPath);
  const register = { path: label, exists: existsSync(registerFile), schema: null, problemCount: null };
  if (register.exists) {
    const loaded = loadRegister(root, { registerPath });
    const data = loaded.data;
    register.schema = data !== null && typeof data === 'object' && typeof data.schema === 'string' ? data.schema : null;
    const checked = checkRepo(root, { registerPath });
    if (checked.progress !== null) register.problemCount = checked.problems.filter((pr) => pr.info !== true).length;
  }

  // The project copy of the JSON Schema is compared only with a known plugin (else nothing to compare).
  const schemaCopy = plugin === null ? null : {
    path: DEFAULTS.schemaCopyPath,
    text: cliReadText(resolve(root, ...DEFAULTS.schemaCopyPath.split('/'))),
    expected: cliReadText(pluginSchemaPath(plugin.root)),
  };
  const report = doctorReport({ copy, plugin, register, schemaCopy, tickets: cliDoctorTickets(p, rt, root) });
  if (p.flags.has('--json')) {
    cliJson(rt, { contract: SHOW_CONTRACT, tool: VERSION, schema: SCHEMA, view: 'doctor', level: report.level, items: report.items });
  } else {
    for (const line of doctorLines(report, { quiet: p.flags.has('--quiet') })) rt.out(line);
  }
  return report.level === 'error' ? 1 : 0;
}

/** The short git commit of the plugin, or `v<VERSION>` when git cannot tell. */
function cliPluginRevision(pluginRoot) {
  try {
    const sha = execFileSync('git', ['-C', pluginRoot, 'rev-parse', '--short', 'HEAD'], {
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'ignore'],
    }).trim();
    if (/^[0-9a-f]{4,40}$/.test(sha)) return sha;
  } catch {
    // not a git checkout (an installed plugin): fall back to the version
  }
  return `v${VERSION}`;
}

async function cliVendor(p, rt) {
  const pluginRoot = cliRunningPluginRoot(rt);
  if (pluginRoot === null) {
    rt.err(CLI_VENDOR_REFUSAL);
    return 1;
  }
  const located = cliRootOrFallback(p, rt);
  const registerPath = cliRegisterPath(p);
  // Without a register at the root, a git repository (a `.git` directory or file at or above the root)
  // is what marks the target as a project repository. With a register the root is the project already.
  const registerFile = isAbsolute(registerPath) ? registerPath : resolve(located.root, registerPath);
  if (!existsSync(registerFile) && !insideGitRepository(located.root)) {
    rt.err(`vendor: ${located.root} is not inside a git repository; run it from the project repository (or pass --root)`);
    return 1;
  }
  const target = vendorTarget({ repoRoot: located.root, to: p.flags.get('--to') ?? 'scripts' });
  const schemaSource = pluginSchemaPath(pluginRoot);
  const schemaText = cliReadText(schemaSource);
  if (schemaText === null) {
    rt.err(`vendor: the plugin has no schema/plan-register-1.schema.json (${schemaSource})`);
    return 1;
  }
  if (!located.found) {
    rt.err(`note: no ${registerPath} found from ${rt.cwd} upwards; vendoring into ${located.root}`);
  }
  const distText = readFileSync(cliRealPath(rt.scriptAbs), 'utf8');
  const content = vendoredContent(distText, cliPluginRevision(pluginRoot));
  const oldText = cliReadText(target);
  const oldHeader = oldText === null ? null : parseHeader(oldText);
  const oldVersion = oldText === null ? 'none' : oldHeader === null ? 'unknown' : oldHeader.version;
  const newVersion = parseHeader(content).version;
  const shown = cliDisplayPath(target, located.root);
  if (oldText === content) {
    rt.out(`${shown}: ${oldVersion} → ${newVersion} (already current)`);
  } else {
    mkdirSync(dirname(target), { recursive: true });
    writeFileSync(target, content);
    rt.out(`${shown}: ${oldVersion} → ${newVersion}`);
  }
  // The JSON Schema, byte for byte, at the fixed DEFAULTS.schemaCopyPath (independent of --to).
  const schemaTarget = resolve(located.root, ...DEFAULTS.schemaCopyPath.split('/'));
  if (cliReadText(schemaTarget) === schemaText) {
    rt.out(`${DEFAULTS.schemaCopyPath}: already current`);
  } else {
    mkdirSync(dirname(schemaTarget), { recursive: true });
    writeFileSync(schemaTarget, schemaText);
    rt.out(`${DEFAULTS.schemaCopyPath}: updated`);
  }
  return 0;
}

async function cliHelp(p, rt) {
  const name = p.positionals[0];
  if (name === undefined) {
    rt.out(cliHelpText(rt));
    return 0;
  }
  if (!Object.hasOwn(COMMANDS, name)) throw cliUsageError(`unknown command ${JSON.stringify(name)}`, 'help');
  rt.out(cliCommandHelp(rt, name));
  return 0;
}

/** `tickets <subcommand> …`, handed over to core/tickets/cli.js. */
async function cliTickets(p, rt) {
  return ticketsMain(p.rest, {
    rt,
    flags: p.flags,
    commonFlags: COMMON_FLAGS,
    commandLine: (args, flags) => cliCommandLine(rt, { flags }, args),
  });
}

const CLI_HANDLERS = Object.freeze({
  check: cliCheck,
  write: cliWrite,
  render: cliRender,
  status: cliStatus,
  show: cliShow,
  next: cliNext,
  chain: cliChain,
  set: cliSet,
  'add-unit': cliAddUnit,
  'add-plan': cliAddPlan,
  'home-todo': cliHomeTodo,
  vendor: cliVendor,
  version: cliVersion,
  doctor: cliDoctor,
  help: cliHelp,
  tickets: cliTickets,
});

/**
 * Runs the CLI.
 *
 * @param {string[]} argv the arguments after the script
 * @param {{ cwd?: string, env?: object, stdout?: { write(s: string): unknown }, stderr?: { write(s: string): unknown },
 *   scriptPath?: string }} [io] `scriptPath` is the running file (process.argv[1]); it is shown in
 *   fix commands and read by `version`, `doctor` and `vendor`
 * @returns {Promise<0 | 1 | 2>}
 */
async function main(argv, { cwd = process.cwd(), env = process.env, stdout = process.stdout, stderr = process.stderr, scriptPath } = {}) {
  const scriptAbs = typeof scriptPath === 'string' && scriptPath !== '' ? resolve(cwd, scriptPath) : null;
  const rt = {
    cwd: resolve(cwd),
    env: env ?? {},
    scriptAbs,
    script: scriptAbs === null ? DEFAULTS.scriptPath : cliDisplayPath(scriptAbs, resolve(cwd)),
    out: (line) => stdout.write(`${line}\n`),
    err: (line) => stderr.write(`${line}\n`),
    write: (text) => stdout.write(text),
  };
  let parsed = null;
  try {
    parsed = cliParse(Array.isArray(argv) ? argv.map(String) : []);
    if (parsed.command === null) {
      stderr.write(`${cliHelpText(rt)}\n`);
      return 2;
    }
    return await CLI_HANDLERS[parsed.command](parsed, rt);
  } catch (e) {
    if (e instanceof UsageError) {
      rt.err(`plan-register: ${e.message}`);
      rt.err(typeof e.usageLine === 'string' ? e.usageLine : cliUsageLine(rt, e.command !== undefined ? e.command : parsed && parsed.command));
      return 2;
    }
    rt.err(`plan-register: ${e && e.message !== undefined ? e.message : String(e)}`);
    return 1;
  }
}

/**
 * Runs `main` with the process arguments when the running script is the module at `metaUrl` (so an
 * `import` of the module does not start the CLI); sets `process.exitCode`.
 *
 * @param {string} metaUrl `import.meta.url` of the entry file (bin/ or dist/)
 */
async function runMain(metaUrl) {
  const entry = process.argv[1];
  if (typeof entry !== 'string' || entry === '') return;
  if (cliRealPath(entry) !== cliRealPath(fileURLToPath(metaUrl))) return;
  process.exitCode = await main(process.argv.slice(2), {
    cwd: process.cwd(),
    env: process.env,
    stdout: process.stdout,
    stderr: process.stderr,
    scriptPath: entry,
  });
}

export { VERSION, SCHEMA, SUPPORTED_SCHEMAS, STATUSES, ROLES, PENDING_TODO_PREFIX, markFences, countCheckboxes, headingAnchors, findSection, tokenMatch, formatRegister, validateStructure, loadRegister, checkRepo, writeRegions, renderView, topoOrder, readyUnits, longestChain, checkTickets };
await runMain(import.meta.url);
